{
	internal static class DateAndTime
	{
		public static void Register(CalcEngine ce)
		{
			ce.RegisterFunction("DATE", 3, Date);
			ce.RegisterFunction("DATEVALUE", 1, Datevalue);
			ce.RegisterFunction("DAY", 1, Day);
			ce.RegisterFunction("DAYS360", 2, 3, Days360);
			ce.RegisterFunction("EDATE", 2, Edate);
			ce.RegisterFunction("EOMONTH", 2, Eomonth);
			ce.RegisterFunction("HOUR", 1, Hour);
			ce.RegisterFunction("MINUTE", 1, Minute);
			ce.RegisterFunction("MONTH", 1, Month);
			ce.RegisterFunction("NETWORKDAYS", 2, 3, Networkdays);
			ce.RegisterFunction("NOW", 0, Now);
			ce.RegisterFunction("SECOND", 1, Second);
			ce.RegisterFunction("TIME", 3, Time);
			ce.RegisterFunction("TIMEVALUE", 1, Timevalue);
			ce.RegisterFunction("TODAY", 0, Today);
			ce.RegisterFunction("WEEKDAY", 1, 2, Weekday);
			ce.RegisterFunction("WEEKNUM", 1, 2, Weeknum);
			ce.RegisterFunction("WORKDAY", 2, 3, Workday);
			ce.RegisterFunction("YEAR", 1, Year);
			ce.RegisterFunction("YEARFRAC", 2, 3, Yearfrac);
		}

		private static object Date(List<Expression> p)
		{
			int year = (int)(double)p[0];
			int month = (int)(double)p[1];
			int day = (int)(double)p[2];
			return (int)Math.Floor(new DateTime(year, month, day).ToOADate());
		}

		private static object Datevalue(List<Expression> p)
		{
			string s = p[0];
			return (int)Math.Floor(DateTime.Parse(s).ToOADate());
		}

		private static object Day(List<Expression> p)
		{
			return ((DateTime)p[0]).Day;
		}

		private static object Month(List<Expression> p)
		{
			return ((DateTime)p[0]).Month;
		}

		private static object Year(List<Expression> p)
		{
			return ((DateTime)p[0]).Year;
		}

		private static object Minute(List<Expression> p)
		{
			return ((DateTime)p[0]).Minute;
		}

		private static object Hour(List<Expression> p)
		{
			return ((DateTime)p[0]).Hour;
		}

		private static object Second(List<Expression> p)
		{
			return ((DateTime)p[0]).Second;
		}

		private static object Now(List<Expression> p)
		{
			return DateTime.Now;
		}

		private static object Time(List<Expression> p)
		{
			int hours = (int)(double)p[0];
			int minutes = (int)(double)p[1];
			int seconds = (int)(double)p[2];
			return new TimeSpan(0, hours, minutes, seconds);
		}

		private static object Timevalue(List<Expression> p)
		{
			DateTime dateTime = p[0];
			return (DateTime.MinValue + dateTime.TimeOfDay).ToOADate();
		}

		private static object Today(List<Expression> p)
		{
			return DateTime.Now.Date;
		}

		private static object Days360(List<Expression> p)
		{
			DateTime date = p[0];
			DateTime date2 = p[1];
			bool isEuropean = p.Count == 3 && (bool)p[2];
			return Days360(date, date2, isEuropean);
		}

		private static int Days360(DateTime date1, DateTime date2, bool isEuropean)
		{
			int num = date1.Day;
			int month = date1.Month;
			int year = date1.Year;
			int num2 = date2.Day;
			int month2 = date2.Month;
			int year2 = date2.Year;
			if (isEuropean)
			{
				if (num == 31)
				{
					num = 30;
				}
				if (num2 == 31)
				{
					num2 = 30;
				}
			}
			else
			{
				if (num == 31)
				{
					num = 30;
				}
				if (num2 == 31 && num == 30)
				{
					num2 = 30;
				}
			}
			return 360 * (year2 - year) + 30 * (month2 - month) + (num2 - num);
		}

		private static object Edate(List<Expression> p)
		{
			DateTime dateTime = p[0];
			int months = (int)(double)p[1];
			DateTime dateTime2 = dateTime.AddMonths(months);
			return dateTime2;
		}

		private static object Eomonth(List<Expression> p)
		{
			DateTime dateTime = p[0];
			int months = (int)(double)p[1];
			DateTime dateTime2 = dateTime.AddMonths(months);
			return new DateTime(dateTime2.Year, dateTime2.Month, 1).AddMonths(1).AddDays(-1.0);
		}

		private static object Networkdays(List<Expression> p)
		{
			DateTime firstDay = p[0];
			DateTime lastDay = p[1];
			List<DateTime> list = new List<DateTime>();
			if (p.Count == 3)
			{
				Tally tally = new Tally();
				tally.Add(p[2]);
				Tally source = tally;
				list.AddRange(source.Select(XLHelper.GetDate));
			}
			return BusinessDaysUntil(firstDay, lastDay, list);
		}

		private static int BusinessDaysUntil(DateTime firstDay, DateTime lastDay, IEnumerable<DateTime> bankHolidays)
		{
			firstDay = firstDay.Date;
			lastDay = lastDay.Date;
			if (firstDay > lastDay)
			{
				throw new ArgumentException("Incorrect last day " + lastDay);
			}
			int num = (lastDay - firstDay).Days + 1;
			int num2 = num / 7;
			if (num > num2 * 7)
			{
				int dayOfWeek = (int)firstDay.DayOfWeek;
				int num3 = (int)lastDay.DayOfWeek;
				if (num3 < dayOfWeek)
				{
					num3 += 7;
				}
				if (dayOfWeek <= 6)
				{
					if (num3 >= 7)
					{
						num -= 2;
					}
					else if (num3 >= 6)
					{
						num--;
					}
				}
				else if (dayOfWeek <= 7 && num3 >= 7)
				{
					num--;
				}
			}
			num -= num2 + num2;
			foreach (DateTime bankHoliday in bankHolidays)
			{
				if (firstDay <= bankHoliday && bankHoliday <= lastDay)
				{
					num--;
				}
			}
			return num;
		}

		private static object Weekday(List<Expression> p)
		{
			int dayOfWeek = (int)((DateTime)p[0]).DayOfWeek;
			return ((p.Count != 2) ? 1 : ((int)(double)p[1])) switch
			{
				2 => dayOfWeek, 
				1 => dayOfWeek + 1, 
				_ => dayOfWeek - 1, 
			};
		}

		private static object Weeknum(List<Expression> p)
		{
			DateTime time = p[0];
			int num = ((p.Count != 2) ? 1 : ((int)(double)p[1]));
			DayOfWeek firstDayOfWeek = ((num != 1) ? DayOfWeek.Monday : DayOfWeek.Sunday);
			GregorianCalendar gregorianCalendar = new GregorianCalendar(GregorianCalendarTypes.Localized);
			int weekOfYear = gregorianCalendar.GetWeekOfYear(time, CalendarWeekRule.FirstDay, firstDayOfWeek);
			return weekOfYear;
		}

		private static object Workday(List<Expression> p)
		{
			DateTime dateTime = p[0];
			int num = (int)(double)p[1];
			if (num == 0)
			{
				return dateTime;
			}
			if (num < 0)
			{
				throw new ArgumentOutOfRangeException("DaysRequired must be >= 0.");
			}
			List<DateTime> list = new List<DateTime>();
			if (p.Count == 3)
			{
				Tally tally = new Tally();
				tally.Add(p[2]);
				Tally source = tally;
				list.AddRange(source.Select(XLHelper.GetDate));
			}
			DateTime testDate = dateTime.AddDays((num / 7 + 2) * 7);
			return Workday(dateTime, testDate, num, list).NextWorkday(list);
		}

		private static DateTime Workday(DateTime startDate, DateTime testDate, int daysRequired, IEnumerable<DateTime> bankHolidays)
		{
			int num = BusinessDaysUntil(startDate, testDate, bankHolidays);
			if (num == daysRequired)
			{
				return testDate;
			}
			int num2 = ((num <= daysRequired) ? 1 : (-1));
			return Workday(startDate, testDate.AddDays(num2), daysRequired, bankHolidays);
		}

		private static object Yearfrac(List<Expression> p)
		{
			DateTime dateTime = p[0];
			DateTime dateTime2 = p[1];
			return ((p.Count == 3) ? ((int)(double)p[2]) : 0) switch
			{
				0 => (double)Days360(dateTime, dateTime2, isEuropean: false) / 360.0, 
				1 => Math.Floor((dateTime2 - dateTime).TotalDays) / GetYearAverage(dateTime, dateTime2), 
				2 => Math.Floor((dateTime2 - dateTime).TotalDays) / 360.0, 
				3 => Math.Floor((dateTime2 - dateTime).TotalDays) / 365.0, 
				_ => (double)Days360(dateTime, dateTime2, isEuropean: true) / 360.0, 
			};
		}

		private static double GetYearAverage(DateTime date1, DateTime date2)
		{
			List<int> list = new List<int>();
			for (int i = date1.Year; i <= date2.Year; i++)
			{
				list.Add(DateTime.IsLeapYear(i) ? 366 : 365);
			}
			return list.Average();
		}
	}
