	public static class XLHelper
	{
		public const int MinRowNumber = 1;

		public const int MinColumnNumber = 1;

		public const int MaxRowNumber = 1048576;

		public const int MaxColumnNumber = 16384;

		public const string MaxColumnLetter = "XFD";

		public const double Epsilon = 1E-10;

		private const int TwoT26 = 676;

		internal static readonly NumberFormatInfo NumberFormatForParse = CultureInfo.InvariantCulture.NumberFormat;

		internal static readonly Graphics Graphic = Graphics.FromImage((Image)new Bitmap(200, 200));

		internal static readonly double DpiX = Graphic.DpiX;

		internal static readonly Regex A1SimpleRegex = new Regex("\\A(?<Reference>(?<Sheet>(\\'([^\\[\\]\\*/\\\\\\?:\\']+|\\'\\')\\'|\\'?\\w+\\'?)!)?(?<Range>\\$?[a-zA-Z]{1,3}\\$?\\d{1,7}(?<RangeEnd>:\\$?[a-zA-Z]{1,3}\\$?\\d{1,7})?|(?<ColumnNumbers>\\$?\\d{1,7}:\\$?\\d{1,7})|(?<ColumnLetters>\\$?[a-zA-Z]{1,3}:\\$?[a-zA-Z]{1,3})))\\Z");

		internal static readonly Regex NamedRangeReferenceRegex = new Regex("^('?(?<Sheet>[^'!]+)'?!(?<Range>.+))|((?<Table>[^\\[]+)\\[(?<Column>[^\\]]+)\\])$", RegexOptions.ExplicitCapture | RegexOptions.Compiled | RegexOptions.CultureInvariant);

		private static readonly Regex A1RegexRelative = new Regex("(?<=\\W)(?<one>\\$?[a-zA-Z]{1,3}\\$?\\d{1,7})(?=\\W)|(?<=\\W)(?<two>\\$?\\d{1,7}:\\$?\\d{1,7})(?=\\W)|(?<=\\W)(?<three>\\$?[a-zA-Z]{1,3}:\\$?[a-zA-Z]{1,3})(?=\\W)", RegexOptions.Compiled);

		public static int GetColumnNumberFromLetter(string columnLetter)
		{
			if (columnLetter[0] <= '9')
			{
				return int.Parse(columnLetter, NumberFormatForParse);
			}
			columnLetter = columnLetter.ToUpper();
			return columnLetter.Length switch
			{
				1 => Convert.ToByte(columnLetter[0]) - 64, 
				2 => (Convert.ToByte(columnLetter[0]) - 64) * 26 + (Convert.ToByte(columnLetter[1]) - 64), 
				3 => (Convert.ToByte(columnLetter[0]) - 64) * 676 + (Convert.ToByte(columnLetter[1]) - 64) * 26 + (Convert.ToByte(columnLetter[2]) - 64), 
				_ => throw new ApplicationException("Column Length must be between 1 and 3."), 
			};
		}

		public static string GetColumnLetterFromNumber(int column)
		{
			if (column <= 0)
			{
				throw new ArgumentOutOfRangeException("column", "Must be more than 0");
			}
			StringBuilder stringBuilder = new StringBuilder(6);
			while (column > 0)
			{
				int num = column % 26;
				column /= 26;
				if (num == 0)
				{
					num = 26;
					column--;
				}
				stringBuilder.Insert(0, (char)(64 + num));
			}
			return stringBuilder.ToString();
		}

		public static bool IsValidColumn(string column)
		{
			int length = column.Length;
			if (IsNullOrWhiteSpace(column) || length > 3)
			{
				return false;
			}
			string text = column.ToUpper();
			bool flag = text[0] >= 'A' && text[0] <= 'Z';
			switch (length)
			{
			case 1:
				return flag;
			case 2:
				if (flag && text[1] >= 'A')
				{
					return text[1] <= 'Z';
				}
				return false;
			default:
				if (text[0] >= 'A' && text[0] < 'X')
				{
					if (text[1] >= 'A' && text[1] <= 'Z' && text[2] >= 'A')
					{
						return text[2] <= 'Z';
					}
					return false;
				}
				if (text[0] != 'X')
				{
					return false;
				}
				if (text[1] < 'F')
				{
					if (text[2] >= 'A')
					{
						return text[2] <= 'Z';
					}
					return false;
				}
				if (text[1] != 'F')
				{
					return false;
				}
				if (text[2] >= 'A')
				{
					return text[2] <= 'D';
				}
				return false;
			}
		}

		public static bool IsValidRow(string rowString)
		{
			if (int.TryParse(rowString, out var result))
			{
				if (result > 0)
				{
					return result <= 1048576;
				}
				return false;
			}
			return false;
		}

		public static bool IsValidA1Address(string address)
		{
			if (IsNullOrWhiteSpace(address))
			{
				return false;
			}
			address = address.Replace("$", "");
			int i = 0;
			int length;
			for (length = address.Length; i < length && (address[i] > '9' || address[i] < '0'); i++)
			{
			}
			if (i < length && IsValidRow(address.Substring(i)))
			{
				return IsValidColumn(address.Substring(0, i));
			}
			return false;
		}

		public static bool IsValidRangeAddress(string rangeAddress)
		{
			return A1SimpleRegex.IsMatch(rangeAddress);
		}

		public static bool IsValidRangeAddress(IXLRangeAddress rangeAddress)
		{
			if (!rangeAddress.IsInvalid && rangeAddress.FirstAddress.RowNumber >= 1 && rangeAddress.LastAddress.RowNumber <= 1048576 && rangeAddress.FirstAddress.ColumnNumber >= 1 && rangeAddress.LastAddress.ColumnNumber <= 16384 && rangeAddress.FirstAddress.RowNumber <= rangeAddress.LastAddress.RowNumber)
			{
				return rangeAddress.FirstAddress.ColumnNumber <= rangeAddress.LastAddress.ColumnNumber;
			}
			return false;
		}

		public static int GetColumnNumberFromAddress(string cellAddressString)
		{
			int i;
			for (i = 0; cellAddressString[i] > '9'; i++)
			{
			}
			return GetColumnNumberFromLetter(cellAddressString.Substring(0, i));
		}

		internal static string[] SplitRange(string range)
		{
			if (!Enumerable.Contains(range, '-'))
			{
				return range.Split(new char[1] { ':' });
			}
			return range.Replace('-', ':').Split(new char[1] { ':' });
		}

		public static int GetPtFromPx(double px)
		{
			return Convert.ToInt32(px * 72.0 / DpiX);
		}

		public static double GetPxFromPt(int pt)
		{
			return Convert.ToDouble(pt) * DpiX / 72.0;
		}

		internal static IXLTableRows InsertRowsWithoutEvents(Func<int, bool, IXLRangeRows> insertFunc, XLTableRange tableRange, int numberOfRows, bool expandTable)
		{
			XLWorksheet worksheet = tableRange.Worksheet;
			bool eventTrackingEnabled = worksheet.EventTrackingEnabled;
			worksheet.EventTrackingEnabled = false;
			XLTableRows rows = new XLTableRows(worksheet.Style);
			IXLRangeRows source = insertFunc(numberOfRows, arg2: false);
			source.ForEach(delegate(IXLRangeRow r)
			{
				rows.Add(new XLTableRow(tableRange, r as XLRangeRow));
			});
			if (expandTable)
			{
				tableRange.Table.ExpandTableRows(numberOfRows);
			}
			worksheet.EventTrackingEnabled = eventTrackingEnabled;
			return rows;
		}

		public static bool IsNullOrWhiteSpace(string value)
		{
			return string.IsNullOrWhiteSpace(value);
		}

		private static string Evaluator(Match match, int row, string column)
		{
			if (match.Groups["one"].Success)
			{
				string[] array = match.Groups["one"].Value.Split(new char[1] { '$' });
				if (array.Length == 1)
				{
					return column + row;
				}
				if (array.Length == 3)
				{
					return match.Groups["one"].Value;
				}
				XLAddress xLAddress = XLAddress.Create(match.Groups["one"].Value);
				if (array[0] == string.Empty)
				{
					return "$" + xLAddress.ColumnLetter + row;
				}
				return column + "$" + xLAddress.RowNumber;
			}
			if (match.Groups["two"].Success)
			{
				return ReplaceGroup(match.Groups["two"].Value, row.ToString());
			}
			return ReplaceGroup(match.Groups["three"].Value, column);
		}

		private static string ReplaceGroup(string value, string item)
		{
			string[] array = value.Split(new char[1] { ':' });
			string text = (array[0].StartsWith("$") ? array[0] : item);
			string text2 = (array[1].StartsWith("$") ? array[1] : item);
			return text + ":" + text2;
		}

		internal static string ReplaceRelative(string value, int row, string column)
		{
			string input = ">" + value + "<";
			string text = A1RegexRelative.Replace(input, (Match m) => Evaluator(m, row, column));
			return text.Substring(1, text.Length - 2);
		}

		public static bool AreEqual(double d1, double d2)
		{
			return Math.Abs(d1 - d2) < 1E-10;
		}

		public static DateTime GetDate(object v)
		{
			if (v is DateTime)
			{
				return (DateTime)v;
			}
			if (v is double)
			{
				return DateTime.FromOADate((double)v);
			}
			return (DateTime)Convert.ChangeType(v, typeof(DateTime));
		}
	}
	public interface IXLFilteredColumn
	{
		IXLFilteredColumn AddFilter<T>(T value) where T : IComparable<T>;
	}
	internal class XLFilteredColumn : IXLFilteredColumn
	{
		private readonly XLAutoFilter _autoFilter;

		private readonly int _column;

		public XLFilteredColumn(XLAutoFilter autoFilter, int column)
		{
			_autoFilter = autoFilter;
			_column = column;
		}

		public IXLFilteredColumn AddFilter<T>(T value) where T : IComparable<T>
		{
			Func<object, bool> func;
			bool flag;
			if (typeof(T) == typeof(string))
			{
				func = (object v) => v.ToString().Equals(value.ToString(), StringComparison.InvariantCultureIgnoreCase);
				flag = true;
			}
			else
			{
				func = (object v) => v.CastTo<T>().CompareTo(value) == 0;
				flag = false;
			}
			_autoFilter.Filters[_column].Add(new XLFilter
			{
				Value = value,
				Condition = func,
				Operator = XLFilterOperator.Equal,
				Connector = XLConnector.Or
			});
			using IXLRangeRows iXLRangeRows = _autoFilter.Range.Rows(2, _autoFilter.Range.RowCount());
			foreach (IXLRangeRow item in iXLRangeRows)
			{
				if ((flag && func(item.Cell(_column).GetString())) || (!flag && item.Cell(_column).DataType == XLCellValues.Number && func(item.Cell(_column).GetValue<T>())))
				{
					item.WorksheetRow().Unhide().Dispose();
				}
			}
			return this;
		}
	}
	public interface IXLCustomFilteredColumn
	{
		void EqualTo<T>(T value) where T : IComparable<T>;

		void NotEqualTo<T>(T value) where T : IComparable<T>;

		void GreaterThan<T>(T value) where T : IComparable<T>;

		void LessThan<T>(T value) where T : IComparable<T>;

		void EqualOrGreaterThan<T>(T value) where T : IComparable<T>;

		void EqualOrLessThan<T>(T value) where T : IComparable<T>;

		void BeginsWith(string value);

		void NotBeginsWith(string value);

		void EndsWith(string value);

		void NotEndsWith(string value);

		void Contains(string value);

		void NotContains(string value);
	}
	internal class XLCustomFilteredColumn : IXLCustomFilteredColumn
	{
		private readonly XLAutoFilter _autoFilter;

		private readonly int _column;

		private readonly XLConnector _connector;

		public XLCustomFilteredColumn(XLAutoFilter autoFilter, int column, XLConnector connector)
		{
			_autoFilter = autoFilter;
			_column = column;
			_connector = connector;
		}

		public void EqualTo<T>(T value) where T : IComparable<T>
		{
			if (typeof(T) == typeof(string))
			{
				ApplyCustomFilter(value, XLFilterOperator.Equal, (object v) => v.ToString().Equals(value.ToString(), StringComparison.InvariantCultureIgnoreCase));
			}
			else
			{
				ApplyCustomFilter(value, XLFilterOperator.Equal, (object v) => v.CastTo<T>().CompareTo(value) == 0);
			}
		}

		public void NotEqualTo<T>(T value) where T : IComparable<T>
		{
			if (typeof(T) == typeof(string))
			{
