			if (takeTop)
			{
				if (type == XLTopBottomType.Items)
				{
					return (from c in source
						select c.GetDouble() into d
						orderby d descending
						select d).Take(value).Distinct();
				}
				IEnumerable<double> source2 = source.Select((IXLCell c) => c.GetDouble());
				int count = source2.Count() * value / 100;
				return source2.OrderByDescending((double d) => d).Take(count).Distinct();
			}
			if (type == XLTopBottomType.Items)
