		private IEnumerable<double> GetAverageValues(bool aboveAverage)
		{
			using IXLRangeColumn iXLRangeColumn = _autoFilter.Range.Column(_column);
			using IXLRangeColumn iXLRangeColumn2 = iXLRangeColumn.Column(2, iXLRangeColumn.CellCount());
			double average = (from c in iXLRangeColumn2.CellsUsed((IXLCell c) => c.DataType == XLCellValues.Number)
				select c.GetDouble()).Average();
			if (aboveAverage)
			{
				return (from c in iXLRangeColumn2.CellsUsed((IXLCell c) => c.DataType == XLCellValues.Number)
					select c.GetDouble() into c
					where c > average
					select c).Distinct();
			}
			return (from c in iXLRangeColumn2.CellsUsed((IXLCell c) => c.DataType == XLCellValues.Number)
				select c.GetDouble() into c
				where c < average
				select c).Distinct();
		}

		private IXLFilterConnector ApplyCustomFilter<T>(T value, XLFilterOperator op, Func<object, bool> condition, XLFilterType filterType = XLFilterType.Custom) where T : IComparable<T>
		{
			_autoFilter.Enabled = true;
			List<XLFilter> value2;
			if (filterType == XLFilterType.Custom)
			{
				Clear();
				_autoFilter.Filters.Add(_column, new List<XLFilter>
				{
					new XLFilter
					{
						Value = value,
						Operator = op,
						Connector = XLConnector.Or,
						Condition = condition
					}
				});
			}
			else if (_autoFilter.Filters.TryGetValue(_column, out value2))
			{
				value2.Add(new XLFilter
				{
					Value = value,
					Operator = op,
					Connector = XLConnector.Or,
					Condition = condition
				});
			}
			else
			{
				_autoFilter.Filters.Add(_column, new List<XLFilter>
				{
					new XLFilter
					{
						Value = value,
						Operator = op,
						Connector = XLConnector.Or,
						Condition = condition
					}
				});
			}
			_autoFilter.Column(_column).FilterType = filterType;
			bool flag = typeof(T) == typeof(string);
			XLWorksheet xLWorksheet = _autoFilter.Range.Worksheet as XLWorksheet;
			xLWorksheet.SuspendEvents();
			IXLRangeRows iXLRangeRows = _autoFilter.Range.Rows(2, _autoFilter.Range.RowCount());
			foreach (IXLRangeRow item in iXLRangeRows)
			{
				bool num;
				if (!flag)
				{
					if (item.Cell(_column).DataType != XLCellValues.Number)
					{
						goto IL_01fb;
					}
					num = condition(item.Cell(_column).GetDouble());
				}
				else
				{
					num = condition(item.Cell(_column).GetString());
				}
				if (num)
				{
					item.WorksheetRow().Unhide();
					continue;
				}
				goto IL_01fb;
				IL_01fb:
				item.WorksheetRow().Hide();
			}
			xLWorksheet.ResumeEvents();
			return new XLFilterConnector(_autoFilter, _column);
		}

