	internal class XLAutoFilter : IXLBaseAutoFilter, IXLAutoFilter, IDisposable
	{
		private readonly Dictionary<int, XLFilterColumn> _columns = new Dictionary<int, XLFilterColumn>();

		public Dictionary<int, List<XLFilter>> Filters { get; private set; }

		public bool Enabled { get; set; }

		public IXLRange Range { get; set; }

		public bool Sorted { get; set; }

		public XLSortOrder SortOrder { get; set; }

		public int SortColumn { get; set; }

		public XLAutoFilter()
		{
			Filters = new Dictionary<int, List<XLFilter>>();
		}

		IXLAutoFilter IXLAutoFilter.Sort(int columnToSortBy, XLSortOrder sortOrder, bool matchCase, bool ignoreBlanks)
		{
			return Sort(columnToSortBy, sortOrder, matchCase, ignoreBlanks);
		}

		public void Dispose()
		{
			if (Range != null)
			{
				Range.Dispose();
			}
		}

		IXLBaseAutoFilter IXLBaseAutoFilter.Clear()
		{
			return Clear();
		}

		IXLBaseAutoFilter IXLBaseAutoFilter.Set(IXLRangeBase range)
		{
			return Set(range);
		}

		IXLBaseAutoFilter IXLBaseAutoFilter.Sort(int columnToSortBy, XLSortOrder sortOrder, bool matchCase, bool ignoreBlanks)
		{
			return Sort(columnToSortBy, sortOrder, matchCase, ignoreBlanks);
		}

		public IXLFilterColumn Column(string column)
		{
			return Column(XLHelper.GetColumnNumberFromLetter(column));
		}

		public IXLFilterColumn Column(int column)
		{
			if (!_columns.TryGetValue(column, out var value))
			{
				value = new XLFilterColumn(this, column);
				_columns.Add(column, value);
			}
			return value;
		}

		public XLAutoFilter Set(IXLRangeBase range)
		{
			Range = range.AsRange();
			Enabled = true;
			return this;
		}

		public XLAutoFilter Clear()
		{
			Enabled = false;
			Filters.Clear();
			foreach (IXLRangeRow item in from r in Range.Rows()
				where r.RowNumber() > 1
				select r)
			{
				item.WorksheetRow().Unhide();
			}
			return this;
		}

		public XLAutoFilter Sort(int columnToSortBy, XLSortOrder sortOrder, bool matchCase, bool ignoreBlanks)
		{
			XLWorksheet xLWorksheet = Range.Worksheet as XLWorksheet;
			xLWorksheet.SuspendEvents();
			Range.Range(Range.FirstCell().CellBelow(), Range.LastCell()).Sort(columnToSortBy, sortOrder, matchCase, ignoreBlanks);
			Sorted = true;
			SortOrder = sortOrder;
			SortColumn = columnToSortBy;
			if (Enabled)
			{
				using (IXLRangeRows iXLRangeRows = Range.Rows(2, Range.RowCount()))
				{
					foreach (IXLRangeRow item in iXLRangeRows)
					{
						item.WorksheetRow().Unhide();
					}
				}
				foreach (KeyValuePair<int, List<XLFilter>> filter in Filters)
				{
					bool flag = true;
					foreach (XLFilter item2 in filter.Value)
