				AddToken('(', TKID.OPEN, TKTYPE.GROUP);
				AddToken(')', TKID.CLOSE, TKTYPE.GROUP);
				AddToken('*', TKID.MUL, TKTYPE.MULDIV);
				AddToken('.', TKID.PERIOD, TKTYPE.GROUP);
				AddToken('/', TKID.DIV, TKTYPE.MULDIV);
				AddToken('\\', TKID.DIVINT, TKTYPE.MULDIV);
