				AddToken('>', TKID.GT, TKTYPE.COMPARE);
				AddToken('<', TKID.LT, TKTYPE.COMPARE);
				AddToken('^', TKID.POWER, TKTYPE.POWER);
				AddToken("<>", TKID.NE, TKTYPE.COMPARE);
				AddToken(">=", TKID.GE, TKTYPE.COMPARE);
				AddToken("<=", TKID.LE, TKTYPE.COMPARE);
