	internal delegate object CalcEngineFunction(List<Expression> parms);
	internal class Expression : IComparable<Expression>
	{
		internal Token _token;

		private static CultureInfo _ci = CultureInfo.InvariantCulture;

		internal Expression()
		{
			_token = new Token(null, TKID.ATOM, TKTYPE.IDENTIFIER);
		}

		internal Expression(object value)
		{
			_token = new Token(value, TKID.ATOM, TKTYPE.LITERAL);
		}

		internal Expression(Token tk)
		{
			_token = tk;
		}

		public virtual object Evaluate()
		{
			if (_token.Type != TKTYPE.LITERAL)
			{
				throw new ArgumentException("Bad expression.");
			}
			return _token.Value;
		}

		public virtual Expression Optimize()
		{
			return this;
		}

		public static implicit operator string(Expression x)
		{
			object obj = x.Evaluate();
			if (obj != null)
			{
				return obj.ToString();
			}
			return string.Empty;
		}

		public static implicit operator double(Expression x)
		{
			object obj = x.Evaluate();
			if (obj is double)
			{
				return (double)obj;
			}
			if (obj is bool)
			{
				return ((bool)obj) ? 1 : 0;
			}
			if (obj is DateTime dateTime)
			{
				return dateTime.ToOADate();
			}
			if (obj == null || obj is string)
			{
				return 0.0;
			}
			return (double)Convert.ChangeType(obj, typeof(double), _ci);
		}

		public static implicit operator bool(Expression x)
		{
			object obj = x.Evaluate();
			if (obj is bool)
			{
				return (bool)obj;
			}
			if (obj == null)
			{
				return false;
			}
			if (obj is double)
			{
				if ((double)obj != 0.0)
				{
					return true;
				}
				return false;
			}
			if ((double)x != 0.0)
			{
				return true;
			}
			return false;
		}

		public static implicit operator DateTime(Expression x)
		{
			object obj = x.Evaluate();
			if (obj is DateTime)
			{
				return (DateTime)obj;
			}
			if (obj is double)
			{
				return DateTime.FromOADate(x);
			}
			return (DateTime)Convert.ChangeType(obj, typeof(DateTime), _ci);
		}

		public int CompareTo(Expression other)
		{
			IComparable comparable = Evaluate() as IComparable;
			IComparable comparable2 = other.Evaluate() as IComparable;
			if (comparable == null && comparable2 == null)
			{
				return 0;
			}
			if (comparable2 == null)
			{
				return -1;
			}
			if (comparable == null)
			{
				return 1;
			}
			if (comparable.GetType() != comparable2.GetType())
			{
				comparable2 = Convert.ChangeType(comparable2, comparable.GetType()) as IComparable;
			}
			return comparable.CompareTo(comparable2);
		}
	}
	internal class UnaryExpression : Expression
	{
		private Expression _expr;

		public UnaryExpression(Token tk, Expression expr)
			: base(tk)
		{
			_expr = expr;
		}

		public override object Evaluate()
		{
			return _token.ID switch
			{
				TKID.ADD => (double)_expr, 
				TKID.SUB => 0.0 - (double)_expr, 
				_ => throw new ArgumentException("Bad expression."), 
			};
		}

		public override Expression Optimize()
		{
			_expr = _expr.Optimize();
			if (_expr._token.Type != TKTYPE.LITERAL)
			{
				return this;
			}
			return new Expression(Evaluate());
		}
	}
	internal class BinaryExpression : Expression
	{
		private Expression _lft;

		private Expression _rgt;

		public BinaryExpression(Token tk, Expression exprLeft, Expression exprRight)
			: base(tk)
		{
			_lft = exprLeft;
			_rgt = exprRight;
		}

		public override object Evaluate()
		{
			if (_token.Type == TKTYPE.COMPARE)
			{
				int num = _lft.CompareTo(_rgt);
				switch (_token.ID)
				{
				case TKID.GT:
					return num > 0;
				case TKID.LT:
					return num < 0;
				case TKID.GE:
					return num >= 0;
				case TKID.LE:
					return num <= 0;
				case TKID.EQ:
					return num == 0;
				case TKID.NE:
					return num != 0;
				}
			}
			switch (_token.ID)
			{
			case TKID.CONCAT:
				return string.Concat(_lft, _rgt);
			case TKID.ADD:
				return (double)_lft + (double)_rgt;
			case TKID.SUB:
				return (double)_lft - (double)_rgt;
			case TKID.MUL:
				return (double)_lft * (double)_rgt;
			case TKID.DIV:
				return (double)_lft / (double)_rgt;
			case TKID.DIVINT:
				return (double)(int)((double)_lft / (double)_rgt);
			case TKID.MOD:
				return (double)(int)((double)_lft % (double)_rgt);
			case TKID.POWER:
			{
				double num2 = _lft;
				double num3 = _rgt;
				if (num3 == 0.0)
				{
					return 1.0;
				}
				if (num3 == 0.5)
				{
					return Math.Sqrt(num2);
				}
				if (num3 == 1.0)
				{
					return num2;
				}
				if (num3 == 2.0)
				{
					return num2 * num2;
				}
				if (num3 == 3.0)
				{
					return num2 * num2 * num2;
				}
				if (num3 == 4.0)
				{
					return num2 * num2 * num2 * num2;
				}
				return Math.Pow(_lft, _rgt);
			}
			default:
				throw new ArgumentException("Bad expression.");
			}
		}

		public override Expression Optimize()
		{
			_lft = _lft.Optimize();
			_rgt = _rgt.Optimize();
			if (_lft._token.Type != TKTYPE.LITERAL || _rgt._token.Type != TKTYPE.LITERAL)
			{
				return this;
			}
			return new Expression(Evaluate());
		}
	}
	internal class FunctionExpression : Expression
	{
		private FunctionDefinition _fn;

		private List<Expression> _parms;

		internal FunctionExpression()
		{
		}

		public FunctionExpression(FunctionDefinition function, List<Expression> parms)
		{
			_fn = function;
			_parms = parms;
		}

		public override object Evaluate()
		{
			return _fn.Function(_parms);
		}

		public override Expression Optimize()
		{
			bool flag = true;
			if (_parms != null)
			{
				for (int i = 0; i < _parms.Count; i++)
				{
					Expression expression = _parms[i].Optimize();
					_parms[i] = expression;
					if (expression._token.Type != TKTYPE.LITERAL)
					{
						flag = false;
					}
				}
			}
			if (!flag)
			{
				return this;
			}
			return new Expression(Evaluate());
		}
	}
