	internal class BindingExpression : Expression
	{
		private CalcEngine _ce;

		private CultureInfo _ci;

		private List<BindingInfo> _bindingPath;

		internal BindingExpression(CalcEngine engine, List<BindingInfo> bindingPath, CultureInfo ci)
		{
			_ce = engine;
			_bindingPath = bindingPath;
			_ci = ci;
		}

		public override object Evaluate()
		{
			return GetValue(_ce.DataContext);
		}

		private object GetValue(object obj)
		{
			if (obj != null)
			{
				foreach (BindingInfo item in _bindingPath)
				{
					if (item.PropertyInfo == null)
					{
						item.PropertyInfo = obj.GetType().GetProperty(item.Name, BindingFlags.IgnoreCase | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public);
					}
					try
					{
						obj = item.PropertyInfo.GetValue(obj, null);
					}
					catch
					{
						item.PropertyInfo = obj.GetType().GetProperty(item.Name, BindingFlags.IgnoreCase | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public);
						item.PropertyInfoItem = null;
						obj = item.PropertyInfo.GetValue(obj, null);
					}
					if (item.Parms != null && item.Parms.Count > 0)
					{
						if (item.PropertyInfoItem == null)
						{
							item.PropertyInfoItem = obj.GetType().GetProperty("Item", BindingFlags.IgnoreCase | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public);
						}
						ParameterInfo[] indexParameters = item.PropertyInfoItem.GetIndexParameters();
						List<object> list = new List<object>();
						for (int i = 0; i < indexParameters.Length; i++)
						{
							object value = item.Parms[i].Evaluate();
							value = Convert.ChangeType(value, indexParameters[i].ParameterType, _ci);
							list.Add(value);
						}
						obj = item.PropertyInfoItem.GetValue(obj, list.ToArray());
					}
				}
			}
			return obj;
		}
	}
