	internal class ExpressionCache
	{
		private Dictionary<string, WeakReference> _dct;

		private CalcEngine _ce;

		private int _hitCount;

		public Expression this[string expression]
		{
			get
			{
				Expression expression2;
				if (_dct.TryGetValue(expression, out var value) && value.IsAlive)
				{
					expression2 = value.Target as Expression;
				}
				else
				{
					if (value != null && _dct.Count > 100 && _hitCount++ > 100)
					{
						RemoveDeadReferences();
						_hitCount = 0;
					}
					expression2 = _ce.Parse(expression);
					_dct[expression] = new WeakReference(expression2);
				}
				return expression2;
			}
		}

		public ExpressionCache(CalcEngine ce)
		{
			_ce = ce;
			_dct = new Dictionary<string, WeakReference>();
		}

		private void RemoveDeadReferences()
		{
			bool flag = false;
			while (!flag)
			{
				flag = true;
				foreach (string key in _dct.Keys)
				{
					if (!_dct[key].IsAlive)
					{
						_dct.Remove(key);
						flag = false;
						break;
					}
				}
			}
		}
	}
