		private static object SumIf(List<Expression> p)
		{
			IEnumerable enumerable = p[0] as IEnumerable;
			IEnumerable enumerable2 = ((p.Count < 3) ? enumerable : (p[2] as IEnumerable));
			object criteria = p[1].Evaluate();
			List<object> list = new List<object>();
			foreach (object item in enumerable)
			{
				list.Add(item);
			}
			List<object> list2 = new List<object>();
			foreach (object item2 in enumerable2)
			{
				list2.Add(item2);
			}
			CalcEngine ce = new CalcEngine();
			Tally tally = new Tally();
			for (int i = 0; i < Math.Min(list.Count, list2.Count); i++)
			{
				if (ValueSatisfiesCriteria(list[i], criteria, ce))
				{
					tally.AddValue(list2[i]);
				}
			}
			return tally.Sum();
		}

		private static bool ValueSatisfiesCriteria(object value, object criteria, CalcEngine ce)
		{
			if (value == null)
			{
				return false;
			}
			if (criteria is double)
			{
				return (double)value == (double)criteria;
			}
			string text = criteria as string;
			if (!string.IsNullOrEmpty(text))
			{
				if (text[0] == '=' || text[0] == '<' || text[0] == '>')
				{
					string text2 = $"{value}{text}";
					string pattern = "(\\w+)(\\W+)(\\w+)";
					Match match = Regex.Match(text2, pattern);
					if (match.Groups.Count == 4 && (!double.TryParse(match.Groups[1].Value, out var result) || !double.TryParse(match.Groups[3].Value, out result)))
					{
						text2 = $"\"{match.Groups[1].Value}\"{match.Groups[2].Value}\"{match.Groups[3].Value}\"";
					}
					return (bool)ce.Evaluate(text2);
				}
				if (text.IndexOf('*') > -1)
				{
					string text3 = text.Replace("\\", "\\\\");
					text3 = text3.Replace(".", "\\");
					text3 = text3.Replace("*", ".*");
					return Regex.IsMatch(value.ToString(), text3, RegexOptions.IgnoreCase);
				}
				return string.Equals(value.ToString(), text, StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

