		private static object Fact(List<Expression> p)
		{
			double num = Math.Floor(p[0]);
			double num2 = 1.0;
			if (num > 1.0)
			{
				for (int i = 2; (double)i <= num; i++)
				{
					num2 *= (double)i;
				}
			}
			return num2;
		}

		private static object FactDouble(List<Expression> p)
		{
			double num = Math.Floor(p[0]);
			double num2 = 1.0;
			if (num > 1.0)
			{
				int num3 = ((!(Math.Abs(num % 2.0) < 1E-10)) ? 1 : 2);
				for (int i = num3; (double)i <= num; i += 2)
				{
					num2 *= (double)i;
				}
			}
			return num2;
		}

