		}

		private static object MRound(List<Expression> p)
		{
			decimal num = (decimal)(double)p[0];
			decimal num2 = (decimal)(double)p[1];
			decimal num3 = num % num2;
			decimal num4 = Math.Floor(num / num2);
			decimal num5 = num2 / 2m;
			if (Math.Abs(num3 - num5) <= 0.0000000001m)
			{
				return num2 * num4 + num2;
			}
			return num2 * num4;
		}

		private static object Multinomial(List<Expression> p)
		{
			return Multinomial(((IEnumerable<Expression>)p).Select((Func<Expression, double>)((Expression v) => v)).ToList());
