		private static double Multinomial(List<double> numbers)
		{
			double num = 0.0;
			foreach (double number in numbers)
			{
				double num2 = number;
				num += num2;
			}
			double num3 = numbers.Max();
			double[] array = new double[(uint)numbers.Max() + 1];
			foreach (double number2 in numbers)
			{
				double num4 = number2;
				for (int i = 2; (double)i <= num4; i++)
				{
					array[i] += 1.0;
				}
			}
			for (int j = 2; j < array.Length; j++)
			{
				array[j] -= 1.0;
			}
			int num5 = 2;
			double num6 = 1.0;
			double num7 = 1.0;
			for (double num8 = num3 + 1.0; num8 <= num; num8 += 1.0)
			{
				double num9 = 1.0;
				while (num9 < num7 && num5 < array.Length)
				{
					if (num6 > array[num5])
					{
						num5++;
						num6 = 1.0;
					}
					else
					{
						num9 *= (double)num5;
						num6 += 1.0;
					}
				}
				num7 = num7 / num9 * num8;
			}
			return num7;
		}

