		private static object Round(List<Expression> p)
		{
			double num = p[0];
			int num2 = (int)(double)p[1];
			if (num2 >= 0)
			{
				return Math.Round(num, num2);
			}
			num2 = Math.Abs(num2);
			double value = num / Math.Pow(10.0, num2);
			value = Math.Round(value, 0);
			return value * Math.Pow(10.0, num2);
		}

		private static object RoundDown(List<Expression> p)
		{
			double num = p[0];
			int num2 = (int)(double)p[1];
			if (num >= 0.0)
			{
				return Math.Floor(num * Math.Pow(10.0, num2)) / Math.Pow(10.0, num2);
			}
			return Math.Ceiling(num * Math.Pow(10.0, num2)) / Math.Pow(10.0, num2);
		}

		private static object RoundUp(List<Expression> p)
		{
			double num = p[0];
			int num2 = (int)(double)p[1];
			if (num >= 0.0)
			{
				return Math.Ceiling(num * Math.Pow(10.0, num2)) / Math.Pow(10.0, num2);
			}
			return Math.Floor(num * Math.Pow(10.0, num2)) / Math.Pow(10.0, num2);
		}

		private static object SeriesSum(List<Expression> p)
		{
			double x = p[0];
			double num = p[1];
			double num2 = p[2];
			if (!(p[3] is XObjectExpression xObjectExpression))
			{
				return (double)p[3] * Math.Pow(x, num);
			}
			double num3 = 0.0;
			int num4 = 0;
			foreach (object item in xObjectExpression)
			{
				num3 += (double)item * Math.Pow(x, num + (double)num4 * num2);
				num4++;
			}
			return num3;
		}

		private static object SqrtPi(List<Expression> p)
		{
			double num = p[0];
			return Math.Sqrt(Math.PI * num);
		}

		private static object Subtotal(List<Expression> p)
		{
			int num = (int)(double)p[0];
			Tally tally = new Tally(p.Skip(1));
			return num switch
			{
				1 => tally.Average(), 
				2 => tally.Count(), 
				3 => tally.CountA(), 
				4 => tally.Max(), 
				5 => tally.Min(), 
				6 => tally.Product(), 
				7 => tally.Std(), 
				8 => tally.StdP(), 
				9 => tally.Sum(), 
				10 => tally.Var(), 
				11 => tally.VarP(), 
				_ => throw new ArgumentException("Function not supported."), 
			};
		}

		private static object SumSq(List<Expression> p)
		{
			Tally tally = new Tally(p);
			return tally.Numerics().Sum((double v) => Math.Pow(v, 2.0));
		}

		private static object MMult(List<Expression> p)
		{
			double[,] array = GetArray(p[0]);
			double[,] array2 = GetArray(p[1]);
			if (array.GetLength(0) != array2.GetLength(0) || array.GetLength(1) != array2.GetLength(1))
			{
				throw new ArgumentException("Ranges must have the same number of rows and columns.");
			}
			double[,] array3 = new double[array.GetLength(0), array.GetLength(1)];
			for (int i = 0; i < array.GetLength(0); i++)
			{
				for (int j = 0; j < array2.GetLength(1); j++)
				{
					for (int k = 0; k < array.GetLength(1); k++)
					{
						array3[i, j] += array[i, k] * array2[k, j];
					}
				}
			}
			return array3;
		}

		private static double[,] GetArray(Expression expression)
		{
			if (!(expression is XObjectExpression xObjectExpression))
			{
				return new double[1, 1] { { expression } };
			}
			IXLRange range = (xObjectExpression.Value as CellRangeReference).Range;
			int num = range.RowCount();
			int num2 = range.ColumnCount();
			double[,] array = new double[num, num2];
			for (int i = 0; i < num; i++)
			{
				for (int j = 0; j < num2; j++)
				{
					array[i, j] = range.Cell(i + 1, j + 1).GetDouble();
				}
			}
			return array;
		}

		private static object MDeterm(List<Expression> p)
		{
			double[,] array = GetArray(p[0]);
			XLMatrix xLMatrix = new XLMatrix(array);
			return xLMatrix.Determinant();
		}

		private static object MInverse(List<Expression> p)
		{
			double[,] array = GetArray(p[0]);
			XLMatrix xLMatrix = new XLMatrix(array);
			return xLMatrix.Invert().mat;
		}
	}
