		{
			return GetTally(p, numbersOnly: false).Count();
		}

		private static object CountBlank(List<Expression> p)
		{
			double num = 0.0;
			foreach (Expression item in p)
			{
				if (item is IEnumerable enumerable)
				{
					foreach (object item2 in enumerable)
					{
						if (IsBlank(item2))
						{
							num += 1.0;
						}
					}
				}
				else if (IsBlank(item.Evaluate()))
				{
					num += 1.0;
				}
			}
			return num;
		}

		private static bool IsBlank(object value)
		{
			if (value != null)
			{
				if (value is string)
				{
					return ((string)value).Length == 0;
				}
				return false;
			}
			return true;
		}

		private static object CountIf(List<Expression> p)
		{
			CalcEngine calcEngine = new CalcEngine();
			double num = 0.0;
			if (p[0] is IEnumerable enumerable)
			{
				string arg = (string)p[1].Evaluate();
				foreach (object item in enumerable)
				{
					if (!IsBlank(item))
					{
						string expression = $"{item}{arg}";
						if ((bool)calcEngine.Evaluate(expression))
						{
							num += 1.0;
						}
					}
				}
			}
			return num;
		}

