	internal class Tally : IEnumerable<object>, IEnumerable
	{
		private readonly List<object> _list = new List<object>();

		public Tally()
		{
		}

		public Tally(IEnumerable<Expression> p)
		{
			foreach (Expression item in p)
			{
				Add(item);
			}
		}

		public void Add(Expression e)
		{
			if (e is IEnumerable enumerable)
			{
				{
					foreach (object item in enumerable)
					{
						_list.Add(item);
					}
					return;
				}
			}
			object obj = e.Evaluate();
			if (!(obj is IEnumerable enumerable2) || obj is string)
			{
				_list.Add(obj);
				return;
			}
			foreach (object item2 in enumerable2)
			{
				_list.Add(item2);
			}
		}

		public void AddValue(object v)
		{
			_list.Add(v);
		}

		public double Count()
		{
			return _list.Count;
		}

		public double CountA()
		{
			double num = 0.0;
			foreach (object item in _list)
			{
				if (!(item is IEnumerable enumerable))
				{
					num += AddCount(item);
					continue;
				}
				{
					IEnumerator enumerator2 = enumerable.GetEnumerator();
					try
					{
						if (enumerator2.MoveNext())
						{
							object current2 = enumerator2.Current;
							num += AddCount(current2);
						}
					}
					finally
					{
						IDisposable disposable = enumerator2 as IDisposable;
						if (disposable != null)
						{
							disposable.Dispose();
						}
					}
				}
			}
			return num;
		}

		private static double AddCount(object value)
		{
			string text = value as string;
			if (value != null && (text == null || !XLHelper.IsNullOrWhiteSpace(text)))
			{
				return 1.0;
			}
			return 0.0;
		}

		public List<double> Numerics()
		{
			List<double> list = new List<double>();
			foreach (object item in _list)
			{
				if (!(item is IEnumerable enumerable))
				{
					AddNumericValue(item, list);
					continue;
				}
				{
					IEnumerator enumerator2 = enumerable.GetEnumerator();
					try
					{
						if (enumerator2.MoveNext())
						{
							object current2 = enumerator2.Current;
							AddNumericValue(current2, list);
						}
					}
					finally
					{
						IDisposable disposable = enumerator2 as IDisposable;
						if (disposable != null)
						{
							disposable.Dispose();
						}
					}
				}
			}
			return list;
		}

		private static void AddNumericValue(object value, List<double> retVal)
		{
			if (double.TryParse(value.ToString(), out var result))
			{
				retVal.Add(result);
			}
		}

		public double Product()
		{
			List<double> list = Numerics();
			if (list.Count == 0)
			{
				return 0.0;
			}
			double retVal = 1.0;
			list.ForEach(delegate(double n)
			{
				retVal *= n;
			});
			return retVal;
		}

		public double Sum()
		{
			return Numerics().Sum();
		}

		public double Average()
		{
			return Numerics().Average();
		}

		public double Min()
		{
			return Numerics().Min();
		}

		public double Max()
		{
			return Numerics().Max();
		}

		public double Range()
		{
			List<double> source = Numerics();
			return source.Max() - source.Min();
		}

		private double Sum2(List<double> nums)
		{
			return nums.Sum((double d) => d * d);
		}

		public double VarP()
		{
			List<double> list = Numerics();
			double num = list.Average();
			double num2 = list.Sum((double d) => d * d);
			if (list.Count > 1)
			{
				return num2 / (double)list.Count - num * num;
			}
			return 0.0;
		}

		public double StdP()
		{
			List<double> list = Numerics();
			double num = list.Average();
			double num2 = list.Sum((double d) => d * d);
			if (list.Count > 1)
			{
				return Math.Sqrt(num2 / (double)list.Count - num * num);
			}
			return 0.0;
		}

		public double Var()
		{
			List<double> list = Numerics();
			double num = list.Average();
			double num2 = list.Sum((double d) => d * d);
			if (list.Count > 1)
			{
				return (num2 / (double)list.Count - num * num) * (double)list.Count / (double)(list.Count - 1);
			}
			return 0.0;
		}

		public double Std()
		{
			List<double> list = Numerics();
			double result = 0.0;
			if (list.Count > 0)
			{
				double avg = list.Average();
				double num = list.Sum((double d) => Math.Pow(d - avg, 2.0));
				result = Math.Sqrt(num / (double)(list.Count() - 1));
			}
			return result;
		}

		public IEnumerator<object> GetEnumerator()
		{
			return _list.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}
	}
	internal static class Text
	{
		public static void Register(CalcEngine ce)
		{
			ce.RegisterFunction("ASC", 1, Asc);
			ce.RegisterFunction("CHAR", 1, _Char);
			ce.RegisterFunction("CLEAN", 1, Clean);
			ce.RegisterFunction("CODE", 1, Code);
			ce.RegisterFunction("CONCATENATE", 1, int.MaxValue, Concat);
			ce.RegisterFunction("DOLLAR", 1, 2, Dollar);
			ce.RegisterFunction("EXACT", 2, Exact);
			ce.RegisterFunction("FIND", 2, 3, Find);
			ce.RegisterFunction("FIXED", 1, 3, Fixed);
			ce.RegisterFunction("LEFT", 1, 2, Left);
			ce.RegisterFunction("LEN", 1, Len);
			ce.RegisterFunction("LOWER", 1, Lower);
			ce.RegisterFunction("MID", 3, Mid);
			ce.RegisterFunction("PROPER", 1, Proper);
			ce.RegisterFunction("REPLACE", 4, Replace);
			ce.RegisterFunction("REPT", 2, Rept);
			ce.RegisterFunction("RIGHT", 1, 2, Right);
			ce.RegisterFunction("SEARCH", 2, Search);
			ce.RegisterFunction("SUBSTITUTE", 3, 4, Substitute);
			ce.RegisterFunction("T", 1, T);
			ce.RegisterFunction("TEXT", 2, _Text);
			ce.RegisterFunction("TRIM", 1, Trim);
			ce.RegisterFunction("UPPER", 1, Upper);
			ce.RegisterFunction("VALUE", 1, Value);
			ce.RegisterFunction("HYPERLINK", 1, Hyperlink);
		}

		private static object _Char(List<Expression> p)
		{
			return ((char)(int)(double)p[0]).ToString();
		}

		private static object Code(List<Expression> p)
		{
			string text = p[0];
			return (int)text[0];
		}

		private static object Concat(List<Expression> p)
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (Expression item in p)
			{
				stringBuilder.Append((string)item);
			}
			return stringBuilder.ToString();
		}

		private static object Find(List<Expression> p)
		{
			return IndexOf(p, StringComparison.Ordinal);
		}

		private static int IndexOf(List<Expression> p, StringComparison cmp)
		{
			string value = p[0];
			string text = p[1];
			int startIndex = 0;
			if (p.Count > 2)
			{
				startIndex = (int)(double)p[2] - 1;
			}
			int num = text.IndexOf(value, startIndex, cmp);
			if (num <= -1)
			{
				return num;
			}
			return num + 1;
		}

		private static object Left(List<Expression> p)
		{
			int length = 1;
			if (p.Count > 1)
			{
				length = (int)(double)p[1];
			}
			return ((string)p[0]).Substring(0, length);
		}

		private static object Len(List<Expression> p)
		{
			return ((string)p[0]).Length;
		}

		private static object Lower(List<Expression> p)
		{
			return ((string)p[0]).ToLower();
		}

		private static object Mid(List<Expression> p)
		{
			return ((string)p[0]).Substring((int)(double)p[1] - 1, (int)(double)p[2]);
		}

		private static object Proper(List<Expression> p)
		{
			string text = p[0];
			return text.Substring(0, 1).ToUpper() + text.Substring(1).ToLower();
		}

		private static object Replace(List<Expression> p)
		{
			string text = p[0];
			int num = (int)(double)p[1] - 1;
			int num2 = (int)(double)p[2];
			string value = p[3];
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(text.Substring(0, num));
			stringBuilder.Append(value);
			stringBuilder.Append(text.Substring(num + num2));
			return stringBuilder.ToString();
		}

		private static object Rept(List<Expression> p)
		{
			StringBuilder stringBuilder = new StringBuilder();
			string value = p[0];
			for (int i = 0; i < (int)(double)p[1]; i++)
			{
				stringBuilder.Append(value);
			}
			return stringBuilder.ToString();
		}

		private static object Right(List<Expression> p)
		{
			int num = 1;
			if (p.Count > 1)
			{
				num = (int)(double)p[1];
			}
			string text = p[0];
			return text.Substring(text.Length - num);
		}

		private static object Search(List<Expression> p)
		{
			return IndexOf(p, StringComparison.OrdinalIgnoreCase);
		}

		private static object Substitute(List<Expression> p)
		{
			string text = p[0];
			string text2 = p[1];
			string text3 = p[2];
			if (p.Count == 3)
			{
				return text.Replace(text2, text3);
			}
			int num = (int)(double)p[3];
			if (num < 1)
			{
				throw new Exception("Invalid index in Substitute.");
			}
			int num2 = text.IndexOf(text2);
			while (num2 > -1 && num > 1)
			{
				num2 = text.IndexOf(text2, num2 + 1);
				num--;
			}
			if (num2 <= -1)
			{
				return text;
			}
			return text.Substring(0, num2) + text3 + text.Substring(num2 + text2.Length);
		}

		private static object T(List<Expression> p)
		{
			return (string)p[0];
		}

		private static object _Text(List<Expression> p)
		{
			return ((double)p[0]).ToString(p[1], CultureInfo.CurrentCulture);
		}

		private static object Trim(List<Expression> p)
		{
			return ((string)p[0]).Trim();
		}

		private static object Upper(List<Expression> p)
		{
			return ((string)p[0]).ToUpper();
		}

		private static object Value(List<Expression> p)
		{
			return double.Parse(p[0], NumberStyles.Any, CultureInfo.InvariantCulture);
		}

		private static object Asc(List<Expression> p)
		{
			return (string)p[0];
		}

		private static object Hyperlink(List<Expression> p)
		{
			string address = p[0];
			string tooltip = ((p.Count == 2) ? ((string)p[1]) : string.Empty);
			return new XLHyperlink(address, tooltip);
		}

		private static object Clean(List<Expression> p)
		{
			string source = p[0];
			StringBuilder stringBuilder = new StringBuilder();
			foreach (char item in from c in source
				let b = (byte)c
				where b >= 32
				select c)
			{
				stringBuilder.Append(item);
			}
			return stringBuilder.ToString();
		}

		private static object Dollar(List<Expression> p)
		{
			double num = p[0];
			int num2 = ((p.Count == 2) ? ((int)(double)p[1]) : 2);
			return num.ToString("C" + num2);
		}

		private static object Exact(List<Expression> p)
		{
			string text = p[0];
			string text2 = p[1];
			return text == text2;
		}

		private static object Fixed(List<Expression> p)
		{
			double num = p[0];
			int num2 = ((p.Count >= 2) ? ((int)(double)p[1]) : 2);
			bool flag = p.Count != 3 || (bool)p[2];
			string text = num.ToString("N" + num2);
			if (flag)
			{
				return text;
			}
			return text.Replace(",", string.Empty);
		}
	}
}
namespace ClosedXML.Excel.CalcEngine.Functions
{
	public static class XLMath
	{
		public static double DegreesToRadians(double degrees)
		{
			return Math.PI / 180.0 * degrees;
		}

		public static double RadiansToDegrees(double radians)
		{
			return 180.0 / Math.PI * radians;
		}

		public static double GradsToRadians(double grads)
		{
			return grads / 200.0 * Math.PI;
		}

		public static double RadiansToGrads(double radians)
		{
			return radians / Math.PI * 200.0;
		}

		public static double DegreesToGrads(double degrees)
		{
			return degrees / 9.0 * 10.0;
		}

		public static double GradsToDegrees(double grads)
		{
			return grads / 10.0 * 9.0;
		}

		public static double ASinh(double x)
		{
			return Math.Log(x + Math.Sqrt(x * x + 1.0));
		}

		public static double ACosh(double x)
		{
			return Math.Log(x + Math.Sqrt(x * x - 1.0));
		}

		public static double ATanh(double x)
		{
			return Math.Log((1.0 + x) / (1.0 - x)) / 2.0;
		}

		public static double ACoth(double x)
		{
			return ATanh(1.0 / x);
		}

		public static double ASech(double x)
		{
			return ACosh(1.0 / x);
		}

		public static double ACsch(double x)
		{
			return ASinh(1.0 / x);
		}

		public static double Sech(double x)
		{
			return 1.0 / Math.Cosh(x);
		}

		public static double Csch(double x)
		{
			return 1.0 / Math.Sinh(x);
		}

		public static double Coth(double x)
		{
			return Math.Cosh(x) / Math.Sinh(x);
		}

		public static double Combin(int n, int k)
		{
			if (k == 0)
			{
				return 1.0;
			}
			return (double)n * Combin(n - 1, k - 1) / (double)k;
		}

		public static bool IsEven(int value)
		{
			return (double)Math.Abs(value % 2) < 1E-10;
		}

		public static bool IsOdd(int value)
		{
			return (double)Math.Abs(value % 2) > 1E-10;
		}

		public static string ToRoman(int number)
		{
			if (number < 0 || number > 3999)
			{
				throw new ArgumentOutOfRangeException("insert value betwheen 1 and 3999");
			}
			if (number < 1)
			{
				return string.Empty;
			}
			if (number >= 1000)
			{
				return "M" + ToRoman(number - 1000);
			}
			if (number >= 900)
			{
				return "CM" + ToRoman(number - 900);
			}
			if (number >= 500)
			{
				return "D" + ToRoman(number - 500);
			}
			if (number >= 400)
			{
				return "CD" + ToRoman(number - 400);
			}
			if (number >= 100)
			{
				return "C" + ToRoman(number - 100);
			}
			if (number >= 90)
			{
				return "XC" + ToRoman(number - 90);
			}
			if (number >= 50)
			{
				return "L" + ToRoman(number - 50);
			}
			if (number >= 40)
			{
				return "XL" + ToRoman(number - 40);
			}
			if (number >= 10)
			{
				return "X" + ToRoman(number - 10);
			}
			if (number >= 9)
			{
				return "IX" + ToRoman(number - 9);
			}
			if (number >= 5)
			{
				return "V" + ToRoman(number - 5);
			}
			if (number >= 4)
			{
				return "IV" + ToRoman(number - 4);
			}
			if (number >= 1)
			{
				return "I" + ToRoman(number - 1);
			}
			throw new ArgumentOutOfRangeException("something bad happened");
		}
	}
	internal class XLMatrix
	{
		public XLMatrix L;

		public XLMatrix U;

		public int cols;

		private double detOfP = 1.0;

		public double[,] mat;

		private int[] pi;

		public int rows;

		public double this[int iRow, int iCol]
		{
			get
			{
				return mat[iRow, iCol];
			}
			set
			{
				mat[iRow, iCol] = value;
			}
		}

		public XLMatrix(int iRows, int iCols)
		{
			rows = iRows;
			cols = iCols;
			mat = new double[rows, cols];
		}

		public XLMatrix(double[,] arr)
			: this(arr.GetLength(0), arr.GetLength(1))
		{
			int length = arr.GetLength(0);
			int length2 = arr.GetLength(1);
			for (int i = 0; i < length; i++)
			{
				for (int j = 0; j < length2; j++)
				{
					mat[i, j] = arr[i, j];
				}
			}
		}

		public bool IsSquare()
		{
			return rows == cols;
		}

		public XLMatrix GetCol(int k)
		{
			XLMatrix xLMatrix = new XLMatrix(rows, 1);
			for (int i = 0; i < rows; i++)
			{
				xLMatrix[i, 0] = mat[i, k];
			}
			return xLMatrix;
		}

		public void SetCol(XLMatrix v, int k)
		{
			for (int i = 0; i < rows; i++)
			{
				mat[i, k] = v[i, 0];
			}
		}

		public void MakeLU()
		{
			if (!IsSquare())
			{
				throw new Exception("The matrix is not square!");
			}
			L = IdentityMatrix(rows, cols);
			U = Duplicate();
			pi = new int[rows];
			for (int i = 0; i < rows; i++)
			{
				pi[i] = i;
			}
			int num = 0;
			for (int j = 0; j < cols - 1; j++)
			{
				double num2 = 0.0;
				for (int k = j; k < rows; k++)
				{
					if (Math.Abs(U[k, j]) > num2)
					{
						num2 = Math.Abs(U[k, j]);
						num = k;
					}
				}
				if (num2 == 0.0)
				{
					throw new Exception("The matrix is singular!");
				}
				int num3 = pi[j];
				pi[j] = pi[num];
				pi[num] = num3;
				for (int l = 0; l < j; l++)
				{
					double value = L[j, l];
					L[j, l] = L[num, l];
					L[num, l] = value;
				}
				if (j != num)
				{
					detOfP *= -1.0;
				}
				for (int m = 0; m < cols; m++)
				{
					double value = U[j, m];
					U[j, m] = U[num, m];
					U[num, m] = value;
				}
				for (int n = j + 1; n < rows; n++)
				{
					L[n, j] = U[n, j] / U[j, j];
					for (int num4 = j; num4 < cols; num4++)
					{
						U[n, num4] -= L[n, j] * U[j, num4];
					}
				}
			}
		}

		public XLMatrix SolveWith(XLMatrix v)
		{
			if (rows != cols)
			{
				throw new Exception("The matrix is not square!");
			}
			if (rows != v.rows)
			{
				throw new Exception("Wrong number of results in solution vector!");
			}
			if (L == null)
			{
				MakeLU();
			}
			XLMatrix xLMatrix = new XLMatrix(rows, 1);
			for (int i = 0; i < rows; i++)
			{
				xLMatrix[i, 0] = v[pi[i], 0];
			}
			XLMatrix b = SubsForth(L, xLMatrix);
			return SubsBack(U, b);
		}

		public XLMatrix Invert()
		{
			if (L == null)
			{
				MakeLU();
			}
			XLMatrix xLMatrix = new XLMatrix(rows, cols);
			for (int i = 0; i < rows; i++)
			{
				XLMatrix xLMatrix2 = ZeroMatrix(rows, 1);
				xLMatrix2[i, 0] = 1.0;
				XLMatrix v = SolveWith(xLMatrix2);
				xLMatrix.SetCol(v, i);
			}
			return xLMatrix;
		}

		public double Determinant()
		{
			if (L == null)
			{
				MakeLU();
			}
			double num = detOfP;
			for (int i = 0; i < rows; i++)
			{
				num *= U[i, i];
			}
			return num;
		}

		public XLMatrix GetP()
		{
			if (L == null)
			{
				MakeLU();
			}
			XLMatrix xLMatrix = ZeroMatrix(rows, cols);
			for (int i = 0; i < rows; i++)
			{
				xLMatrix[pi[i], i] = 1.0;
			}
			return xLMatrix;
		}

		public XLMatrix Duplicate()
		{
			XLMatrix xLMatrix = new XLMatrix(rows, cols);
			for (int i = 0; i < rows; i++)
			{
				for (int j = 0; j < cols; j++)
				{
					xLMatrix[i, j] = mat[i, j];
				}
			}
			return xLMatrix;
		}

		public static XLMatrix SubsForth(XLMatrix A, XLMatrix b)
		{
			if (A.L == null)
			{
				A.MakeLU();
			}
			int num = A.rows;
			XLMatrix xLMatrix = new XLMatrix(num, 1);
			for (int i = 0; i < num; i++)
			{
				xLMatrix[i, 0] = b[i, 0];
				for (int j = 0; j < i; j++)
				{
					xLMatrix[i, 0] -= A[i, j] * xLMatrix[j, 0];
				}
				xLMatrix[i, 0] /= A[i, i];
			}
			return xLMatrix;
		}

		public static XLMatrix SubsBack(XLMatrix A, XLMatrix b)
		{
			if (A.L == null)
			{
				A.MakeLU();
			}
			int num = A.rows;
			XLMatrix xLMatrix = new XLMatrix(num, 1);
			for (int num2 = num - 1; num2 > -1; num2--)
			{
				xLMatrix[num2, 0] = b[num2, 0];
				for (int num3 = num - 1; num3 > num2; num3--)
				{
					xLMatrix[num2, 0] -= A[num2, num3] * xLMatrix[num3, 0];
				}
				xLMatrix[num2, 0] /= A[num2, num2];
			}
			return xLMatrix;
		}

		public static XLMatrix ZeroMatrix(int iRows, int iCols)
		{
			XLMatrix xLMatrix = new XLMatrix(iRows, iCols);
			for (int i = 0; i < iRows; i++)
			{
				for (int j = 0; j < iCols; j++)
				{
					xLMatrix[i, j] = 0.0;
				}
			}
			return xLMatrix;
		}

		public static XLMatrix IdentityMatrix(int iRows, int iCols)
		{
			XLMatrix xLMatrix = ZeroMatrix(iRows, iCols);
			for (int i = 0; i < Math.Min(iRows, iCols); i++)
			{
				xLMatrix[i, i] = 1.0;
			}
			return xLMatrix;
		}

		public static XLMatrix RandomMatrix(int iRows, int iCols, int dispersion)
		{
			Random random = new Random();
			XLMatrix xLMatrix = new XLMatrix(iRows, iCols);
			for (int i = 0; i < iRows; i++)
			{
				for (int j = 0; j < iCols; j++)
				{
					xLMatrix[i, j] = random.Next(-dispersion, dispersion);
				}
			}
			return xLMatrix;
		}

		public static XLMatrix Parse(string ps)
		{
			string input = NormalizeMatrixString(ps);
			string[] array = Regex.Split(input, "\r\n");
			string[] array2 = array[0].Split(new char[1] { ' ' });
			XLMatrix xLMatrix = new XLMatrix(array.Length, array2.Length);
			try
			{
				for (int i = 0; i < array.Length; i++)
				{
					array2 = array[i].Split(new char[1] { ' ' });
					for (int j = 0; j < array2.Length; j++)
					{
						xLMatrix[i, j] = double.Parse(array2[j]);
					}
				}
				return xLMatrix;
			}
			catch (FormatException)
			{
				throw new Exception("Wrong input format!");
			}
		}

		public override string ToString()
		{
			string text = "";
			for (int i = 0; i < rows; i++)
			{
				for (int j = 0; j < cols; j++)
				{
					text = text + $"{mat[i, j],5:0.00}" + " ";
				}
				text += "\r\n";
			}
			return text;
		}

		public static XLMatrix Transpose(XLMatrix m)
		{
			XLMatrix xLMatrix = new XLMatrix(m.cols, m.rows);
			for (int i = 0; i < m.rows; i++)
			{
				for (int j = 0; j < m.cols; j++)
				{
					xLMatrix[j, i] = m[i, j];
				}
			}
			return xLMatrix;
		}

		public static XLMatrix Power(XLMatrix m, int pow)
		{
			if (pow == 0)
			{
				return IdentityMatrix(m.rows, m.cols);
			}
			if (pow == 1)
			{
				return m.Duplicate();
			}
			if (pow == -1)
			{
				return m.Invert();
			}
			XLMatrix xLMatrix;
			if (pow < 0)
			{
				xLMatrix = m.Invert();
				pow *= -1;
			}
			else
			{
				xLMatrix = m.Duplicate();
			}
			XLMatrix result = IdentityMatrix(m.rows, m.cols);
			while (pow != 0)
			{
				if ((pow & 1) == 1)
				{
					result *= xLMatrix;
				}
				xLMatrix *= xLMatrix;
				pow >>= 1;
			}
			return result;
		}

		private static void SafeAplusBintoC(XLMatrix A, int xa, int ya, XLMatrix B, int xb, int yb, XLMatrix C, int size)
		{
			for (int i = 0; i < size; i++)
			{
				for (int j = 0; j < size; j++)
				{
					C[i, j] = 0.0;
					if (xa + j < A.cols && ya + i < A.rows)
					{
						C[i, j] += A[ya + i, xa + j];
					}
					if (xb + j < B.cols && yb + i < B.rows)
					{
						C[i, j] += B[yb + i, xb + j];
					}
				}
			}
		}

		private static void SafeAminusBintoC(XLMatrix A, int xa, int ya, XLMatrix B, int xb, int yb, XLMatrix C, int size)
		{
			for (int i = 0; i < size; i++)
			{
				for (int j = 0; j < size; j++)
				{
					C[i, j] = 0.0;
					if (xa + j < A.cols && ya + i < A.rows)
					{
						C[i, j] += A[ya + i, xa + j];
					}
					if (xb + j < B.cols && yb + i < B.rows)
					{
						C[i, j] -= B[yb + i, xb + j];
					}
				}
			}
		}

		private static void SafeACopytoC(XLMatrix A, int xa, int ya, XLMatrix C, int size)
		{
			for (int i = 0; i < size; i++)
			{
				for (int j = 0; j < size; j++)
				{
					C[i, j] = 0.0;
					if (xa + j < A.cols && ya + i < A.rows)
					{
						C[i, j] += A[ya + i, xa + j];
					}
				}
			}
		}

		private static void AplusBintoC(XLMatrix A, int xa, int ya, XLMatrix B, int xb, int yb, XLMatrix C, int size)
		{
			for (int i = 0; i < size; i++)
			{
				for (int j = 0; j < size; j++)
				{
					C[i, j] = A[ya + i, xa + j] + B[yb + i, xb + j];
				}
			}
		}

		private static void AminusBintoC(XLMatrix A, int xa, int ya, XLMatrix B, int xb, int yb, XLMatrix C, int size)
		{
			for (int i = 0; i < size; i++)
			{
				for (int j = 0; j < size; j++)
				{
					C[i, j] = A[ya + i, xa + j] - B[yb + i, xb + j];
				}
			}
		}

		private static void ACopytoC(XLMatrix A, int xa, int ya, XLMatrix C, int size)
		{
			for (int i = 0; i < size; i++)
			{
				for (int j = 0; j < size; j++)
				{
					C[i, j] = A[ya + i, xa + j];
				}
			}
		}

		private static XLMatrix StrassenMultiply(XLMatrix A, XLMatrix B)
		{
			if (A.cols != B.rows)
			{
				throw new Exception("Wrong dimension of matrix!");
			}
			int num = Math.Max(Math.Max(A.rows, A.cols), Math.Max(B.rows, B.cols));
			XLMatrix xLMatrix;
			if (num < 32)
			{
				xLMatrix = ZeroMatrix(A.rows, B.cols);
				for (int i = 0; i < xLMatrix.rows; i++)
				{
					for (int j = 0; j < xLMatrix.cols; j++)
					{
						for (int k = 0; k < A.cols; k++)
						{
							xLMatrix[i, j] += A[i, k] * B[k, j];
						}
					}
				}
				return xLMatrix;
			}
			int num2 = 1;
			int num3 = 0;
			while (num > num2)
			{
				num2 *= 2;
				num3++;
			}
			int num4 = num2 / 2;
			XLMatrix[,] array = new XLMatrix[num3, 9];
			for (int l = 0; l < num3 - 4; l++)
			{
				int num5 = (int)Math.Pow(2.0, num3 - l - 1);
				for (int m = 0; m < 9; m++)
				{
					array[l, m] = new XLMatrix(num5, num5);
				}
			}
			SafeAplusBintoC(A, 0, 0, A, num4, num4, array[0, 0], num4);
			SafeAplusBintoC(B, 0, 0, B, num4, num4, array[0, 1], num4);
			StrassenMultiplyRun(array[0, 0], array[0, 1], array[0, 2], 1, array);
			SafeAplusBintoC(A, 0, num4, A, num4, num4, array[0, 0], num4);
			SafeACopytoC(B, 0, 0, array[0, 1], num4);
			StrassenMultiplyRun(array[0, 0], array[0, 1], array[0, 3], 1, array);
			SafeACopytoC(A, 0, 0, array[0, 0], num4);
			SafeAminusBintoC(B, num4, 0, B, num4, num4, array[0, 1], num4);
			StrassenMultiplyRun(array[0, 0], array[0, 1], array[0, 4], 1, array);
			SafeACopytoC(A, num4, num4, array[0, 0], num4);
			SafeAminusBintoC(B, 0, num4, B, 0, 0, array[0, 1], num4);
			StrassenMultiplyRun(array[0, 0], array[0, 1], array[0, 5], 1, array);
			SafeAplusBintoC(A, 0, 0, A, num4, 0, array[0, 0], num4);
			SafeACopytoC(B, num4, num4, array[0, 1], num4);
			StrassenMultiplyRun(array[0, 0], array[0, 1], array[0, 6], 1, array);
			SafeAminusBintoC(A, 0, num4, A, 0, 0, array[0, 0], num4);
			SafeAplusBintoC(B, 0, 0, B, num4, 0, array[0, 1], num4);
			StrassenMultiplyRun(array[0, 0], array[0, 1], array[0, 7], 1, array);
			SafeAminusBintoC(A, num4, 0, A, num4, num4, array[0, 0], num4);
			SafeAplusBintoC(B, 0, num4, B, num4, num4, array[0, 1], num4);
			StrassenMultiplyRun(array[0, 0], array[0, 1], array[0, 8], 1, array);
			xLMatrix = new XLMatrix(A.rows, B.cols);
			for (int n = 0; n < Math.Min(num4, xLMatrix.rows); n++)
			{
				for (int num6 = 0; num6 < Math.Min(num4, xLMatrix.cols); num6++)
				{
					xLMatrix[n, num6] = array[0, 2][n, num6] + array[0, 5][n, num6] - array[0, 6][n, num6] + array[0, 8][n, num6];
				}
			}
			for (int num7 = 0; num7 < Math.Min(num4, xLMatrix.rows); num7++)
			{
				for (int num8 = num4; num8 < Math.Min(2 * num4, xLMatrix.cols); num8++)
				{
					xLMatrix[num7, num8] = array[0, 4][num7, num8 - num4] + array[0, 6][num7, num8 - num4];
				}
			}
			for (int num9 = num4; num9 < Math.Min(2 * num4, xLMatrix.rows); num9++)
			{
				for (int num10 = 0; num10 < Math.Min(num4, xLMatrix.cols); num10++)
				{
					xLMatrix[num9, num10] = array[0, 3][num9 - num4, num10] + array[0, 5][num9 - num4, num10];
				}
			}
			for (int num11 = num4; num11 < Math.Min(2 * num4, xLMatrix.rows); num11++)
			{
				for (int num12 = num4; num12 < Math.Min(2 * num4, xLMatrix.cols); num12++)
				{
					xLMatrix[num11, num12] = array[0, 2][num11 - num4, num12 - num4] - array[0, 3][num11 - num4, num12 - num4] + array[0, 4][num11 - num4, num12 - num4] + array[0, 7][num11 - num4, num12 - num4];
				}
			}
			return xLMatrix;
		}

		private static void StrassenMultiplyRun(XLMatrix A, XLMatrix B, XLMatrix C, int l, XLMatrix[,] f)
		{
			int num = A.rows;
			int num2 = num / 2;
			if (num < 32)
			{
				for (int i = 0; i < C.rows; i++)
				{
					for (int j = 0; j < C.cols; j++)
					{
						C[i, j] = 0.0;
						for (int k = 0; k < A.cols; k++)
						{
							C[i, j] += A[i, k] * B[k, j];
						}
					}
				}
				return;
			}
			AplusBintoC(A, 0, 0, A, num2, num2, f[l, 0], num2);
			AplusBintoC(B, 0, 0, B, num2, num2, f[l, 1], num2);
			StrassenMultiplyRun(f[l, 0], f[l, 1], f[l, 2], l + 1, f);
			AplusBintoC(A, 0, num2, A, num2, num2, f[l, 0], num2);
			ACopytoC(B, 0, 0, f[l, 1], num2);
			StrassenMultiplyRun(f[l, 0], f[l, 1], f[l, 3], l + 1, f);
			ACopytoC(A, 0, 0, f[l, 0], num2);
			AminusBintoC(B, num2, 0, B, num2, num2, f[l, 1], num2);
			StrassenMultiplyRun(f[l, 0], f[l, 1], f[l, 4], l + 1, f);
			ACopytoC(A, num2, num2, f[l, 0], num2);
			AminusBintoC(B, 0, num2, B, 0, 0, f[l, 1], num2);
			StrassenMultiplyRun(f[l, 0], f[l, 1], f[l, 5], l + 1, f);
			AplusBintoC(A, 0, 0, A, num2, 0, f[l, 0], num2);
			ACopytoC(B, num2, num2, f[l, 1], num2);
			StrassenMultiplyRun(f[l, 0], f[l, 1], f[l, 6], l + 1, f);
			AminusBintoC(A, 0, num2, A, 0, 0, f[l, 0], num2);
			AplusBintoC(B, 0, 0, B, num2, 0, f[l, 1], num2);
			StrassenMultiplyRun(f[l, 0], f[l, 1], f[l, 7], l + 1, f);
			AminusBintoC(A, num2, 0, A, num2, num2, f[l, 0], num2);
			AplusBintoC(B, 0, num2, B, num2, num2, f[l, 1], num2);
			StrassenMultiplyRun(f[l, 0], f[l, 1], f[l, 8], l + 1, f);
			for (int m = 0; m < num2; m++)
			{
				for (int n = 0; n < num2; n++)
				{
					C[m, n] = f[l, 2][m, n] + f[l, 5][m, n] - f[l, 6][m, n] + f[l, 8][m, n];
				}
			}
			for (int num3 = 0; num3 < num2; num3++)
			{
				for (int num4 = num2; num4 < num; num4++)
				{
					C[num3, num4] = f[l, 4][num3, num4 - num2] + f[l, 6][num3, num4 - num2];
				}
			}
			for (int num5 = num2; num5 < num; num5++)
			{
				for (int num6 = 0; num6 < num2; num6++)
				{
					C[num5, num6] = f[l, 3][num5 - num2, num6] + f[l, 5][num5 - num2, num6];
				}
			}
			for (int num7 = num2; num7 < num; num7++)
			{
				for (int num8 = num2; num8 < num; num8++)
				{
					C[num7, num8] = f[l, 2][num7 - num2, num8 - num2] - f[l, 3][num7 - num2, num8 - num2] + f[l, 4][num7 - num2, num8 - num2] + f[l, 7][num7 - num2, num8 - num2];
				}
			}
		}

		public static XLMatrix StupidMultiply(XLMatrix m1, XLMatrix m2)
		{
			if (m1.cols != m2.rows)
			{
				throw new Exception("Wrong dimensions of matrix!");
			}
			XLMatrix xLMatrix = ZeroMatrix(m1.rows, m2.cols);
			for (int i = 0; i < xLMatrix.rows; i++)
			{
				for (int j = 0; j < xLMatrix.cols; j++)
				{
					for (int k = 0; k < m1.cols; k++)
					{
						xLMatrix[i, j] += m1[i, k] * m2[k, j];
					}
				}
			}
			return xLMatrix;
		}

		private static XLMatrix Multiply(double n, XLMatrix m)
		{
			XLMatrix xLMatrix = new XLMatrix(m.rows, m.cols);
			for (int i = 0; i < m.rows; i++)
			{
				for (int j = 0; j < m.cols; j++)
				{
					xLMatrix[i, j] = m[i, j] * n;
				}
			}
			return xLMatrix;
		}

		private static XLMatrix Add(XLMatrix m1, XLMatrix m2)
		{
			if (m1.rows != m2.rows || m1.cols != m2.cols)
			{
				throw new Exception("Matrices must have the same dimensions!");
			}
			XLMatrix xLMatrix = new XLMatrix(m1.rows, m1.cols);
			for (int i = 0; i < xLMatrix.rows; i++)
			{
				for (int j = 0; j < xLMatrix.cols; j++)
				{
					xLMatrix[i, j] = m1[i, j] + m2[i, j];
				}
			}
			return xLMatrix;
		}

		public static string NormalizeMatrixString(string matStr)
		{
			while (matStr.IndexOf("  ") != -1)
			{
				matStr = matStr.Replace("  ", " ");
			}
			matStr = matStr.Replace(" \r\n", "\r\n");
			matStr = matStr.Replace("\r\n ", "\r\n");
			matStr = matStr.Replace("\r\n", "|");
			while (matStr.LastIndexOf("|") == matStr.Length - 1)
			{
				matStr = matStr.Substring(0, matStr.Length - 1);
			}
			matStr = matStr.Replace("|", "\r\n");
			return matStr;
		}

		public static XLMatrix operator -(XLMatrix m)
		{
			return Multiply(-1.0, m);
		}

		public static XLMatrix operator +(XLMatrix m1, XLMatrix m2)
		{
			return Add(m1, m2);
		}

		public static XLMatrix operator -(XLMatrix m1, XLMatrix m2)
		{
			return Add(m1, -m2);
		}

		public static XLMatrix operator *(XLMatrix m1, XLMatrix m2)
		{
			return StrassenMultiply(m1, m2);
		}

		public static XLMatrix operator *(double n, XLMatrix m)
		{
			return Multiply(n, m);
		}
	}
}
