	internal class XLCalcEngine : CalcEngine
	{
		private readonly IXLWorksheet _ws;

		private readonly XLWorkbook _wb;

		public XLCalcEngine()
		{
		}

		public XLCalcEngine(XLWorkbook wb)
		{
			_wb = wb;
			base.IdentifierChars = "$:!";
		}

		public XLCalcEngine(IXLWorksheet ws)
			: this(ws.Workbook)
		{
			_ws = ws;
		}

		public override object GetExternalObject(string identifier)
		{
			if (identifier.Contains("!") && _wb != null)
			{
				string name = identifier.Substring(0, identifier.IndexOf("!"));
				return new CellRangeReference(_wb.Worksheet(name).Range(identifier.Substring(identifier.IndexOf("!") + 1)), this);
			}
			if (_ws != null)
			{
				return new CellRangeReference(_ws.Range(identifier), this);
			}
			return identifier;
		}
	}
	internal class CellRangeReference : IValueObject, IEnumerable
	{
		private IXLRange _range;

		private XLCalcEngine _ce;

		private bool _evaluating;

		public IXLRange Range => _range;

		public CellRangeReference(IXLRange range, XLCalcEngine ce)
		{
			_range = range;
			_ce = ce;
		}

		public object GetValue()
		{
			return GetValue(_range.FirstCell());
		}

		public IEnumerator GetEnumerator()
		{
			return _range.Cells().Select(GetValue).GetEnumerator();
		}

		private object GetValue(IXLCell cell)
		{
			if (_evaluating)
			{
				throw new Exception("Circular Reference");
			}
			try
			{
				_evaluating = true;
				string formulaA = cell.FormulaA1;
				if (XLHelper.IsNullOrWhiteSpace(formulaA))
				{
					return cell.Value;
				}
				return new XLCalcEngine(cell.Worksheet).Evaluate(formulaA);
			}
			finally
			{
				_evaluating = false;
			}
		}
	}
}
