				this.ForEach(delegate(XLCell c)
				{
					retVal.Add(c.AsRange());
				});
				return retVal;
			}
		}

		public XLCells(bool usedCellsOnly, bool includeFormats, Func<IXLCell, bool> predicate = null)
		{
			_style = new XLStyle(this, XLWorkbook.DefaultStyle);
			_usedCellsOnly = usedCellsOnly;
			_includeFormats = includeFormats;
			_predicate = predicate;
		}

		public IEnumerator<XLCell> GetEnumerator()
		{
			Dictionary<XLWorksheet, HashSet<XLSheetPoint>> cellsInRanges = new Dictionary<XLWorksheet, HashSet<XLSheetPoint>>();
			bool oneRange = _rangeAddresses.Count == 1;
			foreach (XLRangeAddress range in _rangeAddresses)
			{
				HashSet<XLSheetPoint> hash;
				if (cellsInRanges.ContainsKey(range.Worksheet))
				{
					hash = cellsInRanges[range.Worksheet];
				}
				else
				{
					hash = new HashSet<XLSheetPoint>();
					cellsInRanges.Add(range.Worksheet, hash);
				}
				if (_usedCellsOnly)
				{
					if (oneRange)
					{
						IEnumerable<XLCell> cellRange2 = from c in range.Worksheet.Internals.CellsCollection.GetCells(range.FirstAddress.RowNumber, range.FirstAddress.ColumnNumber, range.LastAddress.RowNumber, range.LastAddress.ColumnNumber)
							where !c.IsEmpty(_includeFormats) && (_predicate == null || _predicate(c))
							select c;
						foreach (XLCell item2 in cellRange2)
						{
							yield return item2;
						}
						continue;
					}
					XLRangeAddress xLRangeAddress = range;
					IEnumerable<XLSheetPoint> sheetPoints = range.Worksheet.Internals.CellsCollection.GetSheetPoints(xLRangeAddress.FirstAddress.RowNumber, xLRangeAddress.FirstAddress.ColumnNumber, xLRangeAddress.LastAddress.RowNumber, xLRangeAddress.LastAddress.ColumnNumber);
					foreach (XLSheetPoint item3 in sheetPoints.Where((XLSheetPoint a) => !hash.Contains(a)))
					{
						hash.Add(item3);
					}
					continue;
				}
				MinMax mm = new MinMax
				{
					MinRow = range.FirstAddress.RowNumber,
					MaxRow = range.LastAddress.RowNumber,
					MinColumn = range.FirstAddress.ColumnNumber,
					MaxColumn = range.LastAddress.ColumnNumber
				};
				if (mm.MaxRow <= 0 || mm.MaxColumn <= 0)
				{
					continue;
				}
				for (int ro = mm.MinRow; ro <= mm.MaxRow; ro++)
				{
					for (int co = mm.MinColumn; co <= mm.MaxColumn; co++)
					{
						if (oneRange)
						{
							XLCell c3 = range.Worksheet.Cell(ro, co);
							if (_predicate == null || _predicate(c3))
							{
								yield return c3;
							}
						}
						else
						{
							XLSheetPoint item = new XLSheetPoint(ro, co);
							if (!hash.Contains(item))
							{
								hash.Add(item);
							}
						}
					}
				}
			}
			if (oneRange)
			{
				yield break;
			}
			if (_usedCellsOnly)
			{
				IEnumerable<XLCell> cellRange = cellsInRanges.SelectMany((KeyValuePair<XLWorksheet, HashSet<XLSheetPoint>> cir) => from a in cir.Value
					select cir.Key.Internals.CellsCollection.GetCell(a) into cell
					where cell != null && !cell.IsEmpty(_includeFormats) && (_predicate == null || _predicate(cell))
					select cell);
				{
					foreach (XLCell item4 in cellRange)
					{
						yield return item4;
					}
					yield break;
				}
			}
			foreach (KeyValuePair<XLWorksheet, HashSet<XLSheetPoint>> cir2 in cellsInRanges)
			{
				KeyValuePair<XLWorksheet, HashSet<XLSheetPoint>> keyValuePair = cir2;
				foreach (XLSheetPoint a2 in keyValuePair.Value)
				{
					KeyValuePair<XLWorksheet, HashSet<XLSheetPoint>> keyValuePair2 = cir2;
					XLCell c2 = keyValuePair2.Key.Cell(a2.Row, a2.Column);
					if (_predicate == null || _predicate(c2))
					{
						yield return c2;
					}
				}
			}
		}

		IEnumerator<IXLCell> IEnumerable<IXLCell>.GetEnumerator()
		{
			using IEnumerator<XLCell> enumerator = GetEnumerator();
			while (enumerator.MoveNext())
			{
				yield return enumerator.Current;
			}
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public IXLCells SetDataType(XLCellValues dataType)
		{
			this.ForEach(delegate(XLCell c)
			{
