			});
			return this;
		}

		public IXLCells Clear(XLClearOptions clearOptions = XLClearOptions.ContentsAndFormats)
		{
			this.ForEach(delegate(XLCell c)
			{
				c.Clear(clearOptions);
			});
			return this;
		}

		public void DeleteComments()
		{
			this.ForEach(delegate(XLCell c)
			{
				c.DeleteComment();
			});
		}

		public void Add(XLRangeAddress rangeAddress)
		{
			_rangeAddresses.Add(rangeAddress);
		}

		public void Add(XLCell cell)
		{
			_rangeAddresses.Add(new XLRangeAddress(cell.Address, cell.Address));
		}

		public void Select()
		{
			using IEnumerator<XLCell> enumerator = GetEnumerator();
			while (enumerator.MoveNext())
			{
				XLCell current = enumerator.Current;
				current.Select();
			}
		}
	}
	internal class XLCellsCollection
	{
		private readonly Dictionary<XLSheetPoint, XLCell> _cellsDictionary = new Dictionary<XLSheetPoint, XLCell>();

		public Dictionary<int, int> ColumnsUsed = new Dictionary<int, int>();

		public HashSet<XLSheetPoint> Deleted = new HashSet<XLSheetPoint>();

		public int MaxColumnUsed;

		public int MaxRowUsed;

		public Dictionary<int, int> RowsUsed = new Dictionary<int, int>();

		public int Count { get; private set; }

		public XLCellsCollection()
		{
			Clear();
		}

		public void Add(XLSheetPoint sheetPoint, XLCell cell)
		{
			Add(sheetPoint.Row, sheetPoint.Column, cell);
		}

		public void Add(int row, int column, XLCell cell)
		{
			Count++;
			IncrementUsage(RowsUsed, row);
			IncrementUsage(ColumnsUsed, column);
			_cellsDictionary.Add(new XLSheetPoint(row, column), cell);
			if (row > MaxRowUsed)
			{
				MaxRowUsed = row;
			}
			if (column > MaxColumnUsed)
			{
				MaxColumnUsed = column;
			}
			XLSheetPoint item = new XLSheetPoint(row, column);
			if (Deleted.Contains(item))
			{
				Deleted.Remove(item);
			}
		}

		private static void IncrementUsage(Dictionary<int, int> dictionary, int key)
		{
			if (dictionary.ContainsKey(key))
			{
				dictionary[key]++;
			}
			else
			{
				dictionary.Add(key, 1);
			}
		}

		private static void DecrementUsage(Dictionary<int, int> dictionary, int key)
		{
			if (dictionary.TryGetValue(key, out var value))
			{
				if (value > 0)
				{
					dictionary[key]--;
				}
				else
				{
					dictionary.Remove(key);
				}
			}
		}

		public void Clear()
		{
			Count = 0;
			RowsUsed.Clear();
			ColumnsUsed.Clear();
			_cellsDictionary.Clear();
			MaxRowUsed = 0;
			MaxColumnUsed = 0;
		}

		public void Remove(XLSheetPoint sheetPoint)
		{
			Remove(sheetPoint.Row, sheetPoint.Column);
		}

		public void Remove(int row, int column)
		{
			Count--;
			DecrementUsage(RowsUsed, row);
			DecrementUsage(ColumnsUsed, row);
			XLSheetPoint xLSheetPoint = new XLSheetPoint(row, column);
			Deleted.Add(xLSheetPoint);
			_cellsDictionary.Remove(xLSheetPoint);
		}

		internal IEnumerable<XLCell> GetCells(int rowStart, int columnStart, int rowEnd, int columnEnd, Func<IXLCell, bool> predicate = null)
		{
			int finalRow = ((rowEnd > MaxRowUsed) ? MaxRowUsed : rowEnd);
			int finalColumn = ((columnEnd > MaxColumnUsed) ? MaxColumnUsed : columnEnd);
			for (int ro = rowStart; ro <= finalRow; ro++)
			{
				for (int co = columnStart; co <= finalColumn; co++)
				{
					if (_cellsDictionary.TryGetValue(new XLSheetPoint(ro, co), out var cell) && (predicate == null || predicate(cell)))
					{
						yield return cell;
					}
				}
			}
		}

		internal IEnumerable<XLCell> GetCellsUsed(int rowStart, int columnStart, int rowEnd, int columnEnd, bool includeFormats, Func<IXLCell, bool> predicate = null)
		{
			int finalRow = ((rowEnd > MaxRowUsed) ? MaxRowUsed : rowEnd);
			int finalColumn = ((columnEnd > MaxColumnUsed) ? MaxColumnUsed : columnEnd);
			for (int ro = rowStart; ro <= finalRow; ro++)
			{
				for (int co = columnStart; co <= finalColumn; co++)
				{
					if (_cellsDictionary.TryGetValue(new XLSheetPoint(ro, co), out var cell) && !cell.IsEmpty(includeFormats) && (predicate == null || predicate(cell)))
					{
						yield return cell;
					}
				}
			}
		}

		public XLSheetPoint FirstPointUsed(int rowStart, int columnStart, int rowEnd, int columnEnd, bool includeFormats = false, Func<IXLCell, bool> predicate = null)
		{
			int rowEnd2 = ((rowEnd > MaxRowUsed) ? MaxRowUsed : rowEnd);
			int columnEnd2 = ((columnEnd > MaxColumnUsed) ? MaxColumnUsed : columnEnd);
			int num = FirstRowUsed(rowStart, columnStart, rowEnd2, columnEnd2, includeFormats, predicate);
			if (num == 0)
			{
				return new XLSheetPoint(0, 0);
			}
			int num2 = FirstColumnUsed(rowStart, columnStart, rowEnd2, columnEnd2, includeFormats, predicate);
			if (num2 == 0)
			{
				return new XLSheetPoint(0, 0);
			}
			return new XLSheetPoint(num, num2);
		}

		public XLSheetPoint LastPointUsed(int rowStart, int columnStart, int rowEnd, int columnEnd, bool includeFormats = false, Func<IXLCell, bool> predicate = null)
		{
			int rowEnd2 = ((rowEnd > MaxRowUsed) ? MaxRowUsed : rowEnd);
			int columnEnd2 = ((columnEnd > MaxColumnUsed) ? MaxColumnUsed : columnEnd);
			int num = LastRowUsed(rowStart, columnStart, rowEnd2, columnEnd2, includeFormats, predicate);
			if (num == 0)
			{
				return new XLSheetPoint(0, 0);
			}
			int num2 = LastColumnUsed(rowStart, columnStart, rowEnd2, columnEnd2, includeFormats, predicate);
			if (num2 == 0)
			{
				return new XLSheetPoint(0, 0);
			}
			return new XLSheetPoint(num, num2);
		}

		public int FirstRowUsed(int rowStart, int columnStart, int rowEnd, int columnEnd, bool includeFormats, Func<IXLCell, bool> predicate = null)
		{
			int num = ((rowEnd > MaxRowUsed) ? MaxRowUsed : rowEnd);
			int num2 = ((columnEnd > MaxColumnUsed) ? MaxColumnUsed : columnEnd);
			for (int i = rowStart; i <= num; i++)
			{
				for (int j = columnStart; j <= num2; j++)
				{
					if (_cellsDictionary.TryGetValue(new XLSheetPoint(i, j), out var value) && !value.IsEmpty(includeFormats) && (predicate == null || predicate(value)))
					{
						return i;
					}
				}
			}
			return 0;
		}

		public int FirstColumnUsed(int rowStart, int columnStart, int rowEnd, int columnEnd, bool includeFormats, Func<IXLCell, bool> predicate = null)
		{
			int num = ((rowEnd > MaxRowUsed) ? MaxRowUsed : rowEnd);
			int num2 = ((columnEnd > MaxColumnUsed) ? MaxColumnUsed : columnEnd);
			for (int i = columnStart; i <= num2; i++)
			{
				for (int j = rowStart; j <= num; j++)
				{
					if (_cellsDictionary.TryGetValue(new XLSheetPoint(j, i), out var value) && !value.IsEmpty(includeFormats) && (predicate == null || predicate(value)))
					{
						return i;
					}
				}
			}
			return 0;
		}

		public int LastRowUsed(int rowStart, int columnStart, int rowEnd, int columnEnd, bool includeFormats, Func<IXLCell, bool> predicate = null)
		{
			int num = ((rowEnd > MaxRowUsed) ? MaxRowUsed : rowEnd);
			int num2 = ((columnEnd > MaxColumnUsed) ? MaxColumnUsed : columnEnd);
			for (int num3 = num; num3 >= rowStart; num3--)
			{
				for (int num4 = num2; num4 >= columnStart; num4--)
				{
					if (_cellsDictionary.TryGetValue(new XLSheetPoint(num3, num4), out var value) && !value.IsEmpty(includeFormats) && (predicate == null || predicate(value)))
					{
						return num3;
					}
				}
			}
			return 0;
		}

		public int LastColumnUsed(int rowStart, int columnStart, int rowEnd, int columnEnd, bool includeFormats, Func<IXLCell, bool> predicate = null)
		{
			int num = ((rowEnd > MaxRowUsed) ? MaxRowUsed : rowEnd);
			int num2 = ((columnEnd > MaxColumnUsed) ? MaxColumnUsed : columnEnd);
			for (int num3 = num2; num3 >= columnStart; num3--)
			{
				for (int num4 = num; num4 >= rowStart; num4--)
				{
					if (_cellsDictionary.TryGetValue(new XLSheetPoint(num4, num3), out var value) && !value.IsEmpty(includeFormats) && (predicate == null || predicate(value)))
					{
						return num3;
					}
				}
			}
			return 0;
		}

		public void RemoveAll(int rowStart, int columnStart, int rowEnd, int columnEnd)
		{
			int num = ((rowEnd > MaxRowUsed) ? MaxRowUsed : rowEnd);
			int num2 = ((columnEnd > MaxColumnUsed) ? MaxColumnUsed : columnEnd);
			for (int i = rowStart; i <= num; i++)
			{
				for (int j = columnStart; j <= num2; j++)
				{
					XLSheetPoint xLSheetPoint = new XLSheetPoint(i, j);
					if (_cellsDictionary.ContainsKey(xLSheetPoint))
					{
						Remove(xLSheetPoint);
					}
				}
			}
		}

		public IEnumerable<XLSheetPoint> GetSheetPoints(int rowStart, int columnStart, int rowEnd, int columnEnd)
		{
			int finalRow = ((rowEnd > MaxRowUsed) ? MaxRowUsed : rowEnd);
			int finalColumn = ((columnEnd > MaxColumnUsed) ? MaxColumnUsed : columnEnd);
			for (int ro = rowStart; ro <= finalRow; ro++)
			{
				for (int co = columnStart; co <= finalColumn; co++)
				{
					XLSheetPoint sp = new XLSheetPoint(ro, co);
					if (_cellsDictionary.ContainsKey(sp))
					{
						yield return sp;
					}
				}
			}
		}

		public XLCell GetCell(int row, int column)
		{
			if (row > MaxRowUsed || column > MaxColumnUsed)
			{
				return null;
			}
			XLSheetPoint key = new XLSheetPoint(row, column);
			if (!_cellsDictionary.TryGetValue(key, out var value))
			{
				return null;
			}
			return value;
		}

		public XLCell GetCell(XLSheetPoint sheetPoint)
		{
			if (!_cellsDictionary.TryGetValue(sheetPoint, out var value))
			{
				return null;
			}
			return value;
		}

		internal void SwapRanges(XLSheetRange sheetRange1, XLSheetRange sheetRange2, XLWorksheet worksheet)
		{
			int num = sheetRange1.LastPoint.Row - sheetRange1.FirstPoint.Row + 1;
			int num2 = sheetRange1.LastPoint.Column - sheetRange1.FirstPoint.Column + 1;
			for (int i = 0; i < num; i++)
			{
				for (int j = 0; j < num2; j++)
				{
					XLSheetPoint sheetPoint = new XLSheetPoint(sheetRange1.FirstPoint.Row + i, sheetRange1.FirstPoint.Column + j);
					XLSheetPoint sheetPoint2 = new XLSheetPoint(sheetRange2.FirstPoint.Row + i, sheetRange2.FirstPoint.Column + j);
					XLCell xLCell = GetCell(sheetPoint);
					XLCell xLCell2 = GetCell(sheetPoint2);
					if (xLCell == null)
					{
						xLCell = worksheet.Cell(sheetPoint.Row, sheetPoint.Column);
					}
					if (xLCell2 == null)
					{
						xLCell2 = worksheet.Cell(sheetPoint2.Row, sheetPoint2.Column);
					}
					xLCell.Address = new XLAddress(xLCell.Worksheet, sheetPoint2.Row, sheetPoint2.Column, fixedRow: false, fixedColumn: false);
					Remove(sheetPoint);
					Add(sheetPoint, xLCell2);
					xLCell2.Address = new XLAddress(xLCell2.Worksheet, sheetPoint.Row, sheetPoint.Column, fixedRow: false, fixedColumn: false);
					Remove(sheetPoint2);
					Add(sheetPoint2, xLCell);
				}
			}
		}

		internal IEnumerable<XLCell> GetCells()
		{
			return GetCells(1, 1, MaxRowUsed, MaxColumnUsed);
		}

		internal IEnumerable<XLCell> GetCells(Func<IXLCell, bool> predicate)
		{
			for (int ro = 1; ro <= MaxRowUsed; ro++)
			{
				for (int co = 1; co <= MaxColumnUsed; co++)
				{
					if (_cellsDictionary.TryGetValue(new XLSheetPoint(ro, co), out var cell) && predicate(cell))
					{
						yield return cell;
					}
				}
			}
		}

		public bool Contains(int row, int column)
		{
			return _cellsDictionary.ContainsKey(new XLSheetPoint(row, column));
		}

		public int MinRowInColumn(int column)
		{
			for (int i = 1; i <= MaxRowUsed; i++)
			{
				if (_cellsDictionary.TryGetValue(new XLSheetPoint(i, column), out var _))
				{
					return i;
				}
			}
			return 0;
		}

		public int MaxRowInColumn(int column)
		{
			for (int num = MaxRowUsed; num >= 1; num--)
			{
				if (_cellsDictionary.TryGetValue(new XLSheetPoint(num, column), out var _))
				{
					return num;
				}
			}
			return 0;
		}

		public int MinColumnInRow(int row)
		{
			for (int i = 1; i <= MaxColumnUsed; i++)
			{
				if (_cellsDictionary.TryGetValue(new XLSheetPoint(row, i), out var _))
				{
					return i;
				}
			}
			return 0;
		}

		public int MaxColumnInRow(int row)
		{
			for (int num = MaxColumnUsed; num >= 1; num--)
			{
				if (_cellsDictionary.TryGetValue(new XLSheetPoint(row, num), out var _))
				{
					return num;
				}
			}
			return 0;
		}

		public IEnumerable<XLCell> GetCellsInColumn(int column)
		{
			return GetCells(1, column, MaxRowUsed, column);
		}

		public IEnumerable<XLCell> GetCellsInRow(int row)
		{
			return GetCells(row, 1, row, MaxColumnUsed);
		}
