	internal class XLCFCellIsConverter : IXLCFConverter
	{
		public DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule Convert(IXLConditionalFormat cf, int priority, XLWorkbook.SaveContext context)
		{
			string quoted = GetQuoted(cf.Values[1]);
			DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule conditionalFormattingRule = new DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule();
			conditionalFormattingRule.FormatId = (uint)context.DifferentialFormats[cf.Style];
			conditionalFormattingRule.Operator = cf.Operator.ToOpenXml();
			conditionalFormattingRule.Type = cf.ConditionalFormatType.ToOpenXml();
			conditionalFormattingRule.Priority = priority;
			DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule conditionalFormattingRule2 = conditionalFormattingRule;
			DocumentFormat.OpenXml.Spreadsheet.Formula formula = new DocumentFormat.OpenXml.Spreadsheet.Formula();
			if (cf.Operator == XLCFOperator.Equal || cf.Operator == XLCFOperator.NotEqual)
			{
				formula.Text = quoted;
			}
			else
			{
				formula.Text = quoted;
			}
			conditionalFormattingRule2.Append(formula);
			if (cf.Operator == XLCFOperator.Between || cf.Operator == XLCFOperator.NotBetween)
			{
				DocumentFormat.OpenXml.Spreadsheet.Formula formula2 = new DocumentFormat.OpenXml.Spreadsheet.Formula();
				formula2.Text = GetQuoted(cf.Values[2]);
				DocumentFormat.OpenXml.Spreadsheet.Formula formula3 = formula2;
				conditionalFormattingRule2.Append(formula3);
			}
			return conditionalFormattingRule2;
		}

		private string GetQuoted(XLFormula formula)
		{
			string value = formula.Value;
			if (!double.TryParse(value, out var _) && !formula.IsFormula && value[0] != '"' && !value.EndsWith("\""))
			{
				return string.Format("\"{0}\"", value.Replace("\"", "\"\""));
			}
			return value;
		}
	}
	internal class XLCFEndsWithConverter : IXLCFConverter
	{
		public DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule Convert(IXLConditionalFormat cf, int priority, XLWorkbook.SaveContext context)
		{
			string value = cf.Values[1].Value;
