	internal class XLCFColorScaleConverter : IXLCFConverter
	{
		public DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule Convert(IXLConditionalFormat cf, int priority, XLWorkbook.SaveContext context)
		{
			DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule conditionalFormattingRule = new DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule();
			conditionalFormattingRule.Type = cf.ConditionalFormatType.ToOpenXml();
			conditionalFormattingRule.Priority = priority;
			DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule conditionalFormattingRule2 = conditionalFormattingRule;
			DocumentFormat.OpenXml.Spreadsheet.ColorScale colorScale = new DocumentFormat.OpenXml.Spreadsheet.ColorScale();
			for (int i = 1; i <= cf.Values.Count; i++)
			{
				ConditionalFormatValueObject conditionalFormatValueObject = new ConditionalFormatValueObject();
				conditionalFormatValueObject.Type = cf.ContentTypes[i].ToOpenXml();
				conditionalFormatValueObject.Val = cf.Values[i].Value;
				ConditionalFormatValueObject conditionalFormatValueObject2 = conditionalFormatValueObject;
				colorScale.Append(conditionalFormatValueObject2);
			}
			for (int j = 1; j <= cf.Values.Count; j++)
			{
				DocumentFormat.OpenXml.Spreadsheet.Color color = new DocumentFormat.OpenXml.Spreadsheet.Color();
				color.Rgb = cf.Colors[j].Color.ToHex();
				DocumentFormat.OpenXml.Spreadsheet.Color color2 = color;
				colorScale.Append(color2);
			}
			conditionalFormattingRule2.Append(colorScale);
			return conditionalFormattingRule2;
		}
	}
	internal class XLCFConverters
	{
		private static readonly Dictionary<XLConditionalFormatType, IXLCFConverter> Converters;

		static XLCFConverters()
		{
			Converters = new Dictionary<XLConditionalFormatType, IXLCFConverter>();
			Converters.Add(XLConditionalFormatType.ColorScale, new XLCFColorScaleConverter());
			Converters.Add(XLConditionalFormatType.StartsWith, new XLCFStartsWithConverter());
			Converters.Add(XLConditionalFormatType.EndsWith, new XLCFEndsWithConverter());
			Converters.Add(XLConditionalFormatType.IsBlank, new XLCFIsBlankConverter());
			Converters.Add(XLConditionalFormatType.NotBlank, new XLCFNotBlankConverter());
			Converters.Add(XLConditionalFormatType.IsError, new XLCFIsErrorConverter());
			Converters.Add(XLConditionalFormatType.NotError, new XLCFNotErrorConverter());
			Converters.Add(XLConditionalFormatType.ContainsText, new XLCFContainsConverter());
			Converters.Add(XLConditionalFormatType.NotContainsText, new XLCFNotContainsConverter());
			Converters.Add(XLConditionalFormatType.CellIs, new XLCFCellIsConverter());
			Converters.Add(XLConditionalFormatType.IsUnique, new XLCFUniqueConverter());
			Converters.Add(XLConditionalFormatType.IsDuplicate, new XLCFUniqueConverter());
			Converters.Add(XLConditionalFormatType.Expression, new XLCFCellIsConverter());
			Converters.Add(XLConditionalFormatType.Top10, new XLCFTopConverter());
			Converters.Add(XLConditionalFormatType.DataBar, new XLCFDataBarConverter());
			Converters.Add(XLConditionalFormatType.IconSet, new XLCFIconSetConverter());
		}

		public static DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule Convert(IXLConditionalFormat conditionalFormat, int priority, XLWorkbook.SaveContext context)
		{
			return Converters[conditionalFormat.ConditionalFormatType].Convert(conditionalFormat, priority, context);
		}
