		public T SetVerticalFlip()
		{
			VerticalFlip = true;
			return Container;
		}

		public T SetVerticalFlip(bool verticalFlip)
		{
			VerticalFlip = verticalFlip;
			return Container;
		}

		public T SetRotation(int rotation)
		{
			Rotation = rotation;
			return Container;
		}

		public T SetOffsetX(int offsetX)
		{
			OffsetX = offsetX;
			return Container;
