	internal class XLColumns : IXLColumns, IEnumerable<IXLColumn>, IEnumerable, IDisposable, IXLStylized
	{
		private readonly List<XLColumn> _columns = new List<XLColumn>();

		private readonly XLWorksheet _worksheet;

		internal IXLStyle style;

		public bool StyleChanged { get; set; }

		public IXLStyle Style
		{
			get
			{
				return style;
			}
			set
			{
				style = new XLStyle(this, value);
				if (_worksheet != null)
				{
					_worksheet.Style = value;
					return;
				}
				foreach (XLColumn column in _columns)
				{
					column.Style = value;
				}
			}
		}

		public double Width
		{
			set
			{
				_columns.ForEach(delegate(XLColumn c)
				{
					c.Width = value;
				});
				if (_worksheet != null)
				{
					_worksheet.ColumnWidth = value;
					_worksheet.Internals.ColumnsCollection.ForEach(delegate(KeyValuePair<int, XLColumn> c)
					{
						c.Value.Width = value;
					});
				}
			}
		}

		public IEnumerable<IXLStyle> Styles
		{
			get
			{
				UpdatingStyle = true;
				yield return style;
				if (_worksheet != null)
				{
					yield return _worksheet.Style;
				}
				else
				{
					foreach (IXLStyle item in _columns.SelectMany((XLColumn col) => col.Styles))
					{
						yield return item;
					}
				}
				UpdatingStyle = false;
			}
		}

		public bool UpdatingStyle { get; set; }

		public IXLStyle InnerStyle
		{
			get
			{
				return style;
			}
			set
			{
				style = new XLStyle(this, value);
			}
		}

		public IXLRanges RangesUsed
		{
			get
			{
				XLRanges retVal = new XLRanges();
				this.ForEach(delegate(IXLColumn c)
				{
					retVal.Add(c.AsRange());
				});
				return retVal;
			}
		}

		public XLColumns(XLWorksheet worksheet)
		{
			_worksheet = worksheet;
			style = new XLStyle(this, XLWorkbook.DefaultStyle);
		}

		public IEnumerator<IXLColumn> GetEnumerator()
		{
			return (from IXLColumn r in _columns
				orderby r.ColumnNumber()
				select r).GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public void Delete()
		{
			if (_worksheet != null)
			{
				_worksheet.Internals.ColumnsCollection.Clear();
				_worksheet.Internals.CellsCollection.Clear();
				return;
			}
			Dictionary<IXLWorksheet, List<int>> dictionary = new Dictionary<IXLWorksheet, List<int>>();
			foreach (XLColumn column in _columns)
			{
				if (!dictionary.ContainsKey(column.Worksheet))
				{
					dictionary.Add(column.Worksheet, new List<int>());
				}
				dictionary[column.Worksheet].Add(column.ColumnNumber());
			}
			foreach (KeyValuePair<IXLWorksheet, List<int>> item in dictionary)
			{
				foreach (int item2 in item.Value.OrderByDescending((int c) => c))
				{
					item.Key.Column(item2).Delete();
				}
			}
		}

		public IXLColumns AdjustToContents()
		{
			_columns.ForEach(delegate(XLColumn c)
			{
				c.AdjustToContents();
			});
			return this;
