		public void Select()
		{
			using IEnumerator<IXLColumn> enumerator = GetEnumerator();
			while (enumerator.MoveNext())
			{
				IXLColumn current = enumerator.Current;
				current.Select();
			}
		}
	}
	internal class XLColumnsCollection : IDictionary<int, XLColumn>, ICollection<KeyValuePair<int, XLColumn>>, IEnumerable<KeyValuePair<int, XLColumn>>, IEnumerable, IDisposable
	{
		private readonly Dictionary<int, XLColumn> _dictionary = new Dictionary<int, XLColumn>();

		public ICollection<int> Keys => _dictionary.Keys;

		public ICollection<XLColumn> Values => _dictionary.Values;

		public XLColumn this[int key]
		{
			get
			{
				return _dictionary[key];
			}
			set
			{
				_dictionary[key] = value;
			}
		}

		public int Count => _dictionary.Count;

		public bool IsReadOnly => false;

		public void ShiftColumnsRight(int startingColumn, int columnsToShift)
		{
			foreach (int item in from k in _dictionary.Keys
				where k >= startingColumn
				orderby k descending
				select k)
			{
				XLColumn column = _dictionary[item];
				int num = item + columnsToShift;
				if (num <= 16384)
				{
					XLColumn xLColumn = new XLColumn(column);
					xLColumn.RangeAddress.FirstAddress = new XLAddress(1, num, fixedRow: false, fixedColumn: false);
					xLColumn.RangeAddress.LastAddress = new XLAddress(1048576, num, fixedRow: false, fixedColumn: false);
					XLColumn value = xLColumn;
					_dictionary.Add(num, value);
				}
				_dictionary.Remove(item);
			}
		}

		public void Add(int key, XLColumn value)
		{
			_dictionary.Add(key, value);
		}

		public bool ContainsKey(int key)
		{
			return _dictionary.ContainsKey(key);
		}

		public bool Remove(int key)
		{
			return _dictionary.Remove(key);
		}

		public bool TryGetValue(int key, out XLColumn value)
		{
			return _dictionary.TryGetValue(key, out value);
		}

		public void Add(KeyValuePair<int, XLColumn> item)
		{
			_dictionary.Add(item.Key, item.Value);
		}

		public void Clear()
		{
			_dictionary.Clear();
		}

		public bool Contains(KeyValuePair<int, XLColumn> item)
		{
			return _dictionary.Contains(item);
		}

		public void CopyTo(KeyValuePair<int, XLColumn>[] array, int arrayIndex)
		{
			throw new NotImplementedException();
		}

		public bool Remove(KeyValuePair<int, XLColumn> item)
		{
			return _dictionary.Remove(item.Key);
		}

		public IEnumerator<KeyValuePair<int, XLColumn>> GetEnumerator()
		{
			return _dictionary.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return _dictionary.GetEnumerator();
		}

		public void RemoveAll(Func<XLColumn, bool> predicate)
		{
			_dictionary.RemoveAll(predicate);
		}

		public void Dispose()
		{
			_dictionary.Values.ForEach(delegate(XLColumn c)
			{
				c.Dispose();
			});
		}
	}
	internal struct XLSheetRange : IEquatable<XLSheetRange>
	{
		public readonly XLSheetPoint FirstPoint;

		public readonly XLSheetPoint LastPoint;

		public XLSheetRange(XLSheetPoint firstPoint, XLSheetPoint lastPoint)
		{
			FirstPoint = firstPoint;
			LastPoint = lastPoint;
		}

		public bool Equals(XLSheetRange other)
		{
			if (FirstPoint.Equals(other.FirstPoint))
			{
				return LastPoint.Equals(other.LastPoint);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return FirstPoint.GetHashCode() ^ LastPoint.GetHashCode();
		}
	}
	internal struct XLSheetPoint : IEquatable<XLSheetPoint>
	{
		public readonly int Row;

		public readonly int Column;

		public XLSheetPoint(int row, int column)
		{
			Row = row;
			Column = column;
		}

		public bool Equals(XLSheetPoint other)
		{
			if (Row == other.Row)
			{
				return Column == other.Column;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return (Row * -1) ^ Column;
		}
	}
