	public class XLDictionary<T> : Dictionary<int, T>
	{
		public XLDictionary()
		{
		}

		public XLDictionary(XLDictionary<T> other)
		{
			other.Values.ForEach(Add);
		}

		public void Initialize(T value)
		{
			if (base.Count > 0)
			{
				Clear();
			}
			Add(value);
		}

		public void Add(T value)
		{
			Add(base.Count + 1, value);
		}
	}
	public class XLFormula
	{
		internal string _value;

		public string Value
		{
			get
			{
				return _value;
			}
			set
			{
				if (value == null)
				{
					_value = string.Empty;
					return;
				}
				_value = value.Trim();
				IsFormula = !XLHelper.IsNullOrWhiteSpace(_value) && _value.TrimStart(new char[0])[0] == '=';
				if (IsFormula)
				{
					_value = _value.Substring(1);
				}
			}
		}

		public bool IsFormula { get; internal set; }

		public XLFormula()
		{
		}

		public XLFormula(XLFormula defaultFormula)
		{
			_value = defaultFormula._value;
			IsFormula = defaultFormula.IsFormula;
		}
	}
	internal class XLIdManager
	{
		private HashSet<int> _hash = new HashSet<int>();

		public int GetNext()
		{
			if (_hash.Count == 0)
			{
				_hash.Add(1);
				return 1;
			}
			int i;
			for (i = 1; _hash.Contains(i); i++)
			{
			}
			_hash.Add(i);
			return i;
		}

		public void Add(int value)
		{
			_hash.Add(value);
		}

		public void Add(IEnumerable<int> values)
		{
			values.ForEach(delegate(int v)
			{
				_hash.Add(v);
			});
		}
	}
