		string Format { get; set; }
	}
	public interface IXLPivotValueFormat : IXLNumberFormatBase
	{
		IXLPivotValue SetNumberFormatId(int value);

		IXLPivotValue SetFormat(string value);
	}
	internal class XLPivotValueFormat : IXLPivotValueFormat, IXLNumberFormatBase
	{
		private readonly XLPivotValue _pivotValue;

		private int _numberFormatId = -1;

		private string _format = string.Empty;

		public int NumberFormatId
		{
			get
			{
				return _numberFormatId;
			}
			set
			{
				_numberFormatId = value;
				_format = string.Empty;
			}
		}

		public string Format
		{
			get
			{
				return _format;
			}
			set
			{
				_format = value;
				_numberFormatId = -1;
			}
		}

		public XLPivotValueFormat(XLPivotValue pivotValue)
		{
			_pivotValue = pivotValue;
			_format = "General";
			_numberFormatId = 0;
		}

		public IXLPivotValue SetNumberFormatId(int value)
		{
			NumberFormatId = value;
			return _pivotValue;
		}

		public IXLPivotValue SetFormat(string value)
		{
			Format = value;
			switch (value)
			{
			case "General":
				_numberFormatId = 0;
				break;
			case "0":
				_numberFormatId = 1;
				break;
			case "0.00":
				_numberFormatId = 2;
				break;
			case "#,##0":
				_numberFormatId = 3;
				break;
			case "#,##0.00":
				_numberFormatId = 4;
				break;
			case "0%":
				_numberFormatId = 9;
				break;
			case "0.00%":
				_numberFormatId = 10;
				break;
			case "0.00E+00":
				_numberFormatId = 11;
				break;
			}
			return _pivotValue;
		}
	}
