		public XLPhonetics(IXLFontBase defaultFont)
		{
			_defaultFont = defaultFont;
			Type = XLPhoneticType.FullWidthKatakana;
			Alignment = XLPhoneticAlignment.Left;
			this.CopyFont(_defaultFont);
		}

