		{
			return _phonetics.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public bool Equals(IXLPhonetics other)
		{
			if (other == null)
			{
				return false;
			}
			int count = _phonetics.Count;
			for (int i = 0; i < count; i++)
			{
				if (!_phonetics[i].Equals(other.ElementAt(i)))
				{
					return false;
				}
			}
			if (Bold == other.Bold && Italic == other.Italic && Underline == other.Underline && Strikethrough == other.Strikethrough && VerticalAlignment == other.VerticalAlignment && Shadow == other.Shadow && FontSize == other.FontSize && FontColor.Equals(other.FontColor) && FontName == other.FontName)
			{
				return FontFamilyNumbering == other.FontFamilyNumbering;
			}
			return false;
		}
	}
	public interface IXLPhonetic : IEquatable<IXLPhonetic>
	{
		string Text { get; set; }

		int Start { get; set; }

