	internal abstract class XLRangeBase : IXLRangeBase, IDisposable, IXLStylized
	{
		private struct DataValidationToCopy
		{
			public XLAddress SourceAddress;

			public XLDataValidation DataValidation;
		}

		private IXLStyle _style;

		private XLSortElements _sortRows;

		private XLSortElements _sortColumns;

		private int _styleCacheId;

		private static int IdCounter;

		private readonly int Id;

		private bool _subscribedToShiftedRows;

		private bool _subscribedToShiftedColumns;

		private XLRangeAddress _rangeAddress;

		private RangeShiftedRowsDelegate WorksheetRangeShiftedRows;

		private RangeShiftedColumnsDelegate WorksheetRangeShiftedColumns;

		public bool StyleChanged { get; set; }

		public XLRangeAddress RangeAddress
		{
			get
			{
				return _rangeAddress;
			}
			protected set
			{
				_rangeAddress = value;
			}
		}

		public XLWorksheet Worksheet => RangeAddress.Worksheet;

		public XLDataValidation DataValidation
		{
			get
			{
				IXLDataValidation iXLDataValidation = null;
				List<IXLDataValidation> list = new List<IXLDataValidation>();
				foreach (IXLDataValidation dataValidation in Worksheet.DataValidations)
				{
					foreach (IXLRange item in dataValidation.Ranges.Where((IXLRange dvRange) => dvRange.Intersects(this)))
					{
						if (iXLDataValidation == null)
						{
							iXLDataValidation = dataValidation;
						}
						dataValidation.Ranges.Remove(item);
						foreach (IXLRangeColumn item2 in item.Columns())
						{
							if (item2.Intersects(this))
							{
								int rowNumber = item2.RangeAddress.FirstAddress.RowNumber;
								int rowNumber2 = item2.RangeAddress.LastAddress.RowNumber;
								int rowNumber3 = RangeAddress.FirstAddress.RowNumber;
								int rowNumber4 = RangeAddress.LastAddress.RowNumber;
								if (rowNumber3 > rowNumber && rowNumber4 < rowNumber2)
								{
									IXLRangeColumn iXLRangeColumn = Worksheet.Column(item2.ColumnNumber()).Column(rowNumber, rowNumber3 - 1);
									iXLRangeColumn.Dispose();
									dataValidation.Ranges.Add(iXLRangeColumn);
									IXLRangeColumn iXLRangeColumn2 = Worksheet.Column(item2.ColumnNumber()).Column(rowNumber4 + 1, rowNumber2);
									iXLRangeColumn2.Dispose();
									dataValidation.Ranges.Add(iXLRangeColumn2);
									continue;
								}
								int num = ((rowNumber >= rowNumber3) ? (rowNumber4 + 1) : rowNumber);
								if (num <= rowNumber2)
								{
									int num2 = ((rowNumber2 <= rowNumber4) ? (rowNumber3 - 1) : rowNumber2);
									if (num2 >= rowNumber)
									{
										IXLRangeColumn iXLRangeColumn3 = Worksheet.Column(item2.ColumnNumber()).Column(num, num2);
										iXLRangeColumn3.Dispose();
										dataValidation.Ranges.Add(iXLRangeColumn3);
									}
								}
							}
							else
							{
								item2.Dispose();
								dataValidation.Ranges.Add(item2);
							}
						}
						if (!dataValidation.Ranges.Any())
						{
							list.Add(dataValidation);
						}
					}
				}
				list.ForEach(delegate(IXLDataValidation dv)
				{
					Worksheet.DataValidations.Delete(dv);
				});
				XLRanges xLRanges = new XLRanges();
				xLRanges.Add(AsRange());
				XLRanges ranges = xLRanges;
				XLDataValidation xLDataValidation = new XLDataValidation(ranges);
				if (iXLDataValidation != null)
				{
					xLDataValidation.CopyFrom(iXLDataValidation);
				}
				Worksheet.DataValidations.Add(xLDataValidation);
				return xLDataValidation;
			}
		}

		IXLRangeAddress IXLRangeBase.RangeAddress => RangeAddress;

		IXLWorksheet IXLRangeBase.Worksheet => RangeAddress.Worksheet;

		public string FormulaA1
		{
			set
			{
				Cells().ForEach(delegate(IXLCell c)
				{
					c.FormulaA1 = value;
					c.FormulaReference = RangeAddress;
				});
			}
		}

		public string FormulaR1C1
		{
			set
