				});
			}
		}

		public IXLHyperlinks Hyperlinks
		{
			get
			{
				XLHyperlinks xLHyperlinks = new XLHyperlinks();
				IEnumerable<XLHyperlink> source = Worksheet.Hyperlinks.Where((XLHyperlink hl) => Contains(hl.Cell.AsRange()));
				source.ForEach(xLHyperlinks.Add);
				return xLHyperlinks;
			}
		}

		public object Value
		{
			set
