				UpdatingStyle = true;
				foreach (IXLCell cell in Cells())
				{
					yield return cell.Style;
				}
				UpdatingStyle = false;
			}
		}

		public virtual bool UpdatingStyle { get; set; }

		public virtual IXLStyle InnerStyle
		{
