		public IXLSortElements SortRows => _sortRows ?? (_sortRows = new XLSortElements());

		public IXLSortElements SortColumns => _sortColumns ?? (_sortColumns = new XLSortElements());

		protected void SetStyle(IXLStyle styleToUse)
		{
			_styleCacheId = Worksheet.Workbook.GetStyleId(styleToUse);
			_style = null;
			StyleChanged = false;
		}

		protected void SetStyle(int styleId)
		{
			_styleCacheId = styleId;
			_style = null;
			StyleChanged = false;
		}

		public int GetStyleId()
		{
			if (StyleChanged)
			{
				SetStyle(Style);
			}
			return _styleCacheId;
		}

		protected IXLStyle GetStyle()
		{
			return _style ?? (_style = new XLStyle(this, Worksheet.Workbook.GetStyleById(_styleCacheId)));
		}

		protected XLRangeBase(XLRangeAddress rangeAddress)
		{
			Id = ++IdCounter;
			RangeAddress = new XLRangeAddress(rangeAddress);
		}

		protected void SubscribeToShiftedRows(RangeShiftedRowsDelegate worksheetRangeShiftedRows)
		{
			if (Worksheet != null && Worksheet.EventTrackingEnabled)
			{
				WorksheetRangeShiftedRows = worksheetRangeShiftedRows;
				RangeAddress.Worksheet.RangeShiftedRows += WorksheetRangeShiftedRows;
				_subscribedToShiftedRows = true;
			}
		}

		protected void SubscribeToShiftedColumns(RangeShiftedColumnsDelegate worksheetRangeShiftedColumns)
		{
			if (Worksheet != null && Worksheet.EventTrackingEnabled)
			{
				WorksheetRangeShiftedColumns = worksheetRangeShiftedColumns;
				RangeAddress.Worksheet.RangeShiftedColumns += WorksheetRangeShiftedColumns;
				_subscribedToShiftedColumns = true;
			}
		}

