		public IXLRange Merge()
		{
			return Merge(checkIntersect: true);
		}

		internal IXLRange Merge(bool checkIntersect)
		{
			if (checkIntersect)
			{
				string rangeAddress = RangeAddress.ToString();
				foreach (IXLRange mergedRange in Worksheet.Internals.MergedRanges)
				{
					if (mergedRange.Intersects(rangeAddress))
					{
						Worksheet.Internals.MergedRanges.Remove(mergedRange);
					}
				}
			}
			XLRange xLRange = AsRange();
			Worksheet.Internals.MergedRanges.Add(xLRange);
			return xLRange;
		}

		public IXLRange Unmerge()
