			string tAddress = RangeAddress.ToString();
			XLRange xLRange = AsRange();
			if (Worksheet.Internals.MergedRanges.Select((IXLRange m) => m.RangeAddress.ToString()).Any((string mAddress) => mAddress == tAddress))
			{
				Worksheet.Internals.MergedRanges.Remove(xLRange);
			}
			return xLRange;
		}

		public IXLRangeBase Clear(XLClearOptions clearOptions = XLClearOptions.ContentsAndFormats)
		{
			bool flag = clearOptions == XLClearOptions.Formats || clearOptions == XLClearOptions.ContentsAndFormats;
			foreach (XLCell item in CellsUsed(flag))
			{
				item.Clear(clearOptions);
			}
			if (flag)
			{
				ClearMerged();
			}
			if (clearOptions == XLClearOptions.ContentsAndFormats)
			{
				Worksheet.Internals.CellsCollection.RemoveAll(RangeAddress.FirstAddress.RowNumber, RangeAddress.FirstAddress.ColumnNumber, RangeAddress.LastAddress.RowNumber, RangeAddress.LastAddress.ColumnNumber);
			}
			return this;
		}

