		public bool Contains(string rangeAddress)
		{
			string text = (rangeAddress.Contains("!") ? rangeAddress.Substring(rangeAddress.IndexOf("!") + 1) : rangeAddress);
			XLAddress first;
			XLAddress last;
			if (Enumerable.Contains(text, ':'))
			{
				string[] array = text.Split(new char[1] { ':' });
				first = XLAddress.Create(Worksheet, array[0]);
				last = XLAddress.Create(Worksheet, array[1]);
			}
			else
			{
				first = XLAddress.Create(Worksheet, text);
				last = XLAddress.Create(Worksheet, text);
			}
			return Contains(first, last);
		}

