		public bool Intersects(IXLRangeBase range)
		{
			if (range.RangeAddress.IsInvalid || RangeAddress.IsInvalid)
			{
				return false;
			}
			IXLRangeAddress rangeAddress = range.RangeAddress;
			XLRangeAddress rangeAddress2 = RangeAddress;
			if (rangeAddress.FirstAddress.ColumnNumber <= rangeAddress2.LastAddress.ColumnNumber && rangeAddress.LastAddress.ColumnNumber >= rangeAddress2.FirstAddress.ColumnNumber && rangeAddress.FirstAddress.RowNumber <= rangeAddress2.LastAddress.RowNumber)
			{
				return rangeAddress.LastAddress.RowNumber >= rangeAddress2.FirstAddress.RowNumber;
			}
			return false;
		}

