		public IXLRange AddToNamed(string rangeName, XLScope scope, string comment)
		{
			IXLNamedRanges iXLNamedRanges = ((scope == XLScope.Workbook) ? Worksheet.Workbook.NamedRanges : Worksheet.NamedRanges);
			if (iXLNamedRanges.Any((IXLNamedRange nr) => string.Compare(nr.Name, rangeName, ignoreCase: true) == 0))
			{
				IXLNamedRange iXLNamedRange = iXLNamedRanges.Single((IXLNamedRange nr) => string.Compare(nr.Name, rangeName, ignoreCase: true) == 0);
				iXLNamedRange.Add(Worksheet.Workbook, RangeAddress.ToStringFixed(XLReferenceStyle.A1, includeSheet: true));
			}
			else
			{
				iXLNamedRanges.Add(rangeName, RangeAddress.ToStringFixed(XLReferenceStyle.A1, includeSheet: true), comment);
			}
			return AsRange();
		}

