		public XLCell LastCellUsed(bool includeFormats, Func<IXLCell, bool> predicate)
		{
			int fRow = RangeAddress.FirstAddress.RowNumber;
			int lRow = RangeAddress.LastAddress.RowNumber;
			int fColumn = RangeAddress.FirstAddress.ColumnNumber;
			int lColumn = RangeAddress.LastAddress.ColumnNumber;
			if (includeFormats)
			{
				IEnumerable<KeyValuePair<int, XLRow>> source = Worksheet.Internals.RowsCollection.Where((KeyValuePair<int, XLRow> r) => r.Key >= fRow && r.Key <= lRow && !r.Value.IsEmpty(includeFormats: true));
				IEnumerable<KeyValuePair<int, XLColumn>> source2 = Worksheet.Internals.ColumnsCollection.Where((KeyValuePair<int, XLColumn> c) => c.Key >= fColumn && c.Key <= lColumn && !c.Value.IsEmpty(includeFormats: true));
				int num = 0;
				if (source.Any())
				{
					num = source.Last().Key;
				}
				int num2 = 0;
				if (source2.Any())
				{
					num2 = source2.Last().Key;
				}
				if (num > 0 && num2 > 0)
				{
					return Worksheet.Cell(num, num2);
				}
				if (num > 0 && lColumn < 16384)
				{
					for (num2 = lColumn; num2 >= fColumn; num2--)
					{
						XLCell xLCell = Worksheet.Cell(num, num2);
						if (!xLCell.IsEmpty(includeFormats: true))
						{
							return xLCell;
						}
					}
				}
				else if (num2 > 0 && lRow < 1048576)
				{
					for (num = lRow; num >= fRow; num--)
					{
						XLCell xLCell2 = Worksheet.Cell(num, num2);
						if (!xLCell2.IsEmpty(includeFormats: true))
						{
							return xLCell2;
						}
					}
				}
				if (Worksheet.MergedRanges.Any((IXLRange r) => r.Intersects(this)))
				{
					int row = Worksheet.MergedRanges.Where((IXLRange r) => r.Intersects(this)).Max((IXLRange r) => r.RangeAddress.LastAddress.RowNumber);
					int column = Worksheet.MergedRanges.Where((IXLRange r) => r.Intersects(this)).Max((IXLRange r) => r.RangeAddress.LastAddress.ColumnNumber);
					return Worksheet.Cell(row, column);
				}
			}
			XLSheetPoint xLSheetPoint = Worksheet.Internals.CellsCollection.LastPointUsed(fRow, fColumn, lRow, lColumn, includeFormats, predicate);
			if (xLSheetPoint.Row > 0)
			{
				return Worksheet.Cell(xLSheetPoint.Row, xLSheetPoint.Column);
			}
			return null;
		}

