		public XLCell Cell(XLAddress cellAddressInRange)
		{
			XLAddress xLAddress = cellAddressInRange + RangeAddress.FirstAddress - 1;
			if (xLAddress.RowNumber <= 0 || xLAddress.RowNumber > 1048576)
			{
				throw new IndexOutOfRangeException($"Row number must be between 1 and {1048576}");
			}
			if (xLAddress.ColumnNumber <= 0 || xLAddress.ColumnNumber > 16384)
			{
				throw new IndexOutOfRangeException($"Column number must be between 1 and {16384}");
			}
			XLCell cell = Worksheet.Internals.CellsCollection.GetCell(xLAddress.RowNumber, xLAddress.ColumnNumber);
			if (cell != null)
			{
				return cell;
			}
			int styleId = GetStyleId();
			int styleId2 = Worksheet.GetStyleId();
			if (styleId == styleId2)
			{
				XLColumn value2;
				if (Worksheet.Internals.RowsCollection.TryGetValue(xLAddress.RowNumber, out var value) && value.GetStyleId() != styleId2)
				{
					styleId = value.GetStyleId();
				}
				else if (Worksheet.Internals.ColumnsCollection.TryGetValue(xLAddress.ColumnNumber, out value2) && value2.GetStyleId() != styleId2)
				{
					styleId = value2.GetStyleId();
				}
			}
			XLCell xLCell = new XLCell(Worksheet, xLAddress, styleId);
			Worksheet.Internals.CellsCollection.Add(xLAddress.RowNumber, xLAddress.ColumnNumber, xLCell);
			return xLCell;
		}

