		private XLRange GetRange(XLAddress newFirstCellAddress, XLAddress newLastCellAddress)
		{
			XLRangeAddress rangeAddress = new XLRangeAddress(newFirstCellAddress, newLastCellAddress);
			XLRangeParameters xlRangeParameters = new XLRangeParameters(rangeAddress, Style);
			if (newFirstCellAddress.RowNumber < RangeAddress.FirstAddress.RowNumber || newFirstCellAddress.RowNumber > RangeAddress.LastAddress.RowNumber || newLastCellAddress.RowNumber > RangeAddress.LastAddress.RowNumber || newFirstCellAddress.ColumnNumber < RangeAddress.FirstAddress.ColumnNumber || newFirstCellAddress.ColumnNumber > RangeAddress.LastAddress.ColumnNumber || newLastCellAddress.ColumnNumber > RangeAddress.LastAddress.ColumnNumber)
			{
				throw new ArgumentOutOfRangeException($"The cells {newFirstCellAddress} and {newLastCellAddress} are outside the range '{ToString()}'.");
			}
			return new XLRange(xlRangeParameters);
		}

