		public IXLRangeColumns InsertColumnsAfter(bool onlyUsedCells, int numberOfColumns, bool formatFromLeft = true)
		{
			int num = ColumnCount();
			int num2 = RangeAddress.FirstAddress.ColumnNumber + num;
			if (num2 > 16384)
			{
				num2 = 16384;
			}
			int num3 = num2 + ColumnCount() - 1;
			if (num3 > 16384)
			{
				num3 = 16384;
			}
			int rowNumber = RangeAddress.FirstAddress.RowNumber;
			int num4 = rowNumber + RowCount() - 1;
			if (num4 > 1048576)
			{
				num4 = 1048576;
			}
			XLRange xLRange = Worksheet.Range(rowNumber, num2, num4, num3);
			return xLRange.InsertColumnsBefore(onlyUsedCells, numberOfColumns, formatFromLeft);
