			if (expandRange)
			{
				RangeAddress = new XLRangeAddress(new XLAddress(Worksheet, RangeAddress.FirstAddress.RowNumber, RangeAddress.FirstAddress.ColumnNumber - numberOfColumns, RangeAddress.FirstAddress.FixedRow, RangeAddress.FirstAddress.FixedColumn), new XLAddress(Worksheet, RangeAddress.LastAddress.RowNumber, RangeAddress.LastAddress.ColumnNumber, RangeAddress.LastAddress.FixedRow, RangeAddress.LastAddress.FixedColumn));
			}
			return result;
		}

		public IXLRangeColumns InsertColumnsBefore(bool onlyUsedCells, int numberOfColumns, bool formatFromLeft = true)
		{
			foreach (XLWorksheet item in Worksheet.Workbook.WorksheetsInternal)
			{
				foreach (XLCell cell in item.Internals.CellsCollection.GetCells((IXLCell c) => !XLHelper.IsNullOrWhiteSpace(c.FormulaA1)))
				{
					using XLRange shiftedRange = AsRange();
					cell.ShiftFormulaColumns(shiftedRange, numberOfColumns);
				}
			}
			Dictionary<XLAddress, DataValidationToCopy> dictionary = new Dictionary<XLAddress, DataValidationToCopy>();
			Dictionary<IXLAddress, XLCell> cellsToInsert = new Dictionary<IXLAddress, XLCell>();
			List<IXLAddress> list = new List<IXLAddress>();
			int columnNumber = RangeAddress.FirstAddress.ColumnNumber;
			int rowNumber = RangeAddress.FirstAddress.RowNumber;
			int num = RangeAddress.FirstAddress.RowNumber + RowCount() - 1;
			if (!onlyUsedCells)
			{
				int maxColumnUsed = Worksheet.Internals.CellsCollection.MaxColumnUsed;
				if (maxColumnUsed > 0)
				{
					for (int num2 = maxColumnUsed; num2 >= columnNumber; num2--)
					{
						for (int num3 = num; num3 >= rowNumber; num3--)
						{
							XLAddress xLAddress = new XLAddress(Worksheet, num3, num2, fixedRow: false, fixedColumn: false);
							int columnNumber2 = num2 + numberOfColumns;
							XLAddress xLAddress2 = new XLAddress(Worksheet, num3, columnNumber2, fixedRow: false, fixedColumn: false);
							XLCell xLCell = Worksheet.Internals.CellsCollection.GetCell(num3, num2) ?? Worksheet.Cell(xLAddress);
							XLCell xLCell2 = new XLCell(Worksheet, xLAddress2, xLCell.GetStyleId());
							xLCell2.CopyValues(xLCell);
							xLCell2.FormulaA1 = xLCell.FormulaA1;
							cellsToInsert.Add(xLAddress2, xLCell2);
							list.Add(xLAddress);
						}
					}
				}
			}
			else
			{
				foreach (XLCell cell2 in Worksheet.Internals.CellsCollection.GetCells(rowNumber, columnNumber, num, Worksheet.Internals.CellsCollection.MaxColumnUsed))
				{
					int columnNumber3 = cell2.Address.ColumnNumber + numberOfColumns;
					XLAddress xLAddress3 = new XLAddress(Worksheet, cell2.Address.RowNumber, columnNumber3, fixedRow: false, fixedColumn: false);
					XLCell xLCell3 = new XLCell(Worksheet, xLAddress3, cell2.GetStyleId());
					xLCell3.CopyValues(cell2);
					if (cell2.HasDataValidation)
					{
						dictionary.Add(xLCell3.Address, new DataValidationToCopy
						{
							DataValidation = cell2.DataValidation,
							SourceAddress = cell2.Address
						});
						cell2.DataValidation.Clear();
					}
					xLCell3.FormulaA1 = cell2.FormulaA1;
					cellsToInsert.Add(xLAddress3, xLCell3);
					list.Add(cell2.Address);
				}
			}
			dictionary.ForEach(delegate(KeyValuePair<XLAddress, DataValidationToCopy> kp)
			{
				if (!cellsToInsert.TryGetValue(kp.Key, out var value))
				{
					value = Worksheet.Cell(kp.Key);
				}
				value.CopyDataValidation(Worksheet.Cell(kp.Value.SourceAddress), kp.Value.DataValidation);
			});
			list.ForEach(delegate(IXLAddress c)
			{
				Worksheet.Internals.CellsCollection.Remove(c.RowNumber, c.ColumnNumber);
			});
			cellsToInsert.ForEach(delegate(KeyValuePair<IXLAddress, XLCell> c)
			{
				Worksheet.Internals.CellsCollection.Add(c.Key.RowNumber, c.Key.ColumnNumber, c.Value);
			});
			int rowNumber2 = RangeAddress.FirstAddress.RowNumber;
			int rowNumber3 = RangeAddress.LastAddress.RowNumber;
			int columnNumber4 = RangeAddress.FirstAddress.ColumnNumber;
			int lastCellColumn = RangeAddress.FirstAddress.ColumnNumber + numberOfColumns - 1;
			Worksheet.BreakConditionalFormatsIntoCells(list.Except(cellsToInsert.Keys).ToList());
			using (XLRange range = AsRange())
			{
				Worksheet.NotifyRangeShiftedColumns(range, numberOfColumns);
			}
			XLRange xLRange = Worksheet.Range(rowNumber2, columnNumber4, rowNumber3, lastCellColumn);
			if (formatFromLeft && xLRange.RangeAddress.FirstAddress.ColumnNumber > 1)
			{
				using XLRangeColumn xLRangeColumn = xLRange.FirstColumn();
				using XLRangeColumn xLRangeColumn2 = xLRangeColumn.ColumnLeft();
				XLCell xLCell4 = xLRangeColumn2.FirstCellUsed(includeFormats: true);
				XLCell xLCell5 = xLRangeColumn2.LastCellUsed(includeFormats: true);
				if (xLCell5 != null)
				{
					int num4 = xLCell4.Address.RowNumber - xLRangeColumn2.RangeAddress.FirstAddress.RowNumber + 1;
					int num5 = xLCell5.Address.RowNumber - xLRangeColumn2.RangeAddress.FirstAddress.RowNumber + 1;
					for (int i = num4; i <= num5; i++)
					{
						xLRange.Row(i).Style = xLRangeColumn2.Cell(i).Style;
					}
				}
			}
			else
			{
				XLRangeRow xLRangeRow = xLRange.LastRowUsed(includeFormats: true);
				if (xLRangeRow != null)
				{
					int num6 = xLRangeRow.RowNumber();
					for (int j = 1; j <= num6; j++)
					{
						IXLStyle style = (Worksheet.Internals.RowsCollection.ContainsKey(j) ? Worksheet.Internals.RowsCollection[j].Style : Worksheet.Style);
						xLRange.Row(j).Style = style;
					}
				}
			}
			return xLRange.Columns();
		}

