		public IXLRangeRows InsertRowsAbove(bool onlyUsedCells, int numberOfRows, bool formatFromAbove = true)
		{
			using (XLRange shiftedRange = AsRange())
			{
				foreach (XLWorksheet item in Worksheet.Workbook.WorksheetsInternal)
				{
					foreach (XLCell cell in item.Internals.CellsCollection.GetCells((IXLCell c) => !XLHelper.IsNullOrWhiteSpace(c.FormulaA1)))
					{
						cell.ShiftFormulaRows(shiftedRange, numberOfRows);
					}
				}
			}
			Dictionary<IXLAddress, XLCell> cellsToInsert = new Dictionary<IXLAddress, XLCell>();
			List<IXLAddress> list = new List<IXLAddress>();
			Dictionary<XLAddress, DataValidationToCopy> dictionary = new Dictionary<XLAddress, DataValidationToCopy>();
			int rowNumber = RangeAddress.FirstAddress.RowNumber;
			int columnNumber = RangeAddress.FirstAddress.ColumnNumber;
			int num = RangeAddress.FirstAddress.ColumnNumber + ColumnCount() - 1;
			if (!onlyUsedCells)
			{
				int maxRowUsed = Worksheet.Internals.CellsCollection.MaxRowUsed;
				if (maxRowUsed > 0)
				{
					for (int num2 = maxRowUsed; num2 >= rowNumber; num2--)
					{
						for (int num3 = num; num3 >= columnNumber; num3--)
						{
							XLAddress xLAddress = new XLAddress(Worksheet, num2, num3, fixedRow: false, fixedColumn: false);
							int rowNumber2 = num2 + numberOfRows;
							XLAddress xLAddress2 = new XLAddress(Worksheet, rowNumber2, num3, fixedRow: false, fixedColumn: false);
							XLCell xLCell = Worksheet.Internals.CellsCollection.GetCell(num2, num3) ?? Worksheet.Cell(xLAddress);
							XLCell xLCell2 = new XLCell(Worksheet, xLAddress2, xLCell.GetStyleId());
							xLCell2.CopyValues(xLCell);
							xLCell2.FormulaA1 = xLCell.FormulaA1;
							cellsToInsert.Add(xLAddress2, xLCell2);
							list.Add(xLAddress);
						}
					}
				}
			}
			else
			{
				foreach (XLCell cell2 in Worksheet.Internals.CellsCollection.GetCells(rowNumber, columnNumber, Worksheet.Internals.CellsCollection.MaxRowUsed, num))
				{
					int rowNumber3 = cell2.Address.RowNumber + numberOfRows;
					XLAddress xLAddress3 = new XLAddress(Worksheet, rowNumber3, cell2.Address.ColumnNumber, fixedRow: false, fixedColumn: false);
					XLCell xLCell3 = new XLCell(Worksheet, xLAddress3, cell2.GetStyleId());
					xLCell3.CopyValues(cell2);
					if (cell2.HasDataValidation)
					{
						dictionary.Add(xLCell3.Address, new DataValidationToCopy
						{
							DataValidation = cell2.DataValidation,
							SourceAddress = cell2.Address
						});
						cell2.DataValidation.Clear();
					}
					xLCell3.FormulaA1 = cell2.FormulaA1;
					cellsToInsert.Add(xLAddress3, xLCell3);
					list.Add(cell2.Address);
				}
			}
			dictionary.ForEach(delegate(KeyValuePair<XLAddress, DataValidationToCopy> kp)
			{
				if (!cellsToInsert.TryGetValue(kp.Key, out var value))
				{
					value = Worksheet.Cell(kp.Key);
				}
				value.CopyDataValidation(Worksheet.Cell(kp.Value.SourceAddress), kp.Value.DataValidation);
			});
			list.ForEach(delegate(IXLAddress c)
			{
				Worksheet.Internals.CellsCollection.Remove(c.RowNumber, c.ColumnNumber);
			});
			cellsToInsert.ForEach(delegate(KeyValuePair<IXLAddress, XLCell> c)
			{
				Worksheet.Internals.CellsCollection.Add(c.Key.RowNumber, c.Key.ColumnNumber, c.Value);
			});
			int rowNumber4 = RangeAddress.FirstAddress.RowNumber;
			int lastCellRow = RangeAddress.FirstAddress.RowNumber + numberOfRows - 1;
			int columnNumber2 = RangeAddress.FirstAddress.ColumnNumber;
			int columnNumber3 = RangeAddress.LastAddress.ColumnNumber;
			Worksheet.BreakConditionalFormatsIntoCells(list.Except(cellsToInsert.Keys).ToList());
			using (XLRange range = AsRange())
			{
				Worksheet.NotifyRangeShiftedRows(range, numberOfRows);
			}
			XLRange xLRange = Worksheet.Range(rowNumber4, columnNumber2, lastCellRow, columnNumber3);
			if (formatFromAbove && xLRange.RangeAddress.FirstAddress.RowNumber > 1)
			{
				using XLRangeRow xLRangeRow = xLRange.FirstRow();
				using XLRangeRow xLRangeRow2 = xLRangeRow.RowAbove();
				XLCell xLCell4 = xLRangeRow2.FirstCellUsed(includeFormats: true);
				XLCell xLCell5 = xLRangeRow2.LastCellUsed(includeFormats: true);
				if (xLCell5 != null)
				{
					int num4 = xLCell4.Address.ColumnNumber - xLRangeRow2.RangeAddress.FirstAddress.ColumnNumber + 1;
					int num5 = xLCell5.Address.ColumnNumber - xLRangeRow2.RangeAddress.FirstAddress.ColumnNumber + 1;
					for (int i = num4; i <= num5; i++)
					{
						xLRange.Column(i).Style = xLRangeRow2.Cell(i).Style;
					}
				}
			}
			else
			{
				XLRangeColumn xLRangeColumn = xLRange.LastColumnUsed(includeFormats: true);
				if (xLRangeColumn != null)
				{
					int num6 = xLRangeColumn.ColumnNumber();
					for (int j = 1; j <= num6; j++)
					{
						IXLStyle style = (Worksheet.Internals.ColumnsCollection.ContainsKey(j) ? Worksheet.Internals.ColumnsCollection[j].Style : Worksheet.Style);
						xLRange.Column(j).Style = style;
					}
				}
			}
			return xLRange.Rows();
		}

