		public void Delete(XLShiftDeletedCells shiftDeleteCells)
		{
			int num = RowCount();
			int num2 = ColumnCount();
			IXLRange iXLRange = Worksheet.Range(RangeAddress.FirstAddress.RowNumber, RangeAddress.FirstAddress.ColumnNumber, RangeAddress.LastAddress.RowNumber, RangeAddress.LastAddress.ColumnNumber);
			foreach (XLCell item in Worksheet.Workbook.Worksheets.Cast<XLWorksheet>().SelectMany((XLWorksheet xlWorksheet) => xlWorksheet.Internals.CellsCollection.GetCells((IXLCell c) => !XLHelper.IsNullOrWhiteSpace(c.FormulaA1))))
			{
				if (shiftDeleteCells == XLShiftDeletedCells.ShiftCellsUp)
				{
					item.ShiftFormulaRows((XLRange)iXLRange, num * -1);
				}
				else
				{
					item.ShiftFormulaColumns((XLRange)iXLRange, num2 * -1);
				}
			}
			Dictionary<IXLAddress, XLCell> dictionary = new Dictionary<IXLAddress, XLCell>();
			List<IXLAddress> list = new List<IXLAddress>();
			IEnumerable<XLCell> cells = Worksheet.Internals.CellsCollection.GetCells(RangeAddress.FirstAddress.RowNumber, RangeAddress.FirstAddress.ColumnNumber, RangeAddress.LastAddress.RowNumber, Worksheet.Internals.CellsCollection.MaxColumnUsed);
			IEnumerable<XLCell> cells2 = Worksheet.Internals.CellsCollection.GetCells(RangeAddress.FirstAddress.RowNumber, RangeAddress.FirstAddress.ColumnNumber, Worksheet.Internals.CellsCollection.MaxRowUsed, RangeAddress.LastAddress.ColumnNumber);
			int num3 = ((shiftDeleteCells == XLShiftDeletedCells.ShiftCellsLeft) ? ColumnCount() : 0);
			int num4 = ((shiftDeleteCells == XLShiftDeletedCells.ShiftCellsUp) ? RowCount() : 0);
			IEnumerable<XLCell> enumerable = ((shiftDeleteCells == XLShiftDeletedCells.ShiftCellsLeft) ? cells : cells2);
			foreach (XLCell item2 in enumerable)
			{
				XLAddress xLAddress = new XLAddress(Worksheet, item2.Address.RowNumber - num4, item2.Address.ColumnNumber - num3, fixedRow: false, fixedColumn: false);
				XLCell xLCell = new XLCell(Worksheet, xLAddress, item2.GetStyleId());
				xLCell.CopyValues(item2);
				xLCell.FormulaA1 = item2.FormulaA1;
				list.Add(item2.Address);
				if ((shiftDeleteCells == XLShiftDeletedCells.ShiftCellsLeft) ? (item2.Address.ColumnNumber > RangeAddress.LastAddress.ColumnNumber) : (item2.Address.RowNumber > RangeAddress.LastAddress.RowNumber))
				{
					dictionary.Add(xLAddress, xLCell);
				}
			}
			list.ForEach(delegate(IXLAddress c)
			{
				Worksheet.Internals.CellsCollection.Remove(c.RowNumber, c.ColumnNumber);
			});
			dictionary.ForEach(delegate(KeyValuePair<IXLAddress, XLCell> c)
			{
				Worksheet.Internals.CellsCollection.Add(c.Key.RowNumber, c.Key.ColumnNumber, c.Value);
			});
			List<IXLRange> list2 = Worksheet.Internals.MergedRanges.Where(Contains).ToList();
			list2.ForEach(delegate(IXLRange r)
			{
				Worksheet.Internals.MergedRanges.Remove(r);
			});
			List<XLHyperlink> list3 = Worksheet.Hyperlinks.Where((XLHyperlink hl) => Contains(hl.Cell.AsRange())).ToList();
			list3.ForEach(delegate(XLHyperlink hl)
			{
				Worksheet.Hyperlinks.Delete(hl);
			});
			Worksheet.BreakConditionalFormatsIntoCells(list.Except(dictionary.Keys).ToList());
			using XLRange range = AsRange();
			if (shiftDeleteCells == XLShiftDeletedCells.ShiftCellsUp)
			{
				Worksheet.NotifyRangeShiftedRows(range, num4 * -1);
			}
			else
			{
				Worksheet.NotifyRangeShiftedColumns(range, num3 * -1);
			}
		}

