		public IXLRangeBase Sort()
		{
			if (!SortColumns.Any())
			{
				string text = string.Empty;
				int num = ColumnCount();
				if (num == 16384)
				{
					num = LastCellUsed(includeFormats: true).Address.ColumnNumber;
				}
				for (int i = 1; i <= num; i++)
				{
					text = text + i + ",";
				}
				text = text.Substring(0, text.Length - 1);
				return Sort(text);
			}
			SortRangeRows();
			return this;
		}

		public IXLRangeBase Sort(string columnsToSortBy, XLSortOrder sortOrder = XLSortOrder.Ascending, bool matchCase = false, bool ignoreBlanks = true)
		{
			SortColumns.Clear();
			if (XLHelper.IsNullOrWhiteSpace(columnsToSortBy))
			{
				columnsToSortBy = string.Empty;
				int num = ColumnCount();
				if (num == 16384)
				{
					num = LastCellUsed(includeFormats: true).Address.ColumnNumber;
				}
				for (int i = 1; i <= num; i++)
				{
					columnsToSortBy = columnsToSortBy + i + ",";
				}
				columnsToSortBy = columnsToSortBy.Substring(0, columnsToSortBy.Length - 1);
			}
			foreach (string item in from coPair in columnsToSortBy.Split(new char[1] { ',' })
				select coPair.Trim())
			{
				string text;
				string strA;
				if (Enumerable.Contains(item, ' '))
				{
					string[] array = item.Split(new char[1] { ' ' });
					text = array[0];
					strA = array[1];
				}
				else
				{
					text = item;
					strA = ((sortOrder == XLSortOrder.Ascending) ? "ASC" : "DESC");
				}
				if (!int.TryParse(text, out var result))
				{
					result = XLHelper.GetColumnNumberFromLetter(text);
				}
				SortColumns.Add(result, (string.Compare(strA, "ASC", ignoreCase: true) != 0) ? XLSortOrder.Descending : XLSortOrder.Ascending, ignoreBlanks, matchCase);
			}
			SortRangeRows();
			return this;
		}

		public IXLRangeBase Sort(int columnToSortBy, XLSortOrder sortOrder = XLSortOrder.Ascending, bool matchCase = false, bool ignoreBlanks = true)
		{
			return Sort(columnToSortBy.ToString(), sortOrder, matchCase, ignoreBlanks);
		}

		public IXLRangeBase SortLeftToRight(XLSortOrder sortOrder = XLSortOrder.Ascending, bool matchCase = false, bool ignoreBlanks = true)
		{
			SortRows.Clear();
			int num = ColumnCount();
			if (num == 16384)
			{
				num = LastCellUsed(includeFormats: true).Address.ColumnNumber;
			}
			for (int i = 1; i <= num; i++)
			{
				SortRows.Add(i, sortOrder, ignoreBlanks, matchCase);
			}
			SortRangeColumns();
			return this;
		}

		private void SortRangeRows()
		{
			int num = RowCount();
			if (num == 1048576)
			{
				num = LastCellUsed(includeFormats: true).Address.RowNumber;
			}
			SortingRangeRows(1, num);
		}

		private void SwapRows(int row1, int row2)
		{
			int row3 = RangeAddress.FirstAddress.RowNumber + row1 - 1;
			int row4 = RangeAddress.FirstAddress.RowNumber + row2 - 1;
			int columnNumber = RangeAddress.FirstAddress.ColumnNumber;
			int columnNumber2 = RangeAddress.LastAddress.ColumnNumber;
			XLSheetPoint firstPoint = new XLSheetPoint(row3, columnNumber);
			XLSheetPoint lastPoint = new XLSheetPoint(row3, columnNumber2);
			XLSheetPoint firstPoint2 = new XLSheetPoint(row4, columnNumber);
			XLSheetPoint lastPoint2 = new XLSheetPoint(row4, columnNumber2);
			Worksheet.Internals.CellsCollection.SwapRanges(new XLSheetRange(firstPoint, lastPoint), new XLSheetRange(firstPoint2, lastPoint2), Worksheet);
		}

		private int SortRangeRows(int begPoint, int endPoint)
		{
			int i = begPoint + 1;
			int num = endPoint;
			for (; i < endPoint && RowQuick(begPoint).CompareTo(RowQuick(i), SortColumns) >= 0; i++)
			{
			}
			while (num > begPoint && RowQuick(begPoint).CompareTo(RowQuick(num), SortColumns) <= 0)
			{
				num--;
			}
			while (i < num)
			{
				SwapRows(i, num);
				for (; i < endPoint && RowQuick(begPoint).CompareTo(RowQuick(i), SortColumns) >= 0; i++)
				{
				}
				while (num > begPoint && RowQuick(begPoint).CompareTo(RowQuick(num), SortColumns) <= 0)
				{
					num--;
