		private void SwapColumns(int column1, int column2)
		{
			int column3 = RangeAddress.FirstAddress.ColumnNumber + column1 - 1;
			int column4 = RangeAddress.FirstAddress.ColumnNumber + column2 - 1;
			int rowNumber = RangeAddress.FirstAddress.RowNumber;
			int rowNumber2 = RangeAddress.LastAddress.RowNumber;
			XLSheetPoint firstPoint = new XLSheetPoint(rowNumber, column3);
			XLSheetPoint lastPoint = new XLSheetPoint(rowNumber2, column3);
			XLSheetPoint firstPoint2 = new XLSheetPoint(rowNumber, column4);
			XLSheetPoint lastPoint2 = new XLSheetPoint(rowNumber2, column4);
			Worksheet.Internals.CellsCollection.SwapRanges(new XLSheetRange(firstPoint, lastPoint), new XLSheetRange(firstPoint2, lastPoint2), Worksheet);
		}

		private int SortRangeColumns(int begPoint, int endPoint)
		{
			int i = begPoint + 1;
			int num = endPoint;
			for (; i < endPoint && ColumnQuick(begPoint).CompareTo(ColumnQuick(i), SortRows) >= 0; i++)
			{
			}
			while (num > begPoint && ColumnQuick(begPoint).CompareTo(ColumnQuick(num), SortRows) <= 0)
			{
				num--;
			}
			while (i < num)
			{
				SwapColumns(i, num);
				for (; i < endPoint && ColumnQuick(begPoint).CompareTo(ColumnQuick(i), SortRows) >= 0; i++)
				{
				}
				while (num > begPoint && ColumnQuick(begPoint).CompareTo(ColumnQuick(num), SortRows) <= 0)
				{
					num--;
				}
			}
			if (begPoint != num)
			{
				SwapColumns(num, begPoint);
			}
			return num;
		}

		private void SortingRangeColumns(int beg, int end)
		{
			if (end != beg)
			{
				int num = SortRangeColumns(beg, end);
				if (num > beg)
				{
					SortingRangeColumns(beg, num - 1);
				}
				if (num < end)
				{
					SortingRangeColumns(num + 1, end);
				}
			}
		}

