		public void Transpose(XLTransposeOptions transposeOption)
		{
			int num = RowCount();
			int num2 = ColumnCount();
			int squareSide = ((num > num2) ? num : num2);
			XLCell xLCell = FirstCell();
			MoveOrClearForTranspose(transposeOption, num, num2);
			TransposeMerged(squareSide);
			TransposeRange(squareSide);
			base.RangeAddress.LastAddress = new XLAddress(base.Worksheet, xLCell.Address.RowNumber + num2 - 1, xLCell.Address.ColumnNumber + num - 1, base.RangeAddress.LastAddress.FixedRow, base.RangeAddress.LastAddress.FixedColumn);
