				xLRange.Delete(XLShiftDeletedCells.ShiftCellsUp);
			}
			else if (num2 > num)
			{
				XLRange xLRange2 = base.Worksheet.Range(base.RangeAddress.FirstAddress.RowNumber, base.RangeAddress.LastAddress.ColumnNumber + 1, base.RangeAddress.LastAddress.RowNumber, base.RangeAddress.LastAddress.ColumnNumber + (num2 - num));
				xLRange2.Delete(XLShiftDeletedCells.ShiftCellsLeft);
			}
			foreach (IXLCell item in Range(1, 1, num2, num).Cells())
			{
				XLBorder xLBorder = new XLBorder(this, item.Style.Border);
				item.Style.Border.TopBorder = xLBorder.LeftBorder;
				item.Style.Border.TopBorderColor = xLBorder.LeftBorderColor;
				item.Style.Border.LeftBorder = xLBorder.TopBorder;
				item.Style.Border.LeftBorderColor = xLBorder.TopBorderColor;
				item.Style.Border.RightBorder = xLBorder.BottomBorder;
				item.Style.Border.RightBorderColor = xLBorder.BottomBorderColor;
				item.Style.Border.BottomBorder = xLBorder.RightBorder;
				item.Style.Border.BottomBorderColor = xLBorder.RightBorderColor;
			}
		}

