		public XLRangeRow Row(int row)
		{
			if (row <= 0 || row > 1048576)
			{
				throw new IndexOutOfRangeException($"Row number must be between 1 and {1048576}");
			}
			XLAddress firstAddress = new XLAddress(base.Worksheet, base.RangeAddress.FirstAddress.RowNumber + row - 1, base.RangeAddress.FirstAddress.ColumnNumber, fixedRow: false, fixedColumn: false);
			XLAddress lastAddress = new XLAddress(base.Worksheet, base.RangeAddress.FirstAddress.RowNumber + row - 1, base.RangeAddress.LastAddress.ColumnNumber, fixedRow: false, fixedColumn: false);
			return new XLRangeRow(new XLRangeParameters(new XLRangeAddress(firstAddress, lastAddress), base.Worksheet.Style), quickLoad: false);
		}

		public XLRangeColumn Column(int column)
		{
			if (column <= 0 || column > 16384)
			{
				throw new IndexOutOfRangeException($"Column number must be between 1 and {16384}");
			}
			XLAddress firstAddress = new XLAddress(base.Worksheet, base.RangeAddress.FirstAddress.RowNumber, base.RangeAddress.FirstAddress.ColumnNumber + column - 1, fixedRow: false, fixedColumn: false);
			XLAddress lastAddress = new XLAddress(base.Worksheet, base.RangeAddress.LastAddress.RowNumber, base.RangeAddress.FirstAddress.ColumnNumber + column - 1, fixedRow: false, fixedColumn: false);
			return new XLRangeColumn(new XLRangeParameters(new XLRangeAddress(firstAddress, lastAddress), base.Worksheet.Style), quickLoad: false);
		}

