		private void TransposeRange(int squareSide)
		{
			Dictionary<XLSheetPoint, XLCell> dictionary = new Dictionary<XLSheetPoint, XLCell>();
			List<XLSheetPoint> list = new List<XLSheetPoint>();
			XLRange xLRange = base.Worksheet.Range(base.RangeAddress.FirstAddress.RowNumber, base.RangeAddress.FirstAddress.ColumnNumber, base.RangeAddress.FirstAddress.RowNumber + squareSide - 1, base.RangeAddress.FirstAddress.ColumnNumber + squareSide - 1);
			int num = xLRange.RowCount();
			int num2 = xLRange.ColumnCount();
			for (int i = 1; i <= num; i++)
			{
				for (int j = 1; j <= num2; j++)
				{
					XLCell xLCell = xLRange.Cell(i, j);
					XLAddress address = xLRange.Cell(j, i).Address;
					XLCell xLCell2 = new XLCell(base.Worksheet, address, xLCell.GetStyleId());
					xLCell2.CopyFrom(xLCell, copyDataValidations: true);
					dictionary.Add(new XLSheetPoint(address.RowNumber, address.ColumnNumber), xLCell2);
					list.Add(new XLSheetPoint(xLCell.Address.RowNumber, xLCell.Address.ColumnNumber));
				}
			}
			list.ForEach(delegate(XLSheetPoint c)
			{
				base.Worksheet.Internals.CellsCollection.Remove(c);
			});
			dictionary.ForEach(delegate(KeyValuePair<XLSheetPoint, XLCell> c)
			{
				base.Worksheet.Internals.CellsCollection.Add(c.Key, c.Value);
			});
		}

		private void TransposeMerged(int squareSide)
		{
			XLRange xLRange = base.Worksheet.Range(base.RangeAddress.FirstAddress.RowNumber, base.RangeAddress.FirstAddress.ColumnNumber, base.RangeAddress.FirstAddress.RowNumber + squareSide - 1, base.RangeAddress.FirstAddress.ColumnNumber + squareSide - 1);
			foreach (IXLRange item in base.Worksheet.Internals.MergedRanges.Where(base.Contains))
			{
				item.RangeAddress.LastAddress = xLRange.Cell(item.ColumnCount(), item.RowCount()).Address;
			}
		}

		private void MoveOrClearForTranspose(XLTransposeOptions transposeOption, int rowCount, int columnCount)
		{
			if (transposeOption == XLTransposeOptions.MoveCells)
			{
				if (rowCount > columnCount)
				{
					InsertColumnsAfter(onlyUsedCells: false, rowCount - columnCount, formatFromLeft: false);
				}
				else if (columnCount > rowCount)
				{
					InsertRowsBelow(onlyUsedCells: false, columnCount - rowCount, formatFromAbove: false);
				}
			}
			else if (rowCount > columnCount)
			{
				int num = rowCount - columnCount;
				XLRange xLRange = base.Worksheet.Range(base.RangeAddress.FirstAddress.RowNumber, base.RangeAddress.LastAddress.ColumnNumber + 1, base.RangeAddress.LastAddress.RowNumber, base.RangeAddress.LastAddress.ColumnNumber + num);
				xLRange.Clear();
			}
			else if (columnCount > rowCount)
			{
				int num2 = columnCount - rowCount;
				XLRange xLRange2 = base.Worksheet.Range(base.RangeAddress.LastAddress.RowNumber + 1, base.RangeAddress.FirstAddress.ColumnNumber, base.RangeAddress.LastAddress.RowNumber + num2, base.RangeAddress.LastAddress.ColumnNumber);
				xLRange2.Clear();
			}
		}

		public override bool Equals(object obj)
		{
			XLRange xLRange = (XLRange)obj;
			if (base.RangeAddress.Equals(xLRange.RangeAddress))
			{
				return base.Worksheet.Equals(xLRange.Worksheet);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return base.RangeAddress.GetHashCode() ^ base.Worksheet.GetHashCode();
		}

		public new IXLRange Clear(XLClearOptions clearOptions = XLClearOptions.ContentsAndFormats)
		{
			base.Clear(clearOptions);
			return this;
		}
	}
