		public new IXLTableRows Rows(string rows)
		{
			XLTableRows xLTableRows = new XLTableRows(base.Worksheet.Style);
			string[] source = rows.Split(new char[1] { ',' });
			foreach (string item in source.Select((string pair) => pair.Trim()))
			{
				string s;
				string s2;
				if (Enumerable.Contains(item, ':') || Enumerable.Contains(item, '-'))
				{
					string[] array = XLHelper.SplitRange(item);
					s = array[0];
					s2 = array[1];
				}
				else
				{
					s = item;
					s2 = item;
				}
				foreach (IXLTableRow item2 in Rows(int.Parse(s), int.Parse(s2)))
				{
					xLTableRows.Add(item2);
				}
			}
			return xLTableRows;
		}

