		private string GetTableColumnName(string name)
		{
			return name.Replace("_x000a_", Environment.NewLine).Replace("_x005f_x000a_", "_x000a_");
		}

		private void LoadColorsAndLines<T>(IXLDrawing<T> drawing, XElement shape)
		{
			XAttribute val = shape.Attribute(XName.op_Implicit("strokecolor"));
			if (val != null)
			{
				drawing.Style.ColorsAndLines.LineColor = XLColor.FromHtml(val.Value);
			}
			XAttribute val2 = shape.Attribute(XName.op_Implicit("strokeweight"));
			if (val2 != null)
			{
				drawing.Style.ColorsAndLines.LineWeight = GetPtValue(val2.Value);
			}
			XAttribute val3 = shape.Attribute(XName.op_Implicit("fillcolor"));
			if (val3 != null && !val3.Value.ToLower().Contains("infobackground"))
			{
				drawing.Style.ColorsAndLines.FillColor = XLColor.FromHtml(val3.Value);
			}
			XElement val4 = ((XContainer)shape).Elements().FirstOrDefault((Func<XElement, bool>)((XElement e) => e.Name.LocalName == "fill"));
			if (val4 != null)
			{
				XAttribute val5 = val4.Attribute(XName.op_Implicit("opacity"));
				if (val5 != null)
				{
					string value = val5.Value;
					if (value.EndsWith("f"))
					{
						drawing.Style.ColorsAndLines.FillTransparency = double.Parse(value.Substring(0, value.Length - 1), CultureInfo.InvariantCulture) / 65536.0;
					}
					else
					{
						drawing.Style.ColorsAndLines.FillTransparency = double.Parse(value, CultureInfo.InvariantCulture);
					}
				}
			}
			XElement val6 = ((XContainer)shape).Elements().FirstOrDefault((Func<XElement, bool>)((XElement e) => e.Name.LocalName == "stroke"));
			if (val6 == null)
			{
				return;
			}
			XAttribute val7 = val6.Attribute(XName.op_Implicit("opacity"));
			if (val7 != null)
			{
				string value2 = val7.Value;
				if (value2.EndsWith("f"))
				{
					drawing.Style.ColorsAndLines.LineTransparency = double.Parse(value2.Substring(0, value2.Length - 1), CultureInfo.InvariantCulture) / 65536.0;
				}
				else
				{
