			return double.Parse(value.Replace(keyValuePair.Key, string.Empty), CultureInfo.InvariantCulture) * keyValuePair.Value;
		}

		private void LoadDefinedNames(Workbook workbook)
		{
			if (workbook.DefinedNames == null)
			{
				return;
			}
			foreach (DocumentFormat.OpenXml.Spreadsheet.DefinedName definedName in workbook.DefinedNames)
			{
				StringValue name = definedName.Name;
				if (name == "_xlnm.Print_Area")
				{
					string[] array = definedName.Text.Split(new char[1] { ',' });
					foreach (string text in array)
					{
						if (text.Contains("["))
						{
							text.Substring(0, text.IndexOf("["));
							IXLWorksheet iXLWorksheet = Worksheets.First((IXLWorksheet w) => (w as XLWorksheet).SheetId == (uint)definedName.LocalSheetId + 1);
							iXLWorksheet.PageSetup.PrintAreas.Add(text);
						}
						else
						{
							ParseReference(text, out var sheetName, out var sheetArea);
							if (!sheetArea.Equals("#REF") && !sheetArea.EndsWith("#REF!") && sheetArea.Length != 0)
							{
								WorksheetsInternal.Worksheet(sheetName).PageSetup.PrintAreas.Add(sheetArea);
							}
						}
					}
					continue;
				}
				if (name == "_xlnm.Print_Titles")
				{
					LoadPrintTitles(definedName);
					continue;
				}
				string text2 = definedName.Text;
				if (text2.Equals("#REF") || text2.EndsWith("#REF!"))
				{
					continue;
				}
				UInt32Value localSheetId = definedName.LocalSheetId;
				StringValue comment = definedName.Comment;
				if (localSheetId == null)
				{
					if (!NamedRanges.Any((IXLNamedRange nr) => nr.Name == name))
					{
						NamedRanges.Add(name, text2, comment);
					}
				}
				else if (!Worksheet(int.Parse(localSheetId) + 1).NamedRanges.Any((IXLNamedRange nr) => nr.Name == name))
				{
					Worksheet(int.Parse(localSheetId) + 1).NamedRanges.Add(name, text2, comment);
				}
			}
		}

		private void LoadPrintTitles(DocumentFormat.OpenXml.Spreadsheet.DefinedName definedName)
		{
			string[] array = definedName.Text.Split(new char[1] { ',' });
			if (array.Length > 0)
			{
				string[] array2 = array;
				foreach (string columnsOrRowsToRepeat in array2)
				{
					SetColumnsOrRowsToRepeat(columnsOrRowsToRepeat);
				}
			}
			else
			{
				SetColumnsOrRowsToRepeat(definedName.Text);
			}
		}

		private void SetColumnsOrRowsToRepeat(string area)
		{
			ParseReference(area, out var sheetName, out var sheetArea);
			if (!sheetArea.Equals("#REF"))
			{
				if (IsColReference(sheetArea))
				{
					WorksheetsInternal.Worksheet(sheetName).PageSetup.SetColumnsToRepeatAtLeft(sheetArea);
				}
				if (IsRowReference(sheetArea))
				{
					WorksheetsInternal.Worksheet(sheetName).PageSetup.SetRowsToRepeatAtTop(sheetArea);
				}
			}
		}

		private static bool IsColReference(string sheetArea)
		{
			char c = ((sheetArea[0] == '$') ? sheetArea[1] : sheetArea[0]);
			return char.IsLetter(c);
		}

		private static bool IsRowReference(string sheetArea)
		{
			char c = ((sheetArea[0] == '$') ? sheetArea[1] : sheetArea[0]);
			return char.IsNumber(c);
		}

		private static void ParseReference(string item, out string sheetName, out string sheetArea)
		{
			string[] array = item.Trim().Split(new char[1] { '!' });
			sheetName = array[0].Replace("'", "");
			sheetArea = array[1];
		}

