				if (fillSource.PatternFill.BackgroundColor != null)
				{
					fill.PatternBackgroundColor = GetColor(fillSource.PatternFill.BackgroundColor);
				}
			}
		}

		private void LoadFont(OpenXmlElement fontSource, IXLFontBase fontBase)
