			{
				fontBase.Bold = GetBoolean(fontSource.Elements<Bold>().FirstOrDefault());
				XLColor color = GetColor(fontSource.Elements<DocumentFormat.OpenXml.Spreadsheet.Color>().FirstOrDefault());
