					fontBase.FontName = runFont.Val;
				}
				FontSize fontSize = fontSource.Elements<FontSize>().FirstOrDefault();
				if (fontSize != null && fontSize.Val != null)
				{
					fontBase.FontSize = fontSize.Val;
				}
				fontBase.Italic = GetBoolean(fontSource.Elements<Italic>().FirstOrDefault());
				fontBase.Shadow = GetBoolean(fontSource.Elements<DocumentFormat.OpenXml.Spreadsheet.Shadow>().FirstOrDefault());
				fontBase.Strikethrough = GetBoolean(fontSource.Elements<Strike>().FirstOrDefault());
				DocumentFormat.OpenXml.Spreadsheet.Underline underline = fontSource.Elements<DocumentFormat.OpenXml.Spreadsheet.Underline>().FirstOrDefault();
				if (underline != null)
				{
					fontBase.Underline = ((underline.Val != null) ? underline.Val.Value.ToClosedXml() : XLFontUnderlineValues.Single);
				}
				DocumentFormat.OpenXml.Spreadsheet.VerticalTextAlignment verticalTextAlignment = fontSource.Elements<DocumentFormat.OpenXml.Spreadsheet.VerticalTextAlignment>().FirstOrDefault();
				if (verticalTextAlignment != null)
