		}

		private void LoadRows(Stylesheet s, NumberingFormats numberingFormats, Fills fills, Borders borders, DocumentFormat.OpenXml.Spreadsheet.Fonts fonts, XLWorksheet ws, SharedStringItem[] sharedStrings, Dictionary<uint, string> sharedFormulasR1C1, Dictionary<int, IXLStyle> styleList, Row row)
		{
			int num = ((row.RowIndex == null) ? (++lastRow) : ((int)row.RowIndex.Value));
			XLRow xLRow = ws.Row(num, pingCells: false);
			if (row.Height != null)
			{
				xLRow.Height = row.Height;
			}
			else
			{
				xLRow.Loading = true;
				xLRow.Height = ws.RowHeight;
				xLRow.Loading = false;
			}
			if (row.Hidden != null && (bool)row.Hidden)
			{
				xLRow.Hide();
			}
			if (row.Collapsed != null && (bool)row.Collapsed)
			{
				xLRow.Collapsed = true;
			}
			if (row.OutlineLevel != null && (byte)row.OutlineLevel > 0)
			{
				xLRow.OutlineLevel = (byte)row.OutlineLevel;
			}
			if (row.CustomFormat != null)
			{
				int num2 = ((row.StyleIndex != null) ? int.Parse(row.StyleIndex.InnerText) : (-1));
				if (num2 > 0)
				{
					ApplyStyle(xLRow, num2, s, fills, borders, fonts, numberingFormats);
				}
				else
				{
					xLRow.Style = DefaultStyle;
				}
			}
			lastCell = 0;
			foreach (Cell item in row.Elements<Cell>())
			{
				LoadCells(sharedStrings, s, numberingFormats, fills, borders, fonts, sharedFormulasR1C1, ws, styleList, item, num);
			}
		}

		private void LoadColumns(Stylesheet s, NumberingFormats numberingFormats, Fills fills, Borders borders, DocumentFormat.OpenXml.Spreadsheet.Fonts fonts, XLWorksheet ws, Columns columns)
		{
			if (columns == null)
			{
				return;
			}
			Column column = (from c in columns.Elements<Column>()
				where (uint)c.Max == 16384
				select c).FirstOrDefault();
			if (column != null && column.Width != null)
			{
				ws.ColumnWidth = (double)column.Width - 0.710625;
			}
			int num = ((column != null && column.Style != null) ? int.Parse(column.Style.InnerText) : (-1));
			if (num >= 0)
			{
				ApplyStyle(ws, num, s, fills, borders, fonts, numberingFormats);
			}
			foreach (Column item in columns.Elements<Column>())
			{
				if ((uint)item.Max == 16384)
				{
					continue;
				}
				XLColumns xLColumns = (XLColumns)ws.Columns(item.Min, item.Max);
				if (item.Width != null)
				{
					double width = (double)item.Width - 0.710625;
					xLColumns.Width = width;
				}
				else
				{
					xLColumns.Width = ws.ColumnWidth;
				}
				if (item.Hidden != null && (bool)item.Hidden)
				{
					xLColumns.Hide();
				}
				if (item.Collapsed != null && (bool)item.Collapsed)
				{
					xLColumns.CollapseOnly();
				}
				if (item.OutlineLevel != null)
				{
					ByteValue outlineLevel = item.OutlineLevel;
					xLColumns.ForEach(delegate(IXLColumn c)
					{
						c.OutlineLevel = (byte)outlineLevel;
					});
				}
				int num2 = ((item.Style != null) ? int.Parse(item.Style.InnerText) : (-1));
				if (num2 > 0)
				{
					ApplyStyle(xLColumns, num2, s, fills, borders, fonts, numberingFormats);
				}
				else
				{
					xLColumns.Style = DefaultStyle;
				}
			}
		}

		private static XLCellValues GetDataTypeFromFormat(string format)
		{
			int length = format.Length;
			string text = format.ToLower();
			for (int i = 0; i < length; i++)
			{
				switch (text[i])
				{
				case '"':
					i = text.IndexOf('"', i + 1);
					break;
				case '#':
				case '0':
				case '?':
					return XLCellValues.Number;
				case 'd':
				case 'h':
				case 'm':
				case 's':
				case 'y':
					return XLCellValues.DateTime;
				}
			}
			return XLCellValues.Text;
		}

		private static void LoadAutoFilter(AutoFilter af, XLWorksheet ws)
		{
			if (af != null)
			{
				ws.Range(af.Reference.Value).SetAutoFilter();
				XLAutoFilter autoFilter = ws.AutoFilter;
				LoadAutoFilterSort(af, ws, autoFilter);
				LoadAutoFilterColumns(af, autoFilter);
			}
		}

		private static void LoadAutoFilterColumns(AutoFilter af, XLAutoFilter autoFilter)
		{
			foreach (FilterColumn item in af.Elements<FilterColumn>())
			{
				int num = (int)(item.ColumnId.Value + 1);
				if (item.CustomFilters != null)
				{
					List<XLFilter> list = new List<XLFilter>();
					autoFilter.Column(num).FilterType = XLFilterType.Custom;
					autoFilter.Filters.Add(num, list);
					XLConnector connector = ((item.CustomFilters.And == null || !item.CustomFilters.And.Value) ? XLConnector.Or : XLConnector.And);
					bool flag = false;
					foreach (DocumentFormat.OpenXml.Spreadsheet.CustomFilter customFilter3 in item.CustomFilters)
					{
						string value = customFilter3.Val.Value;
						if (!double.TryParse(value, out var _))
						{
							flag = true;
							break;
						}
					}
					foreach (DocumentFormat.OpenXml.Spreadsheet.CustomFilter customFilter4 in item.CustomFilters)
					{
						XLFilter xlFilter2 = new XLFilter
						{
							Value = customFilter4.Val.Value,
							Connector = connector
						};
						if (flag)
						{
							xlFilter2.Value = customFilter4.Val.Value;
						}
						else
						{
							xlFilter2.Value = double.Parse(customFilter4.Val.Value, CultureInfo.InvariantCulture);
						}
						if (customFilter4.Operator != null)
						{
							xlFilter2.Operator = customFilter4.Operator.Value.ToClosedXml();
						}
						else
						{
							xlFilter2.Operator = XLFilterOperator.Equal;
						}
						Func<object, bool> condition = null;
						switch (xlFilter2.Operator)
						{
						case XLFilterOperator.Equal:
							condition = ((!flag) ? ((Func<object, bool>)((object o) => (o as IComparable).CompareTo(xlFilter2.Value) == 0)) : ((Func<object, bool>)((object o) => o.ToString().Equals(xlFilter2.Value.ToString(), StringComparison.InvariantCultureIgnoreCase))));
							break;
						case XLFilterOperator.EqualOrGreaterThan:
							condition = (object o) => (o as IComparable).CompareTo(xlFilter2.Value) >= 0;
							break;
						case XLFilterOperator.EqualOrLessThan:
							condition = (object o) => (o as IComparable).CompareTo(xlFilter2.Value) <= 0;
							break;
						case XLFilterOperator.GreaterThan:
							condition = (object o) => (o as IComparable).CompareTo(xlFilter2.Value) > 0;
							break;
						case XLFilterOperator.LessThan:
							condition = (object o) => (o as IComparable).CompareTo(xlFilter2.Value) < 0;
							break;
						case XLFilterOperator.NotEqual:
							condition = ((!flag) ? ((Func<object, bool>)((object o) => (o as IComparable).CompareTo(xlFilter2.Value) != 0)) : ((Func<object, bool>)((object o) => !o.ToString().Equals(xlFilter2.Value.ToString(), StringComparison.InvariantCultureIgnoreCase))));
							break;
						}
						xlFilter2.Condition = condition;
						list.Add(xlFilter2);
					}
				}
				else if (item.Filters != null)
				{
					List<XLFilter> list2 = new List<XLFilter>();
					autoFilter.Column(num).FilterType = XLFilterType.Regular;
					autoFilter.Filters.Add((int)(item.ColumnId.Value + 1), list2);
					bool flag2 = false;
					foreach (DocumentFormat.OpenXml.Spreadsheet.Filter filter3 in item.Filters)
					{
						string value2 = filter3.Val.Value;
						if (!double.TryParse(value2, out var _))
						{
							flag2 = true;
							break;
						}
					}
					foreach (DocumentFormat.OpenXml.Spreadsheet.Filter filter4 in item.Filters)
					{
						XLFilter xlFilter = new XLFilter
						{
							Connector = XLConnector.Or,
							Operator = XLFilterOperator.Equal
						};
						Func<object, bool> condition2;
						if (flag2)
						{
							xlFilter.Value = filter4.Val.Value;
							condition2 = (object o) => o.ToString().Equals(xlFilter.Value.ToString(), StringComparison.InvariantCultureIgnoreCase);
						}
						else
						{
							xlFilter.Value = double.Parse(filter4.Val.Value, CultureInfo.InvariantCulture);
							condition2 = (object o) => (o as IComparable).CompareTo(xlFilter.Value) == 0;
						}
						xlFilter.Condition = condition2;
						list2.Add(xlFilter);
					}
				}
				else if (item.Top10 != null)
				{
					IXLFilterColumn iXLFilterColumn = autoFilter.Column(num);
					autoFilter.Filters.Add(num, null);
					iXLFilterColumn.FilterType = XLFilterType.TopBottom;
					if (item.Top10.Percent != null && item.Top10.Percent.Value)
					{
						iXLFilterColumn.TopBottomType = XLTopBottomType.Percent;
					}
					else
					{
						iXLFilterColumn.TopBottomType = XLTopBottomType.Items;
					}
					if (item.Top10.Top != null && !item.Top10.Top.Value)
					{
						iXLFilterColumn.TopBottomPart = XLTopBottomPart.Bottom;
					}
					else
					{
						iXLFilterColumn.TopBottomPart = XLTopBottomPart.Top;
					}
					iXLFilterColumn.TopBottomValue = (int)item.Top10.Val.Value;
				}
				else if (item.DynamicFilter != null)
				{
					autoFilter.Filters.Add(num, null);
					IXLFilterColumn iXLFilterColumn2 = autoFilter.Column(num);
					iXLFilterColumn2.FilterType = XLFilterType.Dynamic;
					if (item.DynamicFilter.Type != null)
					{
						iXLFilterColumn2.DynamicType = item.DynamicFilter.Type.Value.ToClosedXml();
					}
					else
					{
						iXLFilterColumn2.DynamicType = XLFilterDynamicType.AboveAverage;
					}
					iXLFilterColumn2.DynamicValue = item.DynamicFilter.Val.Value;
				}
			}
		}

		private static void LoadAutoFilterSort(AutoFilter af, XLWorksheet ws, IXLBaseAutoFilter autoFilter)
		{
			SortState sortState = af.Elements<SortState>().FirstOrDefault();
			if (sortState != null)
			{
				DocumentFormat.OpenXml.Spreadsheet.SortCondition sortCondition = sortState.Elements<DocumentFormat.OpenXml.Spreadsheet.SortCondition>().FirstOrDefault();
				if (sortCondition != null)
				{
					int sortColumn = ws.Range(sortCondition.Reference.Value).FirstCell().Address.ColumnNumber - autoFilter.Range.FirstCell().Address.ColumnNumber + 1;
					autoFilter.SortColumn = sortColumn;
					autoFilter.Sorted = true;
					autoFilter.SortOrder = ((sortCondition.Descending != null && sortCondition.Descending.Value) ? XLSortOrder.Descending : XLSortOrder.Ascending);
				}
			}
		}

