		private static void LoadDataValidations(DocumentFormat.OpenXml.Spreadsheet.DataValidations dataValidations, XLWorksheet ws)
		{
			if (dataValidations == null)
			{
				return;
			}
			foreach (DocumentFormat.OpenXml.Spreadsheet.DataValidation item in dataValidations.Elements<DocumentFormat.OpenXml.Spreadsheet.DataValidation>())
			{
				string innerText = item.SequenceOfReferences.InnerText;
				if (XLHelper.IsNullOrWhiteSpace(innerText))
				{
					continue;
				}
				foreach (XLDataValidation item2 in from rangeAddress in innerText.Split(new char[1] { ' ' })
					select ws.Range(rangeAddress).DataValidation)
				{
					if (item.AllowBlank != null)
					{
						item2.IgnoreBlanks = item.AllowBlank;
					}
					if (item.ShowDropDown != null)
					{
						item2.InCellDropdown = !item.ShowDropDown.Value;
					}
					if (item.ShowErrorMessage != null)
					{
						item2.ShowErrorMessage = item.ShowErrorMessage;
					}
					if (item.ShowInputMessage != null)
					{
						item2.ShowInputMessage = item.ShowInputMessage;
					}
					if (item.PromptTitle != null)
					{
						item2.InputTitle = item.PromptTitle;
					}
					if (item.Prompt != null)
					{
						item2.InputMessage = item.Prompt;
					}
					if (item.ErrorTitle != null)
					{
						item2.ErrorTitle = item.ErrorTitle;
					}
					if (item.Error != null)
					{
						item2.ErrorMessage = item.Error;
					}
					if (item.ErrorStyle != null)
					{
						item2.ErrorStyle = item.ErrorStyle.Value.ToClosedXml();
					}
					if (item.Type != null)
					{
						item2.AllowedValues = item.Type.Value.ToClosedXml();
					}
					if (item.Operator != null)
					{
						item2.Operator = item.Operator.Value.ToClosedXml();
					}
					if (item.Formula1 != null)
					{
						item2.MinValue = item.Formula1.Text;
					}
					if (item.Formula2 != null)
					{
						item2.MaxValue = item.Formula2.Text;
					}
				}
			}
		}

		private void LoadConditionalFormatting(DocumentFormat.OpenXml.Spreadsheet.ConditionalFormatting conditionalFormatting, XLWorksheet ws, Dictionary<int, DifferentialFormat> differentialFormats)
		{
			if (conditionalFormatting == null)
			{
				return;
			}
			foreach (StringValue item in conditionalFormatting.SequenceOfReferences.Items)
			{
				foreach (DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule item2 in conditionalFormatting.Elements<DocumentFormat.OpenXml.Spreadsheet.ConditionalFormattingRule>())
				{
					XLConditionalFormat xLConditionalFormat = new XLConditionalFormat(ws.Range(item.Value));
					if (item2.FormatId != null)
					{
						LoadFont(differentialFormats[(int)item2.FormatId.Value].Font, xLConditionalFormat.Style.Font);
						LoadFill(differentialFormats[(int)item2.FormatId.Value].Fill, xLConditionalFormat.Style.Fill);
						LoadBorder(differentialFormats[(int)item2.FormatId.Value].Border, xLConditionalFormat.Style.Border);
						LoadNumberFormat(differentialFormats[(int)item2.FormatId.Value].NumberingFormat, xLConditionalFormat.Style.NumberFormat);
					}
					if (item2.Operator != null)
					{
						xLConditionalFormat.Operator = item2.Operator.Value.ToClosedXml();
					}
					if (item2.Type != null)
					{
						xLConditionalFormat.ConditionalFormatType = item2.Type.Value.ToClosedXml();
					}
					if (item2.Text != null)
					{
						xLConditionalFormat.Values.Add(GetFormula(item2.Text.Value));
					}
					if (item2.Percent != null)
					{
						xLConditionalFormat.Percent = item2.Percent.Value;
					}
					if (item2.Bottom != null)
					{
						xLConditionalFormat.Bottom = item2.Bottom.Value;
					}
					if (item2.Rank != null)
					{
						xLConditionalFormat.Values.Add(GetFormula(item2.Rank.Value.ToString()));
					}
					if (item2.Elements<DocumentFormat.OpenXml.Spreadsheet.ColorScale>().Any())
					{
						DocumentFormat.OpenXml.Spreadsheet.ColorScale element = item2.Elements<DocumentFormat.OpenXml.Spreadsheet.ColorScale>().First();
						ExtractConditionalFormatValueObjects(xLConditionalFormat, element);
					}
					else if (item2.Elements<DocumentFormat.OpenXml.Spreadsheet.DataBar>().Any())
					{
						DocumentFormat.OpenXml.Spreadsheet.DataBar dataBar = item2.Elements<DocumentFormat.OpenXml.Spreadsheet.DataBar>().First();
						if (dataBar.ShowValue != null)
						{
							xLConditionalFormat.ShowBarOnly = !dataBar.ShowValue.Value;
						}
						ExtractConditionalFormatValueObjects(xLConditionalFormat, dataBar);
					}
					else if (item2.Elements<DocumentFormat.OpenXml.Spreadsheet.IconSet>().Any())
					{
						DocumentFormat.OpenXml.Spreadsheet.IconSet iconSet = item2.Elements<DocumentFormat.OpenXml.Spreadsheet.IconSet>().First();
						if (iconSet.ShowValue != null)
						{
							xLConditionalFormat.ShowIconOnly = !iconSet.ShowValue.Value;
						}
						if (iconSet.Reverse != null)
						{
							xLConditionalFormat.ReverseIconOrder = iconSet.Reverse.Value;
						}
						if (iconSet.IconSetValue != null)
						{
							xLConditionalFormat.IconSetStyle = iconSet.IconSetValue.Value.ToClosedXml();
						}
						else
						{
							xLConditionalFormat.IconSetStyle = XLIconSetStyle.ThreeTrafficLights1;
						}
						ExtractConditionalFormatValueObjects(xLConditionalFormat, iconSet);
					}
					else
					{
						foreach (DocumentFormat.OpenXml.Spreadsheet.Formula item3 in item2.Elements<DocumentFormat.OpenXml.Spreadsheet.Formula>())
						{
							if (item3.Text != null && (xLConditionalFormat.ConditionalFormatType == XLConditionalFormatType.CellIs || xLConditionalFormat.ConditionalFormatType == XLConditionalFormatType.Expression))
							{
								xLConditionalFormat.Values.Add(GetFormula(item3.Text));
							}
						}
					}
					ws.ConditionalFormats.Add(xLConditionalFormat);
				}
			}
		}

		private static XLFormula GetFormula(string value)
		{
			XLFormula xLFormula = new XLFormula();
			xLFormula._value = value;
			xLFormula.IsFormula = value[0] != '"' || !value.EndsWith("\"");
			return xLFormula;
		}

		private void ExtractConditionalFormatValueObjects(XLConditionalFormat conditionalFormat, OpenXmlElement element)
		{
			foreach (ConditionalFormatValueObject item in element.Elements<ConditionalFormatValueObject>())
			{
				if (item.Type != null)
				{
					conditionalFormat.ContentTypes.Add(item.Type.Value.ToClosedXml());
				}
				if (item.Val != null)
				{
					conditionalFormat.Values.Add(new XLFormula
					{
						Value = item.Val.Value
					});
				}
				if (item.GreaterThanOrEqual != null)
				{
					conditionalFormat.IconSetOperators.Add(item.GreaterThanOrEqual.Value ? XLCFIconSetOperator.EqualOrGreaterThan : XLCFIconSetOperator.GreaterThan);
				}
				else
				{
					conditionalFormat.IconSetOperators.Add(XLCFIconSetOperator.EqualOrGreaterThan);
				}
			}
			foreach (DocumentFormat.OpenXml.Spreadsheet.Color item2 in element.Elements<DocumentFormat.OpenXml.Spreadsheet.Color>())
			{
				conditionalFormat.Colors.Add(GetColor(item2));
			}
		}

		private static void LoadHyperlinks(Hyperlinks hyperlinks, WorksheetPart worksheetPart, XLWorksheet ws)
		{
			Dictionary<string, Uri> dictionary = new Dictionary<string, Uri>();
			if (worksheetPart.HyperlinkRelationships != null)
			{
				dictionary = worksheetPart.HyperlinkRelationships.ToDictionary((HyperlinkRelationship hr) => hr.Id, (HyperlinkRelationship hr) => hr.Uri);
			}
			if (hyperlinks == null)
			{
				return;
			}
			foreach (DocumentFormat.OpenXml.Spreadsheet.Hyperlink item in hyperlinks.Elements<DocumentFormat.OpenXml.Spreadsheet.Hyperlink>())
			{
				if (item.Reference.Value.Equals("#REF"))
				{
					continue;
				}
				string tooltip = ((item.Tooltip != null) ? item.Tooltip.Value : string.Empty);
				XLRange xLRange = ws.Range(item.Reference.Value);
				foreach (XLCell item2 in xLRange.Cells())
				{
					item2.SettingHyperlink = true;
					if (item.Id != null)
					{
						item2.Hyperlink = new XLHyperlink(dictionary[item.Id], tooltip);
					}
					else if (item.Location != null)
					{
						item2.Hyperlink = new XLHyperlink(item.Location.Value, tooltip);
					}
					else
					{
						item2.Hyperlink = new XLHyperlink(item.Reference.Value, tooltip);
					}
					item2.SettingHyperlink = false;
				}
			}
		}

