		private XLColor GetColor(DocumentFormat.OpenXml.Spreadsheet.ColorType color)
		{
			XLColor xLColor = null;
			if (color != null)
			{
				if (color.Rgb != null)
				{
					string text = "#" + color.Rgb.Value;
					System.Drawing.Color color2;
					if (!_colorList.ContainsKey(text))
					{
						color2 = ColorTranslator.FromHtml(text);
						_colorList.Add(text, color2);
					}
					else
					{
						color2 = _colorList[text];
					}
					xLColor = new XLColor(color2);
				}
				else if (color.Indexed != null && (uint)color.Indexed < 64)
				{
					xLColor = new XLColor((int)color.Indexed.Value);
				}
				else if (color.Theme != null)
				{
					xLColor = ((color.Tint != null) ? XLColor.FromTheme((XLThemeColor)color.Theme.Value, color.Tint.Value) : XLColor.FromTheme((XLThemeColor)color.Theme.Value));
				}
			}
			return xLColor ?? new XLColor();
		}

		private void ApplyStyle(IXLStylized xlStylized, int styleIndex, Stylesheet s, Fills fills, Borders borders, DocumentFormat.OpenXml.Spreadsheet.Fonts fonts, NumberingFormats numberingFormats)
		{
			CellFormat cellFormat = (CellFormat)s.CellFormats.ElementAt(styleIndex);
			if (cellFormat.ApplyProtection != null)
			{
				Protection protection = cellFormat.Protection;
				if (protection == null)
				{
					xlStylized.InnerStyle.Protection = new XLProtection(null, DefaultStyle.Protection);
				}
				else
				{
					xlStylized.InnerStyle.Protection.Hidden = protection.Hidden != null && protection.Hidden.HasValue && protection.Hidden.Value;
					xlStylized.InnerStyle.Protection.Locked = protection.Locked == null || (protection.Locked.HasValue && protection.Locked.Value);
				}
			}
			if (UInt32HasValue(cellFormat.FillId))
			{
				DocumentFormat.OpenXml.Spreadsheet.Fill fill = (DocumentFormat.OpenXml.Spreadsheet.Fill)fills.ElementAt((int)cellFormat.FillId.Value);
				if (fill.PatternFill != null)
				{
					if (fill.PatternFill.PatternType != null)
					{
						xlStylized.InnerStyle.Fill.PatternType = fill.PatternFill.PatternType.Value.ToClosedXml();
					}
					XLColor color = GetColor(fill.PatternFill.ForegroundColor);
					if (color.HasValue)
					{
						xlStylized.InnerStyle.Fill.PatternColor = color;
					}
					XLColor color2 = GetColor(fill.PatternFill.BackgroundColor);
					if (color2.HasValue)
					{
						xlStylized.InnerStyle.Fill.PatternBackgroundColor = color2;
					}
				}
			}
			Alignment alignment = cellFormat.Alignment;
			if (alignment != null)
			{
				if (alignment.Horizontal != null)
				{
					xlStylized.InnerStyle.Alignment.Horizontal = alignment.Horizontal.Value.ToClosedXml();
				}
				if (alignment.Indent != null && (uint)alignment.Indent != 0)
				{
					xlStylized.InnerStyle.Alignment.Indent = int.Parse(alignment.Indent.ToString());
				}
				if (alignment.JustifyLastLine != null)
				{
					xlStylized.InnerStyle.Alignment.JustifyLastLine = alignment.JustifyLastLine;
				}
				if (alignment.ReadingOrder != null)
				{
					xlStylized.InnerStyle.Alignment.ReadingOrder = (XLAlignmentReadingOrderValues)int.Parse(alignment.ReadingOrder.ToString());
				}
				if (alignment.RelativeIndent != null)
				{
					xlStylized.InnerStyle.Alignment.RelativeIndent = alignment.RelativeIndent;
				}
				if (alignment.ShrinkToFit != null)
				{
					xlStylized.InnerStyle.Alignment.ShrinkToFit = alignment.ShrinkToFit;
				}
				if (alignment.TextRotation != null)
				{
					xlStylized.InnerStyle.Alignment.TextRotation = (int)alignment.TextRotation.Value;
				}
				if (alignment.Vertical != null)
				{
					xlStylized.InnerStyle.Alignment.Vertical = alignment.Vertical.Value.ToClosedXml();
				}
				if (alignment.WrapText != null)
				{
					xlStylized.InnerStyle.Alignment.WrapText = alignment.WrapText;
				}
			}
			if (UInt32HasValue(cellFormat.BorderId))
			{
				uint value = cellFormat.BorderId.Value;
				Border border = (Border)borders.ElementAt((int)value);
				if (border != null)
				{
					DocumentFormat.OpenXml.Spreadsheet.BottomBorder bottomBorder = border.BottomBorder;
					if (bottomBorder != null)
					{
						if (bottomBorder.Style != null)
						{
							xlStylized.InnerStyle.Border.BottomBorder = bottomBorder.Style.Value.ToClosedXml();
						}
						XLColor color3 = GetColor(bottomBorder.Color);
						if (color3.HasValue)
						{
							xlStylized.InnerStyle.Border.BottomBorderColor = color3;
						}
					}
					DocumentFormat.OpenXml.Spreadsheet.TopBorder topBorder = border.TopBorder;
					if (topBorder != null)
					{
						if (topBorder.Style != null)
						{
							xlStylized.InnerStyle.Border.TopBorder = topBorder.Style.Value.ToClosedXml();
						}
						XLColor color4 = GetColor(topBorder.Color);
						if (color4.HasValue)
						{
							xlStylized.InnerStyle.Border.TopBorderColor = color4;
						}
					}
					DocumentFormat.OpenXml.Spreadsheet.LeftBorder leftBorder = border.LeftBorder;
					if (leftBorder != null)
					{
						if (leftBorder.Style != null)
						{
							xlStylized.InnerStyle.Border.LeftBorder = leftBorder.Style.Value.ToClosedXml();
						}
						XLColor color5 = GetColor(leftBorder.Color);
						if (color5.HasValue)
						{
							xlStylized.InnerStyle.Border.LeftBorderColor = color5;
						}
					}
					DocumentFormat.OpenXml.Spreadsheet.RightBorder rightBorder = border.RightBorder;
					if (rightBorder != null)
					{
						if (rightBorder.Style != null)
						{
							xlStylized.InnerStyle.Border.RightBorder = rightBorder.Style.Value.ToClosedXml();
						}
						XLColor color6 = GetColor(rightBorder.Color);
						if (color6.HasValue)
						{
							xlStylized.InnerStyle.Border.RightBorderColor = color6;
						}
					}
					DiagonalBorder diagonalBorder = border.DiagonalBorder;
					if (diagonalBorder != null)
					{
						if (diagonalBorder.Style != null)
						{
							xlStylized.InnerStyle.Border.DiagonalBorder = diagonalBorder.Style.Value.ToClosedXml();
						}
						XLColor color7 = GetColor(diagonalBorder.Color);
						if (color7.HasValue)
						{
							xlStylized.InnerStyle.Border.DiagonalBorderColor = color7;
						}
						if (border.DiagonalDown != null)
						{
							xlStylized.InnerStyle.Border.DiagonalDown = border.DiagonalDown;
						}
						if (border.DiagonalUp != null)
						{
							xlStylized.InnerStyle.Border.DiagonalUp = border.DiagonalUp;
						}
					}
				}
			}
			if (UInt32HasValue(cellFormat.FontId))
			{
				UInt32Value fontId = cellFormat.FontId;
				Font font = (Font)fonts.ElementAt((int)fontId.Value);
				if (font != null)
				{
					xlStylized.InnerStyle.Font.Bold = GetBoolean(font.Bold);
					XLColor color8 = GetColor(font.Color);
					if (color8.HasValue)
					{
						xlStylized.InnerStyle.Font.FontColor = color8;
					}
					if (font.FontFamilyNumbering != null && font.FontFamilyNumbering.Val != null)
					{
						xlStylized.InnerStyle.Font.FontFamilyNumbering = (XLFontFamilyNumberingValues)int.Parse(font.FontFamilyNumbering.Val.ToString());
					}
					if (font.FontName != null && font.FontName.Val != null)
					{
						xlStylized.InnerStyle.Font.FontName = font.FontName.Val;
					}
					if (font.FontSize != null && font.FontSize.Val != null)
					{
						xlStylized.InnerStyle.Font.FontSize = font.FontSize.Val;
					}
					xlStylized.InnerStyle.Font.Italic = GetBoolean(font.Italic);
					xlStylized.InnerStyle.Font.Shadow = GetBoolean(font.Shadow);
					xlStylized.InnerStyle.Font.Strikethrough = GetBoolean(font.Strike);
					if (font.Underline != null)
					{
						xlStylized.InnerStyle.Font.Underline = ((font.Underline.Val != null) ? font.Underline.Val.Value.ToClosedXml() : XLFontUnderlineValues.Single);
					}
					if (font.VerticalTextAlignment != null)
					{
						xlStylized.InnerStyle.Font.VerticalAlignment = ((font.VerticalTextAlignment.Val != null) ? font.VerticalTextAlignment.Val.Value.ToClosedXml() : XLFontVerticalTextAlignmentValues.Baseline);
					}
				}
			}
			if (UInt32HasValue(cellFormat.NumberFormatId))
			{
				UInt32Value numberFormatId = cellFormat.NumberFormatId;
				string text = string.Empty;
				if (numberingFormats != null && numberingFormats.FirstOrDefault((OpenXmlElement nf) => ((NumberingFormat)nf).NumberFormatId != null && ((NumberingFormat)nf).NumberFormatId.Value == (uint)numberFormatId) is NumberingFormat { FormatCode: not null } numberingFormat)
				{
					text = numberingFormat.FormatCode.Value;
				}
				if (text.Length > 0)
				{
					xlStylized.InnerStyle.NumberFormat.Format = text;
				}
				else
				{
					xlStylized.InnerStyle.NumberFormat.NumberFormatId = (int)numberFormatId.Value;
				}
			}
		}

		private static bool UInt32HasValue(UInt32Value value)
		{
			return value?.HasValue ?? false;
		}

		private static bool GetBoolean(BooleanPropertyType property)
		{
			if (property != null)
			{
				if (property.Val != null)
				{
					return property.Val;
				}
				return true;
			}
			return false;
		}

		private static EnumValue<CellValues> GetCellValue(XLCell xlCell)
		{
			switch (xlCell.DataType)
			{
			case XLCellValues.Text:
				if (!xlCell.ShareString)
				{
					return CvInlineString;
				}
				return CvSharedString;
			case XLCellValues.Number:
				return CvNumber;
			case XLCellValues.DateTime:
				return CvDate;
			case XLCellValues.Boolean:
				return CvBoolean;
			case XLCellValues.TimeSpan:
				return CvNumber;
			default:
				throw new NotImplementedException();
			}
		}

		private void CreatePackage(string filePath)
		{
			PathHelper.CreateDirectory(System.IO.Path.GetDirectoryName(filePath));
			SpreadsheetDocument spreadsheetDocument = (File.Exists(filePath) ? SpreadsheetDocument.Open(filePath, isEditable: true) : SpreadsheetDocument.Create(filePath, SpreadsheetDocumentType.Workbook));
			using (spreadsheetDocument)
			{
				CreateParts(spreadsheetDocument);
			}
		}

		private void CreatePackage(Stream stream, bool newStream)
		{
			SpreadsheetDocument spreadsheetDocument = (newStream ? SpreadsheetDocument.Create(stream, SpreadsheetDocumentType.Workbook) : SpreadsheetDocument.Open(stream, isEditable: true));
			using (spreadsheetDocument)
			{
				CreateParts(spreadsheetDocument);
			}
		}

		private void CreateParts(SpreadsheetDocument document)
		{
			SaveContext saveContext = new SaveContext();
			WorkbookPart workbookPart = document.WorkbookPart ?? document.AddWorkbookPart();
			XLWorksheets worksheets = WorksheetsInternal;
			List<IdPartPair> list = workbookPart.Parts.Where((IdPartPair s) => worksheets.Deleted.Contains(s.RelationshipId)).ToList();
			list.ForEach(delegate(IdPartPair s)
			{
				workbookPart.DeletePart(s.OpenXmlPart);
			});
			saveContext.RelIdGenerator.AddValues(workbookPart.Parts.Select((IdPartPair p) => p.RelationshipId).ToList(), RelType.Workbook);
			ExtendedFilePropertiesPart extendedFilePropertiesPart = document.ExtendedFilePropertiesPart ?? document.AddNewPart<ExtendedFilePropertiesPart>(saveContext.RelIdGenerator.GetNext(RelType.Workbook));
			GenerateExtendedFilePropertiesPartContent(extendedFilePropertiesPart);
			GenerateWorkbookPartContent(workbookPart, saveContext);
			SharedStringTablePart sharedStringTablePart = workbookPart.SharedStringTablePart ?? workbookPart.AddNewPart<SharedStringTablePart>(saveContext.RelIdGenerator.GetNext(RelType.Workbook));
			GenerateSharedStringTablePartContent(sharedStringTablePart, saveContext);
			WorkbookStylesPart workbookStylesPart = workbookPart.WorkbookStylesPart ?? workbookPart.AddNewPart<WorkbookStylesPart>(saveContext.RelIdGenerator.GetNext(RelType.Workbook));
			GenerateWorkbookStylesPartContent(workbookStylesPart, saveContext);
			foreach (XLWorksheet item in from XLWorksheet w in WorksheetsInternal
				orderby w.Position
				select w)
			{
				string wsRelId = item.RelId;
				WorksheetPart worksheetPart;
				if (workbookPart.Parts.Any((IdPartPair p) => p.RelationshipId == wsRelId))
				{
					worksheetPart = (WorksheetPart)workbookPart.GetPartById(wsRelId);
					List<TableDefinitionPart> list2 = worksheetPart.TableDefinitionParts.ToList();
					list2.ForEach(delegate(TableDefinitionPart tdp)
					{
						worksheetPart.DeletePart(tdp);
					});
				}
				else
				{
					worksheetPart = workbookPart.AddNewPart<WorksheetPart>(wsRelId);
				}
				saveContext.RelIdGenerator.AddValues(worksheetPart.HyperlinkRelationships.Select((HyperlinkRelationship hr) => hr.Id).ToList(), RelType.Workbook);
				saveContext.RelIdGenerator.AddValues(worksheetPart.Parts.Select((IdPartPair p) => p.RelationshipId).ToList(), RelType.Workbook);
				if (worksheetPart.DrawingsPart != null)
				{
					saveContext.RelIdGenerator.AddValues(worksheetPart.DrawingsPart.Parts.Select((IdPartPair p) => p.RelationshipId).ToList(), RelType.Workbook);
				}
				DeleteComments(worksheetPart, item, saveContext);
				if (item.Internals.CellsCollection.GetCells((IXLCell c) => c.HasComment).Any())
				{
					WorksheetCommentsPart worksheetCommentsPart = worksheetPart.AddNewPart<WorksheetCommentsPart>(saveContext.RelIdGenerator.GetNext(RelType.Workbook));
					GenerateWorksheetCommentsPartContent(worksheetCommentsPart, item);
					VmlDrawingPart vmlDrawingPart = worksheetPart.VmlDrawingParts.FirstOrDefault();
					if (vmlDrawingPart == null)
					{
						if (XLHelper.IsNullOrWhiteSpace(item.LegacyDrawingId))
						{
							item.LegacyDrawingId = saveContext.RelIdGenerator.GetNext(RelType.Workbook);
							item.LegacyDrawingIsNew = true;
						}
						vmlDrawingPart = worksheetPart.AddNewPart<VmlDrawingPart>(item.LegacyDrawingId);
					}
					GenerateVmlDrawingPartContent(vmlDrawingPart, item, saveContext);
				}
				GenerateWorksheetPartContent(worksheetPart, item, saveContext);
				if (item.PivotTables.Any())
				{
					GeneratePivotTables(workbookPart, worksheetPart, item, saveContext);
				}
			}
			GenerateCalculationChainPartContent(workbookPart, saveContext);
			if (workbookPart.ThemePart == null)
			{
				ThemePart themePart = workbookPart.AddNewPart<ThemePart>(saveContext.RelIdGenerator.GetNext(RelType.Workbook));
				GenerateThemePartContent(themePart);
			}
			if (CustomProperties.Any())
			{
				document.GetPartsOfType<CustomFilePropertiesPart>().ToList().ForEach(delegate(CustomFilePropertiesPart p)
				{
					document.DeletePart(p);
				});
				CustomFilePropertiesPart customFilePropertiesPart = document.AddNewPart<CustomFilePropertiesPart>(saveContext.RelIdGenerator.GetNext(RelType.Workbook));
				GenerateCustomFilePropertiesPartContent(customFilePropertiesPart);
			}
			SetPackageProperties(document);
		}

		private void DeleteComments(WorksheetPart worksheetPart, XLWorksheet worksheet, SaveContext context)
		{
			worksheetPart.DeletePart(worksheetPart.WorksheetCommentsPart);
			VmlDrawingPart vmlDrawingPart = worksheetPart.VmlDrawingParts.FirstOrDefault();
			if (vmlDrawingPart == null)
			{
				return;
			}
			XDocument val = XDocumentExtensions.Load(vmlDrawingPart.GetStream(FileMode.Open));
			Extensions.Remove<XElement>(from e in ((XContainer)val.Root).Elements()
				where e.Name.LocalName == "shapetype" && (string)e.Attribute(XName.op_Implicit("id")) == "_x0000_t202"
				select e);
			Extensions.Remove<XElement>(from e in ((XContainer)val.Root).Elements()
				where e.Name.LocalName == "shape" && (string)e.Attribute(XName.op_Implicit("type")) == "#_x0000_t202"
				select e);
			List<ImagePart> list = vmlDrawingPart.ImageParts.ToList();
			List<LegacyDiagramTextPart> list2 = vmlDrawingPart.LegacyDiagramTextParts.ToList();
			string text = (worksheet.LegacyDrawingId = worksheetPart.GetIdOfPart(vmlDrawingPart));
			worksheetPart.ChangeIdOfPart(vmlDrawingPart, "xxRRxx");
			bool flag = ((XContainer)val.Root).Elements().Any((XElement e) => e.Name.LocalName == "shape" || e.Name.LocalName == "group");
			VmlDrawingPart vmlDrawingPartNew = null;
			bool flag2 = list.Count > 0 || list2.Count > 0 || flag;
			if (flag2)
			{
				vmlDrawingPartNew = worksheetPart.AddNewPart<VmlDrawingPart>(text);
				using (XmlTextWriter xmlTextWriter = new XmlTextWriter(vmlDrawingPartNew.GetStream(FileMode.Create), Encoding.UTF8))
				{
					xmlTextWriter.WriteRaw(((object)val).ToString());
				}
				list.ForEach(delegate(ImagePart p)
				{
					vmlDrawingPartNew.AddPart(p, vmlDrawingPart.GetIdOfPart(p));
				});
				list2.ForEach(delegate(LegacyDiagramTextPart p)
				{
					vmlDrawingPartNew.AddPart(p, vmlDrawingPart.GetIdOfPart(p));
				});
			}
			worksheetPart.DeletePart(vmlDrawingPart);
			if (flag2 && text != worksheetPart.GetIdOfPart(vmlDrawingPartNew))
			{
				worksheetPart.ChangeIdOfPart(vmlDrawingPartNew, text);
			}
		}

		private static void GenerateTables(XLWorksheet worksheet, WorksheetPart worksheetPart, SaveContext context)
		{
			worksheetPart.Worksheet.RemoveAllChildren<TablePart>();
			if (!worksheet.Tables.Any())
			{
				return;
			}
			foreach (IXLTable table in worksheet.Tables)
			{
				string next = context.RelIdGenerator.GetNext(RelType.Workbook);
				XLTable xLTable = (XLTable)table;
				xLTable.RelId = next;
				TableDefinitionPart tableDefinitionPart = worksheetPart.AddNewPart<TableDefinitionPart>(next);
				GenerateTableDefinitionPartContent(tableDefinitionPart, xLTable, context);
			}
		}

		private void GenerateExtendedFilePropertiesPartContent(ExtendedFilePropertiesPart extendedFilePropertiesPart)
		{
			if (extendedFilePropertiesPart.Properties == null)
			{
				extendedFilePropertiesPart.Properties = new DocumentFormat.OpenXml.ExtendedProperties.Properties();
			}
			DocumentFormat.OpenXml.ExtendedProperties.Properties properties = extendedFilePropertiesPart.Properties;
			if (!properties.NamespaceDeclarations.Contains(new KeyValuePair<string, string>("vt", "http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes")))
			{
				properties.AddNamespaceDeclaration("vt", "http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes");
			}
			if (properties.Application == null)
			{
				properties.AppendChild(new Application
				{
					Text = "Microsoft Excel"
				});
			}
			if (properties.DocumentSecurity == null)
			{
				properties.AppendChild(new DocumentSecurity
				{
					Text = "0"
				});
			}
			if (properties.ScaleCrop == null)
			{
				properties.AppendChild(new ScaleCrop
				{
					Text = "false"
				});
			}
			if (properties.HeadingPairs == null)
			{
				properties.HeadingPairs = new HeadingPairs();
			}
			if (properties.TitlesOfParts == null)
			{
				properties.TitlesOfParts = new TitlesOfParts();
			}
			properties.HeadingPairs.VTVector = new VTVector
			{
				BaseType = VectorBaseValues.Variant
			};
			properties.TitlesOfParts.VTVector = new VTVector
			{
				BaseType = VectorBaseValues.Lpstr
			};
			VTVector vTVector = properties.HeadingPairs.VTVector;
			VTVector vTVector2 = properties.TitlesOfParts.VTVector;
			var list = WorksheetsInternal.Select((XLWorksheet w) => new
			{
				Name = w.Name,
				Order = w.Position
			}).ToList();
			List<string> modifiedNamedRanges = GetModifiedNamedRanges();
			int count = list.Count;
			int count2 = modifiedNamedRanges.Count;
			InsertOnVtVector(vTVector, "Worksheets", 0, count.ToString());
			InsertOnVtVector(vTVector, "Named Ranges", 2, count2.ToString());
			vTVector2.Size = (uint)(count2 + count);
			foreach (VTLPSTR item in from w in list
				orderby w.Order
				select new VTLPSTR
				{
					Text = w.Name
				})
			{
				vTVector2.AppendChild(item);
			}
			foreach (VTLPSTR item2 in modifiedNamedRanges.Select((string nr) => new VTLPSTR
			{
				Text = nr
			}))
			{
				vTVector2.AppendChild(item2);
			}
			if (Properties.Manager != null)
			{
				if (!XLHelper.IsNullOrWhiteSpace(Properties.Manager))
				{
					if (properties.Manager == null)
					{
						properties.Manager = new Manager();
					}
					properties.Manager.Text = Properties.Manager;
				}
				else
				{
					properties.Manager = null;
				}
			}
			if (Properties.Company == null)
			{
				return;
			}
			if (!XLHelper.IsNullOrWhiteSpace(Properties.Company))
			{
				if (properties.Company == null)
				{
					properties.Company = new Company();
				}
				properties.Company.Text = Properties.Company;
			}
			else
			{
				properties.Company = null;
			}
		}

		private static void InsertOnVtVector(VTVector vTVector, string property, int index, string text)
		{
			IEnumerable<Variant> source = from e1 in vTVector.Elements<Variant>()
				where e1.Elements<VTLPSTR>().Any((VTLPSTR e2) => e2.Text == property)
				select e1;
			if (!source.Any())
			{
				if (vTVector.Size == null)
				{
					vTVector.Size = new UInt32Value(0u);
				}
				vTVector.Size = (uint)vTVector.Size + 2;
				Variant variant = new Variant();
				VTLPSTR vTLPSTR = new VTLPSTR();
				vTLPSTR.Text = property;
				VTLPSTR newChild = vTLPSTR;
				variant.AppendChild(newChild);
				vTVector.InsertAt(variant, index);
				Variant variant2 = new Variant();
				VTInt32 newChild2 = new VTInt32();
				variant2.AppendChild(newChild2);
				vTVector.InsertAt(variant2, index + 1);
			}
			int num = 0;
			foreach (Variant item in vTVector.Elements<Variant>())
			{
				if (item.Elements<VTLPSTR>().Any((VTLPSTR e2) => e2.Text == property))
				{
					vTVector.ElementAt(num + 1).GetFirstChild<VTInt32>().Text = text;
					break;
				}
				num++;
			}
		}

		private List<string> GetModifiedNamedRanges()
		{
			List<string> list = new List<string>();
			foreach (XLWorksheet item in WorksheetsInternal)
			{
				string wName = item.Name;
				list.AddRange(item.NamedRanges.Select((IXLNamedRange n) => wName + "!" + n.Name));
				list.Add(item.Name + "!Print_Area");
				list.Add(item.Name + "!Print_Titles");
			}
			list.AddRange(NamedRanges.Select((IXLNamedRange n) => n.Name));
			return list;
		}

