		private void GenerateSharedStringTablePartContent(SharedStringTablePart sharedStringTablePart, SaveContext context)
		{
			int x = 0;
			Worksheets.ForEach(delegate(IXLWorksheet w)
			{
				w.Tables.ForEach(delegate(IXLTable t)
				{
					x = (t as XLTable).FieldNames.Count;
				});
			});
			sharedStringTablePart.SharedStringTable = new SharedStringTable
			{
				Count = 0u,
				UniqueCount = 0u
			};
			int num = 0;
			Dictionary<string, int> dictionary = new Dictionary<string, int>();
			Dictionary<IXLRichText, int> dictionary2 = new Dictionary<IXLRichText, int>();
			foreach (XLCell item in Worksheets.Cast<XLWorksheet>().SelectMany((XLWorksheet w) => w.Internals.CellsCollection.GetCells((IXLCell c) => ((c.DataType == XLCellValues.Text && c.ShareString) || c.HasRichText) && (c as XLCell).InnerText.Length > 0 && XLHelper.IsNullOrWhiteSpace(c.FormulaA1))))
			{
				item.DataType = XLCellValues.Text;
				if (item.HasRichText)
				{
					if (dictionary2.ContainsKey(item.RichText))
					{
						item.SharedStringId = dictionary2[item.RichText];
						continue;
					}
					SharedStringItem sharedStringItem = new SharedStringItem();
					foreach (IXLRichString item2 in item.RichText)
					{
						sharedStringItem.Append(GetRun(item2));
					}
					if (item.RichText.HasPhonetics)
					{
						foreach (IXLPhonetic phonetic in item.RichText.Phonetics)
						{
							PhoneticRun phoneticRun = new PhoneticRun();
							phoneticRun.BaseTextStartIndex = (uint)phonetic.Start;
							phoneticRun.EndingBaseIndex = (uint)phonetic.End;
							PhoneticRun phoneticRun2 = phoneticRun;
							DocumentFormat.OpenXml.Spreadsheet.Text text = new DocumentFormat.OpenXml.Spreadsheet.Text();
							text.Text = phonetic.Text;
							DocumentFormat.OpenXml.Spreadsheet.Text text2 = text;
							if (phonetic.Text.PreserveSpaces())
							{
								text2.Space = SpaceProcessingModeValues.Preserve;
							}
							phoneticRun2.Append(text2);
							sharedStringItem.Append(phoneticRun2);
						}
						XLFont xLFont = new XLFont(null, item.RichText.Phonetics);
						if (!context.SharedFonts.ContainsKey(xLFont))
						{
							context.SharedFonts.Add(xLFont, new FontInfo
							{
								Font = xLFont
							});
						}
						PhoneticProperties phoneticProperties = new PhoneticProperties();
						phoneticProperties.FontId = context.SharedFonts[new XLFont(null, item.RichText.Phonetics)].FontId;
						PhoneticProperties phoneticProperties2 = phoneticProperties;
						if (item.RichText.Phonetics.Alignment != XLPhoneticAlignment.Left)
						{
							phoneticProperties2.Alignment = item.RichText.Phonetics.Alignment.ToOpenXml();
						}
						if (item.RichText.Phonetics.Type != 0)
						{
							phoneticProperties2.Type = item.RichText.Phonetics.Type.ToOpenXml();
						}
						sharedStringItem.Append(phoneticProperties2);
					}
					sharedStringTablePart.SharedStringTable.Append(sharedStringItem);
					SharedStringTable sharedStringTable = sharedStringTablePart.SharedStringTable;
					sharedStringTable.Count = (uint)sharedStringTable.Count + 1;
					SharedStringTable sharedStringTable2 = sharedStringTablePart.SharedStringTable;
					sharedStringTable2.UniqueCount = (uint)sharedStringTable2.UniqueCount + 1;
					dictionary2.Add(item.RichText, num);
					item.SharedStringId = num;
					num++;
				}
				else if (dictionary.ContainsKey(item.Value.ToString()))
				{
					item.SharedStringId = dictionary[item.Value.ToString()];
				}
				else
				{
					string text3 = item.Value.ToString();
					SharedStringItem sharedStringItem2 = new SharedStringItem();
