		private static DocumentFormat.OpenXml.Spreadsheet.Run GetRun(IXLRichString rt)
		{
			DocumentFormat.OpenXml.Spreadsheet.Run run = new DocumentFormat.OpenXml.Spreadsheet.Run();
			DocumentFormat.OpenXml.Spreadsheet.RunProperties runProperties = new DocumentFormat.OpenXml.Spreadsheet.RunProperties();
			Bold bold = (rt.Bold ? new Bold() : null);
			Italic italic = (rt.Italic ? new Italic() : null);
			object obj;
			if (rt.Underline == XLFontUnderlineValues.None)
			{
				obj = null;
			}
			else
			{
				DocumentFormat.OpenXml.Spreadsheet.Underline underline = new DocumentFormat.OpenXml.Spreadsheet.Underline();
				underline.Val = rt.Underline.ToOpenXml();
				obj = underline;
			}
			DocumentFormat.OpenXml.Spreadsheet.Underline underline2 = (DocumentFormat.OpenXml.Spreadsheet.Underline)obj;
			Strike strike = (rt.Strikethrough ? new Strike() : null);
			DocumentFormat.OpenXml.Spreadsheet.VerticalTextAlignment verticalTextAlignment = new DocumentFormat.OpenXml.Spreadsheet.VerticalTextAlignment();
			verticalTextAlignment.Val = rt.VerticalAlignment.ToOpenXml();
			DocumentFormat.OpenXml.Spreadsheet.VerticalTextAlignment verticalTextAlignment2 = verticalTextAlignment;
			DocumentFormat.OpenXml.Spreadsheet.Shadow shadow = (rt.Shadow ? new DocumentFormat.OpenXml.Spreadsheet.Shadow() : null);
			FontSize fontSize = new FontSize();
			fontSize.Val = rt.FontSize;
			FontSize fontSize2 = fontSize;
			DocumentFormat.OpenXml.Spreadsheet.Color newColor = GetNewColor(rt.FontColor);
			RunFont runFont = new RunFont();
			runFont.Val = rt.FontName;
			RunFont runFont2 = runFont;
			FontFamily fontFamily = new FontFamily();
			fontFamily.Val = (int)rt.FontFamilyNumbering;
			FontFamily fontFamily2 = fontFamily;
			if (bold != null)
			{
				runProperties.Append(bold);
			}
			if (italic != null)
			{
				runProperties.Append(italic);
			}
			if (strike != null)
			{
				runProperties.Append(strike);
			}
			if (shadow != null)
			{
				runProperties.Append(shadow);
			}
			if (underline2 != null)
			{
				runProperties.Append(underline2);
			}
			runProperties.Append(verticalTextAlignment2);
			runProperties.Append(fontSize2);
			runProperties.Append(newColor);
			runProperties.Append(runFont2);
			runProperties.Append(fontFamily2);
			DocumentFormat.OpenXml.Spreadsheet.Text text = new DocumentFormat.OpenXml.Spreadsheet.Text();
			text.Text = rt.Text;
			DocumentFormat.OpenXml.Spreadsheet.Text text2 = text;
			if (rt.Text.PreserveSpaces())
			{
				text2.Space = SpaceProcessingModeValues.Preserve;
			}
			run.Append(runProperties);
			run.Append(text2);
			return run;
		}

		private void GenerateCalculationChainPartContent(WorkbookPart workbookPart, SaveContext context)
		{
			string next = context.RelIdGenerator.GetNext(RelType.Workbook);
			if (workbookPart.CalculationChainPart == null)
			{
				workbookPart.AddNewPart<CalculationChainPart>(next);
			}
			if (workbookPart.CalculationChainPart.CalculationChain == null)
			{
				workbookPart.CalculationChainPart.CalculationChain = new CalculationChain();
			}
			CalculationChain calculationChain = workbookPart.CalculationChainPart.CalculationChain;
			calculationChain.RemoveAllChildren<CalculationCell>();
			foreach (XLWorksheet item in WorksheetsInternal)
			{
				HashSet<string> cellsWithoutFormulas = new HashSet<string>();
				foreach (XLCell cell in item.Internals.CellsCollection.GetCells())
				{
					if (XLHelper.IsNullOrWhiteSpace(cell.FormulaA1))
					{
						cellsWithoutFormulas.Add(cell.Address.ToStringRelative());
					}
					else if (cell.FormulaA1.StartsWith("{"))
					{
						CalculationCell calculationCell = new CalculationCell();
						calculationCell.CellReference = cell.Address.ToString();
						calculationCell.SheetId = item.SheetId;
						CalculationCell calculationCell2 = calculationCell;
						if (cell.FormulaReference.FirstAddress.Equals(cell.Address))
						{
							calculationCell2.Array = true;
							calculationChain.AppendChild(calculationCell2);
							calculationChain.AppendChild(new CalculationCell
							{
								CellReference = cell.Address.ToString(),
								InChildChain = true
							});
						}
						else
						{
							calculationChain.AppendChild(calculationCell2);
						}
					}
					else
					{
						calculationChain.AppendChild(new CalculationCell
						{
							CellReference = cell.Address.ToString(),
							SheetId = item.SheetId
						});
					}
				}
				IEnumerable<CalculationCell> source = from cc in calculationChain.Elements<CalculationCell>()
					where (cc.SheetId == null && cc.InChildChain == null && (from c1 in calculationChain.Elements<CalculationCell>()
						where c1.SheetId != null
						select c1.CellReference.Value).Contains(cc.CellReference.Value)) || cellsWithoutFormulas.Contains(cc.CellReference.Value)
					select cc;
				source.ToList().ForEach(delegate(CalculationCell cc)
				{
					calculationChain.RemoveChild(cc);
				});
			}
			if (!calculationChain.Any())
			{
				workbookPart.DeletePart(workbookPart.CalculationChainPart);
			}
		}

