		private static string GetTableName(string originalTableName, SaveContext context)
		{
			string text = originalTableName.RemoveSpecialCharacters();
			string text2 = text;
			if (context.TableNames.Contains(text2))
			{
				int num = 1;
				text2 = text + num.ToStringLookup();
				while (context.TableNames.Contains(text2))
				{
					num++;
					text2 = text + num.ToStringLookup();
				}
			}
			context.TableNames.Add(text2);
			return text2;
		}

		private static void GenerateTableDefinitionPartContent(TableDefinitionPart tableDefinitionPart, XLTable xlTable, SaveContext context)
		{
			context.TableId++;
			string text = string.Concat(xlTable.RangeAddress.FirstAddress, ":", xlTable.RangeAddress.LastAddress);
			string tableName = GetTableName(xlTable.Name, context);
			DocumentFormat.OpenXml.Spreadsheet.Table table = new DocumentFormat.OpenXml.Spreadsheet.Table();
			table.Id = context.TableId;
			table.Name = tableName;
