		private static void GeneratePivotTables(WorkbookPart workbookPart, WorksheetPart worksheetPart, XLWorksheet xlWorksheet, SaveContext context)
		{
			foreach (IXLPivotTable pivotTable in xlWorksheet.PivotTables)
			{
				string next = context.RelIdGenerator.GetNext(RelType.Workbook);
				PivotTableCacheDefinitionPart pivotTableCacheDefinitionPart = workbookPart.AddNewPart<PivotTableCacheDefinitionPart>(next);
				GeneratePivotTableCacheDefinitionPartContent(pivotTableCacheDefinitionPart, pivotTable);
				DocumentFormat.OpenXml.Spreadsheet.PivotCaches pivotCaches = new DocumentFormat.OpenXml.Spreadsheet.PivotCaches();
				PivotCache pivotCache = new PivotCache();
				pivotCache.CacheId = 0u;
