				PivotCache newChild = pivotCache;
				pivotCaches.AppendChild(newChild);
				workbookPart.Workbook.AppendChild(pivotCaches);
				PivotTablePart pivotTablePart = worksheetPart.AddNewPart<PivotTablePart>(context.RelIdGenerator.GetNext(RelType.Workbook));
				GeneratePivotTablePartContent(pivotTablePart, pivotTable);
				pivotTablePart.AddPart(pivotTableCacheDefinitionPart, context.RelIdGenerator.GetNext(RelType.Workbook));
