		private static void GenerateWorksheetCommentsPartContent(WorksheetCommentsPart worksheetCommentsPart, XLWorksheet xlWorksheet)
		{
			Comments comments = new Comments();
			CommentList commentList = new CommentList();
			Dictionary<string, int> dictionary = new Dictionary<string, int>();
			foreach (XLCell cell in xlWorksheet.Internals.CellsCollection.GetCells((IXLCell c) => c.HasComment))
			{
				Comment comment = new Comment();
				comment.Reference = cell.Address.ToStringRelative();
				Comment comment2 = comment;
				string author = cell.Comment.Author;
				if (!dictionary.TryGetValue(author, out var value))
				{
					value = dictionary.Count;
					dictionary.Add(author, value);
				}
				comment2.AuthorId = (uint)value;
				CommentText commentText = new CommentText();
				foreach (IXLRichString item in cell.Comment)
				{
					commentText.Append(GetRun(item));
				}
				comment2.Append(commentText);
				commentList.Append(comment2);
			}
			Authors authors = new Authors();
			foreach (Author item2 in dictionary.Select((KeyValuePair<string, int> a) => new Author
			{
				Text = a.Key
			}))
			{
				authors.Append(item2);
			}
			comments.Append(authors);
			comments.Append(commentList);
			worksheetCommentsPart.Comments = comments;
		}

		private static void GenerateVmlDrawingPartContent(VmlDrawingPart vmlDrawingPart, XLWorksheet xlWorksheet, SaveContext context)
		{
			MemoryStream memoryStream = new MemoryStream();
			CopyStream(vmlDrawingPart.GetStream(FileMode.OpenOrCreate), memoryStream);
			memoryStream.Position = 0L;
			XmlTextWriter writer = new XmlTextWriter(vmlDrawingPart.GetStream(FileMode.Create), Encoding.UTF8);
			writer.WriteStartElement("xml");
			Shapetype shapetype = new Shapetype(new Stroke
			{
				JoinStyle = StrokeJoinStyleValues.Miter
			}, new DocumentFormat.OpenXml.Vml.Path
			{
				AllowGradientShape = true,
				ConnectionPointType = ConnectValues.Rectangle
			});
			shapetype.Id = "_x0000_t202";
			shapetype.CoordinateSize = "21600,21600";
			shapetype.OptionalNumber = 202;
			shapetype.EdgePath = "m,l,21600r21600,l21600,xe";
			shapetype.WriteTo(writer);
			IEnumerable<XLCell> enumerable = from c in xlWorksheet.Internals.CellsCollection.GetCells()
				where c.HasComment
				select c;
			foreach (XLCell item in enumerable)
			{
				GenerateShape(item, "_x0000_t202").WriteTo(writer);
			}
			if (memoryStream.Length > 0)
			{
				memoryStream.Position = 0L;
				XDocument val = XDocumentExtensions.Load(memoryStream);
				((XContainer)val.Root).Elements().ForEach(delegate(XElement e)
				{
					writer.WriteRaw(((object)e).ToString());
				});
			}
			writer.WriteEndElement();
			writer.Flush();
			writer.Close();
		}

