			DocumentFormat.OpenXml.Vml.Spreadsheet.Anchor anchor = GetAnchor(c);
			TextBox textBox = GetTextBox(c.Comment.Style);
			DocumentFormat.OpenXml.Vml.Fill fill = new DocumentFormat.OpenXml.Vml.Fill();
