			if (c.Comment.Style.ColorsAndLines.FillTransparency < 1.0)
			{
				fill2.Opacity = Math.Round(Convert.ToDouble(c.Comment.Style.ColorsAndLines.FillTransparency), 2).ToString(CultureInfo.InvariantCulture);
			}
			Stroke stroke = GetStroke(c);
			DocumentFormat.OpenXml.Vml.Shape shape = new DocumentFormat.OpenXml.Vml.Shape(fill2, stroke, new DocumentFormat.OpenXml.Vml.Shadow
			{
				On = true,
				Color = "black",
				Obscured = true
			}, new DocumentFormat.OpenXml.Vml.Path
			{
				ConnectionPointType = ConnectValues.None
			}, textBox, new ClientData(new MoveWithCells((c.Comment.Style.Properties.Positioning == XLDrawingAnchor.Absolute) ? "True" : "False"), new ResizeWithCells((c.Comment.Style.Properties.Positioning == XLDrawingAnchor.MoveAndSizeWithCells) ? "False" : "True"), anchor, new HorizontalTextAlignment(c.Comment.Style.Alignment.Horizontal.ToString().ToCamel()), new DocumentFormat.OpenXml.Vml.Spreadsheet.VerticalTextAlignment(c.Comment.Style.Alignment.Vertical.ToString().ToCamel()), new AutoFill("False"), new CommentRowTarget
			{
				Text = (rowNumber - 1).ToString()
			}, new CommentColumnTarget
			{
				Text = (columnNumber - 1).ToString()
			}, new Locked(c.Comment.Style.Protection.Locked ? "True" : "False"), new LockText(c.Comment.Style.Protection.LockText ? "True" : "False"), new Visible(c.Comment.Visible ? "True" : "False"))
			{
				ObjectType = ObjectValues.Note
			});
			shape.Id = text;
			shape.Type = "#" + shapeTypeId;
			shape.Style = GetCommentStyle(c);
			shape.FillColor = "#" + c.Comment.Style.ColorsAndLines.FillColor.Color.ToHex().Substring(2);
			shape.StrokeColor = "#" + c.Comment.Style.ColorsAndLines.LineColor.Color.ToHex().Substring(2);
			shape.StrokeWeight = $"{c.Comment.Style.ColorsAndLines.LineWeight}pt";
			shape.InsetMode = ((!c.Comment.Style.Margins.Automatic) ? InsetMarginValues.Custom : InsetMarginValues.Auto);
			DocumentFormat.OpenXml.Vml.Shape shape2 = shape;
			if (!XLHelper.IsNullOrWhiteSpace(c.Comment.Style.Web.AlternateText))
			{
				shape2.Alternate = c.Comment.Style.Web.AlternateText;
