			return shape2;
		}

		private static Stroke GetStroke(XLCell c)
		{
			XLDashStyle lineDash = c.Comment.Style.ColorsAndLines.LineDash;
			Stroke stroke = new Stroke();
			stroke.LineStyle = c.Comment.Style.ColorsAndLines.LineStyle.ToOpenXml();
			stroke.DashStyle = ((lineDash == XLDashStyle.RoundDot || lineDash == XLDashStyle.SquareDot) ? "shortDot" : lineDash.ToString().ToCamel());
			Stroke stroke2 = stroke;
			if (lineDash == XLDashStyle.RoundDot)
			{
				stroke2.EndCap = StrokeEndCapValues.Round;
			}
			if (c.Comment.Style.ColorsAndLines.LineTransparency < 1.0)
			{
				stroke2.Opacity = Math.Round(Convert.ToDouble(c.Comment.Style.ColorsAndLines.LineTransparency), 2).ToString(CultureInfo.InvariantCulture);
			}
			return stroke2;
		}

		private static TextBox GetTextBox(IXLDrawingStyle ds)
		{
			StringBuilder stringBuilder = new StringBuilder();
			IXLDrawingAlignment alignment = ds.Alignment;
			if (alignment.Direction == XLDrawingTextDirection.Context)
			{
				stringBuilder.Append("mso-direction-alt:auto;");
			}
			else if (alignment.Direction == XLDrawingTextDirection.RightToLeft)
			{
				stringBuilder.Append("direction:RTL;");
			}
			if (alignment.Orientation != 0)
			{
				stringBuilder.Append("layout-flow:vertical;");
				if (alignment.Orientation == XLDrawingTextOrientation.BottomToTop)
				{
					stringBuilder.Append("mso-layout-flow-alt:bottom-to-top;");
				}
				else if (alignment.Orientation == XLDrawingTextOrientation.Vertical)
				{
					stringBuilder.Append("mso-layout-flow-alt:top-to-bottom;");
				}
			}
			if (alignment.AutomaticSize)
			{
				stringBuilder.Append("mso-fit-shape-to-text:t;");
			}
			TextBox textBox = new TextBox();
			textBox.Style = stringBuilder.ToString();
			TextBox textBox2 = textBox;
			IXLDrawingMargins margins = ds.Margins;
			if (!margins.Automatic)
			{
				textBox2.Inset = $"{margins.Left.ToString(CultureInfo.InvariantCulture)}in,{margins.Top.ToString(CultureInfo.InvariantCulture)}in,{margins.Right.ToString(CultureInfo.InvariantCulture)}in,{margins.Bottom.ToString(CultureInfo.InvariantCulture)}in";
			}
			return textBox2;
		}

		private static DocumentFormat.OpenXml.Vml.Spreadsheet.Anchor GetAnchor(XLCell cell)
		{
			XLComment comment = cell.Comment;
			double width = comment.Style.Size.Width;
			int num = comment.Position.Column - 1;
			int num2 = Convert.ToInt32(comment.Position.ColumnOffset * 7.5);
			double num3 = cell.Worksheet.Column(comment.Position.Column).Width - comment.Position.ColumnOffset;
			XLCell xLCell;
			for (xLCell = cell.CellRight(comment.Position.Column - cell.Address.ColumnNumber); num3 <= width; num3 += xLCell.WorksheetColumn().Width)
			{
				xLCell = xLCell.CellRight();
			}
			int num4 = xLCell.WorksheetColumn().ColumnNumber() - 1;
			int num5 = Convert.ToInt32((xLCell.WorksheetColumn().Width - (num3 - width)) * 7.5);
			double height = comment.Style.Size.Height;
			int num6 = comment.Position.Row - 1;
			int num7 = Convert.ToInt32(comment.Position.RowOffset);
			double num8 = cell.Worksheet.Row(comment.Position.Row).Height - comment.Position.RowOffset;
			for (xLCell = cell.CellBelow(comment.Position.Row - cell.Address.RowNumber); num8 <= height; num8 += xLCell.WorksheetRow().Height)
			{
				xLCell = xLCell.CellBelow();
			}
			int num9 = xLCell.WorksheetRow().RowNumber() - 1;
			int num10 = Convert.ToInt32(xLCell.WorksheetRow().Height - (num8 - height));
			DocumentFormat.OpenXml.Vml.Spreadsheet.Anchor anchor = new DocumentFormat.OpenXml.Vml.Spreadsheet.Anchor();
			anchor.Text = $"{num}, {num2}, {num6}, {num7}, {num4}, {num5}, {num9}, {num10}";
			return anchor;
		}

		private static StringValue GetCommentStyle(XLCell cell)
		{
			XLComment comment = cell.Comment;
			StringBuilder stringBuilder = new StringBuilder("position:absolute; ");
			stringBuilder.Append("visibility:");
			stringBuilder.Append(comment.Visible ? "visible" : "hidden");
			stringBuilder.Append(";");
			stringBuilder.Append("width:");
			stringBuilder.Append(Math.Round(comment.Style.Size.Width * 7.5, 2).ToString(CultureInfo.InvariantCulture));
			stringBuilder.Append("pt;");
			stringBuilder.Append("height:");
			stringBuilder.Append(Math.Round(comment.Style.Size.Height, 2).ToString(CultureInfo.InvariantCulture));
			stringBuilder.Append("pt;");
			stringBuilder.Append("z-index:");
			stringBuilder.Append(comment.ZOrder.ToString());
			return stringBuilder.ToString();
		}

		private void GenerateWorkbookStylesPartContent(WorkbookStylesPart workbookStylesPart, SaveContext context)
		{
