				{
					FontId = 0u,
					Font = (xLStyle.Font as XLFont)
				});
			}
			Dictionary<IXLFill, FillInfo> dictionary = new Dictionary<IXLFill, FillInfo>();
			dictionary.Add(xLStyle.Fill, new FillInfo
			{
				FillId = 2u,
				Fill = (xLStyle.Fill as XLFill)
			});
			Dictionary<IXLFill, FillInfo> dictionary2 = dictionary;
			Dictionary<IXLBorder, BorderInfo> dictionary3 = new Dictionary<IXLBorder, BorderInfo>();
			dictionary3.Add(xLStyle.Border, new BorderInfo
			{
				BorderId = 0u,
				Border = (xLStyle.Border as XLBorder)
			});
			Dictionary<IXLBorder, BorderInfo> dictionary4 = dictionary3;
			Dictionary<IXLNumberFormat, NumberFormatInfo> dictionary5 = new Dictionary<IXLNumberFormat, NumberFormatInfo>();
			dictionary5.Add(xLStyle.NumberFormat, new NumberFormatInfo
			{
				NumberFormatId = 0,
				NumberFormat = xLStyle.NumberFormat
			});
			Dictionary<IXLNumberFormat, NumberFormatInfo> dictionary6 = dictionary5;
			if (workbookStylesPart.Stylesheet == null)
			{
				workbookStylesPart.Stylesheet = new Stylesheet();
			}
			if (workbookStylesPart.Stylesheet.CellStyles == null)
			{
				workbookStylesPart.Stylesheet.CellStyles = new CellStyles();
			}
			uint num = (workbookStylesPart.Stylesheet.CellStyles.Elements<CellStyle>().Any((CellStyle c) => c.Name == "Normal") ? workbookStylesPart.Stylesheet.CellStyles.Elements<CellStyle>().Single((CellStyle c) => c.Name == "Normal").FormatId.Value : (workbookStylesPart.Stylesheet.CellStyles.Elements<CellStyle>().Any() ? (workbookStylesPart.Stylesheet.CellStyles.Elements<CellStyle>().Max((CellStyle c) => c.FormatId.Value) + 1) : 0u));
			context.SharedStyles.Add(styleId, new StyleInfo
			{
				StyleId = num,
				Style = xLStyle,
				FontId = 0u,
				FillId = 0u,
				BorderId = 0u,
				NumberFormatId = 0
			});
			uint num2 = 1u;
			uint num3 = 1u;
			uint num4 = 3u;
			uint num5 = 1u;
			int num6 = 1;
			HashSet<int> xlStyles = new HashSet<int>();
			foreach (XLWorksheet item in WorksheetsInternal)
			{
				foreach (int item2 in from s in item.GetStyleIds()
					where !xlStyles.Contains(s)
					select s)
				{
					xlStyles.Add(item2);
				}
				foreach (int item3 in from kp in item.Internals.ColumnsCollection
					select kp.Value.GetStyleId() into s
					where !xlStyles.Contains(s)
					select s)
				{
					xlStyles.Add(item3);
				}
				foreach (int item4 in from kp in item.Internals.RowsCollection
					select kp.Value.GetStyleId() into s
					where !xlStyles.Contains(s)
					select s)
				{
					xlStyles.Add(item4);
				}
			}
			foreach (IXLStyle item5 in xlStyles.Select(GetStyleById))
			{
				if (!context.SharedFonts.ContainsKey(item5.Font))
				{
					context.SharedFonts.Add(item5.Font, new FontInfo
					{
						FontId = num3++,
						Font = (item5.Font as XLFont)
					});
				}
				if (!dictionary2.ContainsKey(item5.Fill))
				{
					dictionary2.Add(item5.Fill, new FillInfo
					{
						FillId = num4++,
						Fill = (item5.Fill as XLFill)
					});
				}
				if (!dictionary4.ContainsKey(item5.Border))
				{
					dictionary4.Add(item5.Border, new BorderInfo
					{
						BorderId = num5++,
						Border = (item5.Border as XLBorder)
					});
				}
				if (item5.NumberFormat.NumberFormatId == -1 && !dictionary6.ContainsKey(item5.NumberFormat))
				{
					dictionary6.Add(item5.NumberFormat, new NumberFormatInfo
					{
						NumberFormatId = num6 + 164,
						NumberFormat = item5.NumberFormat
					});
					num6++;
				}
			}
			Dictionary<IXLNumberFormat, NumberFormatInfo> dictionary7 = ResolveNumberFormats(workbookStylesPart, dictionary6);
			ResolveFonts(workbookStylesPart, context);
			Dictionary<IXLFill, FillInfo> dictionary8 = ResolveFills(workbookStylesPart, dictionary2);
			Dictionary<IXLBorder, BorderInfo> dictionary9 = ResolveBorders(workbookStylesPart, dictionary4);
			foreach (int item6 in xlStyles)
			{
				IXLStyle styleById = GetStyleById(item6);
				if (!context.SharedStyles.ContainsKey(item6))
				{
					int numberFormatId = ((styleById.NumberFormat.NumberFormatId >= 0) ? styleById.NumberFormat.NumberFormatId : dictionary7[styleById.NumberFormat].NumberFormatId);
					context.SharedStyles.Add(item6, new StyleInfo
					{
						StyleId = num2++,
						Style = styleById,
						FontId = context.SharedFonts[styleById.Font].FontId,
						FillId = dictionary8[styleById.Fill].FillId,
						BorderId = dictionary9[styleById.Border].BorderId,
						NumberFormatId = numberFormatId
					});
				}
			}
			ResolveCellStyleFormats(workbookStylesPart, context);
			ResolveRest(workbookStylesPart, context);
			if (workbookStylesPart.Stylesheet.CellStyles.Elements<CellStyle>().All((CellStyle c) => c.Name != "Normal"))
			{
				CellStyle cellStyle = new CellStyle();
				cellStyle.Name = "Normal";
				cellStyle.FormatId = num;
				cellStyle.BuiltinId = 0u;
				CellStyle newChild = cellStyle;
				workbookStylesPart.Stylesheet.CellStyles.AppendChild(newChild);
