			workbookStylesPart.Stylesheet.CellStyles.Count = (uint)workbookStylesPart.Stylesheet.CellStyles.Count();
			Dictionary<int, StyleInfo> dictionary10 = new Dictionary<int, StyleInfo>();
			foreach (KeyValuePair<int, StyleInfo> sharedStyle in context.SharedStyles)
			{
				int num7 = -1;
				foreach (CellFormat cellFormat in workbookStylesPart.Stylesheet.CellFormats)
				{
					num7++;
					if (CellFormatsAreEqual(cellFormat, sharedStyle.Value))
					{
						break;
					}
				}
				if (num7 == -1)
				{
					num7 = 0;
				}
				StyleInfo value = sharedStyle.Value;
				value.StyleId = (uint)num7;
				dictionary10.Add(sharedStyle.Key, value);
			}
			context.SharedStyles.Clear();
			dictionary10.ForEach(delegate(KeyValuePair<int, StyleInfo> kp)
			{
				context.SharedStyles.Add(kp.Key, kp.Value);
			});
			AddDifferentialFormats(workbookStylesPart, context);
		}

		private void AddDifferentialFormats(WorkbookStylesPart workbookStylesPart, SaveContext context)
		{
			if (workbookStylesPart.Stylesheet.DifferentialFormats == null)
			{
				workbookStylesPart.Stylesheet.DifferentialFormats = new DocumentFormat.OpenXml.Spreadsheet.DifferentialFormats();
			}
			DocumentFormat.OpenXml.Spreadsheet.DifferentialFormats differentialFormats = workbookStylesPart.Stylesheet.DifferentialFormats;
			FillDifferentialFormatsCollection(differentialFormats, context.DifferentialFormats);
			foreach (IXLWorksheet worksheet in Worksheets)
			{
				foreach (IXLConditionalFormat conditionalFormat in worksheet.ConditionalFormats)
				{
					if (!context.DifferentialFormats.ContainsKey(conditionalFormat.Style))
					{
						AddDifferentialFormat(workbookStylesPart.Stylesheet.DifferentialFormats, conditionalFormat, context);
					}
				}
			}
			differentialFormats.Count = (uint)differentialFormats.Count();
			if ((uint)differentialFormats.Count == 0)
			{
				workbookStylesPart.Stylesheet.DifferentialFormats = null;
			}
		}

		private void FillDifferentialFormatsCollection(DocumentFormat.OpenXml.Spreadsheet.DifferentialFormats differentialFormats, Dictionary<IXLStyle, int> dictionary)
		{
			dictionary.Clear();
			int num = 0;
			foreach (DifferentialFormat item in differentialFormats.Elements<DifferentialFormat>())
			{
				XLStyle xLStyle = new XLStyle(new XLStylizedEmpty(DefaultStyle), DefaultStyle);
				LoadFont(item.Font, xLStyle.Font);
				LoadBorder(item.Border, xLStyle.Border);
				LoadNumberFormat(item.NumberingFormat, xLStyle.NumberFormat);
				LoadFill(item.Fill, xLStyle.Fill);
				if (!dictionary.ContainsKey(xLStyle))
				{
					dictionary.Add(xLStyle, ++num);
				}
			}
		}

		private static void AddDifferentialFormat(DocumentFormat.OpenXml.Spreadsheet.DifferentialFormats differentialFormats, IXLConditionalFormat cf, SaveContext context)
		{
			DifferentialFormat differentialFormat = new DifferentialFormat();
			differentialFormat.Append(GetNewFont(new FontInfo
			{
				Font = (cf.Style.Font as XLFont)
			}, ignoreMod: false));
			if (!XLHelper.IsNullOrWhiteSpace(cf.Style.NumberFormat.Format))
			{
				NumberingFormat numberingFormat = new NumberingFormat();
				numberingFormat.NumberFormatId = (uint)(differentialFormats.Count() + 164);
				numberingFormat.FormatCode = cf.Style.NumberFormat.Format;
				NumberingFormat numberingFormat2 = numberingFormat;
				differentialFormat.Append(numberingFormat2);
			}
			differentialFormat.Append(GetNewFill(new FillInfo
			{
				Fill = (cf.Style.Fill as XLFill)
			}, ignoreMod: false));
			differentialFormat.Append(GetNewBorder(new BorderInfo
			{
				Border = (cf.Style.Border as XLBorder)
			}, ignoreMod: false));
			differentialFormats.Append(differentialFormat);
			context.DifferentialFormats.Add(cf.Style, differentialFormats.Count() - 1);
		}

		private static void ResolveRest(WorkbookStylesPart workbookStylesPart, SaveContext context)
		{
			if (workbookStylesPart.Stylesheet.CellFormats == null)
			{
				workbookStylesPart.Stylesheet.CellFormats = new CellFormats();
			}
			foreach (StyleInfo value in context.SharedStyles.Values)
			{
				StyleInfo info = value;
				if (!workbookStylesPart.Stylesheet.CellFormats.Cast<CellFormat>().Any((CellFormat f) => CellFormatsAreEqual(f, info)))
				{
					CellFormat cellFormat = GetCellFormat(value);
					cellFormat.FormatId = 0u;
					Alignment alignment = new Alignment();
					alignment.Horizontal = value.Style.Alignment.Horizontal.ToOpenXml();
					alignment.Vertical = value.Style.Alignment.Vertical.ToOpenXml();
					alignment.Indent = (uint)value.Style.Alignment.Indent;
					alignment.ReadingOrder = (uint)value.Style.Alignment.ReadingOrder;
					alignment.WrapText = value.Style.Alignment.WrapText;
					alignment.TextRotation = (uint)value.Style.Alignment.TextRotation;
					alignment.ShrinkToFit = value.Style.Alignment.ShrinkToFit;
					alignment.RelativeIndent = value.Style.Alignment.RelativeIndent;
					alignment.JustifyLastLine = value.Style.Alignment.JustifyLastLine;
					Alignment newChild = alignment;
					cellFormat.AppendChild(newChild);
					if (cellFormat.ApplyProtection.Value)
					{
						cellFormat.AppendChild(GetProtection(value));
					}
					workbookStylesPart.Stylesheet.CellFormats.AppendChild(cellFormat);
				}
			}
			workbookStylesPart.Stylesheet.CellFormats.Count = (uint)workbookStylesPart.Stylesheet.CellFormats.Count();
		}

		private static void ResolveCellStyleFormats(WorkbookStylesPart workbookStylesPart, SaveContext context)
		{
			if (workbookStylesPart.Stylesheet.CellStyleFormats == null)
			{
				workbookStylesPart.Stylesheet.CellStyleFormats = new CellStyleFormats();
			}
			foreach (StyleInfo value in context.SharedStyles.Values)
			{
				StyleInfo info = value;
				if (!workbookStylesPart.Stylesheet.CellStyleFormats.Cast<CellFormat>().Any((CellFormat f) => CellFormatsAreEqual(f, info)))
				{
					CellFormat cellFormat = GetCellFormat(value);
					if (cellFormat.ApplyProtection.Value)
					{
						cellFormat.AppendChild(GetProtection(value));
					}
					workbookStylesPart.Stylesheet.CellStyleFormats.AppendChild(cellFormat);
				}
			}
			workbookStylesPart.Stylesheet.CellStyleFormats.Count = (uint)workbookStylesPart.Stylesheet.CellStyleFormats.Count();
		}

		private static bool ApplyFill(StyleInfo styleInfo)
		{
			return styleInfo.Style.Fill.PatternType.ToOpenXml() == PatternValues.None;
		}

		private static bool ApplyBorder(StyleInfo styleInfo)
		{
			IXLBorder border = styleInfo.Style.Border;
			if (border.BottomBorder.ToOpenXml() == BorderStyleValues.None && border.DiagonalBorder.ToOpenXml() == BorderStyleValues.None && border.RightBorder.ToOpenXml() == BorderStyleValues.None && border.LeftBorder.ToOpenXml() == BorderStyleValues.None)
			{
				return border.TopBorder.ToOpenXml() != BorderStyleValues.None;
			}
			return true;
		}

		private static bool ApplyProtection(StyleInfo styleInfo)
		{
			return styleInfo.Style.Protection != null;
		}

		private static CellFormat GetCellFormat(StyleInfo styleInfo)
		{
			CellFormat cellFormat = new CellFormat();
			cellFormat.NumberFormatId = (uint)styleInfo.NumberFormatId;
			cellFormat.FontId = styleInfo.FontId;
			cellFormat.FillId = styleInfo.FillId;
			cellFormat.BorderId = styleInfo.BorderId;
			cellFormat.ApplyNumberFormat = false;
			cellFormat.ApplyFill = ApplyFill(styleInfo);
			cellFormat.ApplyBorder = ApplyBorder(styleInfo);
			cellFormat.ApplyAlignment = false;
			cellFormat.ApplyProtection = ApplyProtection(styleInfo);
			return cellFormat;
		}

		private static Protection GetProtection(StyleInfo styleInfo)
		{
			Protection protection = new Protection();
			protection.Locked = styleInfo.Style.Protection.Locked;
			protection.Hidden = styleInfo.Style.Protection.Hidden;
			return protection;
		}

		private static bool CellFormatsAreEqual(CellFormat f, StyleInfo styleInfo)
		{
			if (f.BorderId != null && styleInfo.BorderId == (uint)f.BorderId && f.FillId != null && styleInfo.FillId == (uint)f.FillId && f.FontId != null && styleInfo.FontId == (uint)f.FontId && f.NumberFormatId != null && styleInfo.NumberFormatId == (uint)f.NumberFormatId && f.ApplyNumberFormat != null && !f.ApplyNumberFormat && f.ApplyAlignment != null && !f.ApplyAlignment && f.ApplyFill != null && (bool)f.ApplyFill == ApplyFill(styleInfo) && f.ApplyBorder != null && (bool)f.ApplyBorder == ApplyBorder(styleInfo) && AlignmentsAreEqual(f.Alignment, styleInfo.Style.Alignment))
			{
				return ProtectionsAreEqual(f.Protection, styleInfo.Style.Protection);
			}
			return false;
		}

		private static bool ProtectionsAreEqual(Protection protection, IXLProtection xlProtection)
		{
			XLProtection xLProtection = new XLProtection();
			if (protection != null)
			{
				if (protection.Locked != null)
				{
					xLProtection.Locked = protection.Locked.Value;
				}
				if (protection.Hidden != null)
				{
					xLProtection.Hidden = protection.Hidden.Value;
				}
			}
			return xLProtection.Equals(xlProtection);
		}

		private static bool AlignmentsAreEqual(Alignment alignment, IXLAlignment xlAlignment)
		{
			XLAlignment xLAlignment = new XLAlignment();
			if (alignment != null)
			{
				if (alignment.Indent != null)
				{
					xLAlignment.Indent = (int)alignment.Indent.Value;
				}
				if (alignment.Horizontal != null)
				{
					xLAlignment.Horizontal = alignment.Horizontal.Value.ToClosedXml();
				}
				if (alignment.Vertical != null)
				{
					xLAlignment.Vertical = alignment.Vertical.Value.ToClosedXml();
				}
				if (alignment.ReadingOrder != null)
				{
					xLAlignment.ReadingOrder = alignment.ReadingOrder.Value.ToClosedXml();
				}
				if (alignment.WrapText != null)
				{
					xLAlignment.WrapText = alignment.WrapText.Value;
				}
				if (alignment.TextRotation != null)
				{
					xLAlignment.TextRotation = (int)alignment.TextRotation.Value;
				}
				if (alignment.ShrinkToFit != null)
				{
					xLAlignment.ShrinkToFit = alignment.ShrinkToFit.Value;
				}
				if (alignment.RelativeIndent != null)
				{
					xLAlignment.RelativeIndent = alignment.RelativeIndent.Value;
				}
				if (alignment.JustifyLastLine != null)
				{
					xLAlignment.JustifyLastLine = alignment.JustifyLastLine.Value;
				}
			}
			return xLAlignment.Equals(xlAlignment);
		}

		private Dictionary<IXLBorder, BorderInfo> ResolveBorders(WorkbookStylesPart workbookStylesPart, Dictionary<IXLBorder, BorderInfo> sharedBorders)
		{
			if (workbookStylesPart.Stylesheet.Borders == null)
			{
				workbookStylesPart.Stylesheet.Borders = new Borders();
			}
