		private static void PopulateAutoFilter(XLAutoFilter xlAutoFilter, AutoFilter autoFilter)
		{
			IXLRange range = xlAutoFilter.Range;
			autoFilter.Reference = range.RangeAddress.ToString();
			foreach (KeyValuePair<int, List<XLFilter>> filter in xlAutoFilter.Filters)
			{
				FilterColumn filterColumn = new FilterColumn();
				filterColumn.ColumnId = (uint)(filter.Key - 1);
				FilterColumn filterColumn2 = filterColumn;
				IXLFilterColumn iXLFilterColumn = xlAutoFilter.Column(filter.Key);
				switch (iXLFilterColumn.FilterType)
				{
				case XLFilterType.Custom:
				{
					DocumentFormat.OpenXml.Spreadsheet.CustomFilters customFilters = new DocumentFormat.OpenXml.Spreadsheet.CustomFilters();
					foreach (XLFilter item in filter.Value)
					{
						DocumentFormat.OpenXml.Spreadsheet.CustomFilter customFilter = new DocumentFormat.OpenXml.Spreadsheet.CustomFilter();
						customFilter.Val = item.Value.ToString();
						DocumentFormat.OpenXml.Spreadsheet.CustomFilter customFilter2 = customFilter;
						if (item.Operator != 0)
						{
							customFilter2.Operator = item.Operator.ToOpenXml();
						}
						if (item.Connector == XLConnector.And)
						{
							customFilters.And = true;
						}
						customFilters.Append(customFilter2);
					}
					filterColumn2.Append(customFilters);
					break;
				}
				case XLFilterType.TopBottom:
				{
					Top10 top = new Top10();
					top.Val = iXLFilterColumn.TopBottomValue;
					Top10 top2 = top;
					if (iXLFilterColumn.TopBottomType == XLTopBottomType.Percent)
					{
						top2.Percent = true;
					}
					if (iXLFilterColumn.TopBottomPart == XLTopBottomPart.Bottom)
					{
						top2.Top = false;
					}
					filterColumn2.Append(top2);
					break;
				}
				case XLFilterType.Dynamic:
				{
					DynamicFilter dynamicFilter = new DynamicFilter();
					dynamicFilter.Type = iXLFilterColumn.DynamicType.ToOpenXml();
					dynamicFilter.Val = iXLFilterColumn.DynamicValue;
					DynamicFilter dynamicFilter2 = dynamicFilter;
					filterColumn2.Append(dynamicFilter2);
					break;
				}
				default:
				{
					Filters filters = new Filters();
					foreach (XLFilter item2 in filter.Value)
					{
						filters.Append(new DocumentFormat.OpenXml.Spreadsheet.Filter
						{
							Val = item2.Value.ToString()
						});
					}
					filterColumn2.Append(filters);
					break;
				}
				}
				autoFilter.Append(filterColumn2);
			}
			if (xlAutoFilter.Sorted)
			{
				SortState sortState = new SortState();
				sortState.Reference = range.Range(range.FirstCell().CellBelow(), range.LastCell()).RangeAddress.ToString();
				SortState sortState2 = sortState;
				DocumentFormat.OpenXml.Spreadsheet.SortCondition sortCondition = new DocumentFormat.OpenXml.Spreadsheet.SortCondition();
				sortCondition.Reference = range.Range(1, xlAutoFilter.SortColumn, range.RowCount(), xlAutoFilter.SortColumn).RangeAddress.ToString();
				DocumentFormat.OpenXml.Spreadsheet.SortCondition sortCondition2 = sortCondition;
				if (xlAutoFilter.SortOrder == XLSortOrder.Descending)
				{
					sortCondition2.Descending = true;
				}
				sortState2.Append(sortCondition2);
				autoFilter.Append(sortState2);
			}
		}

