		private static void CollapseColumns(Columns columns, Dictionary<uint, Column> sheetColumns)
		{
			uint lastMin = 1u;
			int count = sheetColumns.Count;
			KeyValuePair<uint, Column>[] array = sheetColumns.OrderBy((KeyValuePair<uint, Column> kp) => kp.Key).ToArray();
			for (int i = 0; i < count; i++)
			{
				KeyValuePair<uint, Column> keyValuePair = array[i];
				if (i + 1 == count || !ColumnsAreEqual(keyValuePair.Value, array[i + 1].Value))
				{
					Column column = (Column)keyValuePair.Value.CloneNode(deep: true);
					column.Min = lastMin;
					uint newColumnMax = column.Max.Value;
					List<Column> list = (from co in columns.Elements<Column>()
						where (uint)co.Min >= lastMin && (uint)co.Max <= newColumnMax
						select (co)).ToList();
					list.ForEach(delegate(Column c)
					{
						columns.RemoveChild(c);
					});
					columns.AppendChild(column);
					lastMin = keyValuePair.Key + 1;
				}
			}
		}

		private static double GetColumnWidth(double columnWidth)
		{
			double num = columnWidth + 0.710625;
			if (!(num > 0.0))
			{
				return 0.0;
			}
			return num;
		}

		private static void UpdateColumn(Column column, Columns columns, Dictionary<uint, Column> sheetColumnsByMin)
		{
			uint value = column.Min.Value;
			Column column2;
			if (!sheetColumnsByMin.ContainsKey(value))
			{
				column2 = (Column)column.CloneNode(deep: true);
				columns.AppendChild(column2);
				sheetColumnsByMin.Add(value, column2);
				return;
			}
			Column column3 = sheetColumnsByMin[column.Min.Value];
			column2 = (Column)column3.CloneNode(deep: true);
			column2.Min = column.Min;
			column2.Max = column.Max;
			column2.Style = column.Style;
			column2.Width = column.Width;
			column2.CustomWidth = column.CustomWidth;
			if (column.Hidden != null)
			{
				column2.Hidden = true;
			}
			else
			{
				column2.Hidden = null;
			}
			if (column.Collapsed != null)
			{
				column2.Collapsed = true;
			}
			else
			{
				column2.Collapsed = null;
			}
			if (column.OutlineLevel != null && (byte)column.OutlineLevel > 0)
			{
				column2.OutlineLevel = (byte)column.OutlineLevel;
			}
			else
			{
				column2.OutlineLevel = null;
			}
			sheetColumnsByMin.Remove(column.Min.Value);
			if ((uint)column3.Min + 1 > (uint)column3.Max)
			{
				columns.RemoveChild(column3);
				columns.AppendChild(column2);
				sheetColumnsByMin.Add(column2.Min.Value, column2);
			}
			else
			{
				columns.AppendChild(column2);
				sheetColumnsByMin.Add(column2.Min.Value, column2);
				column3.Min = (uint)column3.Min + 1;
				sheetColumnsByMin.Add(column3.Min.Value, column3);
			}
		}

		private static bool ColumnsAreEqual(Column left, Column right)
		{
			if (((left.Style == null && right.Style == null) || (left.Style != null && right.Style != null && left.Style.Value == right.Style.Value)) && ((left.Width == null && right.Width == null) || (left.Width != null && right.Width != null && left.Width.Value == right.Width.Value)) && ((left.Hidden == null && right.Hidden == null) || (left.Hidden != null && right.Hidden != null && left.Hidden.Value == right.Hidden.Value)) && ((left.Collapsed == null && right.Collapsed == null) || (left.Collapsed != null && right.Collapsed != null && left.Collapsed.Value == right.Collapsed.Value)))
			{
				if (left.OutlineLevel != null || right.OutlineLevel != null)
				{
					if (left.OutlineLevel != null && right.OutlineLevel != null)
					{
						return left.OutlineLevel.Value == right.OutlineLevel.Value;
					}
					return false;
				}
				return true;
			}
			return false;
		}

		internal int GetStyleId(IXLStyle style)
		{
			if (_stylesByStyle.TryGetValue(style, out var value))
			{
				return value;
			}
			int count = _stylesByStyle.Count;
			XLStyle xLStyle = new XLStyle(null, style);
			_stylesByStyle.Add(xLStyle, count);
			_stylesById.Add(count, xLStyle);
			return count;
		}

		internal IXLStyle GetStyleById(int id)
		{
			return _stylesById[id];
		}

