		internal XLColor GetXLColor(XLThemeColor themeColor)
		{
			return themeColor switch
			{
				XLThemeColor.Text1 => Theme.Text1, 
				XLThemeColor.Background1 => Theme.Background1, 
				XLThemeColor.Text2 => Theme.Text2, 
				XLThemeColor.Background2 => Theme.Background2, 
				XLThemeColor.Accent1 => Theme.Accent1, 
				XLThemeColor.Accent2 => Theme.Accent2, 
				XLThemeColor.Accent3 => Theme.Accent3, 
				XLThemeColor.Accent4 => Theme.Accent4, 
				XLThemeColor.Accent5 => Theme.Accent5, 
				XLThemeColor.Accent6 => Theme.Accent6, 
				_ => throw new ArgumentException("Invalid theme color"), 
			};
		}

		public IXLNamedRange NamedRange(string rangeName)
		{
			if (rangeName.Contains("!"))
			{
				string[] array = rangeName.Split(new char[1] { '!' });
				string text = array[0];
				string name = (text.StartsWith("'") ? text.Substring(1, text.Length - 2) : text);
				string rangeName2 = array[1];
				if (TryGetWorksheet(name, out var worksheet))
				{
					IXLNamedRange iXLNamedRange = worksheet.NamedRange(rangeName2);
					return iXLNamedRange ?? NamedRange(rangeName2);
				}
				return null;
			}
			return NamedRanges.NamedRange(rangeName);
		}

		public bool TryGetWorksheet(string name, out IXLWorksheet worksheet)
		{
			if (Worksheets.Any((IXLWorksheet w) => w.Name.ToLower().Equals(name.ToLower())))
			{
				worksheet = Worksheet(name);
				return true;
			}
			worksheet = null;
			return false;
		}

		public void Save()
		{
			if (_loadSource == XLLoadSource.New)
			{
				throw new Exception("This is a new file, please use one of the SaveAs methods.");
			}
			if (_loadSource == XLLoadSource.Stream)
			{
				CreatePackage(_originalStream, newStream: false);
			}
			else
			{
				CreatePackage(_originalFile);
			}
		}

		public void SaveAs(string file)
		{
			PathHelper.CreateDirectory(System.IO.Path.GetDirectoryName(file));
			if (_loadSource == XLLoadSource.New)
			{
				if (File.Exists(file))
				{
					File.Delete(file);
				}
				CreatePackage(file);
			}
			else if (_loadSource == XLLoadSource.File)
			{
				if (string.Compare(_originalFile.Trim(), file.Trim(), ignoreCase: true) != 0)
				{
					File.Copy(_originalFile, file, overwrite: true);
				}
				CreatePackage(file);
			}
			else if (_loadSource == XLLoadSource.Stream)
			{
				_originalStream.Position = 0L;
				using FileStream fileStream = File.Create(file);
				CopyStream(_originalStream, fileStream);
				CreatePackage(fileStream, newStream: false);
				fileStream.Close();
			}
		}

		public void SaveAs(Stream stream)
		{
			if (_loadSource == XLLoadSource.New)
			{
				CreatePackage(stream, newStream: true);
			}
			else if (_loadSource == XLLoadSource.File)
			{
				using (FileStream fileStream = new FileStream(_originalFile, FileMode.Open, FileAccess.Read))
				{
					CopyStream(fileStream, stream);
					fileStream.Close();
				}
				CreatePackage(stream, newStream: false);
			}
			else if (_loadSource == XLLoadSource.Stream)
			{
				_originalStream.Position = 0L;
				if (_originalStream != stream)
				{
					CopyStream(_originalStream, stream);
				}
				CreatePackage(stream, newStream: false);
			}
		}

		internal static void CopyStream(Stream input, Stream output)
		{
			byte[] array = new byte[8192];
			int count;
			while ((count = input.Read(array, 0, array.Length)) > 0)
			{
				output.Write(array, 0, count);
			}
		}

