		public IXLCells FindCells(Func<IXLCell, bool> predicate)
		{
			XLCells xLCells = new XLCells(usedCellsOnly: false, includeFormats: false);
			foreach (XLWorksheet item in WorksheetsInternal)
			{
				foreach (XLCell item2 in item.CellsUsed(includeFormats: true))
				{
					if (predicate(item2))
					{
						xLCells.Add(item2);
					}
				}
			}
			return xLCells;
		}

		public IXLRows FindRows(Func<IXLRow, bool> predicate)
		{
			XLRows xLRows = new XLRows(null);
			foreach (XLWorksheet item in WorksheetsInternal)
			{
				foreach (IXLRow item2 in item.Rows().Where(predicate))
				{
					xLRows.Add(item2 as XLRow);
				}
			}
			return xLRows;
		}

		public IXLColumns FindColumns(Func<IXLColumn, bool> predicate)
		{
			XLColumns xLColumns = new XLColumns(null);
			foreach (XLWorksheet item in WorksheetsInternal)
			{
				foreach (IXLColumn item2 in item.Columns().Where(predicate))
				{
					xLColumns.Add(item2 as XLColumn);
				}
			}
			return xLColumns;
		}

