		}

		public IXLRanges Ranges(string namedRanges)
		{
			XLRanges xLRanges = new XLRanges();
			string[] source = namedRanges.Split(new char[1] { ',' });
			foreach (IXLRange item in from r in source
				select Range(r.Trim()) into range
				where range != null
				select range)
			{
				xLRanges.Add(item);
			}
			return xLRanges;
		}

