	public interface IXLCustomProperty
	{
		string Name { get; set; }

		XLCustomPropertyType Type { get; }

		object Value { get; set; }

		T GetValue<T>();
	}
	internal class XLCustomProperty : IXLCustomProperty
	{
		private readonly XLWorkbook _workbook;

		private string name;

		public string Name
		{
			get
			{
				return name;
			}
			set
			{
				if (_workbook.CustomProperties.Any((IXLCustomProperty t) => t.Name == value))
				{
					throw new ArgumentException($"This workbook already contains a custom property named '{value}'");
				}
				name = value;
			}
		}

		public XLCustomPropertyType Type
		{
			get
			{
				if (Value is DateTime)
				{
					return XLCustomPropertyType.Date;
				}
				if (Value is bool)
				{
					return XLCustomPropertyType.Boolean;
				}
				if (double.TryParse(Value.ToString(), out var _))
				{
					return XLCustomPropertyType.Number;
				}
				return XLCustomPropertyType.Text;
			}
		}

		public object Value { get; set; }

		public XLCustomProperty(XLWorkbook workbook)
		{
			_workbook = workbook;
		}

		public T GetValue<T>()
		{
			return (T)Convert.ChangeType(Value, typeof(T));
		}
	}
	public enum XLCustomPropertyType
	{
		Text,
		Number,
		Date,
		Boolean
	}
