	internal class XLDataValidation : IXLDataValidation
	{
		private XLAllowedValues _allowedValues;

		public IXLRanges Ranges { get; set; }

		public bool IgnoreBlanks { get; set; }

		public bool InCellDropdown { get; set; }

		public bool ShowInputMessage { get; set; }

		public string InputTitle { get; set; }

		public string InputMessage { get; set; }

		public bool ShowErrorMessage { get; set; }

		public string ErrorTitle { get; set; }

		public string ErrorMessage { get; set; }

		public XLErrorStyle ErrorStyle { get; set; }

		public XLAllowedValues AllowedValues
		{
			get
			{
				return _allowedValues;
			}
			set
			{
				_allowedValues = value;
			}
		}

		public XLOperator Operator { get; set; }

		public string Value
		{
			get
			{
				return MinValue;
			}
			set
			{
				MinValue = value;
			}
		}

		public string MinValue { get; set; }

		public string MaxValue { get; set; }

		public XLWholeNumberCriteria WholeNumber
		{
			get
			{
				AllowedValues = XLAllowedValues.WholeNumber;
				return new XLWholeNumberCriteria(this);
			}
		}

		public XLDecimalCriteria Decimal
		{
			get
			{
				AllowedValues = XLAllowedValues.Decimal;
				return new XLDecimalCriteria(this);
			}
		}

		public XLDateCriteria Date
		{
			get
			{
				AllowedValues = XLAllowedValues.Date;
				return new XLDateCriteria(this);
			}
		}

		public XLTimeCriteria Time
		{
			get
			{
				AllowedValues = XLAllowedValues.Time;
				return new XLTimeCriteria(this);
			}
		}

		public XLTextLengthCriteria TextLength
		{
			get
			{
				AllowedValues = XLAllowedValues.TextLength;
				return new XLTextLengthCriteria(this);
			}
		}

		public XLDataValidation(IXLRanges ranges)
		{
			Ranges = new XLRanges();
			Action<IXLRange> action = delegate(IXLRange r)
			{
				XLRange range = new XLRange(new XLRangeParameters(r.RangeAddress as XLRangeAddress, r.Worksheet.Style)
				{
					IgnoreEvents = true
				});
				(Ranges as XLRanges).Add(range);
			};
			ranges.ForEach(action);
			Initialize();
		}

		private void Initialize()
		{
			AllowedValues = XLAllowedValues.AnyValue;
			IgnoreBlanks = true;
			ShowErrorMessage = true;
			ShowInputMessage = true;
			InCellDropdown = true;
			InputTitle = string.Empty;
			InputMessage = string.Empty;
			ErrorTitle = string.Empty;
			ErrorMessage = string.Empty;
			ErrorStyle = XLErrorStyle.Stop;
			Operator = XLOperator.Between;
			Value = string.Empty;
			MinValue = string.Empty;
			MaxValue = string.Empty;
		}

		public bool IsDirty()
		{
			if (AllowedValues == XLAllowedValues.AnyValue && (!ShowInputMessage || (XLHelper.IsNullOrWhiteSpace(InputTitle) && XLHelper.IsNullOrWhiteSpace(InputMessage))))
			{
				if (ShowErrorMessage)
				{
					if (XLHelper.IsNullOrWhiteSpace(ErrorTitle))
					{
						return !XLHelper.IsNullOrWhiteSpace(ErrorMessage);
					}
					return true;
				}
				return false;
			}
			return true;
		}

		public XLDataValidation(IXLDataValidation dataValidation)
		{
			CopyFrom(dataValidation);
		}

		public void List(string list)
		{
			List(list, inCellDropdown: true);
		}

		public void List(string list, bool inCellDropdown)
		{
			AllowedValues = XLAllowedValues.List;
			InCellDropdown = inCellDropdown;
			Value = list;
		}

		public void List(IXLRange range)
		{
			List(range, inCellDropdown: true);
		}

		public void List(IXLRange range, bool inCellDropdown)
		{
			List(range.RangeAddress.ToStringFixed(XLReferenceStyle.A1, includeSheet: true));
		}

		public void Custom(string customValidation)
		{
			AllowedValues = XLAllowedValues.Custom;
			Value = customValidation;
		}

		public void CopyFrom(IXLDataValidation dataValidation)
		{
			if (dataValidation == this)
			{
				return;
			}
			if (Ranges == null && dataValidation.Ranges != null)
			{
				Ranges = new XLRanges();
				dataValidation.Ranges.ForEach(delegate(IXLRange r)
				{
					Ranges.Add(r);
				});
			}
			IgnoreBlanks = dataValidation.IgnoreBlanks;
			InCellDropdown = dataValidation.InCellDropdown;
			ShowErrorMessage = dataValidation.ShowErrorMessage;
			ShowInputMessage = dataValidation.ShowInputMessage;
			InputTitle = dataValidation.InputTitle;
			InputMessage = dataValidation.InputMessage;
			ErrorTitle = dataValidation.ErrorTitle;
			ErrorMessage = dataValidation.ErrorMessage;
			ErrorStyle = dataValidation.ErrorStyle;
			AllowedValues = dataValidation.AllowedValues;
			Operator = dataValidation.Operator;
			MinValue = dataValidation.MinValue;
			MaxValue = dataValidation.MaxValue;
		}

		public void Clear()
		{
			Initialize();
		}
	}
	public interface IXLDataValidations : IEnumerable<IXLDataValidation>, IEnumerable
	{
		void Add(IXLDataValidation dataValidation);

		bool ContainsSingle(IXLRange range);
	}
	internal class XLDataValidations : IXLDataValidations, IEnumerable<IXLDataValidation>, IEnumerable
	{
		private readonly List<IXLDataValidation> _dataValidations = new List<IXLDataValidation>();

		public void Add(IXLDataValidation dataValidation)
		{
			_dataValidations.Add(dataValidation);
		}

		public IEnumerator<IXLDataValidation> GetEnumerator()
		{
			return _dataValidations.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public bool ContainsSingle(IXLRange range)
		{
			int num = 0;
			foreach (IXLDataValidation item in _dataValidations.Where((IXLDataValidation dv) => dv.Ranges.Contains(range)))
			{
				_ = item;
				num++;
				if (num > 1)
				{
					return false;
				}
			}
			return num == 1;
		}

		public void Delete(IXLDataValidation dataValidation)
		{
			_dataValidations.RemoveAll((IXLDataValidation dv) => dv.Ranges.Equals(dataValidation.Ranges));
		}

		public void Delete(IXLRange range)
		{
			_dataValidations.RemoveAll((IXLDataValidation dv) => dv.Ranges.Contains(range));
		}
	}
