	internal class XLNamedRange : IXLNamedRange
	{
		private List<string> _rangeList = new List<string>();

		private readonly XLNamedRanges _namedRanges;

		public string Name { get; set; }

		public IXLRanges Ranges
		{
			get
			{
				XLRanges xLRanges = new XLRanges();
				foreach (IXLRangeBase item in from s in _rangeList.SelectMany((string c) => c.Split(new char[1] { ',' }))
					where s[0] != '"'
					select s into rangeAddress
					let match = XLHelper.NamedRangeReferenceRegex.Match(rangeAddress)
					select (!match.Groups["Sheet"].Success) ? ((IXLRangeBase)_namedRanges.Workbook.Worksheets.SelectMany((IXLWorksheet sheet) => sheet.Tables).Single((IXLTable table) => table.Name == match.Groups["Table"].Value).DataRange.Column(match.Groups["Column"].Value)) : ((IXLRangeBase)_namedRanges.Workbook.WorksheetsInternal.Worksheet(match.Groups["Sheet"].Value).Range(match.Groups["Range"].Value)))
				{
					xLRanges.Add(item);
				}
				return xLRanges;
			}
		}

		public string Comment { get; set; }

		public string RefersTo
		{
			get
			{
				return ToString();
			}
			set
			{
				_rangeList.Clear();
				_rangeList.Add(value);
			}
		}

		internal List<string> RangeList
		{
			get
			{
				return _rangeList;
			}
			set
			{
				_rangeList = value;
			}
		}

		public XLNamedRange(XLNamedRanges namedRanges, string rangeName, string range, string comment = null)
		{
			Name = rangeName;
			_rangeList.Add(range);
			Comment = comment;
			_namedRanges = namedRanges;
		}

		public XLNamedRange(XLNamedRanges namedRanges, string rangeName, IXLRanges ranges, string comment = null)
		{
			Name = rangeName;
			Action<IXLRange> action = delegate(IXLRange r)
			{
				_rangeList.Add(r.RangeAddress.ToStringFixed(XLReferenceStyle.A1, includeSheet: true));
			};
			ranges.ForEach(action);
			Comment = comment;
			_namedRanges = namedRanges;
		}

		public IXLRanges Add(XLWorkbook workbook, string rangeAddress)
		{
			XLRanges xLRanges = new XLRanges();
			string[] array = rangeAddress.Split(new char[1] { '!' });
			string sheetName = array[0].Replace("'", "");
			string rangeAddress2 = array[1];
			IXLRange range = workbook.WorksheetsInternal.Worksheet(sheetName).Range(rangeAddress2);
			xLRanges.Add(range);
			return Add(xLRanges);
		}

		public IXLRanges Add(IXLRange range)
		{
			XLRanges xLRanges = new XLRanges();
			xLRanges.Add(range);
			XLRanges ranges = xLRanges;
			return Add(ranges);
		}

		public IXLRanges Add(IXLRanges ranges)
		{
			ranges.ForEach(delegate(IXLRange r)
			{
				_rangeList.Add(r.ToString());
			});
			return ranges;
		}

		public void Delete()
		{
			_namedRanges.Delete(Name);
		}

		public void Clear()
		{
			_rangeList.Clear();
		}

		public void Remove(string rangeAddress)
		{
			_rangeList.Remove(rangeAddress);
		}

		public void Remove(IXLRange range)
		{
			_rangeList.Remove(range.ToString());
		}

		public void Remove(IXLRanges ranges)
		{
			ranges.ForEach(delegate(IXLRange r)
			{
				_rangeList.Remove(r.ToString());
			});
		}

		public override string ToString()
		{
			string text = _rangeList.Aggregate(string.Empty, (string agg, string r) => agg + r + ",");
			if (text.Length > 0)
			{
				text = text.Substring(0, text.Length - 1);
			}
			return text;
		}

		public IXLNamedRange SetRefersTo(string range)
		{
			RefersTo = range;
			return this;
		}

		public IXLNamedRange SetRefersTo(IXLRangeBase range)
		{
			_rangeList.Clear();
			_rangeList.Add(range.RangeAddress.ToStringFixed(XLReferenceStyle.A1, includeSheet: true));
			return this;
		}

		public IXLNamedRange SetRefersTo(IXLRanges ranges)
		{
			_rangeList.Clear();
			ranges.ForEach(delegate(IXLRange r)
			{
				_rangeList.Add(r.RangeAddress.ToStringFixed(XLReferenceStyle.A1, includeSheet: true));
			});
			return this;
		}
	}
	internal class XLHFText
	{
		private readonly XLWorksheet _worksheet;

		public XLRichString RichText { get; private set; }

		public XLHFText(XLRichString richText, XLWorksheet worksheet)
		{
			RichText = richText;
			_worksheet = worksheet;
		}

		public string GetHFText(string prevText)
		{
			StringBuilder stringBuilder = new StringBuilder();
			IXLFont font = _worksheet.Style.Font;
			if (RichText.FontName != null && RichText.FontName != font.FontName)
			{
				stringBuilder.Append("&\"" + RichText.FontName);
			}
			else
			{
				stringBuilder.Append("&\"-");
			}
			if (RichText.Bold && RichText.Italic)
			{
				stringBuilder.Append(",Bold Italic\"");
			}
			else if (RichText.Bold)
			{
				stringBuilder.Append(",Bold\"");
			}
			else if (RichText.Italic)
			{
				stringBuilder.Append(",Italic\"");
			}
			else
			{
				stringBuilder.Append(",Regular\"");
			}
			if (RichText.FontSize > 0.0 && Math.Abs(RichText.FontSize - font.FontSize) > 1E-10)
			{
				stringBuilder.Append("&" + RichText.FontSize);
			}
			if (RichText.Strikethrough && !font.Strikethrough)
			{
				stringBuilder.Append("&S");
			}
			if (RichText.VerticalAlignment != font.VerticalAlignment)
			{
				if (RichText.VerticalAlignment == XLFontVerticalTextAlignmentValues.Subscript)
				{
					stringBuilder.Append("&Y");
				}
				else if (RichText.VerticalAlignment == XLFontVerticalTextAlignmentValues.Superscript)
				{
					stringBuilder.Append("&X");
				}
			}
			if (RichText.Underline != font.Underline)
			{
				if (RichText.Underline == XLFontUnderlineValues.Single)
				{
					stringBuilder.Append("&U");
				}
				else if (RichText.Underline == XLFontUnderlineValues.Double)
				{
					stringBuilder.Append("&E");
				}
			}
			int num = prevText.LastIndexOf("&K");
			if ((num >= 0 && !RichText.FontColor.Equals(XLColor.FromHtml("#" + prevText.Substring(num + 2, 6)))) || (num == -1 && !RichText.FontColor.Equals(font.FontColor)))
			{
				stringBuilder.Append("&K" + RichText.FontColor.Color.ToHex().Substring(2));
			}
			stringBuilder.Append(RichText.Text);
			if (RichText.Underline != font.Underline)
			{
				if (RichText.Underline == XLFontUnderlineValues.Single)
				{
					stringBuilder.Append("&U");
				}
				else if (RichText.Underline == XLFontUnderlineValues.Double)
				{
					stringBuilder.Append("&E");
				}
			}
			if (RichText.VerticalAlignment != font.VerticalAlignment)
			{
				if (RichText.VerticalAlignment == XLFontVerticalTextAlignmentValues.Subscript)
				{
					stringBuilder.Append("&Y");
				}
				else if (RichText.VerticalAlignment == XLFontVerticalTextAlignmentValues.Superscript)
				{
					stringBuilder.Append("&X");
				}
			}
			if (RichText.Strikethrough && !font.Strikethrough)
			{
				stringBuilder.Append("&S");
			}
			return stringBuilder.ToString();
		}
	}
