		public bool HasValue { get; private set; }

		public XLColorType ColorType => _colorType;

		public System.Drawing.Color Color
		{
			get
			{
				if (_colorType == XLColorType.Theme)
				{
					throw new Exception("Cannot convert theme color to Color.");
				}
				if (_colorType == XLColorType.Indexed)
				{
					return IndexedColors[_indexed].Color;
				}
				return _color;
			}
		}

		public int Indexed
		{
			get
			{
				if (ColorType == XLColorType.Theme)
				{
					throw new Exception("Cannot convert theme color to indexed color.");
				}
				if (ColorType == XLColorType.Indexed)
				{
					return _indexed;
				}
				throw new Exception("Cannot convert Color to indexed color.");
			}
		}

		public XLThemeColor ThemeColor
		{
			get
			{
				if (ColorType == XLColorType.Theme)
				{
					return _themeColor;
				}
				if (ColorType == XLColorType.Indexed)
				{
					throw new Exception("Cannot convert indexed color to theme color.");
				}
				throw new Exception("Cannot convert Color to theme color.");
			}
		}

		public double ThemeTint
		{
			get
			{
				if (ColorType == XLColorType.Theme)
				{
					return _themeTint;
				}
				if (ColorType == XLColorType.Indexed)
				{
					throw new Exception("Cannot extract theme tint from an indexed color.");
				}
				return (double)(int)_color.A / 255.0;
			}
		}

		public static XLColor FromColor(System.Drawing.Color color)
		{
			return new XLColor(color);
		}

		public static XLColor FromArgb(int argb)
		{
			return new XLColor(System.Drawing.Color.FromArgb(argb));
		}

		public static XLColor FromArgb(int r, int g, int b)
		{
			return new XLColor(System.Drawing.Color.FromArgb(r, g, b));
		}

		public static XLColor FromArgb(int a, int r, int g, int b)
		{
			return new XLColor(System.Drawing.Color.FromArgb(a, r, g, b));
		}

		public static XLColor FromKnownColor(KnownColor color)
		{
			return new XLColor(System.Drawing.Color.FromKnownColor(color));
		}

		public static XLColor FromName(string name)
		{
			return new XLColor(System.Drawing.Color.FromName(name));
		}

		public static XLColor FromHtml(string htmlColor)
		{
			return new XLColor(ColorTranslator.FromHtml(htmlColor));
		}

		public static XLColor FromIndex(int index)
		{
			return new XLColor(index);
		}

		public static XLColor FromTheme(XLThemeColor themeColor)
		{
			return new XLColor(themeColor);
		}

		public static XLColor FromTheme(XLThemeColor themeColor, double themeTint)
		{
			return new XLColor(themeColor, themeTint);
		}

		public bool Equals(XLColor other)
		{
			if (_colorType == other._colorType)
			{
				if (_colorType == XLColorType.Color)
				{
					return _color == other._color;
				}
				if (_colorType == XLColorType.Theme)
				{
					if (_themeColor == other._themeColor)
					{
						return Math.Abs(_themeTint - other._themeTint) < 1E-10;
					}
					return false;
				}
				return _indexed == other._indexed;
			}
			return false;
		}

		public override bool Equals(object obj)
		{
			return Equals((XLColor)obj);
		}

		public override int GetHashCode()
		{
			if (_hashCode == 0)
			{
				if (_colorType == XLColorType.Color)
				{
					_hashCode = _color.GetHashCode();
				}
				else if (_colorType == XLColorType.Theme)
				{
					int hashCode = _themeColor.GetHashCode();
					double themeTint = _themeTint;
					_hashCode = hashCode ^ themeTint.GetHashCode();
				}
				else
				{
					_hashCode = _indexed;
				}
			}
			return _hashCode;
		}

		public override string ToString()
		{
			if (_colorType == XLColorType.Color)
			{
				return Color.ToHex();
			}
			if (_colorType == XLColorType.Theme)
			{
				string arg = _themeColor.ToString();
				double themeTint = _themeTint;
				return $"Color Theme: {arg}, Tint: {themeTint.ToString()}";
			}
			return "Color Index: " + _indexed;
		}

		public static bool operator ==(XLColor left, XLColor right)
		{
			if (object.ReferenceEquals(left, right))
			{
				return true;
			}
			if ((object)left == null || (object)right == null)
			{
				return false;
			}
			return left.Equals(right);
		}

		public static bool operator !=(XLColor left, XLColor right)
		{
			return !(left == right);
		}

		internal XLColor(XLColor defaultColor)
		{
			if (defaultColor._colorType == XLColorType.Color)
			{
				_color = defaultColor._color;
			}
			else if (defaultColor._colorType == XLColorType.Theme)
			{
				_themeColor = defaultColor._themeColor;
				_themeTint = defaultColor._themeTint;
			}
			else
			{
				_indexed = defaultColor._indexed;
			}
			HasValue = true;
			_hashCode = defaultColor._hashCode;
			_colorType = defaultColor._colorType;
		}

		internal XLColor()
		{
			HasValue = false;
			_hashCode = 0;
		}

		internal XLColor(System.Drawing.Color color)
		{
			_color = color;
			_hashCode = 0xD ^ color.ToArgb();
			HasValue = true;
			_colorType = XLColorType.Color;
		}

		internal XLColor(int index)
		{
			_indexed = index;
			_hashCode = 0xB ^ _indexed;
			HasValue = true;
			_colorType = XLColorType.Indexed;
		}

		internal XLColor(XLThemeColor themeColor)
		{
			_themeColor = themeColor;
			_themeTint = 1.0;
			_hashCode = 7 ^ _themeColor.GetHashCode() ^ _themeTint.GetHashCode();
			HasValue = true;
			_colorType = XLColorType.Theme;
		}

		internal XLColor(XLThemeColor themeColor, double themeTint)
		{
			_themeColor = themeColor;
			_themeTint = themeTint;
			_hashCode = 7 ^ _themeColor.GetHashCode() ^ _themeTint.GetHashCode();
			HasValue = true;
			_colorType = XLColorType.Theme;
		}
	}
	public enum XLColorType
	{
		Color,
		Theme,
		Indexed
	}
	public enum XLThemeColor
	{
		Background1,
		Text1,
		Background2,
		Text2,
		Accent1,
		Accent2,
		Accent3,
		Accent4,
		Accent5,
		Accent6,
		Hyperlink,
		FollowedHyperlink
	}
	public interface IXLProtection : IEquatable<IXLProtection>
	{
		bool Locked { get; set; }

		bool Hidden { get; set; }

		IXLStyle SetLocked();

		IXLStyle SetLocked(bool value);

		IXLStyle SetHidden();

		IXLStyle SetHidden(bool value);
	}
	internal class XLProtection : IXLProtection, IEquatable<IXLProtection>
	{
		private readonly IXLStylized _container;

		private bool _hidden;

		private bool _locked;

		public bool Locked
		{
			get
			{
				return _locked;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Protection.Locked = value;
					});
				}
				else
				{
					_locked = value;
				}
			}
		}

		public bool Hidden
		{
			get
			{
				return _hidden;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Protection.Hidden = value;
					});
				}
				else
				{
					_hidden = value;
				}
			}
		}

		public bool Equals(IXLProtection other)
		{
			if (!(other is XLProtection xLProtection))
			{
				return false;
			}
			if (_locked == xLProtection._locked)
			{
				return _hidden == xLProtection._hidden;
			}
			return false;
		}

		public IXLStyle SetLocked()
		{
			Locked = true;
			return _container.Style;
		}

		public IXLStyle SetLocked(bool value)
		{
			Locked = value;
			return _container.Style;
		}

		public IXLStyle SetHidden()
		{
			Hidden = true;
			return _container.Style;
		}

		public IXLStyle SetHidden(bool value)
		{
			Hidden = value;
			return _container.Style;
		}

		public XLProtection()
			: this(null, XLWorkbook.DefaultStyle.Protection)
		{
		}

		public XLProtection(IXLStylized container, IXLProtection defaultProtection = null)
		{
			_container = container;
			if (defaultProtection != null)
			{
				_locked = defaultProtection.Locked;
				_hidden = defaultProtection.Hidden;
			}
		}

		private void SetStyleChanged()
		{
			if (_container != null)
			{
				_container.StyleChanged = true;
			}
		}

		public override bool Equals(object obj)
		{
			return Equals((IXLProtection)obj);
		}

		public override int GetHashCode()
		{
			if (Locked)
			{
				if (!Hidden)
				{
					return 10;
				}
				return 11;
			}
			if (!Hidden)
			{
				return 0;
			}
			return 1;
		}

		public override string ToString()
		{
			if (Locked)
			{
				if (!Hidden)
				{
					return "Locked";
				}
				return "Locked-Hidden";
			}
			if (!Hidden)
			{
				return "None";
			}
			return "Hidden";
		}
	}
	internal class XLStylizedContainer : IXLStylized
	{
		private readonly IXLStylized _container;

		public bool StyleChanged { get; set; }

		public IXLStyle Style { get; set; }

		public IEnumerable<IXLStyle> Styles
		{
			get
			{
				_container.UpdatingStyle = true;
				yield return Style;
				_container.UpdatingStyle = false;
			}
		}

		public bool UpdatingStyle { get; set; }

		public IXLStyle InnerStyle { get; set; }

		public IXLRanges RangesUsed { get; set; }

		public XLStylizedContainer(IXLStyle style, IXLStylized container)
		{
			Style = style;
			_container = container;
			RangesUsed = container.RangesUsed;
		}
	}
	public interface IXLTableField
	{
		int Index { get; set; }

		string Name { get; set; }

		string TotalsRowLabel { get; set; }

		string TotalsRowFormulaA1 { get; set; }

		string TotalsRowFormulaR1C1 { get; set; }

		XLTotalsRowFunction TotalsRowFunction { get; set; }
	}
	internal class XLTableField : IXLTableField
	{
		private XLTable table;

		internal string totalsRowLabel;

		internal XLTotalsRowFunction totalsRowFunction;

		public int Index { get; set; }

		public string Name { get; set; }

		public string TotalsRowLabel
		{
			get
			{
				return totalsRowLabel;
			}
			set
			{
				totalsRowFunction = XLTotalsRowFunction.None;
				table.TotalsRow().Cell(Index + 1).SetValue(value);
				totalsRowLabel = value;
			}
		}

		public string TotalsRowFormulaA1
		{
			get
			{
				return table.TotalsRow().Cell(Index + 1).FormulaA1;
			}
			set
			{
				totalsRowFunction = XLTotalsRowFunction.Custom;
				table.TotalsRow().Cell(Index + 1).FormulaA1 = value;
			}
		}

		public string TotalsRowFormulaR1C1
		{
			get
			{
				return table.TotalsRow().Cell(Index + 1).FormulaR1C1;
			}
			set
			{
				totalsRowFunction = XLTotalsRowFunction.Custom;
				table.TotalsRow().Cell(Index + 1).FormulaR1C1 = value;
			}
		}

		public XLTotalsRowFunction TotalsRowFunction
		{
			get
			{
				return totalsRowFunction;
			}
			set
			{
				if (value != 0 && value != XLTotalsRowFunction.Custom)
				{
					IXLCell iXLCell = table.TotalsRow().Cell(Index + 1);
					string text = string.Empty;
					switch (value)
					{
					case XLTotalsRowFunction.Sum:
						text = "109";
						break;
					case XLTotalsRowFunction.Minimum:
						text = "105";
						break;
					case XLTotalsRowFunction.Maximum:
						text = "104";
						break;
					case XLTotalsRowFunction.Average:
						text = "101";
						break;
					case XLTotalsRowFunction.Count:
						text = "103";
						break;
					case XLTotalsRowFunction.CountNumbers:
						text = "102";
						break;
					case XLTotalsRowFunction.StandardDeviation:
						text = "107";
						break;
					case XLTotalsRowFunction.Variance:
						text = "110";
						break;
					}
					iXLCell.FormulaA1 = "SUBTOTAL(" + text + ",[" + Name + "])";
					IXLCell iXLCell2 = table.LastRow().Cell(Index + 1);
					if (iXLCell2.DataType != 0)
					{
						iXLCell.DataType = iXLCell2.DataType;
						iXLCell.Style.NumberFormat = iXLCell2.Style.NumberFormat;
					}
				}
				totalsRowFunction = value;
			}
		}

		public XLTableField(XLTable table)
		{
			this.table = table;
		}
	}
	public enum XLTotalsRowFunction
	{
		None,
		Sum,
		Minimum,
		Maximum,
		Average,
		Count,
		CountNumbers,
		StandardDeviation,
		Variance,
		Custom
	}
	public interface IXLTableRows : IEnumerable<IXLTableRow>, IEnumerable
	{
		IXLStyle Style { get; set; }

		void Add(IXLTableRow tableRow);

		IXLCells Cells();

		IXLCells CellsUsed();

		IXLCells CellsUsed(bool includeFormats);

		IXLTableRows Clear(XLClearOptions clearOptions = XLClearOptions.ContentsAndFormats);

		void Select();
	}
	internal class XLTableRows : IXLTableRows, IEnumerable<IXLTableRow>, IEnumerable, IXLStylized
	{
		private readonly List<XLTableRow> _ranges = new List<XLTableRow>();

		private IXLStyle _style;

		public bool StyleChanged { get; set; }

		public IEnumerable<IXLStyle> Styles
		{
			get
			{
				UpdatingStyle = true;
				yield return _style;
				foreach (XLTableRow rng in _ranges)
				{
					yield return rng.Style;
					foreach (XLCell r in rng.Worksheet.Internals.CellsCollection.GetCells(rng.RangeAddress.FirstAddress.RowNumber, rng.RangeAddress.FirstAddress.ColumnNumber, rng.RangeAddress.LastAddress.RowNumber, rng.RangeAddress.LastAddress.ColumnNumber))
					{
						yield return r.Style;
					}
				}
				UpdatingStyle = false;
			}
		}

		public bool UpdatingStyle { get; set; }

		public IXLStyle InnerStyle
		{
			get
			{
				return _style;
			}
			set
			{
				_style = new XLStyle(this, value);
			}
		}

		public IXLRanges RangesUsed
		{
			get
			{
				XLRanges retVal = new XLRanges();
				this.ForEach(delegate(IXLTableRow c)
				{
					retVal.Add(c.AsRange());
				});
				return retVal;
			}
		}

		public IXLStyle Style
		{
			get
			{
				return _style;
			}
			set
			{
				_style = new XLStyle(this, value);
				_ranges.ForEach(delegate(XLTableRow r)
				{
					r.Style = value;
				});
			}
		}

		public XLTableRows(IXLStyle defaultStyle)
		{
			_style = new XLStyle(this, defaultStyle);
		}

		public IXLTableRows Clear(XLClearOptions clearOptions = XLClearOptions.ContentsAndFormats)
		{
			_ranges.ForEach(delegate(XLTableRow r)
			{
				r.Clear(clearOptions);
			});
			return this;
		}

		public void Add(IXLTableRow range)
		{
			_ranges.Add((XLTableRow)range);
		}

		public IEnumerator<IXLTableRow> GetEnumerator()
		{
			List<IXLTableRow> list = new List<IXLTableRow>();
			_ranges.ForEach(list.Add);
			return list.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public IXLCells Cells()
		{
			XLCells xLCells = new XLCells(usedCellsOnly: false, includeFormats: false);
			foreach (XLTableRow range in _ranges)
			{
				xLCells.Add(range.RangeAddress);
			}
			return xLCells;
		}

		public IXLCells CellsUsed()
		{
			XLCells xLCells = new XLCells(usedCellsOnly: true, includeFormats: false);
			foreach (XLTableRow range in _ranges)
			{
				xLCells.Add(range.RangeAddress);
			}
			return xLCells;
		}

		public IXLCells CellsUsed(bool includeFormats)
		{
			XLCells xLCells = new XLCells(usedCellsOnly: false, includeFormats);
			foreach (XLTableRow range in _ranges)
			{
				xLCells.Add(range.RangeAddress);
			}
			return xLCells;
		}

		public void Select()
		{
