		public override XLRange Range(string rangeAddressStr)
		{
			string rangeAddress;
			if (Enumerable.Contains(rangeAddressStr, ':') || Enumerable.Contains(rangeAddressStr, '-'))
			{
				if (Enumerable.Contains(rangeAddressStr, '-'))
				{
					rangeAddressStr = rangeAddressStr.Replace('-', ':');
				}
				string[] array = rangeAddressStr.Split(new char[1] { ':' });
				string address = array[0];
				string address2 = array[1];
				rangeAddress = FixRowAddress(address) + ":" + FixRowAddress(address2);
			}
			else
			{
				rangeAddress = FixRowAddress(rangeAddressStr);
			}
			XLRangeAddress rangeAddress2 = new XLRangeAddress(base.Worksheet, rangeAddress);
			return Range(rangeAddress2);
		}

		public int CompareTo(XLRangeRow otherRow, IXLSortElements columnsToSort)
		{
			foreach (IXLSortElement item in columnsToSort)
			{
				XLCell xLCell = (XLCell)Cell(item.ElementNumber);
				XLCell xLCell2 = (XLCell)otherRow.Cell(item.ElementNumber);
				bool flag = xLCell.IsEmpty();
				bool flag2 = xLCell2.IsEmpty();
				int num = ((item.IgnoreBlanks && (flag || flag2)) ? ((!flag || !flag2) ? ((!flag) ? ((item.SortOrder != 0) ? 1 : (-1)) : ((item.SortOrder == XLSortOrder.Ascending) ? 1 : (-1))) : 0) : ((xLCell.DataType == xLCell2.DataType) ? ((xLCell.DataType == XLCellValues.Text) ? (item.MatchCase ? xLCell.InnerText.CompareTo(xLCell2.InnerText) : string.Compare(xLCell.InnerText, xLCell2.InnerText, ignoreCase: true)) : ((xLCell.DataType != XLCellValues.TimeSpan) ? double.Parse(xLCell.InnerText).CompareTo(double.Parse(xLCell2.InnerText)) : xLCell.GetTimeSpan().CompareTo(xLCell2.GetTimeSpan()))) : ((!item.MatchCase) ? xLCell.GetString().CompareTo(xLCell2.GetString()) : string.Compare(xLCell.GetString(), xLCell2.GetString(), ignoreCase: true))));
				if (num != 0)
				{
					return (item.SortOrder == XLSortOrder.Ascending) ? num : (num * -1);
				}
			}
			return 0;
		}

		private XLRangeRow RowShift(int rowsToShift)
		{
			int num = RowNumber() + rowsToShift;
			return base.Worksheet.Range(num, base.RangeAddress.FirstAddress.ColumnNumber, num, base.RangeAddress.LastAddress.ColumnNumber).FirstRow();
		}

