	internal class XLTable : XLRange, IXLTable, IXLRange, IXLRangeBase, IDisposable
	{
		private string _name;

		internal bool _showTotalsRow;

		internal HashSet<string> _uniqueNames;

		private IXLRangeAddress _lastRangeAddress;

		private Dictionary<string, IXLTableField> _fieldNames;

		private XLAutoFilter _autoFilter;

		private bool _showAutoFilter;

		internal bool _showHeaderRow;

		public Dictionary<string, IXLTableField> FieldNames
		{
			get
			{
				if (_fieldNames != null && _lastRangeAddress != null && _lastRangeAddress.Equals(base.RangeAddress))
				{
					return _fieldNames;
				}
				_fieldNames = new Dictionary<string, IXLTableField>();
				_lastRangeAddress = base.RangeAddress;
				if (ShowHeaderRow)
				{
					IXLRangeRow iXLRangeRow = HeadersRow();
					int num = 0;
					foreach (IXLCell item in iXLRangeRow.Cells())
					{
						string text = item.GetString();
						if (XLHelper.IsNullOrWhiteSpace(text))
						{
							text = "Column" + (num + 1);
							item.SetValue(text);
						}
						if (_fieldNames.ContainsKey(text))
						{
							throw new ArgumentException("The header row contains more than one field name '" + text + "'.");
						}
						_fieldNames.Add(text, new XLTableField(this)
						{
							Index = num++,
							Name = text
						});
					}
				}
				else
				{
					if (_fieldNames == null)
					{
						_fieldNames = new Dictionary<string, IXLTableField>();
					}
					int num2 = ColumnCount();
					int i;
					for (i = 1; i <= num2; i++)
					{
						if (!_fieldNames.Values.Any((IXLTableField f) => f.Index == i - 1))
						{
							string text2 = "Column" + i;
							_fieldNames.Add(text2, new XLTableField(this)
							{
								Index = i - 1,
								Name = text2
							});
						}
					}
				}
				return _fieldNames;
			}
		}

		public string RelId { get; set; }

		public IXLTableRange DataRange
		{
			get
			{
				XLRange range = ((!_showHeaderRow) ? (_showTotalsRow ? Range(1, 1, RowCount() - 1, ColumnCount()) : Range(1, 1, RowCount(), ColumnCount())) : (_showTotalsRow ? Range(2, 1, RowCount() - 1, ColumnCount()) : Range(2, 1, RowCount(), ColumnCount())));
				return new XLTableRange(range, this);
			}
		}

		public XLAutoFilter AutoFilter
		{
			get
			{
				using (XLRange range = (ShowTotalsRow ? Range(1, 1, RowCount() - 1, ColumnCount()) : AsRange()))
				{
					if (_autoFilter == null)
					{
						_autoFilter = new XLAutoFilter();
					}
					_autoFilter.Range = range;
				}
				return _autoFilter;
			}
		}

		public bool EmphasizeFirstColumn { get; set; }

		public bool EmphasizeLastColumn { get; set; }

		public bool ShowRowStripes { get; set; }

		public bool ShowColumnStripes { get; set; }

		public bool ShowAutoFilter
		{
			get
			{
				if (_showHeaderRow)
				{
					return _showAutoFilter;
				}
				return false;
			}
			set
			{
				_showAutoFilter = value;
			}
		}

		public XLTableTheme Theme { get; set; }

		public string Name
		{
			get
			{
				return _name;
			}
			set
			{
				if (base.Worksheet.Tables.Any((IXLTable t) => t.Name == value))
				{
					throw new ArgumentException($"This worksheet already contains a table named '{value}'");
				}
				_name = value;
			}
		}

		public bool ShowTotalsRow
		{
			get
			{
				return _showTotalsRow;
			}
			set
			{
				if (value && !_showTotalsRow)
				{
					InsertRowsBelow(1);
				}
				else if (!value && _showTotalsRow)
				{
					TotalsRow().Delete();
				}
				_showTotalsRow = value;
				if (_showTotalsRow)
				{
					AutoFilter.Range = base.Worksheet.Range(base.RangeAddress.FirstAddress.RowNumber, base.RangeAddress.FirstAddress.ColumnNumber, base.RangeAddress.LastAddress.RowNumber - 1, base.RangeAddress.LastAddress.ColumnNumber);
				}
				else
				{
					AutoFilter.Range = base.Worksheet.Range(base.RangeAddress);
				}
			}
		}

		public IEnumerable<IXLTableField> Fields
		{
			get
			{
