				for (int co = 0; co < columnCount; co++)
				{
					yield return Field(co);
				}
			}
		}

		IXLBaseAutoFilter IXLTable.AutoFilter => AutoFilter;

		public bool ShowHeaderRow
		{
			get
			{
				return _showHeaderRow;
			}
			set
			{
				if (_showHeaderRow == value)
				{
					return;
				}
				if (_showHeaderRow)
				{
					IXLRangeRow iXLRangeRow = HeadersRow();
					_uniqueNames = new HashSet<string>();
					int num = 1;
					foreach (IXLCell item in iXLRangeRow.Cells())
					{
						if (XLHelper.IsNullOrWhiteSpace(((XLCell)item).InnerText))
						{
							item.Value = GetUniqueName("Column" + num.ToStringLookup());
						}
						_uniqueNames.Add(item.GetString());
						num++;
					}
					iXLRangeRow.Clear();
					base.RangeAddress.FirstAddress = new XLAddress(base.Worksheet, base.RangeAddress.FirstAddress.RowNumber + 1, base.RangeAddress.FirstAddress.ColumnNumber, base.RangeAddress.FirstAddress.FixedRow, base.RangeAddress.FirstAddress.FixedColumn);
					HeadersRow().DataType = XLCellValues.Text;
				}
				else
				{
					using XLRange xLRange = base.Worksheet.Range(base.RangeAddress.FirstAddress.RowNumber - 1, base.RangeAddress.FirstAddress.ColumnNumber, base.RangeAddress.LastAddress.RowNumber, base.RangeAddress.LastAddress.ColumnNumber);
					using XLRangeRow xLRangeRow = xLRange.FirstRow();
					IXLRangeRow iXLRangeRow2;
					if (xLRangeRow.IsEmpty(includeFormats: true))
					{
						iXLRangeRow2 = xLRangeRow;
						base.RangeAddress.FirstAddress = new XLAddress(base.Worksheet, base.RangeAddress.FirstAddress.RowNumber - 1, base.RangeAddress.FirstAddress.ColumnNumber, base.RangeAddress.FirstAddress.FixedRow, base.RangeAddress.FirstAddress.FixedColumn);
					}
					else
					{
						XLAddress firstAddress = base.RangeAddress.FirstAddress;
						XLAddress lastAddress = base.RangeAddress.LastAddress;
						iXLRangeRow2 = xLRangeRow.InsertRowsBelow(1, expandRange: false).First();
						base.RangeAddress.FirstAddress = new XLAddress(base.Worksheet, firstAddress.RowNumber, firstAddress.ColumnNumber, firstAddress.FixedRow, firstAddress.FixedColumn);
						base.RangeAddress.LastAddress = new XLAddress(base.Worksheet, lastAddress.RowNumber + 1, lastAddress.ColumnNumber, lastAddress.FixedRow, lastAddress.FixedColumn);
					}
					int num2 = 1;
					foreach (string key in FieldNames.Keys)
					{
						iXLRangeRow2.Cell(num2).SetValue(key);
						num2++;
					}
				}
				_showHeaderRow = value;
			}
		}

		public XLTable(XLRange range, bool addToTables, bool setAutofilter = true)
			: base(new XLRangeParameters(range.RangeAddress, range.Style))
		{
			InitializeValues(setAutofilter);
			int num = 1;
			string tableName;
			while (true)
			{
				tableName = $"Table{num}";
				if (!base.Worksheet.Tables.Any((IXLTable t) => t.Name == tableName))
				{
					break;
				}
				num++;
			}
			Name = tableName;
			AddToTables(range, addToTables);
		}

