		public new IXLRange Sort(string columnsToSortBy, XLSortOrder sortOrder = XLSortOrder.Ascending, bool matchCase = false, bool ignoreBlanks = true)
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (string item in from coPair in columnsToSortBy.Split(new char[1] { ',' })
				select coPair.Trim())
			{
				string text;
				string value;
				if (Enumerable.Contains(item, ' '))
				{
					string[] array = item.Split(new char[1] { ' ' });
					text = array[0];
					value = array[1];
				}
				else
				{
					text = item;
					value = "ASC";
				}
				if (!int.TryParse(text, out var result))
				{
					result = Field(text).Index + 1;
				}
				stringBuilder.Append(result);
				stringBuilder.Append(" ");
				stringBuilder.Append(value);
				stringBuilder.Append(",");
			}
			return DataRange.Sort(stringBuilder.ToString(0, stringBuilder.Length - 1), sortOrder, matchCase, ignoreBlanks);
		}

