		private void AddToTables(XLRange range, bool addToTables)
		{
			if (!addToTables)
			{
				return;
			}
			_uniqueNames = new HashSet<string>();
			int num = 1;
			foreach (IXLCell item in range.Row(1).Cells())
			{
				if (XLHelper.IsNullOrWhiteSpace(((XLCell)item).InnerText))
				{
					item.Value = GetUniqueName("Column" + num.ToStringLookup());
				}
				_uniqueNames.Add(item.GetString());
				num++;
			}
			base.Worksheet.Tables.Add(this);
		}

		private string GetUniqueName(string originalName)
		{
			string text = originalName;
			if (_uniqueNames.Contains(text))
			{
				int num = 1;
				text = originalName + num.ToStringLookup();
				while (_uniqueNames.Contains(text))
				{
					num++;
					text = originalName + num.ToStringLookup();
				}
			}
			_uniqueNames.Add(text);
			return text;
		}

		public int GetFieldIndex(string name)
		{
			if (FieldNames.ContainsKey(name))
			{
				return FieldNames[name].Index;
			}
			throw new ArgumentOutOfRangeException("The header row doesn't contain field name '" + name + "'.");
		}

