	internal class XLRangeAddress : IXLRangeAddress
	{
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private XLAddress _firstAddress;

		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private XLAddress _lastAddress;

		public XLWorksheet Worksheet { get; internal set; }

		public XLAddress FirstAddress
		{
			get
			{
				if (IsInvalid)
				{
					throw new Exception("Range is invalid.");
				}
				return _firstAddress;
			}
			set
			{
				_firstAddress = value;
			}
		}

		public XLAddress LastAddress
		{
			get
			{
				if (IsInvalid)
				{
					throw new Exception("Range is an invalid state.");
				}
				return _lastAddress;
			}
			set
			{
				_lastAddress = value;
			}
		}

		IXLWorksheet IXLRangeAddress.Worksheet => Worksheet;

		IXLAddress IXLRangeAddress.FirstAddress
		{
			[DebuggerStepThrough]
			get
			{
				return FirstAddress;
			}
			set
			{
				FirstAddress = value as XLAddress;
			}
		}

		IXLAddress IXLRangeAddress.LastAddress
		{
			[DebuggerStepThrough]
			get
			{
				return LastAddress;
			}
			set
			{
				LastAddress = value as XLAddress;
			}
		}

		public bool IsInvalid { get; set; }

		public XLRangeAddress(XLRangeAddress rangeAddress)
			: this(rangeAddress.FirstAddress, rangeAddress.LastAddress)
		{
		}

		public XLRangeAddress(XLAddress firstAddress, XLAddress lastAddress)
		{
			Worksheet = firstAddress.Worksheet;
			FirstAddress = XLAddress.Create(firstAddress);
			LastAddress = XLAddress.Create(lastAddress);
		}

		public XLRangeAddress(XLWorksheet worksheet, string rangeAddress)
		{
			string text = (rangeAddress.Contains("!") ? rangeAddress.Substring(rangeAddress.IndexOf("!") + 1) : rangeAddress);
			string text2;
			string text3;
			if (Enumerable.Contains(text, ':'))
			{
				string[] array = text.Split(new char[1] { ':' });
				text2 = array[0];
				text3 = array[1];
			}
			else
			{
				text2 = text;
				text3 = text;
			}
			if (XLHelper.IsValidA1Address(text2))
			{
				FirstAddress = XLAddress.Create(worksheet, text2);
				LastAddress = XLAddress.Create(worksheet, text3);
			}
			else
			{
				text2 = text2.Replace("$", string.Empty);
				text3 = text3.Replace("$", string.Empty);
				if (char.IsDigit(text2[0]))
				{
					FirstAddress = XLAddress.Create(worksheet, "A" + text2);
					LastAddress = XLAddress.Create(worksheet, "XFD" + text3);
				}
				else
				{
					FirstAddress = XLAddress.Create(worksheet, text2 + "1");
					LastAddress = XLAddress.Create(worksheet, text3 + 1048576.ToStringLookup());
				}
			}
			Worksheet = worksheet;
		}

		public string ToStringRelative()
		{
			return ToStringRelative(includeSheet: false);
		}

		public string ToStringFixed()
		{
			return ToStringFixed(XLReferenceStyle.A1);
		}

		public string ToStringRelative(bool includeSheet)
		{
			if (includeSheet)
			{
				return $"'{Worksheet.Name}'!{_firstAddress.ToStringRelative()}:{_lastAddress.ToStringRelative()}";
			}
			return _firstAddress.ToStringRelative() + ":" + _lastAddress.ToStringRelative();
		}

		public string ToStringFixed(XLReferenceStyle referenceStyle)
		{
			return ToStringFixed(referenceStyle, includeSheet: false);
		}

		public string ToStringFixed(XLReferenceStyle referenceStyle, bool includeSheet)
		{
			if (includeSheet)
			{
				return $"'{Worksheet.Name}'!{_firstAddress.ToStringFixed(referenceStyle)}:{_lastAddress.ToStringFixed(referenceStyle)}";
			}
			return _firstAddress.ToStringFixed(referenceStyle) + ":" + _lastAddress.ToStringFixed(referenceStyle);
		}

		public override string ToString()
		{
			return string.Concat(_firstAddress, ":", _lastAddress);
		}

		public override bool Equals(object obj)
		{
			XLRangeAddress xLRangeAddress = (XLRangeAddress)obj;
			if (Worksheet.Equals(xLRangeAddress.Worksheet) && FirstAddress.Equals(xLRangeAddress.FirstAddress))
			{
				return LastAddress.Equals(xLRangeAddress.LastAddress);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return Worksheet.GetHashCode() ^ FirstAddress.GetHashCode() ^ LastAddress.GetHashCode();
		}
	}
