		public new IXLRangeColumn CopyTo(IXLCell target)
		{
			base.CopyTo(target);
			int num = target.Address.RowNumber + RowCount() - 1;
			if (num > 1048576)
			{
				num = 1048576;
			}
			int num2 = target.Address.ColumnNumber + ColumnCount() - 1;
			if (num2 > 16384)
			{
				num2 = 16384;
			}
			return target.Worksheet.Range(target.Address.RowNumber, target.Address.ColumnNumber, num, num2).Column(1);
		}

		public new IXLRangeColumn CopyTo(IXLRangeBase target)
		{
			base.CopyTo(target);
			int num = target.RangeAddress.FirstAddress.RowNumber + RowCount() - 1;
			if (num > 1048576)
			{
				num = 1048576;
			}
			int num2 = target.RangeAddress.FirstAddress.ColumnNumber + ColumnCount() - 1;
			if (num2 > 16384)
			{
				num2 = 16384;
			}
			return target.Worksheet.Range(target.RangeAddress.FirstAddress.RowNumber, target.RangeAddress.FirstAddress.ColumnNumber, num, num2).Column(1);
		}

