		public IXLRangeColumns Columns(string columns)
		{
			XLRangeColumns xLRangeColumns = new XLRangeColumns();
			string[] source = columns.Split(new char[1] { ',' });
			foreach (string item in source.Select((string pair) => pair.Trim()))
			{
				string firstCellAddress;
				string lastCellAddress;
				if (Enumerable.Contains(item, ':') || Enumerable.Contains(item, '-'))
				{
					string[] array = (Enumerable.Contains(item, '-') ? item.Replace('-', ':').Split(new char[1] { ':' }) : item.Split(new char[1] { ':' }));
					firstCellAddress = array[0];
					lastCellAddress = array[1];
				}
				else
				{
					firstCellAddress = item;
					lastCellAddress = item;
				}
				xLRangeColumns.Add(Range(firstCellAddress, lastCellAddress).FirstColumn());
			}
			return xLRangeColumns;
		}

