	internal class XLRowsCollection : IDictionary<int, XLRow>, ICollection<KeyValuePair<int, XLRow>>, IEnumerable<KeyValuePair<int, XLRow>>, IEnumerable, IDisposable
	{
		private readonly Dictionary<int, XLRow> _deleted = new Dictionary<int, XLRow>();

		private readonly Dictionary<int, XLRow> _dictionary = new Dictionary<int, XLRow>();

		public int MaxRowUsed;

		public Dictionary<int, XLRow> Deleted => _deleted;

		public ICollection<int> Keys => _dictionary.Keys;

		public ICollection<XLRow> Values => _dictionary.Values;

		public XLRow this[int key]
		{
			get
			{
				return _dictionary[key];
			}
			set
			{
				_dictionary[key] = value;
			}
		}

		public int Count => _dictionary.Count;

		public bool IsReadOnly => false;

		public void Add(int key, XLRow value)
		{
			if (key > MaxRowUsed)
			{
				MaxRowUsed = key;
			}
			if (_deleted.ContainsKey(key))
			{
				_deleted.Remove(key);
			}
			_dictionary.Add(key, value);
		}

		public bool ContainsKey(int key)
		{
			return _dictionary.ContainsKey(key);
		}

		public bool Remove(int key)
		{
			if (!_deleted.ContainsKey(key))
			{
				_deleted.Add(key, _dictionary[key]);
			}
			return _dictionary.Remove(key);
		}

		public bool TryGetValue(int key, out XLRow value)
		{
			return _dictionary.TryGetValue(key, out value);
		}

		public void Add(KeyValuePair<int, XLRow> item)
		{
			if (item.Key > MaxRowUsed)
			{
				MaxRowUsed = item.Key;
			}
			if (_deleted.ContainsKey(item.Key))
			{
				_deleted.Remove(item.Key);
			}
			_dictionary.Add(item.Key, item.Value);
		}

		public void Clear()
		{
			foreach (KeyValuePair<int, XLRow> item in _dictionary.Where((KeyValuePair<int, XLRow> kp) => !_deleted.ContainsKey(kp.Key)))
			{
				_deleted.Add(item.Key, item.Value);
			}
			_dictionary.Clear();
		}

		public bool Contains(KeyValuePair<int, XLRow> item)
		{
			return _dictionary.Contains(item);
		}

		public void CopyTo(KeyValuePair<int, XLRow>[] array, int arrayIndex)
		{
			throw new NotImplementedException();
		}

		public bool Remove(KeyValuePair<int, XLRow> item)
		{
			if (!_deleted.ContainsKey(item.Key))
			{
				_deleted.Add(item.Key, _dictionary[item.Key]);
			}
			return _dictionary.Remove(item.Key);
		}

		public IEnumerator<KeyValuePair<int, XLRow>> GetEnumerator()
		{
			return _dictionary.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return _dictionary.GetEnumerator();
		}

		public void ShiftRowsDown(int startingRow, int rowsToShift)
		{
			foreach (int item in from k in _dictionary.Keys
				where k >= startingRow
				orderby k descending
				select k)
			{
				XLRow row = _dictionary[item];
				int num = item + rowsToShift;
				if (num <= 1048576)
				{
					XLRow xLRow = new XLRow(row);
					xLRow.RangeAddress.FirstAddress = new XLAddress(num, 1, fixedRow: false, fixedColumn: false);
					xLRow.RangeAddress.LastAddress = new XLAddress(num, 16384, fixedRow: false, fixedColumn: false);
					XLRow value = xLRow;
					_dictionary.Add(num, value);
				}
				_dictionary.Remove(item);
			}
		}

		public void RemoveAll(Func<XLRow, bool> predicate)
		{
			foreach (XLRow item in from c in _dictionary.Values.Where(predicate)
				select (c) into kp
				where !_deleted.ContainsKey(kp.RowNumber())
				select kp)
			{
				_deleted.Add(item.RowNumber(), item);
			}
			_dictionary.RemoveAll(predicate);
		}

		public void Dispose()
		{
			_dictionary.Values.ForEach(delegate(XLRow r)
			{
				r.Dispose();
			});
		}
	}
