		public IXLSheetProtection Protect()
		{
			return Protect(string.Empty);
		}

		public IXLSheetProtection Protect(string password)
		{
			if (Protected)
			{
				throw new InvalidOperationException("The worksheet is already protected");
			}
			Protected = true;
			PasswordHash = GetPasswordHash(password);
			return this;
		}

		public IXLSheetProtection Unprotect()
		{
			return Unprotect(string.Empty);
		}

		public IXLSheetProtection Unprotect(string password)
		{
			if (Protected)
			{
				string passwordHash = GetPasswordHash(password);
				if (passwordHash != PasswordHash)
				{
					throw new ArgumentException("Invalid password");
				}
				Protected = false;
				PasswordHash = string.Empty;
			}
			return this;
		}

		private string GetPasswordHash(string password)
		{
			int length = password.Length;
			int num = 0;
			if (length == 0)
			{
				return string.Empty;
			}
			for (int num2 = length - 1; num2 >= 0; num2--)
			{
				num ^= password[num2];
				num = ((num >> 14) & 1) | ((num << 1) & 0x7FFF);
			}
			num ^= 0xCE4B;
			return (num ^ length).ToString("X");
		}
	}
	internal class XLSheetView : IXLSheetView
	{
		public int SplitRow { get; set; }

		public int SplitColumn { get; set; }

		public bool FreezePanes { get; set; }

