		public XLSheetView()
		{
			View = XLSheetViewOptions.Normal;
		}

		public XLSheetView(IXLSheetView sheetView)
			: this()
		{
			SplitRow = sheetView.SplitRow;
			SplitColumn = sheetView.SplitColumn;
			FreezePanes = ((XLSheetView)sheetView).FreezePanes;
		}

		public void FreezeRows(int rows)
		{
			SplitRow = rows;
			FreezePanes = true;
		}

