	internal class XLRanges : IXLRanges, IEnumerable<IXLRange>, IEnumerable, IDisposable, IXLStylized
	{
		private readonly List<XLRange> _ranges = new List<XLRange>();

		private IXLStyle _style;

		public int Count { get; private set; }

		public IXLStyle Style
		{
			get
			{
				return _style;
			}
			set
			{
				_style = new XLStyle(this, value);
				foreach (XLRange range in _ranges)
				{
					range.Style = value;
				}
			}
		}

		public IXLDataValidation DataValidation
		{
			get
			{
				foreach (XLRange range in _ranges)
				{
					foreach (IXLDataValidation dataValidation in range.Worksheet.DataValidations)
					{
						foreach (IXLRange item in dataValidation.Ranges.Where((IXLRange dvRange) => dvRange.Intersects(range)))
						{
							dataValidation.Ranges.Remove(item);
							foreach (IXLCell item2 in from c in item.Cells()
								where !range.Contains(c.Address.ToString())
								select c)
							{
								IXLRange iXLRange = item2.AsRange();
								iXLRange.Dispose();
								dataValidation.Ranges.Add(iXLRange);
							}
						}
					}
				}
				XLDataValidation xLDataValidation = new XLDataValidation(this);
				_ranges.First().Worksheet.DataValidations.Add(xLDataValidation);
				return xLDataValidation;
			}
		}

		public object Value
		{
			set
			{
				_ranges.ForEach(delegate(XLRange r)
				{
					r.Value = value;
				});
			}
		}

		public bool StyleChanged { get; set; }

		public IEnumerable<IXLStyle> Styles
		{
			get
			{
				UpdatingStyle = true;
				yield return _style;
				foreach (XLRange rng in _ranges)
				{
					yield return rng.Style;
					foreach (XLCell r in rng.Worksheet.Internals.CellsCollection.GetCells(rng.RangeAddress.FirstAddress.RowNumber, rng.RangeAddress.FirstAddress.ColumnNumber, rng.RangeAddress.LastAddress.RowNumber, rng.RangeAddress.LastAddress.ColumnNumber))
					{
						yield return r.Style;
					}
				}
				UpdatingStyle = false;
			}
		}

		public bool UpdatingStyle { get; set; }

		public IXLStyle InnerStyle
		{
			get
			{
				return _style;
			}
			set
			{
				_style = new XLStyle(this, value);
			}
		}

		public IXLRanges RangesUsed => this;

		public XLRanges()
		{
			_style = new XLStyle(this, XLWorkbook.DefaultStyle);
		}

		public IXLRanges Clear(XLClearOptions clearOptions = XLClearOptions.ContentsAndFormats)
		{
			_ranges.ForEach(delegate(XLRange c)
			{
				c.Clear(clearOptions);
			});
			return this;
		}

		public void Add(XLRange range)
		{
			Count++;
			_ranges.Add(range);
		}

		public void Add(IXLRangeBase range)
		{
			Count++;
			_ranges.Add(range.AsRange() as XLRange);
		}

		public void Add(IXLCell cell)
		{
			Add(cell.AsRange());
		}

		public void Remove(IXLRange range)
		{
			Count--;
			_ranges.RemoveAll((XLRange r) => r.ToString() == range.ToString());
		}

		public IEnumerator<IXLRange> GetEnumerator()
		{
			List<IXLRange> list = new List<IXLRange>();
			list.AddRange(_ranges.Where((XLRange r) => XLHelper.IsValidRangeAddress(r.RangeAddress)).Cast<IXLRange>());
			return list.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public bool Contains(IXLRange range)
		{
			return _ranges.Any((XLRange r) => !r.RangeAddress.IsInvalid && r.Contains(range));
		}

		public IXLRanges AddToNamed(string rangeName)
		{
			return AddToNamed(rangeName, XLScope.Workbook);
		}

		public IXLRanges AddToNamed(string rangeName, XLScope scope)
		{
			return AddToNamed(rangeName, XLScope.Workbook, null);
		}

		public IXLRanges AddToNamed(string rangeName, XLScope scope, string comment)
		{
			_ranges.ForEach(delegate(XLRange r)
			{
				r.AddToNamed(rangeName, scope, comment);
			});
			return this;
		}

		public IXLRanges SetValue<T>(T value)
		{
			_ranges.ForEach(delegate(XLRange r)
			{
				r.SetValue(value);
			});
			return this;
		}

		public IXLCells Cells()
		{
			XLCells xLCells = new XLCells(usedCellsOnly: false, includeFormats: false);
			foreach (XLRange range in _ranges)
			{
				xLCells.Add(range.RangeAddress);
			}
			return xLCells;
		}

		public IXLCells CellsUsed()
		{
			XLCells xLCells = new XLCells(usedCellsOnly: true, includeFormats: false);
			foreach (XLRange range in _ranges)
			{
				xLCells.Add(range.RangeAddress);
			}
			return xLCells;
		}

		public IXLCells CellsUsed(bool includeFormats)
		{
			XLCells xLCells = new XLCells(usedCellsOnly: true, includeFormats);
			foreach (XLRange range in _ranges)
			{
				xLCells.Add(range.RangeAddress);
			}
			return xLCells;
		}

		public IXLRanges SetDataType(XLCellValues dataType)
		{
			_ranges.ForEach(delegate(XLRange c)
			{
				c.DataType = dataType;
			});
			return this;
		}

		public void Dispose()
		{
			_ranges.ForEach(delegate(XLRange r)
			{
				r.Dispose();
			});
		}

		public override string ToString()
		{
			string text = _ranges.Aggregate(string.Empty, (string agg, XLRange r) => agg + r.ToString() + ",");
			if (text.Length > 0)
			{
				text = text.Substring(0, text.Length - 1);
			}
			return text;
		}

		public override bool Equals(object obj)
		{
			XLRanges other = (XLRanges)obj;
			if (_ranges.Count == other._ranges.Count)
			{
				return _ranges.Select((XLRange thisRange) => Enumerable.Contains(other._ranges, thisRange)).All((bool foundOne) => foundOne);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return _ranges.Aggregate(0, (int current, XLRange r) => current ^ r.GetHashCode());
		}

		public IXLDataValidation SetDataValidation()
		{
			return DataValidation;
		}

		public void Select()
		{
			using IEnumerator<IXLRange> enumerator = GetEnumerator();
			while (enumerator.MoveNext())
			{
				IXLRange current = enumerator.Current;
				current.Select();
			}
		}
	}
