	internal class XLHeaderFooter : IXLHeaderFooter
	{
		private Dictionary<XLHFOccurrence, string> innerTexts = new Dictionary<XLHFOccurrence, string>();

		private Dictionary<XLHFOccurrence, string> _initialTexts;

		private bool _changed;

		public IXLHFItem Left { get; private set; }

		public IXLHFItem Center { get; private set; }

		public IXLHFItem Right { get; private set; }

		internal bool Changed
		{
			get
			{
				if (!_changed)
				{
					return _initialTexts.Any((KeyValuePair<XLHFOccurrence, string> it) => GetText(it.Key) != it.Value);
				}
				return true;
			}
			set
			{
				_changed = value;
			}
		}

		public XLHeaderFooter(XLWorksheet worksheet)
		{
			Left = new XLHFItem(worksheet);
			Right = new XLHFItem(worksheet);
			Center = new XLHFItem(worksheet);
			SetAsInitial();
		}

		public XLHeaderFooter(XLHeaderFooter defaultHF, XLWorksheet worksheet)
		{
			Dictionary<XLHFOccurrence, string> source = defaultHF.innerTexts;
			Action<KeyValuePair<XLHFOccurrence, string>> action = delegate(KeyValuePair<XLHFOccurrence, string> kp)
			{
				innerTexts.Add(kp.Key, kp.Value);
			};
			source.ForEach(action);
			Left = new XLHFItem(defaultHF.Left as XLHFItem, worksheet);
			Center = new XLHFItem(defaultHF.Center as XLHFItem, worksheet);
			Right = new XLHFItem(defaultHF.Right as XLHFItem, worksheet);
			SetAsInitial();
		}

		public string GetText(XLHFOccurrence occurrence)
		{
			if (innerTexts.ContainsKey(occurrence))
			{
				return innerTexts[occurrence];
			}
			string empty = string.Empty;
			string text = Left.GetText(occurrence);
			string text2 = Center.GetText(occurrence);
			string text3 = Right.GetText(occurrence);
			empty += ((text.Length > 0) ? ("&L" + text) : string.Empty);
			empty += ((text2.Length > 0) ? ("&C" + text2) : string.Empty);
			empty += ((text3.Length > 0) ? ("&R" + text3) : string.Empty);
			if (empty.Length > 255)
			{
				throw new ArgumentOutOfRangeException("Headers and Footers cannot be longer than 255 characters (including style markups)");
			}
			return empty;
		}

		internal string SetInnerText(XLHFOccurrence occurrence, string text)
		{
			if (innerTexts.ContainsKey(occurrence))
			{
				innerTexts[occurrence] = text;
			}
			else
			{
				innerTexts.Add(occurrence, text);
			}
			return innerTexts[occurrence];
		}

		internal void SetAsInitial()
		{
			_initialTexts = new Dictionary<XLHFOccurrence, string>();
			foreach (XLHFOccurrence item in Enum.GetValues(typeof(XLHFOccurrence)).Cast<XLHFOccurrence>())
			{
				_initialTexts.Add(item, GetText(item));
			}
		}

		public IXLHeaderFooter Clear(XLHFOccurrence occurrence = XLHFOccurrence.AllPages)
		{
			Left.Clear(occurrence);
			Right.Clear(occurrence);
			Center.Clear(occurrence);
			return this;
		}
	}
	internal class XLHFItem : IXLHFItem, IXLWithRichString
	{
		private readonly XLWorksheet _worksheet;

		private readonly Dictionary<XLHFOccurrence, List<XLHFText>> texts = new Dictionary<XLHFOccurrence, List<XLHFText>>();

		public XLHFItem(XLWorksheet worksheet)
		{
			_worksheet = worksheet;
		}

		public XLHFItem(XLHFItem defaultHFItem, XLWorksheet worksheet)
			: this(worksheet)
		{
			Dictionary<XLHFOccurrence, List<XLHFText>> source = defaultHFItem.texts;
			Action<KeyValuePair<XLHFOccurrence, List<XLHFText>>> action = delegate(KeyValuePair<XLHFOccurrence, List<XLHFText>> kp)
			{
				texts.Add(kp.Key, kp.Value);
			};
			source.ForEach(action);
		}

		public string GetText(XLHFOccurrence occurrence)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (texts.ContainsKey(occurrence))
			{
				foreach (XLHFText item in texts[occurrence])
				{
					stringBuilder.Append(item.GetHFText(stringBuilder.ToString()));
				}
			}
			return stringBuilder.ToString();
		}

		public IXLRichString AddText(string text)
		{
			return AddText(text, XLHFOccurrence.AllPages);
		}

		public IXLRichString AddText(XLHFPredefinedText predefinedText)
		{
			return AddText(predefinedText, XLHFOccurrence.AllPages);
		}

		public IXLRichString AddText(string text, XLHFOccurrence occurrence)
		{
			XLRichString xLRichString = new XLRichString(text, XLWorkbook.DefaultStyle.Font, this);
			XLHFText hfText = new XLHFText(xLRichString, _worksheet);
			if (occurrence == XLHFOccurrence.AllPages)
			{
				AddTextToOccurrence(hfText, XLHFOccurrence.EvenPages);
				AddTextToOccurrence(hfText, XLHFOccurrence.FirstPage);
				AddTextToOccurrence(hfText, XLHFOccurrence.OddPages);
			}
			else
			{
				AddTextToOccurrence(hfText, occurrence);
			}
			return xLRichString;
		}

		public IXLRichString AddNewLine()
		{
			return AddText(Environment.NewLine);
		}

		public IXLRichString AddImage(string imagePath, XLHFOccurrence occurrence = XLHFOccurrence.AllPages)
		{
			throw new NotImplementedException();
		}

		private void AddTextToOccurrence(XLHFText hfText, XLHFOccurrence occurrence)
		{
			if (texts.ContainsKey(occurrence))
			{
				texts[occurrence].Add(hfText);
				return;
			}
			texts.Add(occurrence, new List<XLHFText> { hfText });
		}

		public IXLRichString AddText(XLHFPredefinedText predefinedText, XLHFOccurrence occurrence)
		{
			return AddText(predefinedText switch
			{
				XLHFPredefinedText.PageNumber => "&P", 
				XLHFPredefinedText.NumberOfPages => "&N", 
				XLHFPredefinedText.Date => "&D", 
				XLHFPredefinedText.Time => "&T", 
				XLHFPredefinedText.Path => "&Z", 
				XLHFPredefinedText.File => "&F", 
				XLHFPredefinedText.SheetName => "&A", 
				XLHFPredefinedText.FullPath => "&Z&F", 
				_ => throw new NotImplementedException(), 
			}, occurrence);
		}

		public void Clear(XLHFOccurrence occurrence = XLHFOccurrence.AllPages)
		{
			if (occurrence == XLHFOccurrence.AllPages)
			{
				ClearOccurrence(XLHFOccurrence.EvenPages);
				ClearOccurrence(XLHFOccurrence.FirstPage);
				ClearOccurrence(XLHFOccurrence.OddPages);
			}
			else
			{
				ClearOccurrence(occurrence);
			}
		}

		private void ClearOccurrence(XLHFOccurrence occurrence)
		{
			if (texts.ContainsKey(occurrence))
			{
				texts.Remove(occurrence);
			}
		}
	}
