	internal class XLRows : IXLRows, IEnumerable<IXLRow>, IEnumerable, IDisposable, IXLStylized
	{
		private readonly List<XLRow> _rows = new List<XLRow>();

		private readonly XLWorksheet _worksheet;

		internal IXLStyle style;

		public bool StyleChanged { get; set; }

		public IXLStyle Style
		{
			get
			{
				return style;
			}
			set
			{
				style = new XLStyle(this, value);
				if (_worksheet != null)
				{
					_worksheet.Style = value;
					return;
				}
				foreach (XLRow row in _rows)
				{
					row.Style = value;
				}
			}
		}

		public double Height
		{
			set
			{
				_rows.ForEach(delegate(XLRow c)
				{
					c.Height = value;
				});
				if (_worksheet != null)
				{
					_worksheet.RowHeight = value;
					_worksheet.Internals.RowsCollection.ForEach(delegate(KeyValuePair<int, XLRow> r)
					{
						r.Value.Height = value;
					});
				}
			}
		}

		public IEnumerable<IXLStyle> Styles
		{
			get
			{
				UpdatingStyle = true;
				yield return style;
				if (_worksheet != null)
				{
					yield return _worksheet.Style;
				}
				else
				{
					foreach (IXLStyle item in _rows.SelectMany((XLRow row) => row.Styles))
					{
						yield return item;
					}
				}
				UpdatingStyle = false;
			}
		}

		public bool UpdatingStyle { get; set; }

		public IXLStyle InnerStyle
		{
			get
			{
				return style;
			}
			set
			{
				style = new XLStyle(this, value);
			}
		}

		public IXLRanges RangesUsed
		{
			get
			{
				XLRanges retVal = new XLRanges();
				this.ForEach(delegate(IXLRow c)
				{
					retVal.Add(c.AsRange());
				});
				return retVal;
			}
		}

		public XLRows(XLWorksheet worksheet)
		{
			_worksheet = worksheet;
			style = new XLStyle(this, XLWorkbook.DefaultStyle);
		}

		public IEnumerator<IXLRow> GetEnumerator()
		{
			return (from IXLRow r in _rows
				orderby r.RowNumber()
				select r).GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public void Delete()
		{
			if (_worksheet != null)
			{
				_worksheet.Internals.RowsCollection.Clear();
				_worksheet.Internals.CellsCollection.Clear();
				return;
			}
			Dictionary<IXLWorksheet, List<int>> dictionary = new Dictionary<IXLWorksheet, List<int>>();
			foreach (XLRow row in _rows)
			{
				if (!dictionary.ContainsKey(row.Worksheet))
				{
					dictionary.Add(row.Worksheet, new List<int>());
				}
				dictionary[row.Worksheet].Add(row.RowNumber());
			}
			foreach (KeyValuePair<IXLWorksheet, List<int>> item in dictionary)
			{
				foreach (int item2 in item.Value.OrderByDescending((int r) => r))
				{
					item.Key.Row(item2).Delete();
				}
			}
		}

