		public IXLRows AddHorizontalPageBreaks()
		{
			foreach (XLRow row in _rows)
			{
				row.Worksheet.PageSetup.AddHorizontalPageBreak(row.RowNumber());
			}
			return this;
		}

		public IXLRows SetDataType(XLCellValues dataType)
		{
			_rows.ForEach(delegate(XLRow c)
			{
				c.DataType = dataType;
			});
			return this;
		}

		public void Add(XLRow row)
		{
			_rows.Add(row);
		}

		public IXLRows Clear(XLClearOptions clearOptions = XLClearOptions.ContentsAndFormats)
		{
			_rows.ForEach(delegate(XLRow c)
			{
				c.Clear(clearOptions);
			});
			return this;
		}

		public void Dispose()
		{
			if (_rows != null)
			{
				_rows.ForEach(delegate(XLRow r)
				{
					r.Dispose();
				});
			}
		}

		public void Select()
		{
			using IEnumerator<IXLRow> enumerator = GetEnumerator();
			while (enumerator.MoveNext())
			{
				IXLRow current = enumerator.Current;
				current.Select();
			}
		}
	}
