	internal class XLAlignment : IXLAlignment, IEquatable<IXLAlignment>
	{
		private readonly IXLStylized _container;

		private XLAlignmentHorizontalValues _horizontal;

		private int _indent;

		private bool _justifyLastLine;

		private XLAlignmentReadingOrderValues _readingOrder;

		private int _relativeIndent;

		private bool _shrinkToFit;

		private int _textRotation;

		private XLAlignmentVerticalValues _vertical;

		private bool _wrapText;

		public XLAlignmentHorizontalValues Horizontal
		{
			get
			{
				return _horizontal;
			}
			set
			{
				SetStyleChanged();
				bool updateIndent = value != XLAlignmentHorizontalValues.Left && value != XLAlignmentHorizontalValues.Right && value != XLAlignmentHorizontalValues.Distributed;
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Alignment.Horizontal = value;
						if (updateIndent)
						{
							s.Alignment.Indent = 0;
						}
					});
				}
				else
				{
					_horizontal = value;
					if (updateIndent)
					{
						_indent = 0;
					}
				}
			}
		}

		public XLAlignmentVerticalValues Vertical
		{
			get
			{
				return _vertical;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Alignment.Vertical = value;
					});
				}
				else
				{
					_vertical = value;
				}
			}
		}

		public int Indent
		{
			get
			{
				return _indent;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Alignment.Indent = value;
					});
				}
				else if (_indent != value)
				{
					if (_horizontal == XLAlignmentHorizontalValues.General)
					{
						_horizontal = XLAlignmentHorizontalValues.Left;
					}
					if (value > 0 && _horizontal != XLAlignmentHorizontalValues.Left && _horizontal != XLAlignmentHorizontalValues.Right && _horizontal != XLAlignmentHorizontalValues.Distributed)
					{
						throw new ArgumentException("For indents, only left, right, and distributed horizontal alignments are supported.");
					}
					_indent = value;
				}
			}
		}

		public bool JustifyLastLine
		{
			get
			{
				return _justifyLastLine;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Alignment.JustifyLastLine = value;
					});
				}
				else
				{
					_justifyLastLine = value;
				}
			}
		}

		public XLAlignmentReadingOrderValues ReadingOrder
		{
			get
			{
				return _readingOrder;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Alignment.ReadingOrder = value;
					});
				}
				else
				{
					_readingOrder = value;
				}
			}
		}

		public int RelativeIndent
		{
			get
			{
				return _relativeIndent;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Alignment.RelativeIndent = value;
					});
				}
				else
				{
					_relativeIndent = value;
				}
			}
		}

		public bool ShrinkToFit
		{
			get
			{
				return _shrinkToFit;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Alignment.ShrinkToFit = value;
					});
				}
				else
				{
					_shrinkToFit = value;
				}
			}
		}

		public int TextRotation
		{
			get
			{
				return _textRotation;
			}
			set
			{
				SetStyleChanged();
				int rotation = value;
				if (rotation != 255 && (rotation < -90 || rotation > 180))
				{
					throw new ArgumentException("TextRotation must be between -90 and 180 degrees, or 255.");
				}
				if (rotation < 0)
				{
					rotation = 90 + rotation * -1;
				}
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Alignment.TextRotation = rotation;
					});
				}
				else
				{
					_textRotation = rotation;
				}
			}
		}

		public bool WrapText
		{
			get
			{
				return _wrapText;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Alignment.WrapText = value;
