	internal class XLFill : IXLFill, IEquatable<IXLFill>
	{
		private XLColor _patternBackgroundColor;

		private XLColor _patternColor;

		private XLFillPatternValues _patternType;

		public bool PatternColorModified;

		public bool PatternBackgroundColorModified;

		public bool PatternTypeModified;

		private readonly IXLStylized _container;

		public XLColor BackgroundColor
		{
			get
			{
				return _patternColor;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Fill.BackgroundColor = value;
					});
					return;
				}
				_patternType = (value.HasValue ? XLFillPatternValues.Solid : XLFillPatternValues.None);
				_patternColor = new XLColor(value);
				_patternBackgroundColor = new XLColor(value);
				PatternTypeModified = true;
				PatternColorModified = true;
				PatternBackgroundColorModified = true;
			}
		}

		public XLColor PatternColor
		{
			get
			{
				return _patternColor;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Fill.PatternColor = value;
					});
				}
				else
				{
					_patternColor = value;
					PatternColorModified = true;
				}
			}
		}

		public XLColor PatternBackgroundColor
		{
			get
			{
				return _patternBackgroundColor;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Fill.PatternBackgroundColor = value;
					});
				}
				else
				{
					_patternBackgroundColor = value;
					PatternBackgroundColorModified = true;
				}
			}
		}

		public XLFillPatternValues PatternType
		{
			get
			{
				return _patternType;
			}
			set
			{
				SetStyleChanged();
				if (_container != null && !_container.UpdatingStyle)
				{
					_container.Styles.ForEach(delegate(IXLStyle s)
					{
						s.Fill.PatternType = value;
					});
				}
				else
				{
					_patternType = value;
					PatternTypeModified = true;
				}
			}
		}

		public bool Equals(IXLFill other)
		{
			if (_patternType == other.PatternType && _patternColor.Equals(other.PatternColor))
			{
				return _patternBackgroundColor.Equals(other.PatternBackgroundColor);
			}
			return false;
		}

		private void SetStyleChanged()
		{
			if (_container != null)
			{
				_container.StyleChanged = true;
			}
		}

		public override bool Equals(object obj)
		{
			return Equals((XLFill)obj);
		}

		public override int GetHashCode()
		{
			return BackgroundColor.GetHashCode() ^ (int)PatternType ^ PatternColor.GetHashCode();
		}

		public IXLStyle SetBackgroundColor(XLColor value)
		{
			BackgroundColor = value;
			return _container.Style;
		}

		public IXLStyle SetPatternColor(XLColor value)
		{
			PatternColor = value;
			return _container.Style;
		}

		public IXLStyle SetPatternBackgroundColor(XLColor value)
		{
			PatternBackgroundColor = value;
			return _container.Style;
		}

		public IXLStyle SetPatternType(XLFillPatternValues value)
		{
			PatternType = value;
			return _container.Style;
		}

		public XLFill()
			: this(null, XLWorkbook.DefaultStyle.Fill)
		{
		}

		public XLFill(IXLStylized container, IXLFill defaultFill = null, bool useDefaultModify = true)
		{
			_container = container;
			if (defaultFill != null)
			{
				_patternType = defaultFill.PatternType;
				_patternColor = new XLColor(defaultFill.PatternColor);
				_patternBackgroundColor = new XLColor(defaultFill.PatternBackgroundColor);
				if (useDefaultModify)
				{
					XLFill xLFill = defaultFill as XLFill;
					PatternBackgroundColorModified = xLFill.PatternBackgroundColorModified;
					PatternColorModified = xLFill.PatternColorModified;
					PatternTypeModified = xLFill.PatternTypeModified;
				}
			}
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(BackgroundColor);
			stringBuilder.Append("-");
			stringBuilder.Append(PatternType.ToString());
			stringBuilder.Append("-");
			stringBuilder.Append(PatternColor);
			return stringBuilder.ToString();
		}
	}
