		public IXLCell SetValue<T>(T value)
		{
			FormulaA1 = string.Empty;
			_richText = null;
			if (value is string || value is char)
			{
				_cellValue = value.ToString();
				_dataType = XLCellValues.Text;
				if (_cellValue.Contains(Environment.NewLine) && !GetStyleForRead().Alignment.WrapText)
				{
					Style.Alignment.WrapText = true;
				}
			}
			else if (value is TimeSpan)
			{
				_cellValue = value.ToString();
				_dataType = XLCellValues.TimeSpan;
				Style.NumberFormat.NumberFormatId = 46;
			}
			else if (value is DateTime)
			{
				_dataType = XLCellValues.DateTime;
				DateTime dateTime = (DateTime)Convert.ChangeType(value, typeof(DateTime));
				Style.NumberFormat.NumberFormatId = ((dateTime.Date == dateTime) ? 14 : 22);
				_cellValue = dateTime.ToOADate().ToString();
			}
			else if (value is sbyte || value is byte || value is short || value is ushort || value is int || value is uint || value is long || value is ulong || value is float || value is double || value is decimal)
			{
				if (double.IsNaN((double)Convert.ChangeType(value, typeof(double))) || double.IsInfinity((double)Convert.ChangeType(value, typeof(double))))
				{
					_cellValue = value.ToString();
					_dataType = XLCellValues.Text;
				}
				else
				{
					_dataType = XLCellValues.Number;
					_cellValue = value.ToString();
				}
			}
			else if (value is bool)
			{
				_dataType = XLCellValues.Boolean;
				_cellValue = (((bool)Convert.ChangeType(value, typeof(bool))) ? "1" : "0");
			}
			else
			{
				_cellValue = value.ToString();
				_dataType = XLCellValues.Text;
			}
			return this;
		}

