		public string GetFormattedString()
		{
			if (FormulaA1.Length > 0)
			{
				return string.Empty;
			}
			string cellValue = _cellValue;
			if (_dataType == XLCellValues.Boolean)
			{
				return (cellValue != "0").ToString();
