		public bool TryGetValue<T>(out T value)
		{
			object value2 = Value;
			if (value2 == null)
			{
				value = default(T);
				return true;
			}
			if (TryGetTimeSpanValue<T>(out value, value2, out var b))
			{
				return b;
			}
			if (TryGetRichStringValue<T>(out value))
			{
				return true;
			}
			if (TryGetStringValue<T>(out value, value2))
			{
				return true;
			}
			string currValue = value2.ToString();
			if (typeof(T) == typeof(bool))
			{
				return TryGetBasicValue<T, bool>(out value, currValue, bool.TryParse);
			}
			if (typeof(T) == typeof(sbyte))
			{
				return TryGetBasicValue<T, sbyte>(out value, currValue, sbyte.TryParse);
			}
			if (typeof(T) == typeof(byte))
			{
				return TryGetBasicValue<T, byte>(out value, currValue, byte.TryParse);
			}
			if (typeof(T) == typeof(short))
			{
				return TryGetBasicValue<T, short>(out value, currValue, short.TryParse);
			}
			if (typeof(T) == typeof(ushort))
			{
				return TryGetBasicValue<T, ushort>(out value, currValue, ushort.TryParse);
			}
			if (typeof(T) == typeof(int))
			{
				return TryGetBasicValue<T, int>(out value, currValue, int.TryParse);
			}
			if (typeof(T) == typeof(uint))
			{
				return TryGetBasicValue<T, uint>(out value, currValue, uint.TryParse);
			}
			if (typeof(T) == typeof(long))
			{
				return TryGetBasicValue<T, long>(out value, currValue, long.TryParse);
			}
			if (typeof(T) == typeof(ulong))
			{
				return TryGetBasicValue<T, ulong>(out value, currValue, ulong.TryParse);
			}
			if (typeof(T) == typeof(float))
			{
				return TryGetBasicValue<T, float>(out value, currValue, float.TryParse);
			}
			if (typeof(T) == typeof(double))
			{
				return TryGetBasicValue<T, double>(out value, currValue, double.TryParse);
			}
			if (typeof(T) == typeof(decimal))
			{
				return TryGetBasicValue<T, decimal>(out value, currValue, decimal.TryParse);
			}
			if (typeof(T) == typeof(XLHyperlink))
			{
				XLHyperlink hyperlink = GetHyperlink();
				if (hyperlink != null)
				{
					value = (T)Convert.ChangeType(hyperlink, typeof(T));
					return true;
				}
				value = default(T);
				return false;
			}
			try
			{
				value = (T)Convert.ChangeType(value2, typeof(T));
				return true;
			}
			catch
			{
				value = default(T);
				return false;
			}
		}

		private static bool TryGetTimeSpanValue<T>(out T value, object currValue, out bool b)
		{
			if (typeof(T) == typeof(TimeSpan))
			{
				bool flag = true;
				TimeSpan result;
				if (currValue is TimeSpan)
				{
					result = (TimeSpan)currValue;
				}
				else if (!TimeSpan.TryParse(currValue.ToString(), out result))
				{
					flag = false;
				}
				value = (T)Convert.ChangeType(result, typeof(T));
				b = flag;
				return true;
			}
			value = default(T);
			b = false;
			return false;
		}

		private bool TryGetRichStringValue<T>(out T value)
		{
			if (typeof(T) == typeof(IXLRichText))
			{
				value = (T)RichText;
				return true;
			}
			value = default(T);
			return false;
		}

		private static bool TryGetStringValue<T>(out T value, object currValue)
		{
			if (typeof(T) == typeof(string))
			{
				string text = currValue.ToString();
				if (!utfPattern.Match(text).Success)
				{
					value = (T)Convert.ChangeType(text, typeof(T));
					return true;
				}
				StringBuilder stringBuilder = new StringBuilder();
				int num = 0;
				foreach (Match item in utfPattern.Matches(text))
				{
					string value2 = item.Value;
					int index = item.Index;
					stringBuilder.Append(text.Substring(num, index - num));
					stringBuilder.Append((char)int.Parse(item.Groups[1].Value, NumberStyles.AllowHexSpecifier));
					num = index + value2.Length;
				}
				if (num < text.Length)
				{
					stringBuilder.Append(text.Substring(num));
				}
				value = (T)Convert.ChangeType(stringBuilder.ToString(), typeof(T));
				return true;
			}
			value = default(T);
			return false;
		}

		private static bool TryGetBooleanValue<T>(out T value, object currValue)
		{
			if (typeof(T) == typeof(bool) && bool.TryParse(currValue.ToString(), out var result))
			{
				value = (T)Convert.ChangeType(result, typeof(T));
				return true;
			}
			value = default(T);
			return false;
		}

		private static bool TryGetBasicValue<T, U>(out T value, string currValue, Func<U> func)
		{
			if (func(currValue, out var output))
			{
				value = (T)Convert.ChangeType(output, typeof(T));
				return true;
			}
			value = default(T);
			return false;
		}

