		private bool SetRange(object rangeObject)
		{
			XLRangeBase asRange = rangeObject as XLRangeBase;
			if (asRange == null && rangeObject is XLCell xLCell)
			{
				asRange = xLCell.AsRange();
			}
			if (asRange != null)
			{
				if (!(asRange is XLRow) && !(asRange is XLColumn))
				{
					int lastCellRow = asRange.RowCount();
					int lastCellColumn = asRange.ColumnCount();
					Worksheet.Range(Address.RowNumber, Address.ColumnNumber, lastCellRow, lastCellColumn).Clear();
				}
				int rowNumber = asRange.RangeAddress.FirstAddress.RowNumber;
				int columnNumber = asRange.RangeAddress.FirstAddress.ColumnNumber;
				foreach (XLCell item in asRange.CellsUsed(includeFormats: true))
				{
					Worksheet.Cell(Address.RowNumber + item.Address.RowNumber - rowNumber, Address.ColumnNumber + item.Address.ColumnNumber - columnNumber).CopyFrom(item, copyDataValidations: true);
				}
				List<IXLRange> list = (from mergedRange in asRange.Worksheet.Internals.MergedRanges
					where asRange.Contains(mergedRange)
					let initialRo = Address.RowNumber + (mergedRange.RangeAddress.FirstAddress.RowNumber - asRange.RangeAddress.FirstAddress.RowNumber)
					let initialCo = Address.ColumnNumber + (mergedRange.RangeAddress.FirstAddress.ColumnNumber - asRange.RangeAddress.FirstAddress.ColumnNumber)
					select Worksheet.Range(initialRo, initialCo, initialRo + mergedRange.RowCount() - 1, initialCo + mergedRange.ColumnCount() - 1)).Cast<IXLRange>().ToList();
				list.ForEach(delegate(IXLRange r)
				{
					r.Merge();
				});
				return true;
			}
			return false;
		}

		private bool SetEnumerable(object collectionObject)
		{
			IEnumerable data = collectionObject as IEnumerable;
			return InsertData(data) != null;
		}

		private void ClearMerged()
		{
			XLRange asRange = AsRange();
			List<IXLRange> list;
			try
			{
				list = Worksheet.Internals.MergedRanges.Where((IXLRange merge) => merge.Intersects(asRange)).ToList();
			}
			finally
			{
				if (asRange != null)
				{
					((IDisposable)asRange).Dispose();
				}
			}
			list.ForEach(delegate(IXLRange m)
			{
				Worksheet.Internals.MergedRanges.Remove(m);
			});
		}

		private void SetValue<T>(T value, int ro, int co) where T : class
		{
			if (value == null)
			{
				_worksheet.Cell(ro, co).SetValue(string.Empty);
			}
			else if (value is IConvertible)
			{
				_worksheet.Cell(ro, co).SetValue((T)Convert.ChangeType(value, typeof(T)));
			}
			else
			{
				_worksheet.Cell(ro, co).SetValue(value);
			}
		}

		private void SetValue(object value)
		{
			FormulaA1 = string.Empty;
			string text = ((value == null) ? string.Empty : value.ToString());
			_richText = null;
			if (text.Length == 0)
			{
				_dataType = XLCellValues.Text;
			}
			else
			{
				IXLStyle styleForRead = GetStyleForRead();
				TimeSpan result;
				double result2;
				DateTime result3;
				bool result4;
				if (styleForRead.NumberFormat.Format == "@")
				{
					_dataType = XLCellValues.Text;
					if (text.Contains(Environment.NewLine) && !styleForRead.Alignment.WrapText)
					{
						Style.Alignment.WrapText = true;
					}
				}
				else if (text[0] == '\'')
				{
					text = text.Substring(1, text.Length - 1);
					_dataType = XLCellValues.Text;
					if (text.Contains(Environment.NewLine) && !styleForRead.Alignment.WrapText)
					{
						Style.Alignment.WrapText = true;
					}
				}
				else if (value is TimeSpan || (TimeSpan.TryParse(text, out result) && !double.TryParse(text, out result2)))
				{
					_dataType = XLCellValues.TimeSpan;
					if (styleForRead.NumberFormat.Format == string.Empty && styleForRead.NumberFormat.NumberFormatId == 0)
					{
						Style.NumberFormat.NumberFormatId = 46;
					}
				}
				else if (text.Trim() != "NaN" && double.TryParse(text, out result2))
				{
					_dataType = XLCellValues.Number;
				}
				else if (DateTime.TryParse(text, out result3) && result3 >= BaseDate)
				{
					_dataType = XLCellValues.DateTime;
					if (styleForRead.NumberFormat.Format == string.Empty && styleForRead.NumberFormat.NumberFormatId == 0)
					{
						Style.NumberFormat.NumberFormatId = ((result3.Date == result3) ? 14 : 22);
					}
					text = result3.ToOADate().ToString();
				}
				else if (bool.TryParse(text, out result4))
				{
					_dataType = XLCellValues.Boolean;
					text = (result4 ? "1" : "0");
				}
				else
				{
					_dataType = XLCellValues.Text;
					if (text.Contains(Environment.NewLine) && !styleForRead.Alignment.WrapText)
					{
						Style.Alignment.WrapText = true;
					}
				}
			}
			if (text.Length > 32767)
			{
				throw new ArgumentException("Cells can only hold 32,767 characters.");
			}
			_cellValue = text;
		}

		private static Dictionary<int, string> GetFormatCodes()
		{
			if (_formatCodes == null)
			{
				Dictionary<int, string> dictionary = new Dictionary<int, string>();
				dictionary.Add(0, string.Empty);
				dictionary.Add(1, "0");
				dictionary.Add(2, "0.00");
				dictionary.Add(3, "#,##0");
				dictionary.Add(4, "#,##0.00");
				dictionary.Add(7, "$#,##0.00_);($#,##0.00)");
				dictionary.Add(9, "0%");
				dictionary.Add(10, "0.00%");
				dictionary.Add(11, "0.00E+00");
				dictionary.Add(12, "# ?/?");
				dictionary.Add(13, "# ??/??");
				dictionary.Add(14, "M/d/yyyy");
				dictionary.Add(15, "d-MMM-yy");
				dictionary.Add(16, "d-MMM");
				dictionary.Add(17, "MMM-yy");
				dictionary.Add(18, "h:mm tt");
				dictionary.Add(19, "h:mm:ss tt");
				dictionary.Add(20, "H:mm");
				dictionary.Add(21, "H:mm:ss");
				dictionary.Add(22, "M/d/yyyy H:mm");
				dictionary.Add(37, "#,##0 ;(#,##0)");
				dictionary.Add(38, "#,##0 ;[Red](#,##0)");
				dictionary.Add(39, "#,##0.00;(#,##0.00)");
				dictionary.Add(40, "#,##0.00;[Red](#,##0.00)");
				dictionary.Add(45, "mm:ss");
				dictionary.Add(46, "[h]:mm:ss");
				dictionary.Add(47, "mmss.0");
				dictionary.Add(48, "##0.0E+0");
				dictionary.Add(49, "@");
				Dictionary<int, string> formatCodes = dictionary;
				_formatCodes = formatCodes;
			}
			return _formatCodes;
		}

		private string GetFormulaR1C1(string value)
		{
			return GetFormula(value, FormulaConversionType.A1ToR1C1, 0, 0);
		}

		private string GetFormulaA1(string value)
		{
			return GetFormula(value, FormulaConversionType.R1C1ToA1, 0, 0);
		}

		private string GetFormula(string strValue, FormulaConversionType conversionType, int rowsToShift, int columnsToShift)
		{
			if (XLHelper.IsNullOrWhiteSpace(strValue))
			{
				return string.Empty;
			}
			string text = ">" + strValue + "<";
			Regex regex = ((conversionType == FormulaConversionType.A1ToR1C1) ? A1Regex : R1C1Regex);
			StringBuilder stringBuilder = new StringBuilder();
			int num = 0;
			foreach (Match item in regex.Matches(text).Cast<Match>())
			{
				string value = item.Value;
				int index = item.Index;
				if (text.Substring(0, index).CharCount('"') % 2 == 0)
				{
					stringBuilder.Append(text.Substring(num, index - num));
					stringBuilder.Append((conversionType == FormulaConversionType.A1ToR1C1) ? GetR1C1Address(value, rowsToShift, columnsToShift) : GetA1Address(value, rowsToShift, columnsToShift));
				}
				else
				{
					stringBuilder.Append(text.Substring(num, index - num + value.Length));
				}
				num = index + value.Length;
			}
			if (num < text.Length)
			{
				stringBuilder.Append(text.Substring(num));
			}
			string text2 = stringBuilder.ToString();
			return text2.Substring(1, text2.Length - 2);
		}

		private string GetA1Address(string r1C1Address, int rowsToShift, int columnsToShift)
		{
			string text = r1C1Address.ToUpper();
			if (Enumerable.Contains(text, ':'))
			{
				string[] array = text.Split(new char[1] { ':' });
				string text2 = array[0];
				string text3 = array[1];
				string text4;
				string text5;
				if (text2.StartsWith("R"))
				{
					text4 = GetA1Row(text2, rowsToShift);
					text5 = GetA1Row(text3, rowsToShift);
				}
				else
				{
					text4 = GetA1Column(text2, columnsToShift);
					text5 = GetA1Column(text3, columnsToShift);
				}
				return text4 + ":" + text5;
			}
			string rowPart = text.Substring(0, text.IndexOf("C"));
			string a1Row = GetA1Row(rowPart, rowsToShift);
			string columnPart = text.Substring(text.IndexOf("C"));
			string a1Column = GetA1Column(columnPart, columnsToShift);
			return a1Column + a1Row;
		}

		private string GetA1Column(string columnPart, int columnsToShift)
		{
			if (columnPart == "C")
			{
				return XLHelper.GetColumnLetterFromNumber(Address.ColumnNumber + columnsToShift);
			}
			int num = columnPart.IndexOf("[");
			int num2 = columnPart.IndexOf("-");
			if (num >= 0)
			{
				return XLHelper.GetColumnLetterFromNumber(Address.ColumnNumber + int.Parse(columnPart.Substring(num + 1, columnPart.Length - num - 2)) + columnsToShift);
			}
			if (num2 >= 0)
			{
				return XLHelper.GetColumnLetterFromNumber(Address.ColumnNumber + int.Parse(columnPart.Substring(num2)) + columnsToShift);
			}
			return "$" + XLHelper.GetColumnLetterFromNumber(int.Parse(columnPart.Substring(1)) + columnsToShift);
		}

		private string GetA1Row(string rowPart, int rowsToShift)
		{
			if (rowPart == "R")
			{
				return (Address.RowNumber + rowsToShift).ToString();
			}
			int num = rowPart.IndexOf("[");
			if (num >= 0)
			{
				return (Address.RowNumber + int.Parse(rowPart.Substring(num + 1, rowPart.Length - num - 2)) + rowsToShift).ToString();
			}
			return "$" + (int.Parse(rowPart.Substring(1)) + rowsToShift);
		}

		private string GetR1C1Address(string a1Address, int rowsToShift, int columnsToShift)
		{
			if (Enumerable.Contains(a1Address, ':'))
			{
				string[] array = a1Address.Split(new char[1] { ':' });
				string text = array[0];
				string text2 = array[1];
				if (int.TryParse(text.Replace("$", string.Empty), out var result))
				{
					int rowNumber = int.Parse(text2.Replace("$", string.Empty));
					string r1C1Row = GetR1C1Row(result, Enumerable.Contains(text, '$'), rowsToShift);
					string r1C1Row2 = GetR1C1Row(rowNumber, Enumerable.Contains(text2, '$'), rowsToShift);
					return r1C1Row + ":" + r1C1Row2;
				}
				int columnNumberFromLetter = XLHelper.GetColumnNumberFromLetter(text.Replace("$", string.Empty));
				int columnNumberFromLetter2 = XLHelper.GetColumnNumberFromLetter(text2.Replace("$", string.Empty));
				string r1C1Column = GetR1C1Column(columnNumberFromLetter, Enumerable.Contains(text, '$'), columnsToShift);
				string r1C1Column2 = GetR1C1Column(columnNumberFromLetter2, Enumerable.Contains(text2, '$'), columnsToShift);
				return r1C1Column + ":" + r1C1Column2;
			}
			XLAddress xLAddress = XLAddress.Create(_worksheet, a1Address);
			string r1C1Row3 = GetR1C1Row(xLAddress.RowNumber, xLAddress.FixedRow, rowsToShift);
			string r1C1Column3 = GetR1C1Column(xLAddress.ColumnNumber, xLAddress.FixedColumn, columnsToShift);
			return r1C1Row3 + r1C1Column3;
		}

		private string GetR1C1Row(int rowNumber, bool fixedRow, int rowsToShift)
		{
			rowNumber += rowsToShift;
			int num = rowNumber - Address.RowNumber;
			if (num != 0 || fixedRow)
			{
				return fixedRow ? $"R{rowNumber}" : $"R[{num}]";
			}
			return "R";
		}

		private string GetR1C1Column(int columnNumber, bool fixedColumn, int columnsToShift)
		{
			columnNumber += columnsToShift;
			int num = columnNumber - Address.ColumnNumber;
			if (num != 0 || fixedColumn)
			{
				return fixedColumn ? $"C{columnNumber}" : $"C[{num}]";
			}
			return "C";
		}

		internal void CopyValues(XLCell source)
		{
			_cellValue = source._cellValue;
			_dataType = source._dataType;
			FormulaR1C1 = source.FormulaR1C1;
			_richText = ((source._richText == null) ? null : new XLRichText(source._richText, source.Style.Font));
			_comment = ((source._comment == null) ? null : new XLComment(this, source._comment, source.Style.Font));
			if (source._hyperlink != null)
			{
				SettingHyperlink = true;
				Hyperlink = new XLHyperlink(source.Hyperlink);
				SettingHyperlink = false;
			}
		}

		private IXLCell GetTargetCell(string target, XLWorksheet defaultWorksheet)
		{
			string[] array = target.Split(new char[1] { '!' });
			if (array.Length == 1)
			{
				return defaultWorksheet.Cell(target);
			}
			string text = array[0];
			if (text.StartsWith("'"))
			{
				text = text.Substring(1, text.Length - 2);
			}
			return defaultWorksheet.Workbook.Worksheet(text).Cell(array[1]);
		}

		public IXLCell CopyFrom(XLCell otherCell, bool copyDataValidations)
		{
			XLCell xLCell = otherCell;
			CopyValues(otherCell);
			SetStyle(xLCell._style ?? xLCell.Worksheet.Workbook.GetStyleById(xLCell._styleCacheId));
			List<IXLConditionalFormat> list = otherCell.Worksheet.ConditionalFormats.Where((IXLConditionalFormat c) => c.Range.Contains(otherCell)).ToList();
			foreach (IXLConditionalFormat item in list)
			{
				XLConditionalFormat xLConditionalFormat = new XLConditionalFormat(item as XLConditionalFormat);
				xLConditionalFormat.Range = AsRange();
				XLConditionalFormat xLConditionalFormat2 = xLConditionalFormat;
				List<XLFormula> list2 = xLConditionalFormat2.Values.Values.ToList();
				xLConditionalFormat2.Values.Clear();
				foreach (XLFormula item2 in list2)
				{
					string value = item2.Value;
					if (item2.IsFormula)
					{
						string formulaR1C = otherCell.GetFormulaR1C1(value);
						value = GetFormulaA1(formulaR1C);
					}
					xLConditionalFormat2.Values.Add(new XLFormula
					{
						_value = value,
						IsFormula = item2.IsFormula
					});
				}
				_worksheet.ConditionalFormats.Add(xLConditionalFormat2);
			}
			if (copyDataValidations)
			{
				bool eventTrackingEnabled = Worksheet.EventTrackingEnabled;
				Worksheet.EventTrackingEnabled = false;
				if (otherCell.HasDataValidation)
				{
					CopyDataValidation(otherCell, otherCell.DataValidation);
				}
				else if (HasDataValidation)
				{
					using XLRange range = AsRange();
					Worksheet.DataValidations.Delete(range);
				}
				Worksheet.EventTrackingEnabled = eventTrackingEnabled;
			}
			return this;
		}

		internal void CopyDataValidation(XLCell otherCell, XLDataValidation otherDv)
		{
			XLDataValidation dataValidation = DataValidation;
			dataValidation.CopyFrom(otherDv);
			dataValidation.Value = GetFormulaA1(otherCell.GetFormulaR1C1(otherDv.Value));
			dataValidation.MinValue = GetFormulaA1(otherCell.GetFormulaR1C1(otherDv.MinValue));
			dataValidation.MaxValue = GetFormulaA1(otherCell.GetFormulaR1C1(otherDv.MaxValue));
		}

		internal void ShiftFormulaRows(XLRange shiftedRange, int rowsShifted)
		{
			_formulaA1 = ShiftFormulaRows(FormulaA1, Worksheet, shiftedRange, rowsShifted);
		}

		internal static string ShiftFormulaRows(string formulaA1, XLWorksheet worksheetInAction, XLRange shiftedRange, int rowsShifted)
		{
			if (XLHelper.IsNullOrWhiteSpace(formulaA1))
			{
				return string.Empty;
			}
			Regex a1SimpleRegex = A1SimpleRegex;
			StringBuilder stringBuilder = new StringBuilder();
			int num = 0;
			string name = shiftedRange.Worksheet.Name;
			foreach (Match item in a1SimpleRegex.Matches(formulaA1).Cast<Match>())
			{
				string value = item.Value;
				int index = item.Index;
				if (formulaA1.Substring(0, index).CharCount('"') % 2 == 0)
				{
					stringBuilder.Append(formulaA1.Substring(num, index - num));
					bool flag = false;
					string text;
					if (Enumerable.Contains(value, '!'))
					{
						text = value.Substring(0, value.IndexOf('!'));
						if (text[0] == '\'')
						{
							text = text.Substring(1, text.Length - 2);
						}
						flag = true;
					}
					else
					{
						text = worksheetInAction.Name;
					}
					if (string.Compare(text, name, ignoreCase: true) == 0)
					{
						string text2 = value.Substring(value.IndexOf('!') + 1);
						if (!A1ColumnRegex.IsMatch(text2))
						{
							IXLRange iXLRange = worksheetInAction.Workbook.Worksheet(text).Range(text2);
							if (shiftedRange.RangeAddress.FirstAddress.RowNumber <= iXLRange.RangeAddress.LastAddress.RowNumber && shiftedRange.RangeAddress.FirstAddress.ColumnNumber <= iXLRange.RangeAddress.FirstAddress.ColumnNumber && shiftedRange.RangeAddress.LastAddress.ColumnNumber >= iXLRange.RangeAddress.LastAddress.ColumnNumber)
							{
								if (A1RowRegex.IsMatch(text2))
								{
									string[] array = text2.Split(new char[1] { ':' });
									string text3 = array[0];
									string text4 = array[1];
									string text5 = ((text3[0] != '$') ? (int.Parse(text3) + rowsShifted).ToStringLookup() : ("$" + (int.Parse(text3.Substring(1)) + rowsShifted).ToStringLookup()));
									string text6 = ((text4[0] != '$') ? (int.Parse(text4) + rowsShifted).ToStringLookup() : ("$" + (int.Parse(text4.Substring(1)) + rowsShifted).ToStringLookup()));
									stringBuilder.Append(flag ? $"'{text}'!{text5}:{text6}" : $"{text5}:{text6}");
								}
								else if (shiftedRange.RangeAddress.FirstAddress.RowNumber <= iXLRange.RangeAddress.FirstAddress.RowNumber)
								{
									if (Enumerable.Contains(text2, ':'))
									{
										if (flag)
										{
