		internal static string ShiftFormulaColumns(string formulaA1, XLWorksheet worksheetInAction, XLRange shiftedRange, int columnsShifted)
		{
			if (XLHelper.IsNullOrWhiteSpace(formulaA1))
			{
				return string.Empty;
			}
			Regex a1SimpleRegex = A1SimpleRegex;
			StringBuilder stringBuilder = new StringBuilder();
			int num = 0;
			foreach (Match item in a1SimpleRegex.Matches(formulaA1).Cast<Match>())
			{
				string value = item.Value;
				int index = item.Index;
				if (formulaA1.Substring(0, index).CharCount('"') % 2 == 0)
				{
					stringBuilder.Append(formulaA1.Substring(num, index - num));
					bool flag = false;
					string text;
					if (Enumerable.Contains(value, '!'))
					{
						text = value.Substring(0, value.IndexOf('!'));
						if (text[0] == '\'')
						{
							text = text.Substring(1, text.Length - 2);
						}
						flag = true;
					}
					else
					{
						text = worksheetInAction.Name;
					}
					if (string.Compare(text, shiftedRange.Worksheet.Name, ignoreCase: true) == 0)
					{
						string text2 = value.Substring(value.IndexOf('!') + 1);
						if (!A1RowRegex.IsMatch(text2))
						{
							IXLRange iXLRange = worksheetInAction.Workbook.Worksheet(text).Range(text2);
							if (shiftedRange.RangeAddress.FirstAddress.ColumnNumber <= iXLRange.RangeAddress.LastAddress.ColumnNumber && shiftedRange.RangeAddress.FirstAddress.RowNumber <= iXLRange.RangeAddress.FirstAddress.RowNumber && shiftedRange.RangeAddress.LastAddress.RowNumber >= iXLRange.RangeAddress.LastAddress.RowNumber)
							{
								if (A1ColumnRegex.IsMatch(text2))
								{
									string[] array = text2.Split(new char[1] { ':' });
									string text3 = array[0];
									string text4 = array[1];
									string text5 = ((text3[0] != '$') ? XLHelper.GetColumnLetterFromNumber(XLHelper.GetColumnNumberFromLetter(text3) + columnsShifted) : ("$" + XLHelper.GetColumnLetterFromNumber(XLHelper.GetColumnNumberFromLetter(text3.Substring(1)) + columnsShifted)));
									string text6 = ((text4[0] != '$') ? XLHelper.GetColumnLetterFromNumber(XLHelper.GetColumnNumberFromLetter(text4) + columnsShifted) : ("$" + XLHelper.GetColumnLetterFromNumber(XLHelper.GetColumnNumberFromLetter(text4.Substring(1)) + columnsShifted)));
									stringBuilder.Append(flag ? $"'{text}'!{text5}:{text6}" : $"{text5}:{text6}");
								}
								else if (shiftedRange.RangeAddress.FirstAddress.ColumnNumber <= iXLRange.RangeAddress.FirstAddress.ColumnNumber)
								{
									if (Enumerable.Contains(text2, ':'))
									{
										if (flag)
										{
											stringBuilder.Append($"'{text}'!{new XLAddress(worksheetInAction, iXLRange.RangeAddress.FirstAddress.RowNumber, iXLRange.RangeAddress.FirstAddress.ColumnNumber + columnsShifted, iXLRange.RangeAddress.FirstAddress.FixedRow, iXLRange.RangeAddress.FirstAddress.FixedColumn)}:{new XLAddress(worksheetInAction, iXLRange.RangeAddress.LastAddress.RowNumber, iXLRange.RangeAddress.LastAddress.ColumnNumber + columnsShifted, iXLRange.RangeAddress.LastAddress.FixedRow, iXLRange.RangeAddress.LastAddress.FixedColumn)}");
										}
