											stringBuilder.Append($"{new XLAddress(worksheetInAction, iXLRange.RangeAddress.FirstAddress.RowNumber, iXLRange.RangeAddress.FirstAddress.ColumnNumber + columnsShifted, iXLRange.RangeAddress.FirstAddress.FixedRow, iXLRange.RangeAddress.FirstAddress.FixedColumn)}:{new XLAddress(worksheetInAction, iXLRange.RangeAddress.LastAddress.RowNumber, iXLRange.RangeAddress.LastAddress.ColumnNumber + columnsShifted, iXLRange.RangeAddress.LastAddress.FixedRow, iXLRange.RangeAddress.LastAddress.FixedColumn)}");
										}
									}
									else if (flag)
									{
										stringBuilder.Append($"'{text}'!{new XLAddress(worksheetInAction, iXLRange.RangeAddress.FirstAddress.RowNumber, iXLRange.RangeAddress.FirstAddress.ColumnNumber + columnsShifted, iXLRange.RangeAddress.FirstAddress.FixedRow, iXLRange.RangeAddress.FirstAddress.FixedColumn)}");
									}
									else
									{
										stringBuilder.Append($"{new XLAddress(worksheetInAction, iXLRange.RangeAddress.FirstAddress.RowNumber, iXLRange.RangeAddress.FirstAddress.ColumnNumber + columnsShifted, iXLRange.RangeAddress.FirstAddress.FixedRow, iXLRange.RangeAddress.FirstAddress.FixedColumn)}");
									}
								}
								else if (flag)
								{
									stringBuilder.Append($"'{text}'!{iXLRange.RangeAddress.FirstAddress}:{new XLAddress(worksheetInAction, iXLRange.RangeAddress.LastAddress.RowNumber, iXLRange.RangeAddress.LastAddress.ColumnNumber + columnsShifted, iXLRange.RangeAddress.LastAddress.FixedRow, iXLRange.RangeAddress.LastAddress.FixedColumn)}");
								}
								else
								{
									stringBuilder.Append($"{iXLRange.RangeAddress.FirstAddress}:{new XLAddress(worksheetInAction, iXLRange.RangeAddress.LastAddress.RowNumber, iXLRange.RangeAddress.LastAddress.ColumnNumber + columnsShifted, iXLRange.RangeAddress.LastAddress.FixedRow, iXLRange.RangeAddress.LastAddress.FixedColumn)}");
