		public void Delete()
		{
			int columnNumber = ColumnNumber();
			using (XLRange xLRange = AsRange())
			{
				xLRange.Delete(XLShiftDeletedCells.ShiftCellsLeft);
			}
			base.Worksheet.Internals.ColumnsCollection.Remove(columnNumber);
			List<int> list = new List<int>();
			list.AddRange(from c in base.Worksheet.Internals.ColumnsCollection
				where c.Key > columnNumber
				select c.Key);
			foreach (int item in list.OrderBy((int c) => c))
			{
				base.Worksheet.Internals.ColumnsCollection.Add(item - 1, base.Worksheet.Internals.ColumnsCollection[item]);
				base.Worksheet.Internals.ColumnsCollection.Remove(item);
			}
