		public new IXLColumns InsertColumnsAfter(int numberOfColumns)
		{
			int num = ColumnNumber();
			base.Worksheet.Internals.ColumnsCollection.ShiftColumnsRight(num + 1, numberOfColumns);
			using (XLColumn xLColumn = base.Worksheet.Column(num))
			{
				using XLRange xLRange = xLColumn.AsRange();
				xLRange.InsertColumnsAfter(onlyUsedCells: true, numberOfColumns).Dispose();
			}
			IXLColumns iXLColumns = base.Worksheet.Columns(num + 1, num + numberOfColumns);
			CopyColumns(iXLColumns);
			return iXLColumns;
		}

		public new IXLColumns InsertColumnsBefore(int numberOfColumns)
		{
			int num = ColumnNumber();
			if (num > 1)
			{
				using (XLColumn xLColumn = base.Worksheet.Column(num - 1))
				{
					return xLColumn.InsertColumnsAfter(numberOfColumns);
				}
			}
			base.Worksheet.Internals.ColumnsCollection.ShiftColumnsRight(num, numberOfColumns);
			using (XLColumn xLColumn2 = base.Worksheet.Column(num))
			{
				using XLRange xLRange = xLColumn2.AsRange();
				xLRange.InsertColumnsBefore(onlyUsedCells: true, numberOfColumns).Dispose();
			}
			return base.Worksheet.Columns(num, num + numberOfColumns - 1);
		}

		private void CopyColumns(IXLColumns newColumns)
		{
