		public IXLColumn AdjustToContents(int startRow, int endRow, double minWidth, double maxWidth)
		{
			Dictionary<IXLFontBase, Font> fontCache = new Dictionary<IXLFontBase, Font>();
			double num = minWidth;
			foreach (XLCell item in Column(startRow, endRow).CellsUsed())
			{
				if (item.IsMerged())
				{
					continue;
				}
				double num2 = 0.0;
				int textRotation = item.Style.Alignment.TextRotation;
				if (item.HasRichText || textRotation != 0 || item.InnerText.Contains(Environment.NewLine))
				{
					List<KeyValuePair<IXLFontBase, string>> list = new List<KeyValuePair<IXLFontBase, string>>();
					if (item.HasRichText)
					{
						foreach (IXLRichString item2 in item.RichText)
						{
							string text = item2.Text;
							string[] array = text.Split(new string[1] { Environment.NewLine }, StringSplitOptions.None);
							int num3 = array.Count();
							for (int i = 0; i < num3; i++)
							{
								string text2 = array[i];
								if (i < num3 - 1)
								{
									text2 += Environment.NewLine;
								}
								list.Add(new KeyValuePair<IXLFontBase, string>(item2, text2));
							}
						}
					}
					else
					{
						string formattedString = item.GetFormattedString();
						string[] array2 = formattedString.Split(new string[1] { Environment.NewLine }, StringSplitOptions.None);
						int num4 = array2.Count();
						for (int j = 0; j < num4; j++)
						{
							string text3 = array2[j];
							if (j < num4 - 1)
							{
								text3 += Environment.NewLine;
							}
							list.Add(new KeyValuePair<IXLFontBase, string>(item.Style.Font, text3));
						}
					}
					double num5 = 0.0;
					bool flag = false;
					double num6 = 0.0;
					int num7 = 1;
					foreach (KeyValuePair<IXLFontBase, string> item3 in list)
					{
						IXLFontBase key = item3.Key;
						string value = item3.Value;
						int num8 = value.IndexOf(Environment.NewLine);
						switch (textRotation)
						{
						case 0:
							if (num8 >= 0)
							{
								if (num8 > 0)
								{
									num5 += key.GetWidth(value.Substring(0, num8), fontCache);
								}
								if (num5 > num2)
								{
									num2 = num5;
								}
								num5 = ((num8 < value.Length - 2) ? key.GetWidth(value.Substring(num8 + 2), fontCache) : 0.0);
							}
							else
							{
								num5 += key.GetWidth(value, fontCache);
							}
							continue;
						case 255:
							if (num5 <= 0.0)
							{
								num5 = key.GetWidth("X", fontCache);
							}
							if (num8 >= 0)
							{
								num5 += key.GetWidth("X", fontCache);
							}
							continue;
						}
						flag = true;
						double width = key.GetWidth("X", fontCache);
						if (width > num6)
						{
							num6 = width;
						}
						if (num8 >= 0)
						{
							num7++;
							if (num8 > 0)
							{
								num5 += key.GetWidth(value.Substring(0, num8), fontCache);
							}
							if (num5 > num2)
							{
								num2 = num5;
							}
							num5 = ((num8 < value.Length - 2) ? key.GetWidth(value.Substring(num8 + 2), fontCache) : 0.0);
						}
						else
						{
							num5 += key.GetWidth(value, fontCache);
						}
					}
					if (num5 > num2)
					{
						num2 = num5;
					}
					if (flag)
					{
						int num9 = ((textRotation != 90 && textRotation != 180 && textRotation != 255) ? (textRotation % 90) : 90);
						double d = DegreeToRadian(num9);
						num2 = num2 * Math.Cos(d) + num6 * (double)num7;
					}
				}
				else
				{
					num2 = item.Style.Font.GetWidth(item.GetFormattedString(), fontCache);
				}
				if (num2 >= maxWidth)
				{
					num = maxWidth;
					break;
				}
				if (num2 > num)
				{
					num = num2 + 1.0;
				}
			}
			if (num <= 0.0)
			{
				num = base.Worksheet.ColumnWidth;
			}
			Width = num;
			return this;
		}

