		private void WorksheetRangeShiftedColumns(XLRange range, int columnsShifted)
		{
			if (range.RangeAddress.FirstAddress.ColumnNumber <= ColumnNumber())
			{
				SetColumnNumber(ColumnNumber() + columnsShifted);
			}
		}

		private void SetColumnNumber(int column)
		{
			if (column <= 0)
			{
				base.RangeAddress.IsInvalid = false;
				return;
			}
			base.RangeAddress.FirstAddress = new XLAddress(base.Worksheet, 1, column, base.RangeAddress.FirstAddress.FixedRow, base.RangeAddress.FirstAddress.FixedColumn);
			base.RangeAddress.LastAddress = new XLAddress(base.Worksheet, 1048576, column, base.RangeAddress.LastAddress.FixedRow, base.RangeAddress.LastAddress.FixedColumn);
		}

		public override XLRange Range(string rangeAddressStr)
		{
			string rangeAddress;
			if (Enumerable.Contains(rangeAddressStr, ':') || Enumerable.Contains(rangeAddressStr, '-'))
			{
				if (Enumerable.Contains(rangeAddressStr, '-'))
				{
					rangeAddressStr = rangeAddressStr.Replace('-', ':');
				}
				string[] array = rangeAddressStr.Split(new char[1] { ':' });
				string address = array[0];
				string address2 = array[1];
				rangeAddress = FixColumnAddress(address) + ":" + FixColumnAddress(address2);
			}
			else
			{
				rangeAddress = FixColumnAddress(rangeAddressStr);
			}
			XLRangeAddress rangeAddress2 = new XLRangeAddress(base.Worksheet, rangeAddress);
			return Range(rangeAddress2);
		}

