		public XLRow(int row, XLRowParameters xlRowParameters)
			: base(new XLRangeAddress(new XLAddress(xlRowParameters.Worksheet, row, 1, fixedRow: false, fixedColumn: false), new XLAddress(xlRowParameters.Worksheet, row, 16384, fixedRow: false, fixedColumn: false)))
		{
