			SetStyle(xlRowParameters.DefaultStyleId);
			_height = xlRowParameters.Worksheet.RowHeight;
		}

		public XLRow(XLRow row)
			: base(new XLRangeAddress(new XLAddress(row.Worksheet, row.RowNumber(), 1, fixedRow: false, fixedColumn: false), new XLAddress(row.Worksheet, row.RowNumber(), 16384, fixedRow: false, fixedColumn: false)))
		{
			_height = row._height;
			IsReference = row.IsReference;
			if (IsReference)
			{
				SubscribeToShiftedRows(WorksheetRangeShiftedRows);
			}
			_collapsed = row._collapsed;
			_isHidden = row._isHidden;
			_outlineLevel = row._outlineLevel;
