		public void Delete()
		{
			int rowNumber = RowNumber();
			using (XLRange xLRange = AsRange())
			{
				xLRange.Delete(XLShiftDeletedCells.ShiftCellsUp);
			}
			base.Worksheet.Internals.RowsCollection.Remove(rowNumber);
			List<int> list = new List<int>();
			list.AddRange(from c in base.Worksheet.Internals.RowsCollection
				where c.Key > rowNumber
				select c.Key);
			foreach (int item in list.OrderBy((int r) => r))
			{
				base.Worksheet.Internals.RowsCollection.Add(item - 1, base.Worksheet.Internals.RowsCollection[item]);
				base.Worksheet.Internals.RowsCollection.Remove(item);
			}
		}

		public new IXLRows InsertRowsBelow(int numberOfRows)
		{
			int num = RowNumber();
			base.Worksheet.Internals.RowsCollection.ShiftRowsDown(num + 1, numberOfRows);
			using (XLRow xLRow = base.Worksheet.Row(num))
			{
				using XLRange xLRange = xLRow.AsRange();
				xLRange.InsertRowsBelow(onlyUsedCells: true, numberOfRows).Dispose();
			}
			IXLRows iXLRows = base.Worksheet.Rows(num + 1, num + numberOfRows);
			CopyRows(iXLRows);
			return iXLRows;
		}

		private void CopyRows(IXLRows newRows)
		{
			foreach (IXLRow newRow in newRows)
			{
				XLRow xLRow = base.Worksheet.Internals.RowsCollection[newRow.RowNumber()];
				xLRow._height = Height;
				xLRow.SetStyle(Style);
				xLRow._collapsed = Collapsed;
				xLRow._isHidden = IsHidden;
				xLRow._outlineLevel = OutlineLevel;
			}
		}

		public new IXLRows InsertRowsAbove(int numberOfRows)
		{
			int num = RowNumber();
			if (num > 1)
			{
				using (XLRow xLRow = base.Worksheet.Row(num - 1))
				{
					return xLRow.InsertRowsBelow(numberOfRows);
				}
			}
			base.Worksheet.Internals.RowsCollection.ShiftRowsDown(num, numberOfRows);
			using (XLRow xLRow2 = base.Worksheet.Row(num))
			{
				using XLRange xLRange = xLRow2.AsRange();
				xLRange.InsertRowsAbove(onlyUsedCells: true, numberOfRows).Dispose();
			}
			return base.Worksheet.Rows(num, num + numberOfRows - 1);
		}

