		public IXLRow AdjustToContents(int startColumn, int endColumn, double minHeight, double maxHeight)
		{
			Dictionary<IXLFontBase, Font> fontCache = new Dictionary<IXLFontBase, Font>();
			double num = minHeight;
			foreach (XLCell item in from XLCell c in Row(startColumn, endColumn).CellsUsed()
				where !c.IsMerged()
				select c)
			{
				int textRotation = item.Style.Alignment.TextRotation;
				double num7;
				if (item.HasRichText || textRotation != 0 || item.InnerText.Contains(Environment.NewLine))
				{
					List<KeyValuePair<IXLFontBase, string>> list = new List<KeyValuePair<IXLFontBase, string>>();
					if (item.HasRichText)
					{
						foreach (IXLRichString item2 in item.RichText)
						{
							string text = item2.Text;
							string[] array = text.Split(new string[1] { Environment.NewLine }, StringSplitOptions.None);
							int num2 = array.Count();
							for (int i = 0; i < num2; i++)
							{
								string text2 = array[i];
								if (i < num2 - 1)
								{
									text2 += Environment.NewLine;
								}
								list.Add(new KeyValuePair<IXLFontBase, string>(item2, text2));
							}
						}
					}
					else
					{
						string formattedString = item.GetFormattedString();
						string[] array2 = formattedString.Split(new string[1] { Environment.NewLine }, StringSplitOptions.None);
						int num3 = array2.Count();
						for (int j = 0; j < num3; j++)
						{
							string text3 = array2[j];
							if (j < num3 - 1)
							{
								text3 += Environment.NewLine;
							}
							list.Add(new KeyValuePair<IXLFontBase, string>(item.Style.Font, text3));
						}
					}
					double num4 = list.Max((KeyValuePair<IXLFontBase, string> kp) => kp.Value.Length);
					double num5 = list.Max((KeyValuePair<IXLFontBase, string> kp) => kp.Key.GetHeight(fontCache));
					int num6 = list.Count((KeyValuePair<IXLFontBase, string> kp) => kp.Value.Contains(Environment.NewLine)) + 1;
					if (textRotation == 0)
					{
						num7 = num5 * (double)num6;
					}
					else if (textRotation == 255)
					{
						num7 = num4 * num5;
					}
					else
					{
						double num8 = ((textRotation != 90 && textRotation != 180 && textRotation != 255) ? ((double)(textRotation % 90)) : 90.0);
						num7 = num8 / 90.0 * num5 * num4 * 0.5;
					}
				}
				else
				{
					num7 = item.Style.Font.GetHeight(fontCache);
				}
				if (num7 >= maxHeight)
				{
					num = maxHeight;
					break;
				}
				if (num7 > num)
				{
					num = num7;
				}
			}
			if (num <= 0.0)
			{
				num = base.Worksheet.RowHeight;
			}
			Height = num;
			return this;
		}

