		private void WorksheetRangeShiftedRows(XLRange range, int rowsShifted)
		{
			if (range.RangeAddress.FirstAddress.RowNumber <= RowNumber())
			{
				SetRowNumber(RowNumber() + rowsShifted);
			}
		}

		private void SetRowNumber(int row)
		{
			if (row <= 0)
			{
				base.RangeAddress.IsInvalid = false;
				return;
			}
			base.RangeAddress.FirstAddress = new XLAddress(base.Worksheet, row, 1, base.RangeAddress.FirstAddress.FixedRow, base.RangeAddress.FirstAddress.FixedColumn);
			base.RangeAddress.LastAddress = new XLAddress(base.Worksheet, row, 16384, base.RangeAddress.LastAddress.FixedRow, base.RangeAddress.LastAddress.FixedColumn);
		}

		public override XLRange Range(string rangeAddressStr)
		{
			string rangeAddress;
			if (Enumerable.Contains(rangeAddressStr, ':') || Enumerable.Contains(rangeAddressStr, '-'))
			{
				if (Enumerable.Contains(rangeAddressStr, '-'))
				{
					rangeAddressStr = rangeAddressStr.Replace('-', ':');
				}
				string[] array = rangeAddressStr.Split(new char[1] { ':' });
				string address = array[0];
				string address2 = array[1];
				rangeAddress = FixRowAddress(address) + ":" + FixRowAddress(address2);
			}
			else
			{
				rangeAddress = FixRowAddress(rangeAddressStr);
			}
			XLRangeAddress rangeAddress2 = new XLRangeAddress(base.Worksheet, rangeAddress);
			return Range(rangeAddress2);
		}

		public IXLRow AdjustToContents()
		{
			return AdjustToContents(1);
		}

		internal void SetStyleNoColumns(IXLStyle value)
		{
			if (IsReference)
			{
				base.Worksheet.Internals.RowsCollection[RowNumber()].SetStyleNoColumns(value);
				return;
			}
			SetStyle(value);
			int row = RowNumber();
			foreach (XLCell item in base.Worksheet.Internals.CellsCollection.GetCellsInRow(row))
			{
				item.Style = value;
			}
		}

		private XLRow RowShift(int rowsToShift)
		{
			return base.Worksheet.Row(RowNumber() + rowsToShift);
