		public XLWorksheet(string sheetName, XLWorkbook workbook)
			: base(new XLRangeAddress(new XLAddress(null, 1, 1, fixedRow: false, fixedColumn: false), new XLAddress(null, 1048576, 16384, fixedRow: false, fixedColumn: false)))
		{
			EventTrackingEnabled = workbook.EventTracking == XLEventTracking.Enabled;
			base.RangeAddress.Worksheet = this;
			base.RangeAddress.FirstAddress.Worksheet = this;
			base.RangeAddress.LastAddress.Worksheet = this;
			NamedRanges = new XLNamedRanges(workbook);
			SheetView = new XLSheetView();
			Tables = new XLTables();
