		public IXLColumns Columns()
		{
			XLColumns xLColumns = new XLColumns(this);
			List<int> columnList = new List<int>();
			if (Internals.CellsCollection.Count > 0)
			{
				columnList.AddRange(Internals.CellsCollection.ColumnsUsed.Keys);
			}
			if (Internals.ColumnsCollection.Count > 0)
			{
				columnList.AddRange(Internals.ColumnsCollection.Keys.Where((int c) => !columnList.Contains(c)));
			}
			foreach (int item in columnList)
			{
				xLColumns.Add(Column(item));
			}
			return xLColumns;
		}

		public IXLColumns Columns(string columns)
		{
			XLColumns xLColumns = new XLColumns(null);
			string[] source = columns.Split(new char[1] { ',' });
			foreach (string item in source.Select((string pair) => pair.Trim()))
			{
				string text;
				string text2;
				if (Enumerable.Contains(item, ':') || Enumerable.Contains(item, '-'))
				{
					string[] array = XLHelper.SplitRange(item);
					text = array[0];
					text2 = array[1];
				}
				else
				{
					text = item;
					text2 = item;
				}
				if (int.TryParse(text, out var _))
				{
					foreach (IXLColumn item2 in Columns(int.Parse(text), int.Parse(text2)))
					{
						xLColumns.Add((XLColumn)item2);
					}
					continue;
				}
				foreach (IXLColumn item3 in Columns(text, text2))
				{
					xLColumns.Add((XLColumn)item3);
				}
			}
			return xLColumns;
		}

