		public IXLWorksheet CopyTo(XLWorkbook workbook, string newSheetName, int position)
		{
			XLWorksheet targetSheet = (XLWorksheet)workbook.WorksheetsInternal.Add(newSheetName, position);
			Internals.CellsCollection.GetCells().ForEach(delegate(XLCell c)
			{
				targetSheet.Cell(c.Address).CopyFrom(c, copyDataValidations: false);
			});
			DataValidations.ForEach(delegate(IXLDataValidation dv)
			{
				targetSheet.DataValidations.Add(new XLDataValidation(dv));
			});
			Internals.ColumnsCollection.ForEach(delegate(KeyValuePair<int, XLColumn> kp)
			{
				targetSheet.Internals.ColumnsCollection.Add(kp.Key, new XLColumn(kp.Value));
			});
			Internals.RowsCollection.ForEach(delegate(KeyValuePair<int, XLRow> kp)
			{
				targetSheet.Internals.RowsCollection.Add(kp.Key, new XLRow(kp.Value));
			});
			targetSheet.Visibility = Visibility;
			targetSheet.ColumnWidth = ColumnWidth;
			targetSheet.ColumnWidthChanged = ColumnWidthChanged;
			targetSheet.RowHeight = RowHeight;
			targetSheet.RowHeightChanged = RowHeightChanged;
			targetSheet.SetStyle(Style);
			targetSheet.PageSetup = new XLPageSetup((XLPageSetup)PageSetup, targetSheet);
			(targetSheet.PageSetup.Header as XLHeaderFooter).Changed = true;
			(targetSheet.PageSetup.Footer as XLHeaderFooter).Changed = true;
			targetSheet.Outline = new XLOutline(Outline);
			targetSheet.SheetView = new XLSheetView(SheetView);
			Internals.MergedRanges.ForEach(delegate(IXLRange kp)
			{
				targetSheet.Internals.MergedRanges.Add(targetSheet.Range(kp.RangeAddress.ToString()));
			});
			foreach (IXLNamedRange namedRange in NamedRanges)
			{
				XLRanges xLRanges = new XLRanges();
				namedRange.Ranges.ForEach(xLRanges.Add);
				targetSheet.NamedRanges.Add(namedRange.Name, xLRanges);
			}
			foreach (XLTable item in Tables.Cast<XLTable>())
			{
				string tableName = item.Name;
				XLTable table = (targetSheet.Tables.Any((IXLTable tt) => tt.Name == tableName) ? new XLTable(targetSheet.Range(item.RangeAddress.ToString()), addToTables: true) : new XLTable(targetSheet.Range(item.RangeAddress.ToString()), tableName, addToTables: true));
				table.RelId = item.RelId;
				table.EmphasizeFirstColumn = item.EmphasizeFirstColumn;
				table.EmphasizeLastColumn = item.EmphasizeLastColumn;
				table.ShowRowStripes = item.ShowRowStripes;
				table.ShowColumnStripes = item.ShowColumnStripes;
				table.ShowAutoFilter = item.ShowAutoFilter;
				table.Theme = item.Theme;
				table._showTotalsRow = item.ShowTotalsRow;
				table._uniqueNames.Clear();
				item._uniqueNames.ForEach(delegate(string n)
				{
					table._uniqueNames.Add(n);
				});
				int num = item.ColumnCount();
				for (int i = 0; i < num; i++)
				{
					table.Field(i).Index = item.Field(i).Index;
					table.Field(i).Name = item.Field(i).Name;
					(table.Field(i) as XLTableField).totalsRowLabel = (item.Field(i) as XLTableField).totalsRowLabel;
					(table.Field(i) as XLTableField).totalsRowFunction = (item.Field(i) as XLTableField).totalsRowFunction;
				}
			}
			if (AutoFilter.Enabled)
			{
				targetSheet.Range(AutoFilter.Range.RangeAddress).SetAutoFilter();
			}
			return targetSheet;
		}

		private string ReplaceRelativeSheet(string newSheetName, string value)
		{
			if (XLHelper.IsNullOrWhiteSpace(value))
			{
				return value;
			}
			StringBuilder stringBuilder = new StringBuilder();
			string[] array = value.Split(new char[1] { ',' });
			string[] array2 = array;
			foreach (string text in array2)
			{
				string[] array3 = text.Split(new char[1] { '!' });
				if (array3.Length == 2)
				{
					string text2 = array3[0];
					if (text2.StartsWith("'"))
					{
						text2 = text2.Substring(1, text2.Length - 2);
					}
					string arg = (text2.ToLower().Equals(Name.ToLower()) ? newSheetName : text2);
					stringBuilder.Append($"'{arg}'!{array3[1]}");
				}
				else
				{
					stringBuilder.Append(text);
				}
			}
			return stringBuilder.ToString();
		}

