		public new IXLRanges Ranges(string ranges)
		{
			XLRanges xLRanges = new XLRanges();
			foreach (string rangeAddressStr in from s in ranges.Split(new char[1] { ',' })
				select s.Trim())
			{
				if (XLHelper.IsValidRangeAddress(rangeAddressStr))
				{
					xLRanges.Add(Range(new XLRangeAddress(base.Worksheet, rangeAddressStr)));
					continue;
				}
				if (NamedRanges.Any((IXLNamedRange n) => string.Compare(n.Name, rangeAddressStr, ignoreCase: true) == 0))
				{
					NamedRange(rangeAddressStr).Ranges.ForEach(xLRanges.Add);
					continue;
				}
				Workbook.NamedRanges.First((IXLNamedRange n) => string.Compare(n.Name, rangeAddressStr, ignoreCase: true) == 0 && n.Ranges.First().Worksheet == this).Ranges.ForEach(xLRanges.Add);
			}
			return xLRanges;
		}

		public IXLRows RowsUsed(bool includeFormats = false, Func<IXLRow, bool> predicate = null)
		{
			XLRows xLRows = new XLRows(base.Worksheet);
			HashSet<int> rowsUsed = new HashSet<int>();
			Internals.RowsCollection.Keys.ForEach(delegate(int r)
			{
				rowsUsed.Add(r);
			});
			Internals.CellsCollection.RowsUsed.Keys.ForEach(delegate(int r)
			{
				rowsUsed.Add(r);
			});
			foreach (int item in rowsUsed)
			{
				XLRow xLRow = Row(item);
				if (!xLRow.IsEmpty(includeFormats) && (predicate == null || predicate(xLRow)))
				{
					xLRows.Add(xLRow);
				}
				else
				{
					xLRow.Dispose();
				}
			}
			return xLRows;
		}

		public IXLRows RowsUsed(Func<IXLRow, bool> predicate = null)
		{
			return RowsUsed(includeFormats: false, predicate);
		}

