		public void IncrementColumnOutline(int level)
		{
			if (level > 0)
			{
				if (!_columnOutlineCount.ContainsKey(level))
				{
					_columnOutlineCount.Add(level, 0);
				}
				_columnOutlineCount[level]++;
			}
		}

		public void DecrementColumnOutline(int level)
		{
			if (level > 0)
			{
				if (!_columnOutlineCount.ContainsKey(level))
				{
					_columnOutlineCount.Add(level, 0);
				}
				if (_columnOutlineCount[level] > 0)
				{
					_columnOutlineCount[level]--;
				}
			}
		}

		public int GetMaxColumnOutline()
		{
			List<KeyValuePair<int, int>> list = _columnOutlineCount.Where((KeyValuePair<int, int> kp) => kp.Value > 0).ToList();
			if (list.Count != 0)
			{
				return list.Max((KeyValuePair<int, int> kp) => kp.Key);
			}
			return 0;
		}

