		public XLColumn Column(int column)
		{
			if (column <= 0 || column > 16384)
			{
				throw new IndexOutOfRangeException($"Column number must be between 1 and {16384}");
			}
			int styleId = GetStyleId();
			if (!Internals.ColumnsCollection.ContainsKey(column))
			{
				Internals.RowsCollection.Keys.ForEach(delegate(int r)
				{
					Cell(r, column);
				});
				Internals.ColumnsCollection.Add(column, new XLColumn(column, new XLColumnParameters(this, styleId, isReference: false)));
			}
			return new XLColumn(column, new XLColumnParameters(this, styleId, isReference: true));
		}

