		private void WorksheetRangeShiftedColumns(XLRange range, int columnsShifted)
		{
			XLRanges xLRanges = new XLRanges();
			foreach (IXLRange mergedRange in Internals.MergedRanges)
			{
				if (range.RangeAddress.FirstAddress.ColumnNumber <= mergedRange.RangeAddress.FirstAddress.ColumnNumber && mergedRange.RangeAddress.FirstAddress.RowNumber >= range.RangeAddress.FirstAddress.RowNumber && mergedRange.RangeAddress.LastAddress.RowNumber <= range.RangeAddress.LastAddress.RowNumber)
				{
					XLRange range2 = Range(mergedRange.RangeAddress.FirstAddress.RowNumber, mergedRange.RangeAddress.FirstAddress.ColumnNumber + columnsShifted, mergedRange.RangeAddress.LastAddress.RowNumber, mergedRange.RangeAddress.LastAddress.ColumnNumber + columnsShifted);
					xLRanges.Add(range2);
				}
				else if (range.RangeAddress.FirstAddress.ColumnNumber > mergedRange.RangeAddress.FirstAddress.ColumnNumber || range.RangeAddress.FirstAddress.RowNumber > mergedRange.RangeAddress.LastAddress.RowNumber)
				{
					xLRanges.Add(mergedRange);
				}
			}
			Internals.MergedRanges = xLRanges;
			Workbook.Worksheets.ForEach(delegate(IXLWorksheet ws)
			{
				MoveNamedRangesColumns(range, columnsShifted, ws.NamedRanges);
			});
			MoveNamedRangesColumns(range, columnsShifted, Workbook.NamedRanges);
			ShiftConditionalFormattingColumns(range, columnsShifted);
		}

		private void ShiftConditionalFormattingColumns(XLRange range, int columnsShifted)
		{
			int columnNumber = range.RangeAddress.FirstAddress.ColumnNumber;
			if (columnNumber == 1)
			{
				return;
			}
			int lastCellColumn = range.RangeAddress.FirstAddress.ColumnNumber + columnsShifted - 1;
			int rowNumber = range.RangeAddress.FirstAddress.RowNumber;
			int rowNumber2 = range.RangeAddress.LastAddress.RowNumber;
			XLRange xLRange = Range(rowNumber, columnNumber, rowNumber2, lastCellColumn);
			XLRangeColumn xLRangeColumn = xLRange.FirstColumn();
			XLRangeColumn model = xLRangeColumn.ColumnLeft();
			int rowNumber3 = model.RangeAddress.FirstAddress.RowNumber;
			if (ConditionalFormats.Any((IXLConditionalFormat cf) => cf.Range.Intersects(model)))
			{
				for (int i = rowNumber; i <= rowNumber2; i++)
				{
					XLCell cellModel = model.Cell(i - rowNumber3 + 1);
					foreach (IXLConditionalFormat item in ConditionalFormats.Where((IXLConditionalFormat cf) => cf.Range.Intersects(cellModel.AsRange())).ToList())
					{
						Range(i, columnNumber, i, lastCellColumn).AddConditionalFormat(item);
					}
				}
			}
			xLRange.Dispose();
			model.Dispose();
			xLRangeColumn.Dispose();
		}

		private void WorksheetRangeShiftedRows(XLRange range, int rowsShifted)
		{
			XLRanges xLRanges = new XLRanges();
			foreach (IXLRange mergedRange in Internals.MergedRanges)
			{
				if (range.RangeAddress.FirstAddress.RowNumber <= mergedRange.RangeAddress.FirstAddress.RowNumber && mergedRange.RangeAddress.FirstAddress.ColumnNumber >= range.RangeAddress.FirstAddress.ColumnNumber && mergedRange.RangeAddress.LastAddress.ColumnNumber <= range.RangeAddress.LastAddress.ColumnNumber)
				{
					XLRange range2 = Range(mergedRange.RangeAddress.FirstAddress.RowNumber + rowsShifted, mergedRange.RangeAddress.FirstAddress.ColumnNumber, mergedRange.RangeAddress.LastAddress.RowNumber + rowsShifted, mergedRange.RangeAddress.LastAddress.ColumnNumber);
					xLRanges.Add(range2);
				}
				else if (range.RangeAddress.FirstAddress.RowNumber > mergedRange.RangeAddress.FirstAddress.RowNumber || range.RangeAddress.FirstAddress.ColumnNumber > mergedRange.RangeAddress.LastAddress.ColumnNumber)
				{
					xLRanges.Add(mergedRange);
				}
			}
			Internals.MergedRanges = xLRanges;
			Workbook.Worksheets.ForEach(delegate(IXLWorksheet ws)
			{
				MoveNamedRangesRows(range, rowsShifted, ws.NamedRanges);
			});
			MoveNamedRangesRows(range, rowsShifted, Workbook.NamedRanges);
			ShiftConditionalFormattingRows(range, rowsShifted);
		}

		private void ShiftConditionalFormattingRows(XLRange range, int rowsShifted)
		{
			int rowNumber = range.RangeAddress.FirstAddress.RowNumber;
			if (rowNumber == 1)
			{
				return;
			}
			SuspendEvents();
			IXLRange iXLRange = range.Worksheet.RangeUsed(includeFormats: true);
			IXLRangeAddress iXLRangeAddress = ((iXLRange != null) ? iXLRange.RangeAddress : range.RangeAddress);
			ResumeEvents();
			if (rowNumber < iXLRangeAddress.FirstAddress.RowNumber)
			{
				rowNumber = iXLRangeAddress.FirstAddress.RowNumber;
			}
			int num = range.RangeAddress.FirstAddress.RowNumber + rowsShifted - 1;
			if (num > iXLRangeAddress.LastAddress.RowNumber)
			{
				num = iXLRangeAddress.LastAddress.RowNumber;
			}
			int columnNumber = range.RangeAddress.FirstAddress.ColumnNumber;
			if (columnNumber < iXLRangeAddress.FirstAddress.ColumnNumber)
			{
				columnNumber = iXLRangeAddress.FirstAddress.ColumnNumber;
			}
			int columnNumber2 = range.RangeAddress.LastAddress.ColumnNumber;
			if (columnNumber2 > iXLRangeAddress.LastAddress.ColumnNumber)
			{
				columnNumber2 = iXLRangeAddress.LastAddress.ColumnNumber;
			}
			XLRange xLRange = Range(rowNumber, columnNumber, num, columnNumber2);
			XLRangeRow xLRangeRow = xLRange.FirstRow();
			XLRangeRow model = xLRangeRow.RowAbove();
			int columnNumber3 = model.RangeAddress.FirstAddress.ColumnNumber;
			if (ConditionalFormats.Any((IXLConditionalFormat cf) => cf.Range.Intersects(model)))
			{
				for (int i = columnNumber; i <= columnNumber2; i++)
				{
					IXLCell cellModel = model.Cell(i - columnNumber3 + 1);
					foreach (IXLConditionalFormat item in ConditionalFormats.Where((IXLConditionalFormat cf) => cf.Range.Intersects(cellModel.AsRange())).ToList())
					{
						Range(rowNumber, i, num, i).AddConditionalFormat(item);
					}
				}
			}
			xLRange.Dispose();
			model.Dispose();
			xLRangeRow.Dispose();
		}

		internal void BreakConditionalFormatsIntoCells(List<IXLAddress> addresses)
		{
			XLConditionalFormats xLConditionalFormats = new XLConditionalFormats();
			SuspendEvents();
			foreach (IXLConditionalFormat conditionalFormat in ConditionalFormats)
			{
				foreach (XLCell item in conditionalFormat.Range.Cells((IXLCell c) => !addresses.Contains(c.Address)))
				{
					int row = item.Address.RowNumber;
					string column = item.Address.ColumnLetter;
					XLConditionalFormat xLConditionalFormat = new XLConditionalFormat(item.AsRange(), copyDefaultModify: true);
					xLConditionalFormat.CopyFrom(conditionalFormat);
					xLConditionalFormat.Values.Values.Where((XLFormula f) => f.IsFormula).ForEach(delegate(XLFormula f)
					{
						f._value = XLHelper.ReplaceRelative(f.Value, row, column);
					});
					xLConditionalFormats.Add(xLConditionalFormat);
				}
				conditionalFormat.Range.Dispose();
			}
			ResumeEvents();
			ConditionalFormats = xLConditionalFormats;
		}

		private void MoveNamedRangesRows(XLRange range, int rowsShifted, IXLNamedRanges namedRanges)
		{
			foreach (XLNamedRange namedRange in namedRanges)
			{
				List<string> rangeList = (from r in namedRange.RangeList
					select XLCell.ShiftFormulaRows(r, this, range, rowsShifted) into newReference
					where newReference.Length > 0
					select newReference).ToList();
				namedRange.RangeList = rangeList;
			}
		}

		private void MoveNamedRangesColumns(XLRange range, int columnsShifted, IXLNamedRanges namedRanges)
		{
			foreach (XLNamedRange namedRange in namedRanges)
			{
				List<string> rangeList = (from r in namedRange.RangeList
					select XLCell.ShiftFormulaColumns(r, this, range, columnsShifted) into newReference
					where newReference.Length > 0
					select newReference).ToList();
				namedRange.RangeList = rangeList;
			}
		}

		public void NotifyRangeShiftedRows(XLRange range, int rowsShifted)
		{
			if (this.RangeShiftedRows != null)
			{
				this.RangeShiftedRows(range, rowsShifted);
			}
		}

		public void NotifyRangeShiftedColumns(XLRange range, int columnsShifted)
		{
			if (this.RangeShiftedColumns != null)
			{
				this.RangeShiftedColumns(range, columnsShifted);
			}
		}

		public XLRow Row(int row, bool pingCells)
		{
			if (row <= 0 || row > 1048576)
			{
				throw new IndexOutOfRangeException($"Row number must be between 1 and {1048576}");
			}
			int styleId;
			if (Internals.RowsCollection.TryGetValue(row, out var value))
			{
				styleId = value.GetStyleId();
			}
			else
			{
				if (pingCells)
				{
					IEnumerable<int> source = from c in Internals.ColumnsCollection
						join dc in Internals.CellsCollection.ColumnsUsed.Keys on c.Key equals dc
						where !Internals.CellsCollection.Contains(row, dc)
						select dc;
					source.ForEach(delegate(int c)
					{
						Cell(row, c);
					});
				}
				styleId = GetStyleId();
				Internals.RowsCollection.Add(row, new XLRow(row, new XLRowParameters(this, styleId, isReference: false)));
			}
			return new XLRow(row, new XLRowParameters(this, styleId));
		}

		private IXLRange GetRangeForSort()
		{
			IXLRange range = RangeUsed();
			base.SortColumns.ForEach(delegate(IXLSortElement e)
			{
				range.SortColumns.Add(e.ElementNumber, e.SortOrder, e.IgnoreBlanks, e.MatchCase);
			});
			base.SortRows.ForEach(delegate(IXLSortElement e)
			{
				range.SortRows.Add(e.ElementNumber, e.SortOrder, e.IgnoreBlanks, e.MatchCase);
			});
			return range;
		}

		public XLPivotTable PivotTable(string name)
		{
			return (XLPivotTable)PivotTables.PivotTable(name);
		}

		public new XLCells Cells()
		{
			return CellsUsed(includeFormats: true);
		}

		public new XLCell Cell(string cellAddressInRange)
		{
			if (XLHelper.IsValidA1Address(cellAddressInRange))
			{
				return Cell(XLAddress.Create(this, cellAddressInRange));
			}
			if (NamedRanges.Any((IXLNamedRange n) => string.Compare(n.Name, cellAddressInRange, ignoreCase: true) == 0))
			{
				return (XLCell)NamedRange(cellAddressInRange).Ranges.First().FirstCell();
			}
			IXLNamedRange iXLNamedRange = Workbook.NamedRanges.FirstOrDefault((IXLNamedRange n) => string.Compare(n.Name, cellAddressInRange, ignoreCase: true) == 0 && n.Ranges.First().Worksheet == this && n.Ranges.Count == 1);
			if (iXLNamedRange == null || !iXLNamedRange.Ranges.Any())
			{
				return null;
			}
			return (XLCell)iXLNamedRange.Ranges.First().FirstCell();
		}

		public XLCell CellFast(string cellAddressInRange)
		{
			return Cell(XLAddress.Create(this, cellAddressInRange));
		}

		public override XLRange Range(string rangeAddressStr)
		{
			if (XLHelper.IsValidRangeAddress(rangeAddressStr))
			{
				return Range(new XLRangeAddress(base.Worksheet, rangeAddressStr));
			}
			if (rangeAddressStr.Contains("["))
			{
				return Table(rangeAddressStr.Substring(0, rangeAddressStr.IndexOf("["))) as XLRange;
			}
			if (NamedRanges.Any((IXLNamedRange n) => string.Compare(n.Name, rangeAddressStr, ignoreCase: true) == 0))
			{
				return (XLRange)NamedRange(rangeAddressStr).Ranges.First();
			}
			IXLNamedRange iXLNamedRange = Workbook.NamedRanges.FirstOrDefault((IXLNamedRange n) => string.Compare(n.Name, rangeAddressStr, ignoreCase: true) == 0 && n.Ranges.First().Worksheet == this && n.Ranges.Count == 1);
			if (iXLNamedRange == null || !iXLNamedRange.Ranges.Any())
			{
				return null;
			}
			return (XLRange)iXLNamedRange.Ranges.First();
		}

		public void SuspendEvents()
		{
			_eventTracking = EventTrackingEnabled;
			EventTrackingEnabled = false;
		}

		public void ResumeEvents()
		{
			EventTrackingEnabled = _eventTracking;
		}

		public object Evaluate(string expression)
		{
			return CalcEngine.Evaluate(expression);
		}
	}
