	internal class XLWorksheets : IXLWorksheets, IEnumerable<IXLWorksheet>, IEnumerable<XLWorksheet>, IEnumerable
	{
		private readonly XLWorkbook _workbook;

		private readonly Dictionary<string, XLWorksheet> _worksheets = new Dictionary<string, XLWorksheet>();

		public HashSet<string> Deleted = new HashSet<string>();

		public int Count
		{
			[DebuggerStepThrough]
			get
			{
				return _worksheets.Count;
			}
		}

		public XLWorksheets(XLWorkbook workbook)
		{
			_workbook = workbook;
		}

		public IEnumerator<XLWorksheet> GetEnumerator()
		{
			return ((IEnumerable<XLWorksheet>)_worksheets.Values).GetEnumerator();
		}

		public bool TryGetWorksheet(string sheetName, out IXLWorksheet worksheet)
		{
			if (_worksheets.TryGetValue(sheetName, out var value))
			{
				worksheet = value;
				return true;
			}
			worksheet = null;
			return false;
		}

		public IXLWorksheet Worksheet(string sheetName)
		{
			if (_worksheets.TryGetValue(sheetName, out var value))
			{
				return value;
			}
			IEnumerable<KeyValuePair<string, XLWorksheet>> source = _worksheets.Where((KeyValuePair<string, XLWorksheet> ws) => ws.Key.ToLower().Equals(sheetName.ToLower()));
			if (source.Any())
			{
				return source.First().Value;
			}
			throw new Exception("There isn't a worksheet named '" + sheetName + "'.");
		}

		public IXLWorksheet Worksheet(int position)
		{
			int num = _worksheets.Values.Count((XLWorksheet w) => w.Position == position);
			if (num == 0)
			{
				throw new Exception("There isn't a worksheet associated with that position.");
			}
			if (num > 1)
			{
				throw new Exception("Can't retrieve a worksheet because there are multiple worksheets associated with that position.");
			}
			return _worksheets.Values.Single((XLWorksheet w) => w.Position == position);
		}

		public IXLWorksheet Add(string sheetName)
		{
			XLWorksheet xLWorksheet = new XLWorksheet(sheetName, _workbook);
			_worksheets.Add(sheetName, xLWorksheet);
			xLWorksheet._position = _worksheets.Count + _workbook.UnsupportedSheets.Count;
			return xLWorksheet;
		}

		public IXLWorksheet Add(string sheetName, int position)
		{
			_worksheets.Values.Where((XLWorksheet w) => w._position >= position).ForEach(delegate(XLWorksheet w)
			{
				w._position++;
			});
			_workbook.UnsupportedSheets.Where((XLWorkbook.UnsupportedSheet w) => w.Position >= position).ForEach(delegate(XLWorkbook.UnsupportedSheet w)
			{
				w.Position++;
			});
			XLWorksheet xLWorksheet = new XLWorksheet(sheetName, _workbook);
			_worksheets.Add(sheetName, xLWorksheet);
			xLWorksheet._position = position;
			return xLWorksheet;
		}

		public void Delete(string sheetName)
		{
			Delete(_worksheets[sheetName].Position);
		}

		public void Delete(int position)
		{
			int num = _worksheets.Values.Count((XLWorksheet w) => w.Position == position);
			if (num == 0)
			{
				throw new Exception("There isn't a worksheet associated with that index.");
			}
			if (num > 1)
			{
				throw new Exception("Can't delete the worksheet because there are multiple worksheets associated with that index.");
			}
			XLWorksheet xLWorksheet = _worksheets.Values.Single((XLWorksheet w) => w.Position == position);
			if (!XLHelper.IsNullOrWhiteSpace(xLWorksheet.RelId) && !Deleted.Contains(xLWorksheet.RelId))
			{
				Deleted.Add(xLWorksheet.RelId);
			}
			_worksheets.RemoveAll((XLWorksheet w) => w.Position == position);
			_worksheets.Values.Where((XLWorksheet w) => w.Position > position).ForEach(delegate(XLWorksheet w)
			{
				w._position--;
			});
			_workbook.UnsupportedSheets.Where((XLWorkbook.UnsupportedSheet w) => w.Position > position).ForEach(delegate(XLWorkbook.UnsupportedSheet w)
			{
				w.Position--;
			});
		}

		IEnumerator<IXLWorksheet> IEnumerable<IXLWorksheet>.GetEnumerator()
		{
			return _worksheets.Values.Cast<IXLWorksheet>().GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public IXLWorksheet Add(DataTable dataTable)
		{
			return Add(dataTable, dataTable.TableName);
		}

		public IXLWorksheet Add(DataTable dataTable, string sheetName)
		{
			IXLWorksheet iXLWorksheet = Add(sheetName);
			iXLWorksheet.Cell(1, 1).InsertTable(dataTable);
			iXLWorksheet.Columns().AdjustToContents(1, 75);
			return iXLWorksheet;
		}

		public void Add(DataSet dataSet)
		{
			foreach (DataTable table in dataSet.Tables)
			{
				Add(table);
			}
		}

		public void Rename(string oldSheetName, string newSheetName)
		{
			if (!XLHelper.IsNullOrWhiteSpace(oldSheetName) && _worksheets.ContainsKey(oldSheetName))
			{
				XLWorksheet value = _worksheets[oldSheetName];
				_worksheets.Remove(oldSheetName);
				_worksheets.Add(newSheetName, value);
			}
		}
	}
